window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-1.html"] = [{"so":"1","ten":"指示代词“任何”","tenVn":"Đại từ chỉ thị 「任何」 — bất kỳ, bất cứ","cauTruc":["任何 + danh từ + 都 / 也 + động từ","Phủ định: 没有 / 不 + động từ + 任何 + danh từ"],"giaiThich":"「任何」 có nghĩa là 「无论什么」 (bất kể cái gì / ai). Khi bổ nghĩa cho danh từ thường KHÔNG thêm 「的」, và phía sau hay có 「都」 hoặc 「也」 đi kèm. Mẹo cho người Việt: “bất kỳ … nào cũng …” → 任何……都 / 也……; “không … bất kỳ … nào” → 没有任何…… hoặc 任何……都不…….","viDu":[{"zh":"你们以后有任何问题都可以来找我。","py":"Nǐmen yǐhòu yǒu rènhé wèntí dōu kěyǐ lái zhǎo wǒ.","vn":"Sau này các em có bất kỳ vấn đề gì đều có thể đến tìm cô."},{"zh":"明天我们8点出发，任何人也不能迟到。","py":"Míngtiān wǒmen 8 diǎn chūfā, rènhé rén yě bù néng chídào.","vn":"Mai chúng ta xuất phát lúc 8 giờ, bất kỳ ai cũng không được đến muộn."},{"zh":"学校有任何通知，我都会第一时间告诉你。","py":"Xuéxiào yǒu rènhé tōngzhī, wǒ dōu huì dì yìshíjiān gàosu nǐ.","vn":"Trường có bất kỳ thông báo nào, tôi đều sẽ báo cho bạn ngay."},{"zh":"这件事他没有告诉任何人。","py":"Zhè jiàn shì tā méiyǒu gàosu rènhé rén.","vn":"Việc này anh ấy không nói với bất kỳ ai. (câu phủ định: 任何 đứng sau động từ)"}],"loi":[{"sai":"任何的问题都可以问我。","why":"Trước danh từ, 任何 thường không thêm 的.","dung":"任何问题都可以问我。"},{"sai":"任何人可以参加。","why":"Thiếu 都 / 也 — câu “bất kỳ … cũng …” gần như luôn có 都 / 也.","dung":"任何人都可以参加。"},{"sai":"他不认识任何人们。","why":"任何 đã mang nghĩa “mọi / bất kỳ”, không thêm 们.","dung":"他不认识任何人。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["你们以后有","问题都可以来找我。"],"dap":[["任何"]],"chon":["任何","每","所有的"],"goiY":"“Sau này có bất kỳ vấn đề gì đều có thể đến tìm cô.”","giai":"任何 + danh từ + 都 + V."},{"kieu":"dien","phan":["明天8点出发，任何人","不能迟到。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“Bất kỳ ai cũng không được đến muộn.”","giai":"任何……也 + phủ định."},{"kieu":"dien","phan":["学校有任何通知，我","会第一时间告诉你。"],"dap":[["都"]],"chon":["都","还","再"],"goiY":"“Có bất kỳ thông báo nào, tôi đều báo cho bạn ngay.”","giai":"任何……都…… — 都 đứng trước động từ của vế sau."},{"kieu":"dien","phan":["这件事他没有告诉","人。"],"dap":[["任何"]],"chon":["任何","什么的","哪"],"goiY":"“Việc này anh ấy không nói với bất kỳ ai.”","giai":"没有 + V + 任何 + N."},{"kieu":"dien","phan":["","时候你都可以给我打电话。"],"dap":[["任何"]],"chon":["任何","那","一"],"goiY":"“Bất cứ lúc nào em cũng có thể gọi cho cô.”","giai":"任何时候 = bất cứ lúc nào."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你","有","任何","问题","都","可以","问我"],"dap":["你有任何问题都可以问我。"],"goiY":"Em có bất kỳ vấn đề gì đều có thể hỏi tôi.","giai":"任何 + N + 都 + 可以 + V."},{"kieu":"xep","manh":["任何人","也","不能","迟到"],"dap":["任何人也不能迟到。"],"goiY":"Bất kỳ ai cũng không được đến muộn.","giai":"任何人 + 也 + 不能."},{"kieu":"xep","manh":["他","没有","告诉","任何人","这件事"],"dap":["这件事他没有告诉任何人。","他没有告诉任何人这件事。"],"goiY":"Việc này anh ấy không nói với ai cả.","giai":"Phủ định: 没有 + V + 任何 + N."},{"kieu":"dungsai","cau":"任何的学生都可以参加。","dung":false,"sua":"任何学生都可以参加。","giai":"任何 + N, không thêm 的."},{"kieu":"dungsai","cau":"我们有任何问题都可以找王老师。","dung":true,"giai":"Đúng: 任何问题 + 都 + 可以."},{"kieu":"dungsai","cau":"他不认识任何人们。","dung":false,"sua":"他不认识任何人。","giai":"任何 không đi với 们."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 3)","huongDan":"Viết câu trả lời của B, có dùng 任何","cau":[{"kieu":"vandung","de":"A：听说王老师特别热情？ B：＿＿＿。","goiY":"Đồng ý, nói có bất kỳ vấn đề gì cũng có thể tìm cô ấy (任何……都……)","mau":"对，我们有任何问题都可以找她。","can":[["任何"],["都","也"]]},{"kieu":"vandung","de":"A：外国学生能参加学校运动会吗？ B：＿＿＿。","goiY":"Trả lời: được, bất kỳ sinh viên nào cũng có thể tham gia","mau":"能，任何学生都可以参加。","can":[["任何"],["都","也"]]},{"kieu":"vandung","de":"A：明天的会议，不会有变化了吧？ B：＿＿＿。","goiY":"Khẳng định: sẽ không có bất kỳ thay đổi nào nữa","mau":"对，不会有任何变化了。","can":[["任何"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bất cứ lúc nào em cũng có thể gọi điện cho cô.","dap":["任何时候你都可以给我打电话。","你任何时候都可以给我打电话。"],"giai":"任何时候 + 都 + 可以."},{"kieu":"dich","vn":"Trong thư viện, bất kỳ ai cũng không được nói to.","dap":["在图书馆里，任何人都不能大声说话。","在图书馆里，任何人也不能大声说话。"],"giai":"任何人 + 都 / 也 + 不能."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu giới thiệu trường / lớp của em, có dùng 「任何……都……」","mau":"我们学校的图书馆，任何学生都可以进去看书。","can":[["任何"],["都","也"]]}]}]},{"so":"2","ten":"假设复句“要是……，就……”","tenVn":"Câu phức giả thiết 「要是……，就……」 — nếu … thì …","cauTruc":["要是 + giả thiết，(chủ ngữ) + 就 + kết quả","Chủ ngữ + 要是 + giả thiết，就 + kết quả"],"giaiThich":"Vế trước nêu GIẢ THIẾT, vế sau nói KẾT QUẢ nếu giả thiết đó thành sự thật. 「要是」 mang tính khẩu ngữ, nghĩa như 「如果」 (đã học ở HSK 3). 「就」 đứng sau chủ ngữ của vế sau, trước động từ. 「要是」 có thể đứng trước hoặc sau chủ ngữ vế đầu: 要是你明天有时间 = 你要是明天有时间.","viDu":[{"zh":"要是申请到奖学金，就能减轻不少经济压力。","py":"Yàoshi shēnqǐng dào jiǎngxuéjīn, jiù néng jiǎnqīng bùshǎo jīngjì yālì.","vn":"Nếu xin được học bổng thì có thể giảm được không ít áp lực kinh tế."},{"zh":"你要是明天有时间，就跟我一起去爬山吧。","py":"Nǐ yàoshi míngtiān yǒu shíjiān, jiù gēn wǒ yìqǐ qù páshān ba.","vn":"Nếu mai cậu có thời gian thì đi leo núi với tớ nhé."},{"zh":"要是她不愿意参加比赛，我们就再问问别人。","py":"Yàoshi tā bú yuànyì cānjiā bǐsài, wǒmen jiù zài wènwen biérén.","vn":"Nếu cô ấy không muốn tham gia cuộc thi thì chúng ta hỏi người khác xem."},{"zh":"要是没有你的帮助，我自己一定做不好这件事。","py":"Yàoshi méiyǒu nǐ de bāngzhù, wǒ zìjǐ yídìng zuò bù hǎo zhè jiàn shì.","vn":"Nếu không có sự giúp đỡ của bạn, một mình tôi nhất định không làm tốt việc này. (ôn bổ ngữ khả năng 做不好)"}],"loi":[{"sai":"要是明天下雨，我们不去公园了。","why":"Vế sau nên có 就 để nối kết quả.","dung":"要是明天下雨，我们就不去公园了。"},{"sai":"要是你明天有时间，你跟我就去吧。","why":"就 đứng sau chủ ngữ và ngay trước động từ của vế sau.","dung":"要是你明天有时间，就跟我去吧。"},{"sai":"就要是你来，我们很高兴。","why":"要是 ở vế trước, 就 ở vế sau, không đảo.","dung":"要是你来，我们就很高兴。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","申请到奖学金，就能减轻不少经济压力。"],"dap":[["要是"]],"chon":["要是","虽然","因为"],"goiY":"“Nếu xin được học bổng thì …”","giai":"要是 nêu giả thiết."},{"kieu":"dien","phan":["你要是明天有时间，","跟我一起去爬山吧。"],"dap":[["就"]],"chon":["就","才","也"],"goiY":"“… thì đi leo núi với tớ nhé.”","giai":"要是……，就……"},{"kieu":"dien","phan":["要是她不愿意参加比赛，我们","再问问别人。"],"dap":[["就"]],"chon":["就","还","都"],"goiY":"“… thì chúng ta hỏi người khác.”","giai":"就 đứng sau chủ ngữ 我们."},{"kieu":"dien","phan":["要是你饿了，我们就先去","吧。"],"dap":[["食堂"]],"chon":["食堂","签证","证件"],"goiY":"“Nếu bạn đói thì mình đi nhà ăn trước.” (ôn từ mới)","giai":"食堂 = nhà ăn."},{"kieu":"dien","phan":["","不办签证，就不能来中国留学。"],"dap":[["要是"]],"chon":["要是","一方面","随着"],"goiY":"“Nếu không làm visa thì không thể sang Trung Quốc du học.”","giai":"要是 + phủ định 不……，就不能……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["要是","明天","下雨","，","我们","就","不去了"],"dap":["要是明天下雨，我们就不去了。"],"goiY":"Nếu mai mưa thì chúng ta không đi nữa.","giai":"要是 + giả thiết，chủ ngữ + 就 + V."},{"kieu":"xep","manh":["你","要是","累了","，","就","休息","一下吧"],"dap":["你要是累了，就休息一下吧。"],"goiY":"Nếu bạn mệt rồi thì nghỉ một chút đi.","giai":"要是 đứng sau chủ ngữ 你."},{"kieu":"xep","manh":["要是","有","问题","，","就","来","找我"],"dap":["要是有问题，就来找我。"],"goiY":"Nếu có vấn đề thì đến tìm tôi.","giai":"要是……，就……"},{"kieu":"dungsai","cau":"要是你不舒服，就去看医生吧。","dung":true,"giai":"Đúng: 要是……，就……"},{"kieu":"dungsai","cau":"要是明天有时间，我们去就看电影。","dung":false,"sua":"要是明天有时间，我们就去看电影。","giai":"就 đứng trước động từ 去."},{"kieu":"dungsai","cau":"要是我有钱，我就买一辆新车。","dung":true,"giai":"Đúng: chủ ngữ 我 + 就 + V."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 5)","huongDan":"Hoàn thành câu, có dùng 要是……，就……","cau":[{"kieu":"vandung","de":"A：你不开心的时候会做什么？ B：我要是不开心，＿＿＿。","goiY":"Nói việc em sẽ làm khi buồn (就……)","mau":"就会去找朋友玩","can":[["就"]]},{"kieu":"vandung","de":"＿＿＿，咱们就去看电影。","goiY":"A rủ B: nêu điều kiện (要是……), B trả lời 「好啊，没问题。」","mau":"要是你明天有时间","can":[["要是"]]},{"kieu":"vandung","de":"A：谢谢你帮助了我。＿＿＿。 B：不客气。","goiY":"Nói: nếu không có sự giúp đỡ của bạn thì một mình tôi không làm được (要是……，……)","mau":"要是没有你的帮助，我自己一定做不好这件事","can":[["要是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Nếu xin được học bổng thì tôi sẽ học thạc sĩ ở Trung Quốc.","dap":["要是申请到奖学金，我就在中国读硕士。","要是我申请到奖学金，就在中国读硕士。"],"giai":"要是……，就…… + từ mới 申请, 奖学金, 硕士."},{"kieu":"dich","vn":"Nếu bạn không hiểu thì hỏi cô giáo đi.","dap":["要是你不懂，就问老师吧。","你要是不懂，就问老师吧。"],"giai":"要是……，就……吧."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về kế hoạch của em khi đi du học, có dùng 「要是……，就……」","mau":"要是我能去中国留学，就去北京学习中文。","can":[["要是"],["就"]]}]}]},{"so":"3","ten":"介词“随着”","tenVn":"Giới từ 「随着」 — cùng với, theo (sự thay đổi)","cauTruc":["随着 + danh từ + 的 + 发展 / 提高 / 变化，chủ ngữ + vị ngữ","随着 + câu ngắn chỉ sự thay đổi (越来越……)，……"],"giaiThich":"Sau 「随着」 thường là từ / câu ngắn biểu thị SỰ THAY ĐỔI (发展, 提高, 越来越多…). Cả cụm nêu điều kiện: vì cái này thay đổi nên việc ở vế sau mới xảy ra / thay đổi theo. Vế sau thường có 越来越, 也, 变…. Lưu ý: 随着 đứng ĐẦU câu, sau nó không phải là một hành động đơn lẻ (✗ 随着他来了).","viDu":[{"zh":"随着中国的发展，越来越多的外国学生来到中国的大学学习。","py":"Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí.","vn":"Cùng với sự phát triển của Trung Quốc, ngày càng nhiều sinh viên nước ngoài đến đại học Trung Quốc học tập."},{"zh":"随着中文水平的提高，我现在能看懂中文报纸了。","py":"Suízhe Zhōngwén shuǐpíng de tígāo, wǒ xiànzài néng kàndǒng Zhōngwén bàozhǐ le.","vn":"Cùng với trình độ tiếng Trung được nâng cao, giờ tôi đã đọc hiểu được báo tiếng Trung."},{"zh":"随着小区的环境越来越好，来这里买房子的人也变多了。","py":"Suízhe xiǎoqū de huánjìng yuèláiyuè hǎo, lái zhèli mǎi fángzi de rén yě biàn duō le.","vn":"Theo môi trường khu dân cư ngày càng tốt, người đến đây mua nhà cũng nhiều lên."},{"zh":"随着天气越来越冷，人们都穿上了厚衣服。","py":"Suízhe tiānqì yuèláiyuè lěng, rénmen dōu chuānshang le hòu yīfu.","vn":"Theo trời ngày càng lạnh, mọi người đều mặc áo dày. (ôn 越来越 – HSK 3)"}],"loi":[{"sai":"随着他来了，我们就开始上课。","why":"Sau 随着 phải là sự thay đổi, không phải một hành động đơn lẻ; nói thời điểm thì dùng ……以后 / 等……","dung":"他来了以后，我们就开始上课。"},{"sai":"随着中国发展，……","why":"Thường nói 随着 + N + 的 + 发展 / 提高.","dung":"随着中国的发展，……"},{"sai":"人们越来越关注健康，随着生活水平的提高。","why":"随着 đặt ở đầu câu, nêu điều kiện trước.","dung":"随着生活水平的提高，人们越来越关注健康。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","中国的发展，越来越多的外国学生来中国学习。"],"dap":[["随着"]],"chon":["随着","通过","除了"],"goiY":"“Cùng với sự phát triển của Trung Quốc …”","giai":"随着 + N 的发展."},{"kieu":"dien","phan":["随着中文水平的","，我现在能看懂中文报纸了。"],"dap":[["提高"]],"chon":["提高","知识","方面"],"goiY":"“Cùng với trình độ tiếng Trung nâng cao …”","giai":"随着……的提高."},{"kieu":"dien","phan":["随着天气","热，人们都换上了凉快的衣服。"],"dap":[["越来越"]],"chon":["越来越","一方面","任何"],"goiY":"“Theo trời ngày càng nóng …”","giai":"随着 + 越来越 + tính từ."},{"kieu":"dien","phan":["","这些交流，外国学生能更快地适应中国的大学生活。"],"dap":[["通过"]],"chon":["通过","随着","要是"],"goiY":"“Thông qua những giao lưu này …” (phân biệt với 随着)","giai":"通过 = nhờ/qua cách gì; 随着 = theo sự thay đổi."},{"kieu":"dien","phan":["随着来中国留学的人越来越多，中国学生和外国学生的交流","越来越多。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… giao lưu cũng ngày càng nhiều.”","giai":"Vế sau thường có 也 + 越来越."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["随着","经济","的","发展","，","人们的生活","越来越好"],"dap":["随着经济的发展，人们的生活越来越好。"],"goiY":"Cùng với kinh tế phát triển, đời sống mọi người ngày càng tốt.","giai":"随着 + N 的 + 发展，……越来越……"},{"kieu":"xep","manh":["随着","年龄","的","增长","，","他","越来越","懂事了"],"dap":["随着年龄的增长，他越来越懂事了。"],"goiY":"Cùng với tuổi tác tăng lên, cậu ấy ngày càng hiểu chuyện.","giai":"随着……的增长."},{"kieu":"dungsai","cau":"随着我到了北京，就给你打电话。","dung":false,"sua":"我到了北京以后，就给你打电话。","giai":"“Đến Bắc Kinh” là hành động, không phải sự thay đổi dần → dùng ……以后."},{"kieu":"dungsai","cau":"随着生活水平的提高，人们越来越关注身体健康。","dung":true,"giai":"Đúng: 随着……的提高，……越来越……"},{"kieu":"dungsai","cau":"人们都换上了凉快的衣服，随着天气越来越热。","dung":false,"sua":"随着天气越来越热，人们都换上了凉快的衣服。","giai":"Cụm 随着 đặt ở đầu câu."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 7)","huongDan":"Hoàn thành câu, dùng từ trong ngoặc","cau":[{"kieu":"vandung","de":"随着＿＿＿，人们越来越关注身体健康。","goiY":"Dùng từ 「提高」: mức sống nâng cao","mau":"生活水平的提高","can":[["提高"]]},{"kieu":"vandung","de":"随着来中国留学的人越来越多，＿＿＿。","goiY":"Dùng từ 「交流」: giao lưu giữa sinh viên Trung Quốc và nước ngoài cũng nhiều hơn","mau":"中国学生和外国学生的交流也越来越多","can":[["交流"]]},{"kieu":"vandung","de":"随着＿＿＿，人们都换上了凉快的衣服。","goiY":"Dùng từ 「天气」: trời ngày càng nóng","mau":"天气越来越热","can":[["天气"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cùng với sự phát triển kinh tế, ngày càng nhiều người đi du lịch nước ngoài.","dap":["随着经济的发展，越来越多的人去国外旅游。"],"giai":"随着……的发展，越来越多的……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu nói về sự thay đổi của em hoặc quê em, có dùng 「随着」","mau":"随着中文水平的提高，我交了越来越多的中国朋友。","can":[["随着"]]}]}]},{"so":"4","ten":"并列复句“一方面……，另一方面……”","tenVn":"Câu phức song song 「一方面……，另一方面……」 — một mặt …, mặt khác …","cauTruc":["一方面 + nguyên nhân / tình hình 1，另一方面 + (也) + nguyên nhân / tình hình 2"],"giaiThich":"Dùng để nói HAI MẶT (hai lý do, hai tình hình) cùng tồn tại của một sự việc. Vế sau thường thêm 「也」. Hay đi sau 因为 / 是为了 để nêu hai lý do: 一方面因为……，另一方面因为……. Hai vế nên có cấu trúc giống nhau cho cân đối.","viDu":[{"zh":"来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","py":"Láidào Zhōngguó liúxué, yìfāngmiàn shì wèile xuéxí yǔyán hé zhīshi, lìngyìfāngmiàn yě shì wèi jiānglái de gōngzuò hé shēnghuó zuò zhǔnbèi.","vn":"Đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là chuẩn bị cho công việc và cuộc sống sau này."},{"zh":"他经常在网上买东西，一方面因为便宜，另一方面因为方便。","py":"Tā jīngcháng zài wǎngshang mǎi dōngxi, yìfāngmiàn yīnwèi piányi, lìngyìfāngmiàn yīnwèi fāngbiàn.","vn":"Anh ấy hay mua đồ trên mạng, một mặt vì rẻ, mặt khác vì tiện."},{"zh":"多做运动一方面能让身体更健康，另一方面也能减轻压力。","py":"Duō zuò yùndòng yìfāngmiàn néng ràng shēntǐ gèng jiànkāng, lìngyìfāngmiàn yě néng jiǎnqīng yālì.","vn":"Tập thể dục nhiều một mặt giúp cơ thể khỏe hơn, mặt khác cũng giảm được áp lực."},{"zh":"我选这个专业，一方面是对它感兴趣，另一方面是将来好找工作。","py":"Wǒ xuǎn zhège zhuānyè, yìfāngmiàn shì duì tā gǎnxìngqù, lìngyìfāngmiàn shì jiānglái hǎo zhǎo gōngzuò.","vn":"Tôi chọn ngành này, một mặt vì có hứng thú, mặt khác vì sau này dễ tìm việc. (ôn 对……感兴趣)"}],"loi":[{"sai":"一方面便宜，一方面方便。","why":"Vế sau phải là 另一方面.","dung":"一方面便宜，另一方面方便。"},{"sai":"一方面我喜欢旅游，另一方面我。","why":"Hai vế phải đều có nội dung đầy đủ, cân đối.","dung":"一方面我喜欢旅游，另一方面我想了解中国文化。"},{"sai":"他一方面是学生，另外方面是老师。","why":"Viết 另一方面, không phải 另外方面.","dung":"他一方面是学生，另一方面也是老师。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["他经常在网上买东西，一方面因为便宜，","因为方便。"],"dap":[["另一方面"]],"chon":["另一方面","一方面","另外"],"goiY":"“… mặt khác vì tiện.”","giai":"一方面……，另一方面……"},{"kieu":"dien","phan":["多做运动一方面能让身体更健康，另一方面","能减轻压力。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… mặt khác cũng giảm được áp lực.”","giai":"Vế 另一方面 thường có 也."},{"kieu":"dien","phan":["来中国留学，","是为了学习语言，另一方面也是为将来做准备。"],"dap":[["一方面"]],"chon":["一方面","随着","要是"],"goiY":"“Một mặt là để học ngôn ngữ …”","giai":"Vế đầu dùng 一方面."},{"kieu":"dien","phan":["我想了解更多国际贸易","的知识。"],"dap":[["方面"]],"chon":["方面","知识","专业"],"goiY":"“… kiến thức về thương mại quốc tế.” (ôn từ 方面)","giai":"N + 方面的知识."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","骑车上班","，","一方面","对环境好","，","另一方面","对身体也好"],"dap":["我骑车上班，一方面对环境好，另一方面对身体也好。"],"goiY":"Tôi đạp xe đi làm, một mặt tốt cho môi trường, mặt khác cũng tốt cho sức khỏe.","giai":"一方面……，另一方面……也……"},{"kieu":"xep","manh":["学中文","一方面","为了","工作","，","另一方面","为了","了解中国文化"],"dap":["学中文一方面为了工作，另一方面为了了解中国文化。"],"goiY":"Học tiếng Trung một mặt vì công việc, mặt khác để hiểu văn hóa Trung Quốc.","giai":"Hai vế cân đối: 为了……，为了……"},{"kieu":"dungsai","cau":"他一方面是学生，另外方面是老师。","dung":false,"sua":"他一方面是学生，另一方面也是老师。","giai":"Phải là 另一方面."},{"kieu":"dungsai","cau":"我住在学校里，一方面因为便宜，另一方面因为方便。","dung":true,"giai":"Đúng: nêu hai lý do song song."},{"kieu":"dungsai","cau":"一方面天气很好，一方面我们去公园吧。","dung":false,"sua":"天气很好，我们去公园吧。","giai":"Hai vế không phải hai mặt song song của một sự việc → không dùng cấu trúc này."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 9)","huongDan":"Hoàn thành câu, dùng 一方面……，另一方面……","cau":[{"kieu":"vandung","de":"我很喜欢旅游，因为＿＿＿。","goiY":"Nêu hai lý do: được đi chơi + hiểu văn hóa","mau":"一方面可以出去玩，另一方面可以了解文化","can":[["一方面"],["另一方面"]]},{"kieu":"vandung","de":"要想学好中文，＿＿＿。","goiY":"Nêu hai việc cần làm: đọc nhiều sách tiếng Trung + giao lưu nhiều với người Trung Quốc","mau":"一方面要多读中文书，另一方面要多和中国人交流","can":[["一方面"],["另一方面"]]},{"kieu":"vandung","de":"我每天骑自行车上下班，＿＿＿。","goiY":"Nêu hai lợi ích: tốt cho môi trường + tốt cho sức khỏe","mau":"一方面对环境好，另一方面对身体也好","can":[["一方面"],["另一方面"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi chọn ngành kinh tế, một mặt vì có hứng thú, mặt khác vì sau này muốn làm thương mại quốc tế.","dap":["我选择经济专业，一方面是因为感兴趣，另一方面是因为将来想做国际贸易。","我选经济专业，一方面因为感兴趣，另一方面因为将来想做国际贸易。"],"giai":"一方面……，另一方面…… + từ mới 专业, 将来, 国际贸易."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu nói vì sao em học tiếng Trung, có dùng 「一方面……，另一方面……」","mau":"我学中文，一方面是因为喜欢中国文化，另一方面是为了将来找一个好工作。","can":[["一方面"],["另一方面"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-2.html"] = [{"so":"1","ten":"固定格式“×就是了”","tenVn":"Cấu trúc cố định 「×就是了」 — cứ … là được","cauTruc":["(Chủ ngữ) + động từ / cụm động từ + 就是了","Hay đi sau câu điều kiện: 如果 / 要是……，(Sub) + V + 就是了"],"giaiThich":"「×就是了」 dùng trong KHẨU NGỮ, đặt ở CUỐI câu để khẳng định, làm người nghe yên tâm: “cứ … là được, … thôi mà”. Chữ × là một động từ / cụm động từ (告诉我, 放心, 努力, 租下来…). Mẹo cho người Việt: khi muốn nói “cứ … là được / đừng lo, cứ … đi” thì đặt 就是了 ở cuối câu. Lưu ý: phải có 「了」 (✗ 告诉我就是); câu là câu trần thuật, không dùng làm câu hỏi; khác với 「就是」 ở giữa câu nghĩa là “chính là” (他就是房东 = ông ấy chính là chủ nhà).","viDu":[{"zh":"如果决定租了，告诉我就是了。","py":"Rúguǒ juédìng zū le, gàosu wǒ jiùshì le.","vn":"Nếu quyết định thuê thì cứ báo tôi là được."},{"zh":"我一定能办到，您放心就是了。","py":"Wǒ yídìng néng bàn dào, nín fàngxīn jiùshì le.","vn":"Tôi nhất định làm được, ông cứ yên tâm."},{"zh":"这次考得不好没关系，下次努力就是了。","py":"Zhè cì kǎo de bù hǎo méiguānxì, xià cì nǔlì jiùshì le.","vn":"Lần này thi không tốt không sao, lần sau cố gắng là được."},{"zh":"要是你不喜欢这个房间，换一个就是了。","py":"Yàoshi nǐ bù xǐhuan zhège fángjiān, huàn yí gè jiùshì le.","vn":"Nếu bạn không thích phòng này thì đổi phòng khác là được. (ôn 要是 – Bài 1 · điểm 2)"}],"loi":[{"sai":"如果决定租了，告诉我就是。","why":"Thiếu 了 — cấu trúc cố định là 「就是了」.","dung":"如果决定租了，告诉我就是了。"},{"sai":"就是了你放心。","why":"就是了 đứng ở CUỐI câu, sau động từ.","dung":"你放心就是了。"},{"sai":"你放心就是了吗？","why":"就是了 dùng để khẳng định, trấn an — không dùng trong câu hỏi.","dung":"你放心就是了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["如果决定租了，告诉我","。"],"dap":[["就是了"]],"chon":["就是了","就是","是了"],"goiY":"“Nếu quyết định thuê thì cứ báo tôi là được.”","giai":"Cấu trúc cố định: V + 就是了 (phải có 了)."},{"kieu":"dien","phan":["我一定能办到，您","就是了。"],"dap":[["放心"]],"chon":["放心","担心","关心"],"goiY":"“Tôi nhất định làm được, ông cứ yên tâm.”","giai":"放心就是了 = cứ yên tâm."},{"kieu":"dien","phan":["这次考得不好没关系，下次努力","。"],"dap":[["就是了"]],"chon":["就是了","才是了","也是了"],"goiY":"“Lần sau cố gắng là được.”","giai":"Đặt 就是了 ở cuối câu để động viên."},{"kieu":"dien","phan":["你要是满意，","下来就是了。"],"dap":[["租"]],"chon":["租","出租","房租"],"goiY":"“Bạn hài lòng thì cứ thuê luôn.” (ôn từ mới + 要是 – Bài 1)","giai":"租下来 = thuê luôn; 出租 = cho thuê; 房租 = tiền thuê."},{"kieu":"dien","phan":["房间已经","好了，你今天搬进来就是了。"],"dap":[["收拾"]],"chon":["收拾","入住","毕业"],"goiY":"“Phòng đã dọn xong, hôm nay bạn cứ dọn vào.”","giai":"收拾好了 = dọn dẹp xong."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你","要是","满意","，","租下来","就是了"],"dap":["你要是满意，租下来就是了。","要是你满意，租下来就是了。"],"goiY":"Nếu bạn hài lòng thì cứ thuê luôn đi.","giai":"要是……，V + 就是了."},{"kieu":"xep","manh":["有","任何","问题","，","给我","打电话","就是了"],"dap":["有任何问题，给我打电话就是了。"],"goiY":"Có bất kỳ vấn đề gì cứ gọi cho tôi là được.","giai":"Ôn 任何 (Bài 1) + 就是了 cuối câu."},{"kieu":"xep","manh":["不会","做","没关系","，","我","教你","就是了"],"dap":["不会做没关系，我教你就是了。"],"goiY":"Không biết làm cũng không sao, tôi dạy bạn là được.","giai":"Chủ ngữ 我 + V + 就是了."},{"kieu":"dungsai","cau":"你别担心，我明天一定来就是了。","dung":true,"giai":"Đúng: 就是了 cuối câu, trấn an người nghe."},{"kieu":"dungsai","cau":"这件衣服很漂亮，你买下来就是。","dung":false,"sua":"这件衣服很漂亮，你买下来就是了。","giai":"Thiếu 了."},{"kieu":"dungsai","cau":"就是了你下次努力。","dung":false,"sua":"你下次努力就是了。","giai":"就是了 phải đặt cuối câu."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 14)","huongDan":"Viết câu trả lời của B, có dùng 「……就是了」","cau":[{"kieu":"vandung","de":"A：这个房子很干净，小区也安静，我租不租呢？ B：＿＿＿。","goiY":"Khuyên bạn: nếu hài lòng thì cứ thuê luôn (要是……，……就是了)","mau":"你要是满意，租下来就是了","can":[["就是了"]]},{"kieu":"vandung","de":"A：这里离地铁站比较远，我怎么去好呢？ B：＿＿＿。","goiY":"Gợi ý một cách đi đơn giản: bắt taxi","mau":"打车就是了","can":[["就是了"]]},{"kieu":"vandung","de":"A：你觉得这件衣服怎么样？我要不要买？ B：我觉得很漂亮，＿＿＿。","goiY":"Khuyên bạn cứ mua luôn","mau":"买下来就是了","can":[["就是了"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Nếu bạn thích thì cứ lấy đi là được.","dap":["你要是喜欢，拿走就是了。","要是你喜欢，拿走就是了。"],"giai":"要是……，V + 就是了 (ôn Bài 1 · điểm 2)."},{"kieu":"dich","vn":"Có bất kỳ vấn đề gì, bạn cứ hỏi tôi là được.","dap":["有任何问题，你问我就是了。","你有任何问题，问我就是了。"],"giai":"任何 (Bài 1 · điểm 1) + 就是了."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em đang lo chuyện tìm nhà thuê. Hãy trấn an bạn bằng một câu có 「……就是了」","mau":"房子的事你别担心，我帮你一起找就是了。","can":[["就是了"]]}]}]},{"so":"2","ten":"转折复句“……，不过……”","tenVn":"Câu phức chuyển ngoặt 「……，不过……」 — …, có điều …","cauTruc":["Vế 1 (nhận xét / sự việc)，不过 + vế 2 (ý chuyển ngoặt, bổ sung điều khác)","Sub + Adj / V……，不过 + (Sub) + ……"],"giaiThich":"Liên từ 「不过」 đứng ở ĐẦU vế câu sau, biểu thị chuyển ngoặt: vế sau nói một điều trái với / khác với điều người nghe chờ đợi từ vế trước. So với 「但是」 (HSK 2–3), 「不过」 nhẹ nhàng, khẩu ngữ hơn — rất hay dùng khi “khen trước, góp ý sau”: 这个房间挺亮，不过有点儿小. Mẹo cho người Việt: 不过 ≈ “có điều / chỉ có điều / nhưng mà”. Lưu ý: 不过 đứng TRƯỚC chủ ngữ vế sau (✗ 他不过不想去 → ✓ 不过他不想去); hai vế phải có ý trái chiều, nếu cùng chiều thì dùng 而且 / 还.","viDu":[{"zh":"这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。","py":"Zhège xiǎoqū de huánjìng zhēn búcuò, búguò wǒ tīngshuō, fùjìn yǒu shíjǐ jiā gōngsī, hěn duō gāng bìyè de xuésheng dōu zū zhù zài zhèli.","vn":"Môi trường khu chung cư này đẹp thật, có điều tôi nghe nói gần đây có mười mấy công ty, nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây."},{"zh":"我们在动物园看见了很多动物，不过没看见大熊猫。","py":"Wǒmen zài dòngwùyuán kànjiàn le hěn duō dòngwù, búguò méi kànjiàn dàxióngmāo.","vn":"Chúng tôi thấy rất nhiều động vật ở sở thú, có điều không thấy gấu trúc."},{"zh":"我刚来北京时还不太习惯这里的天气，不过很快就适应了。","py":"Wǒ gāng lái Běijīng shí hái bú tài xíguàn zhèli de tiānqì, búguò hěn kuài jiù shìyìng le.","vn":"Mới đến Bắc Kinh tôi chưa quen thời tiết ở đây lắm, có điều rất nhanh đã thích nghi."},{"zh":"这个房子位置很好，不过房租有点儿高，要是能再便宜些就好了。","py":"Zhège fángzi wèizhì hěn hǎo, búguò fángzū yǒudiǎnr gāo, yàoshi néng zài piányi xiē jiù hǎo le.","vn":"Căn nhà này vị trí rất tốt, có điều tiền thuê hơi cao, nếu rẻ hơn chút thì tốt. (ôn 要是 – Bài 1 · điểm 2)"}],"loi":[{"sai":"不过有点儿贵，这个手机还可以。","why":"不过 đứng đầu vế SAU, không mở đầu câu.","dung":"这个手机还可以，不过有点儿贵。"},{"sai":"这个小区环境不错，不过很安静。","why":"Hai vế cùng chiều tích cực, không có ý chuyển ngoặt → dùng 而且.","dung":"这个小区环境不错，而且很安静。"},{"sai":"这个房子很大，他不过不想租。","why":"不过 là liên từ, đứng trước chủ ngữ của vế sau.","dung":"这个房子很大，不过他不想租。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["这个小区的环境真不错，","我听说，附近有十几家公司。"],"dap":[["不过"]],"chon":["不过","所以","而且"],"goiY":"“Môi trường đẹp thật, có điều nghe nói gần đây có nhiều công ty.”","giai":"Vế sau chuyển ý → 不过."},{"kieu":"dien","phan":["我们在动物园看见了很多动物，不过","看见大熊猫。"],"dap":[["没"]],"chon":["没","不","别"],"goiY":"“… có điều không thấy gấu trúc.”","giai":"Phủ định việc đã xảy ra: 没 + V."},{"kieu":"dien","phan":["我刚来北京时还不太习惯这里的天气，不过很快就","了。"],"dap":[["适应"]],"chon":["适应","交流","申请"],"goiY":"“… có điều rất nhanh đã thích nghi.” (ôn từ Bài 1)","giai":"适应 = thích nghi."},{"kieu":"dien","phan":["这个房间挺","，不过有点儿小。"],"dap":[["亮"]],"chon":["亮","租","种"],"goiY":"“Phòng này khá sáng, có điều hơi nhỏ.”","giai":"挺亮 = khá sáng (tính từ)."},{"kieu":"dien","phan":["房租不高，","离公司有点儿远。"],"dap":[["不过"]],"chon":["不过","因为","并且"],"goiY":"“Tiền thuê không cao, có điều hơi xa công ty.”","giai":"Khen trước, góp ý sau → 不过."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这个手机","还可以","，","不过","有点儿贵"],"dap":["这个手机还可以，不过有点儿贵。"],"goiY":"Chiếc điện thoại này cũng được, có điều hơi đắt.","giai":"……，不过 + ý chuyển."},{"kieu":"xep","manh":["房子","很漂亮","，","不过","周围","不太安静"],"dap":["房子很漂亮，不过周围不太安静。"],"goiY":"Nhà rất đẹp, có điều xung quanh không yên tĩnh lắm.","giai":"不过 đứng trước chủ ngữ vế sau (周围)."},{"kieu":"xep","manh":["我","很想去","，","不过","恐怕","没有时间"],"dap":["我很想去，不过恐怕没有时间。"],"goiY":"Tôi rất muốn đi, có điều e là không có thời gian.","giai":"不过 + 恐怕 (từ mới bài này)."},{"kieu":"dungsai","cau":"这个小区很安静，不过环境也很好。","dung":false,"sua":"这个小区很安静，而且环境也很好。","giai":"Hai ý cùng chiều tốt → dùng 而且, không dùng 不过."},{"kieu":"dungsai","cau":"天气预报说明天是晴天，不过可能会刮风。","dung":true,"giai":"Đúng: trời nắng (tốt) — có điều có gió (chưa tốt)."},{"kieu":"dungsai","cau":"不过他很忙，他每天都去跑步。","dung":false,"sua":"他很忙，不过每天都去跑步。","giai":"不过 đứng ở đầu vế SAU."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 16)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「不过」","cau":[{"kieu":"vandung","de":"A：你觉得这个手机怎么样？ B：还可以，不过＿＿＿。","goiY":"Nêu một điểm chưa tốt của chiếc điện thoại (ví dụ: giá)","mau":"有点儿贵"},{"kieu":"vandung","de":"A：你生病了？ B：没有，＿＿＿。","goiY":"Không ốm, có điều hơi khó chịu trong người","mau":"不过有点儿不舒服","can":[["不过"]]},{"kieu":"vandung","de":"A：我们可以走着去那里吗？ B：可以，＿＿＿。","goiY":"Đồng ý, có điều không biết có mưa không","mau":"不过不知道会不会下雨","can":[["不过"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Căn nhà này vị trí rất tốt, có điều tiền thuê hơi đắt.","dap":["这个房子位置很好，不过房租有点儿贵。","这个房子位置很好，不过房租有点儿高。"],"giai":"位置, 房租 (từ mới) + 不过."},{"kieu":"dich","vn":"Tôi rất muốn đi du lịch, có điều e là không có thời gian.","dap":["我很想去旅游，不过恐怕没有时间。","我很想去旅游，不过恐怕没时间。"],"giai":"不过 + 恐怕."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nhận xét phòng / ký túc xá của em: khen một điểm, rồi dùng 「不过」 nói một điểm chưa tốt","mau":"我的宿舍又干净又亮，不过离教室有点儿远。","can":[["不过"]]}]}]},{"so":"3","ten":"连词/副词“并”","tenVn":"Liên từ / phó từ 「并」 — và, đồng thời; hoàn toàn (không)","cauTruc":["Liên từ: V1 + O1，并 + V2 + O2 (vế sau tiến thêm một bước)","Phó từ: 并 + 不 / 没(有) + V / Adj — hoàn toàn không, chẳng hề"],"giaiThich":"「并」 có nhiều cách dùng, bài này học hai cách. (1) LIÊN TỪ: nối hai động từ hai âm tiết, hai cụm động từ hoặc hai câu ngắn song song, có ý “tiến thêm một bước” — nghĩa “và, đồng thời, rồi còn”. Thường dùng trong văn viết; chủ ngữ hai vế giống nhau nên vế sau KHÔNG lặp lại chủ ngữ. Không dùng 并 để nối hai danh từ (danh từ dùng 和). (2) PHÓ TỪ: đứng TRƯỚC từ phủ định 不 / 没, làm giọng phủ định mạnh hơn, nói rằng sự thật KHÔNG như người ta (hoặc mình) nghĩ — giống tiếng Việt “chẳng hề, đâu có, hoàn toàn không”. Mẹo: thấy 并 + 不 / 没 là có ý “phản bác”: 租房并不容易 (ai cũng tưởng dễ, thật ra chẳng dễ chút nào). Thứ tự luôn là 并不 / 并没有, không phải 不并.","viDu":[{"zh":"房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","py":"Fángdōng yòu xiàng wǒ jièshào le yíxià fángzi lǐ de dōngxi, bìng gàosu wǒ zhèxiē dōngxi zěnme yòng.","vn":"Chủ nhà lại giới thiệu cho tôi đồ đạc trong nhà, và chỉ cho tôi cách dùng."},{"zh":"她考上了北京大学并申请到了奖学金。","py":"Tā kǎoshàng le běijīngdàxué bìng shēnqǐng dào le jiǎngxuéjīn.","vn":"Cô ấy thi đỗ Đại học Bắc Kinh, lại còn xin được học bổng."},{"zh":"我并没有答应你就租这个房子，我还要再想想。","py":"Wǒ bìng méiyǒu dāying nǐ jiù zū zhège fángzi, wǒ hái yào zài xiǎngxiang.","vn":"Tôi đâu có đồng ý với bạn là thuê ngay căn nhà này, tôi còn phải nghĩ thêm. (答应 dāying = đồng ý, hứa)"},{"zh":"随着中文水平的提高，我发现学汉字并不难。","py":"Suízhe Zhōngwén shuǐpíng de tígāo, wǒ fāxiàn xué hànzì bìng bù nán.","vn":"Cùng với trình độ tiếng Trung nâng cao, tôi thấy học chữ Hán chẳng khó chút nào. (ôn 随着 – Bài 1 · điểm 3)"}],"loi":[{"sai":"我并她都是留学生。","why":"并 không nối hai danh từ; nối danh từ dùng 和.","dung":"我和她都是留学生。"},{"sai":"这次考试不并难。","why":"Phó từ 并 đứng TRƯỚC từ phủ định: 并不 / 并没有.","dung":"这次考试并不难。"},{"sai":"她考上了北京大学，并她申请到了奖学金。","why":"Hai vế cùng chủ ngữ — sau 并 không lặp lại chủ ngữ.","dung":"她考上了北京大学并申请到了奖学金。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["房东又向我介绍了一下房子里的东西，","告诉我这些东西怎么用。"],"dap":[["并"]],"chon":["并","和","跟"],"goiY":"“… và chỉ cho tôi cách dùng.”","giai":"Nối hai cụm động từ → 并 (和 nối danh từ)."},{"kieu":"dien","phan":["对白家月来说，这次租房并","容易。"],"dap":[["不"]],"chon":["不","没","很"],"goiY":"“… lần thuê nhà này chẳng hề dễ.”","giai":"并不 + tính từ."},{"kieu":"dien","phan":["她考上了北京大学并申请到了","。"],"dap":[["奖学金"]],"chon":["奖学金","房租","工资"],"goiY":"“… và xin được học bổng.” (ôn từ Bài 1)","giai":"申请到 + 奖学金."},{"kieu":"dien","phan":["我","没有答应你就租这个房子，我还要再想想。"],"dap":[["并"]],"chon":["并","也","就"],"goiY":"“Tôi đâu có đồng ý thuê ngay …”","giai":"并没有 = phủ định mạnh, phản bác."},{"kieu":"dien","phan":["学汉字","不难，多写多练就是了。"],"dap":[["并"]],"chon":["并","和","还"],"goiY":"“Học chữ Hán chẳng khó, cứ viết nhiều luyện nhiều là được.” (ôn 就是了 – điểm 1)","giai":"并不难 = chẳng khó chút nào."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","毕业后","来北京工作","，","并","在公司附近","租了个房子"],"dap":["他毕业后来北京工作，并在公司附近租了个房子。"],"goiY":"Tốt nghiệp xong anh ấy đến Bắc Kinh làm việc, và thuê một căn nhà gần công ty.","giai":"V1……，并 + V2……"},{"kieu":"xep","manh":["这个","小区","并","不","安静"],"dap":["这个小区并不安静。"],"goiY":"Khu chung cư này chẳng yên tĩnh chút nào.","giai":"并不 + Adj."},{"kieu":"xep","manh":["我们","讨论了","这个问题","，","并","做出了","决定"],"dap":["我们讨论了这个问题，并做出了决定。"],"goiY":"Chúng tôi đã thảo luận vấn đề này và đưa ra quyết định.","giai":"Hai hành động nối tiếp, cùng chủ ngữ."},{"kieu":"dungsai","cau":"我买了苹果并香蕉。","dung":false,"sua":"我买了苹果和香蕉。","giai":"并 không nối hai danh từ."},{"kieu":"dungsai","cau":"其实这个问题并不难。","dung":true,"giai":"Đúng: 并不 phản bác suy nghĩ “khó”."},{"kieu":"dungsai","cau":"在北京租房子不并容易。","dung":false,"sua":"在北京租房子并不容易。","giai":"Thứ tự đúng: 并不."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 18)","huongDan":"Hoàn thành câu, dùng 「并」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"他毕业后来到北京工作，＿＿＿。（租）","goiY":"Nói thêm việc thứ hai: thuê nhà gần công ty","mau":"并在公司附近租了个房子","can":[["并"],["租"]]},{"kieu":"vandung","de":"我吃完饭＿＿＿后，才去公园跑步。（收拾）","goiY":"Ăn xong và dọn bếp xong","mau":"并收拾好厨房","can":[["并"],["收拾"]]},{"kieu":"vandung","de":"她＿＿＿这个小区，这里人太多，她不喜欢。（入住）","goiY":"Cô ấy chẳng hề muốn dọn vào khu này","mau":"并不想入住","can":[["并"],["入住"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cô ấy tìm được việc làm và thuê một căn nhà gần công ty.","dap":["她找到了工作，并在公司附近租了一个房子。","她找到了工作，并在公司附近租了个房子。","她找到了工作并在公司附近租了一个房子。"],"giai":"并 nối hai hành động, không lặp chủ ngữ."},{"kieu":"dich","vn":"Thực ra thuê nhà ở Bắc Kinh chẳng hề rẻ.","dap":["其实在北京租房子并不便宜。","其实在北京租房并不便宜。"],"giai":"并不 + Adj: phản bác suy nghĩ “rẻ”."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Phản bác một suy nghĩ sai về việc học tiếng Trung, dùng 「并不 / 并没有」","mau":"很多人觉得汉字很难，其实汉字并不难，多写多练就是了。","can":[["并"]]}]}]},{"so":"4","ten":"连词/介词“由于”","tenVn":"Liên từ / giới từ 「由于」 — do, bởi vì","cauTruc":["Liên từ: 由于 + nguyên nhân，所以 / 因此 + kết quả","Giới từ: 由于 + danh từ (cụm danh từ)，+ kết quả"],"giaiThich":"「由于」 có hai cách dùng. (1) LIÊN TỪ: đặt ở ĐẦU vế trước của câu phức để nêu NGUYÊN NHÂN; vế sau thường mở đầu bằng 「所以」 hoặc 「因此」 (yīncǐ, vì vậy). (2) GIỚI TỪ: 由于 + danh từ, nêu nguyên nhân / lý do: 由于大家的努力 (nhờ sự nỗ lực của mọi người). So với 「因为」 (HSK 2), 「由于」 trang trọng hơn, hay gặp trong văn viết, tin tức. Mẹo cho người Việt: 由于 thường đứng vế TRƯỚC (✗ ……，由于…… → ✓ 由于……，所以……; muốn đặt nguyên nhân ở sau thì dùng ……，是因为……). Không dùng 但是 / 虽然 với 由于 (đó là quan hệ nhượng bộ, không phải nhân quả).","viDu":[{"zh":"在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","py":"Zài Zhōngguó, yóuyú hěn duō gāng gōngzuò de niánqīngrén gōngzī hái bú tài gāo, suǒyǐ tāmen yì kāishǐ yě bù mǎi fáng, dōu xuǎnzé zū fáng.","vn":"Ở Trung Quốc, do nhiều người trẻ mới đi làm lương còn chưa cao lắm, nên lúc đầu họ cũng không mua nhà mà đều chọn thuê nhà."},{"zh":"由于一直下大雨，所以我们决定不爬山了。","py":"Yóuyú yìzhí xià dàyǔ, suǒyǐ wǒmen juédìng bù páshān le.","vn":"Do trời mưa to suốt, nên chúng tôi quyết định không leo núi nữa."},{"zh":"由于大家的努力，这次运动会我们班获得了第一名。","py":"Yóuyú dàjiā de nǔlì, zhè cì yùndònghuì wǒmen bān huòdé le dì yì míng.","vn":"Nhờ sự nỗ lực của mọi người, đại hội thể thao lần này lớp ta giành giải nhất."},{"zh":"由于申请到了奖学金，她减轻了不少经济压力。","py":"Yóuyú shēnqǐng dào le jiǎngxuéjīn, tā jiǎnqīng le bùshǎo jīngjì yālì.","vn":"Do xin được học bổng, cô ấy giảm được không ít áp lực kinh tế. (ôn 申请, 奖学金, 减轻 – Bài 1)"}],"loi":[{"sai":"我们决定不爬山了，由于一直下大雨。","why":"由于 thường đứng ở vế TRƯỚC; vế sau dùng 所以 / 因此.","dung":"由于一直下大雨，所以我们决定不爬山了。"},{"sai":"由于下雨，但是我们没去公园。","why":"由于 (nhân quả) không đi với 但是 (chuyển ngoặt).","dung":"由于下雨，所以我们没去公园。"},{"sai":"由于他生病了，因为他没来上课。","why":"Vế sau dùng 所以 / 因此, không dùng 因为.","dung":"由于他生病了，所以他没来上课。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","一直下大雨，所以我们决定不爬山了。"],"dap":[["由于"]],"chon":["由于","虽然","要是"],"goiY":"“Do trời mưa to suốt, nên …”","giai":"由于……，所以…… (nhân quả)."},{"kieu":"dien","phan":["由于很多刚工作的年轻人工资还不太高，","他们一开始也不买房。"],"dap":[["所以"]],"chon":["所以","但是","而且"],"goiY":"“… nên lúc đầu họ cũng không mua nhà.”","giai":"Vế sau của 由于 dùng 所以 / 因此."},{"kieu":"dien","phan":["由于大家的","，这次运动会我们班获得了第一名。"],"dap":[["努力"]],"chon":["努力","房租","位置"],"goiY":"“Nhờ sự nỗ lực của mọi người …”","giai":"Giới từ: 由于 + danh từ."},{"kieu":"dien","phan":["由于这个小区很安静，房子价格也不高，","，很多人都喜欢在这里租房子。"],"dap":[["因此"]],"chon":["因此","不过","并"],"goiY":"“… vì vậy nhiều người thích thuê nhà ở đây.”","giai":"由于……，因此…… (因此 yīncǐ = vì vậy)."},{"kieu":"dien","phan":["由于新公司离她住的地方比较远，她决定在公司","租个房子。"],"dap":[["附近"]],"chon":["附近","价格","信息"],"goiY":"“… cô ấy quyết định thuê nhà gần công ty.”","giai":"在 + nơi + 附近 = ở gần …"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["由于","手机","没电了","，","她","没有办法","打电话"],"dap":["由于手机没电了，她没有办法打电话。"],"goiY":"Do điện thoại hết pin, cô ấy không có cách nào gọi điện.","giai":"由于 + nguyên nhân，kết quả."},{"kieu":"xep","manh":["由于","工资","不太高","，","所以","他","选择租房"],"dap":["由于工资不太高，所以他选择租房。"],"goiY":"Do lương không cao lắm nên anh ấy chọn thuê nhà.","giai":"由于……，所以……"},{"kieu":"xep","manh":["由于","大家的","帮助","，","我们","很快就","完成了工作"],"dap":["由于大家的帮助，我们很快就完成了工作。"],"goiY":"Nhờ sự giúp đỡ của mọi người, chúng tôi đã nhanh chóng hoàn thành công việc.","giai":"Giới từ: 由于 + cụm danh từ."},{"kieu":"dungsai","cau":"由于天气不好，所以飞机晚到了两个小时。","dung":true,"giai":"Đúng: 由于……，所以……"},{"kieu":"dungsai","cau":"由于下雨，但是比赛没有停。","dung":false,"sua":"虽然下雨，但是比赛没有停。","giai":"Đây là quan hệ nhượng bộ → 虽然……但是……; 由于 chỉ nguyên nhân."},{"kieu":"dungsai","cau":"我没去上课，由于我生病了。","dung":false,"sua":"由于我生病了，所以没去上课。","giai":"由于 đứng ở vế trước."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 20)","huongDan":"Hoàn thành câu có 「由于」","cau":[{"kieu":"vandung","de":"由于手机没电了，＿＿＿。","goiY":"Nói kết quả: không gọi điện được","mau":"她没有办法打电话"},{"kieu":"vandung","de":"由于这个小区很安静，房子价格也不高，因此，＿＿＿。","goiY":"Nói kết quả: nhiều người thích thuê nhà ở đây","mau":"很多人都喜欢在这里租房子"},{"kieu":"vandung","de":"＿＿＿，我们很快就完成了这个工作。","goiY":"Nêu nguyên nhân bằng giới từ 由于 + danh từ: nhờ sự nỗ lực của mọi người","mau":"由于大家的努力","can":[["由于"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Do lương còn chưa cao nên nhiều người trẻ chọn thuê nhà.","dap":["由于工资还不太高，所以很多年轻人选择租房。","由于工资还不高，所以很多年轻人选择租房。","由于工资还不太高，很多年轻人选择租房。"],"giai":"由于……，所以…… + từ mới 工资."},{"kieu":"dich","vn":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp.","dap":["由于李文的帮助，白家月租到了合适的房子。"],"giai":"Giới từ: 由于 + cụm danh từ."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giải thích vì sao em chọn ở ký túc xá / thuê nhà / ở nhà, dùng 「由于……，所以 / 因此……」","mau":"由于学校宿舍离教室很近，房租也不高，所以我选择住在宿舍。","can":[["由于"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-3.html"] = [{"so":"1","ten":"转折复句“……×是×，就是/不过……”","tenVn":"Câu phức chuyển ngoặt 「×是×，就是 / 不过……」 — … thì … thật, nhưng / chỉ là …","cauTruc":["(Chủ ngữ) + A + 是 + A，就是 / 不过 + mặt hạn chế","A là tính từ (大是大), động từ (想是想了) hoặc cụm động từ (写完是写完了)"],"giaiThich":"「×是×」 là khung cố định: lặp lại CÙNG MỘT TỪ ở hai bên 是 để THỪA NHẬN một tình hình / đặc điểm (“to thì to thật”, “rẻ thì rẻ thật”). Vế sau dùng 「就是」 hoặc 「不过」 (đã học ở Bài 2) để chuyển ý hoặc bổ sung, chỉ ra mặt hạn chế của vế trước. Người Việt nói “… thì … thật, nhưng mà / có điều …” → tiếng Trung: A是A，就是 / 不过……. Lưu ý: 1) 就是 ở đây = “chỉ là, có điều” (không phải “chính là”); 2) hai bên 是 giống hệt nhau, KHÔNG thêm 很 / 非常; 3) nếu có 了 thì đặt ở cuối: 想是想了 / 写完是写完了.","viDu":[{"zh":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。","py":"Běijīng dà shì dà, búguò zhèbiān de lù jīběn shàng dōu shì zhèng nán zhèng běi, zhèng dōng zhèng xī de, hěn hǎo zhǎo.","vn":"Bắc Kinh rộng thì rộng thật, nhưng đường bên này hầu như đều theo hướng chính Nam – Bắc, chính Đông – Tây, rất dễ tìm."},{"zh":"这个房子便宜是便宜，就是离我的公司太远了。","py":"Zhège fángzi piányi shì piányi, jiùshì lí wǒ de gōngsī tài yuǎn le.","vn":"Căn nhà này rẻ thì rẻ thật, chỉ là cách công ty tôi xa quá."},{"zh":"我们想是想了，就是没想出更好的办法。","py":"Wǒmen xiǎng shì xiǎng le, jiùshì méi xiǎngchū gèng hǎo de bànfǎ.","vn":"Chúng tôi nghĩ thì có nghĩ rồi, chỉ là không nghĩ ra cách nào tốt hơn."},{"zh":"这个房子大是大，就是离地铁站太远，我并不想租。","py":"Zhège fángzi dà shì dà, jiùshì lí dìtiězhàn tài yuǎn, wǒ bìng bù xiǎng zū.","vn":"Căn nhà này rộng thì rộng thật, có điều xa ga tàu điện ngầm quá, tôi hoàn toàn không muốn thuê. (ôn 并不 – Bài 2 · điểm 3, chủ đề thuê nhà)"}],"loi":[{"sai":"北京大是很大，不过路很好找。","why":"Hai bên 是 phải là cùng một từ, không thêm 很 vào sau 是.","dung":"北京大是大，不过路很好找。"},{"sai":"这个房子便宜是便宜，所以离公司太远了。","why":"Vế sau phải mang ý chuyển ngoặt (就是 / 不过 / 但是), không dùng 所以.","dung":"这个房子便宜是便宜，就是离公司太远了。"},{"sai":"我们想了是想，就是没想出好办法。","why":"Có 了 thì 了 đứng ở cuối khung: 想是想了.","dung":"我们想是想了，就是没想出好办法。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["北京大是","，不过这边的路基本上都是正南正北的。"],"dap":[["大"]],"chon":["大","很大","太大"],"goiY":"“Bắc Kinh to thì to thật, nhưng …”","giai":"Hai bên 是 lặp lại đúng một từ: 大是大."},{"kieu":"dien","phan":["这个房子便宜是便宜，","离我的公司太远了。"],"dap":[["就是"]],"chon":["就是","所以","因为"],"goiY":"“Căn nhà này rẻ thì rẻ thật, chỉ là cách công ty xa quá.”","giai":"Vế sau dùng 就是 / 不过 chỉ ra hạn chế."},{"kieu":"dien","phan":["我们想是","了，就是没想出更好的办法。"],"dap":[["想"]],"chon":["想","想想","想到"],"goiY":"“Chúng tôi nghĩ thì có nghĩ rồi …”","giai":"想是想了 — 了 ở cuối khung."},{"kieu":"dien","phan":["网购方便是方便，就是容易","花钱。"],"dap":[["乱"]],"chon":["乱","正","直接"],"goiY":"“… chỉ là dễ tiêu tiền lung tung.” (ôn từ mới)","giai":"乱花钱 = tiêu tiền lung tung."},{"kieu":"dien","phan":["凉快是凉快了，","夏天还没结束，过几天又会热起来了。"],"dap":[["不过"]],"chon":["不过","于是","甚至"],"goiY":"“Mát thì mát rồi, có điều mùa hè chưa hết …”","giai":"×是×，不过……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这件衣服","好看","是","好看","，","就是","有点儿贵"],"dap":["这件衣服好看是好看，就是有点儿贵。"],"goiY":"Cái áo này đẹp thì đẹp thật, chỉ là hơi đắt.","giai":"A是A，就是……"},{"kieu":"xep","manh":["这个软件","方便","是","方便","，","不过","我还不太会用"],"dap":["这个软件方便是方便，不过我还不太会用。"],"goiY":"Phần mềm này tiện thì tiện thật, nhưng tôi vẫn chưa biết dùng lắm.","giai":"A是A，不过……"},{"kieu":"xep","manh":["作业","写完","是","写完了","，","不过","有的题","不会写"],"dap":["作业写完是写完了，不过有的题不会写。"],"goiY":"Bài tập viết xong thì viết xong rồi, nhưng có câu không biết làm.","giai":"Cụm động từ: 写完是写完了."},{"kieu":"dungsai","cau":"北京大是很大，不过路很好找。","dung":false,"sua":"北京大是大，不过路很好找。","giai":"Hai bên 是 giống hệt nhau, không thêm 很."},{"kieu":"dungsai","cau":"这家饭馆的菜好吃是好吃，就是价格有点儿高。","dung":true,"giai":"Đúng: A是A，就是……"},{"kieu":"dungsai","cau":"我累是累，所以还想再学一会儿。","dung":false,"sua":"我累是累，不过还想再学一会儿。","giai":"Vế sau là chuyển ngoặt → 不过 / 就是, không dùng 所以."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 25)","huongDan":"Hoàn thành câu trả lời của B, dùng 「×是×，就是 / 不过……」","cau":[{"kieu":"vandung","de":"A：你们那里凉快了吧？ B：＿＿＿，不过夏天还没结束，过几天又会热起来了。","goiY":"Thừa nhận trời đã mát rồi (凉快是凉快了)","mau":"凉快是凉快了","can":[["凉快是凉快"]]},{"kieu":"vandung","de":"A：网购真是太方便了！ B：方便是方便，＿＿＿。","goiY":"Nêu mặt hạn chế của mua online: dễ tiêu tiền lung tung (就是……)","mau":"就是容易乱花钱","can":[["就是","不过"]]},{"kieu":"vandung","de":"A：你们的作业写完了吗？ B：＿＿＿，＿＿＿。","goiY":"Viết xong thì viết xong rồi, nhưng có câu không biết làm","mau":"写完是写完了，不过有的题不会写","can":[["写完是写完了"],["不过","就是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Điện thoại này đẹp thì đẹp thật, chỉ là hơi đắt.","dap":["这个手机好看是好看，就是有点儿贵。","这个手机漂亮是漂亮，就是有点儿贵。","这个手机好看是好看，不过有点儿贵。"],"giai":"A是A，就是 / 不过……"},{"kieu":"dich","vn":"Tôi muốn đi thì muốn thật, có điều hôm nay không có thời gian.","dap":["我想去是想去，不过今天没有时间。","我想去是想去，就是今天没有时间。","我想去是想去，不过今天没时间。"],"giai":"Cụm động từ 想去是想去."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói ưu điểm và nhược điểm của thanh toán bằng điện thoại / mua online, có dùng 「×是×，就是 / 不过……」","mau":"手机支付快是快，就是手机没电的时候就不能用了。","can":[["是"],["就是","不过"]]}]}]},{"so":"2","ten":"递进复句“不仅/不光……，还/而且……”","tenVn":"Câu phức tăng tiến 「不仅 / 不光……，还 / 而且……」 — không những … mà còn …","cauTruc":["Chủ ngữ + 不仅 / 不光 + A，还 / 而且 + B","Hai vế cùng một chủ ngữ: chủ ngữ đứng TRƯỚC 不仅"],"giaiThich":"「不仅 / 不光 (bùguāng) ……，还 / 而且……」 biểu thị quan hệ tăng tiến: vế sau là phần mở rộng, bổ sung cho vế trước, ý nghĩa tiến thêm một bước. Bài này học loại câu CÙNG MỘT CHỦ NGỮ: chủ ngữ + 不仅……，还 / 而且……. 不光 mang tính khẩu ngữ hơn 不仅. Vị trí: 还 đứng ngay trước động từ / tính từ của vế sau; 而且 đứng đầu vế sau, có thể thêm 也 / 还 (而且……也……). Cùng nghĩa với 不但……而且…… đã học ở HSK 3. Mẹo cho người Việt: “không những … mà còn …” — tuyệt đối không ghép 不仅 với 但是.","viDu":[{"zh":"现在我不仅会扫码结账，还会用手机在网上购物了。","py":"Xiànzài wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì yòng shǒujī zài wǎngshang gòuwù le.","vn":"Giờ tôi không những biết quét mã thanh toán, mà còn biết dùng điện thoại mua hàng trên mạng nữa."},{"zh":"王老师不光教我们说中文，而且带我们了解中国文化。","py":"Wáng lǎoshī bùguāng jiào wǒmen shuō Zhōngwén, érqiě dài wǒmen liǎojiě Zhōngguó wénhuà.","vn":"Thầy Vương không những dạy chúng tôi nói tiếng Trung, mà còn đưa chúng tôi tìm hiểu văn hóa Trung Quốc."},{"zh":"现在很多书店不仅卖书，还卖咖啡和奶茶。","py":"Xiànzài hěn duō shūdiàn bùjǐn mài shū, hái mài kāfēi hé nǎichá.","vn":"Bây giờ nhiều hiệu sách không những bán sách, mà còn bán cà phê và trà sữa."},{"zh":"由于手机支付很方便，现在我不仅不带现金，而且连钱包也不带了。","py":"Yóuyú shǒujī zhīfù hěn fāngbiàn, xiànzài wǒ bùjǐn bú dài xiànjīn, érqiě lián qiánbāo yě bú dài le.","vn":"Vì thanh toán bằng điện thoại rất tiện, giờ tôi không những không mang tiền mặt, mà ngay cả ví cũng không mang nữa. (ôn 由于 – Bài 2 · điểm 4; 连……也…… – HSK 3)"}],"loi":[{"sai":"不仅我会说中文，还会写汉字。","why":"Hai vế cùng chủ ngữ thì chủ ngữ đứng trước 不仅.","dung":"我不仅会说中文，还会写汉字。"},{"sai":"他不仅会唱歌，而且会跳舞还。","why":"还 phải đứng trước động từ, không đứng cuối câu.","dung":"他不仅会唱歌，还会跳舞。"},{"sai":"这家店不仅便宜，但是东西很好。","why":"不仅 đi với 还 / 而且 / 也, không đi với 但是.","dung":"这家店不仅便宜，而且东西很好。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["现在我","会扫码结账，还会用手机在网上购物了。"],"dap":[["不仅"]],"chon":["不仅","虽然","要是"],"goiY":"“Giờ tôi không những biết quét mã thanh toán …”","giai":"不仅……，还……"},{"kieu":"dien","phan":["王老师不光教我们说中文，","带我们了解中国文化。"],"dap":[["而且"]],"chon":["而且","但是","所以"],"goiY":"“… mà còn đưa chúng tôi tìm hiểu văn hóa.”","giai":"不光……，而且……"},{"kieu":"dien","phan":["现在很多书店不仅卖书，","卖咖啡和奶茶。"],"dap":[["还"]],"chon":["还","就","才"],"goiY":"“… mà còn bán cà phê và trà sữa.”","giai":"还 đứng ngay trước động từ 卖."},{"kieu":"dien","phan":["这个软件不仅能支付，还能","快递。"],"dap":[["寄"]],"chon":["寄","管","转"],"goiY":"“… mà còn gửi được chuyển phát nhanh.” (ôn từ mới)","giai":"寄快递 = gửi chuyển phát nhanh."},{"kieu":"dien","phan":["在中国网购，不仅选择多、价格不高，","送货很快。"],"dap":[["而且"]],"chon":["而且","于是","不过"],"goiY":"“… mà giao hàng còn nhanh.”","giai":"不仅……，而且……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["她","不仅","会唱","中文歌","，","而且","唱得很好"],"dap":["她不仅会唱中文歌，而且唱得很好。"],"goiY":"Cô ấy không những biết hát bài tiếng Trung, mà còn hát rất hay.","giai":"Chủ ngữ + 不仅……，而且……"},{"kieu":"xep","manh":["我","不仅","会","扫码结账","，","还","会","网购"],"dap":["我不仅会扫码结账，还会网购。"],"goiY":"Tôi không những biết quét mã thanh toán, mà còn biết mua online.","giai":"还 + 会 + V."},{"kieu":"xep","manh":["这家饭馆","不光","菜好吃","，","而且","价格","也不高"],"dap":["这家饭馆不光菜好吃，而且价格也不高。"],"goiY":"Quán này không những món ngon mà giá cũng không cao.","giai":"而且……也……"},{"kieu":"dungsai","cau":"不仅他会说中文，还会说英文。","dung":false,"sua":"他不仅会说中文，还会说英文。","giai":"Cùng chủ ngữ → chủ ngữ đứng trước 不仅."},{"kieu":"dungsai","cau":"现在很多书店不仅卖书，还卖咖啡和奶茶。","dung":true,"giai":"Đúng: chủ ngữ + 不仅……，还……"},{"kieu":"dungsai","cau":"她不仅很漂亮，但是很聪明。","dung":false,"sua":"她不仅很漂亮，而且很聪明。","giai":"不仅 đi với 而且 / 还, không đi với 但是."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 27)","huongDan":"Hoàn thành đối thoại, dùng 「不仅 / 不光……，还 / 而且……」","cau":[{"kieu":"vandung","de":"A：她中文怎么说得这么好了？ B：她不仅每天认真听课，＿＿＿。","goiY":"Nói thêm: về nhà ngày nào cũng ôn bài (而且……)","mau":"而且每天回去都复习","can":[["而且","还"]]},{"kieu":"vandung","de":"A：你妹妹一年前就开始学唱中文歌，现在已经会唱了吧？ B：她＿＿＿，而且唱得很好。","goiY":"Không những biết hát rồi (不仅……)","mau":"不仅会唱了","can":[["不仅","不光"]]},{"kieu":"vandung","de":"A：你们都去看了这个电影，觉得怎么样？ B：＿＿＿，＿＿＿。","goiY":"Phim không những có nhiều người nổi tiếng mà câu chuyện cũng rất hay","mau":"这个电影里不仅有很多名人，而且故事也很好","can":[["不仅","不光"],["而且","还"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Thanh toán bằng điện thoại không những nhanh mà còn rất tiện.","dap":["用手机支付不仅很快，而且很方便。","手机支付不仅很快，还很方便。","用手机支付不仅快，而且很方便。"],"giai":"不仅……，而且 / 还……"},{"kieu":"dich","vn":"Cậu ấy không những giúp tôi tải WeChat, mà còn dạy tôi cách dùng.","dap":["他不仅帮我下载了微信，还教我怎么用。","他不仅帮我下载了微信，还教了我怎么用。","他不仅帮我下载了微信，而且教我怎么用。"],"giai":"Chủ ngữ 他 đứng trước 不仅."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu giới thiệu những việc chiếc điện thoại của em làm được, có dùng 「不仅……，还 / 而且……」","mau":"我的手机不仅能打电话，还能扫码支付和网购。","can":[["不仅","不光"],["还","而且"]]}]}]},{"so":"3","ten":"连词“甚至”","tenVn":"Liên từ 「甚至」 — thậm chí, ngay cả","cauTruc":["……，(chủ ngữ) + 甚至 + V / câu ngắn","A、B，甚至 + (还) + C — C là điều bất ngờ nhất","甚至 + 连……都 / 也……"],"giaiThich":"Liên từ 「甚至」 nhấn mạnh một tình huống còn nổi bật hơn, vượt ngoài dự đoán thông thường — tiếng Việt là “thậm chí, ngay cả”. Thường đặt ở vế sau, ngay trước phần được nhấn mạnh; hay đi với 还, 都, 也, 连……都……. Khi liệt kê, 甚至 đứng trước mục cuối cùng — mục “bất ngờ” nhất (có vườn hoa, sân bóng, thậm chí còn có siêu thị). Mẹo: phần sau 甚至 phải “hơn” phần trước một bậc; nếu hai phần ngang nhau thì chỉ dùng 还 / 也. 甚至 không mở đầu câu đơn lẻ — phía trước phải có phần làm nền.","viDu":[{"zh":"在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","py":"Zài Zhōngguó wǎnggòu, bùjǐn xuǎnzé duō, jiàgé bù gāo, érqiě sònghuò hěn kuài, hěn duō liúxuéshēng shènzhì gǎibiàn le zìjǐ de gòuwù xíguàn.","vn":"Mua online ở Trung Quốc không những nhiều lựa chọn, giá không cao mà giao hàng còn nhanh, nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"zh":"高铁速度真快，甚至还没看清楚，它就已经开过去了。","py":"Gāotiě sùdù zhēn kuài, shènzhì hái méi kàn qīngchu, tā jiù yǐjīng kāi guòqu le.","vn":"Tàu cao tốc nhanh thật, thậm chí còn chưa nhìn rõ thì nó đã chạy qua rồi."},{"zh":"这个小区真不错，有小花园、球场，甚至还有一个超市。","py":"Zhège xiǎoqū zhēn búcuò, yǒu xiǎo huāyuán, qiúchǎng, shènzhì hái yǒu yí gè chāoshì.","vn":"Khu dân cư này thật không tệ, có vườn hoa nhỏ, sân bóng, thậm chí còn có một siêu thị."},{"zh":"随着网络的发展，现在甚至连买菜都可以在网上买了。","py":"Suízhe wǎngluò de fāzhǎn, xiànzài shènzhì lián mǎi cài dōu kěyǐ zài wǎngshang mǎi le.","vn":"Cùng với sự phát triển của Internet, giờ thậm chí ngay cả mua rau cũng mua được trên mạng. (ôn 随着 – Bài 1 · điểm 3)"}],"loi":[{"sai":"甚至在中国网购很方便。","why":"甚至 không mở đầu một câu đơn lẻ; phía trước phải có phần làm nền.","dung":"在中国网购很方便，甚至动动手指就能买到想要的东西。"},{"sai":"他很忙，甚至吃饭。","why":"Sau 甚至 phải là một tình huống đầy đủ, mức độ cao hơn phần trước.","dung":"他很忙，甚至连吃饭的时间都没有。"},{"sai":"他甚至没吃午饭，也没吃早饭。","why":"Phần “bất ngờ hơn” đặt SAU 甚至, ở vế sau.","dung":"他没吃早饭，甚至连午饭也没吃。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["在中国网购，送货很快，很多留学生","改变了自己的购物习惯。"],"dap":[["甚至"]],"chon":["甚至","不仅","于是"],"goiY":"“… nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm.”","giai":"甚至 + V: nhấn mạnh điều vượt dự đoán."},{"kieu":"dien","phan":["高铁速度真快，","还没看清楚，它就已经开过去了。"],"dap":[["甚至"]],"chon":["甚至","虽然","要是"],"goiY":"“Tàu cao tốc nhanh thật, thậm chí chưa nhìn rõ …”","giai":"甚至 đứng trước phần được nhấn mạnh."},{"kieu":"dien","phan":["这个小区真不错，有小花园、球场，甚至","有一个超市。"],"dap":[["还"]],"chon":["还","就","才"],"goiY":"“… thậm chí còn có một siêu thị.”","giai":"甚至还 + 有……"},{"kieu":"dien","phan":["他太忙了，甚至","吃饭的时间都没有。"],"dap":[["连"]],"chon":["连","把","被"],"goiY":"“… thậm chí ngay cả thời gian ăn cơm cũng không có.”","giai":"甚至连……都……"},{"kieu":"dien","phan":["这家咖啡店很有名，甚至很多","都会来喝咖啡。"],"dap":[["名人"]],"chon":["名人","手指","现金"],"goiY":"“… thậm chí nhiều người nổi tiếng cũng đến uống.”","giai":"名人 = người nổi tiếng."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","太了解我了","，","甚至","我还没说话","，","他就知道","我想做什么"],"dap":["他太了解我了，甚至我还没说话，他就知道我想做什么。"],"goiY":"Anh ấy hiểu tôi quá, thậm chí tôi chưa nói anh ấy đã biết tôi muốn làm gì.","giai":"甚至 + câu ngắn (还没……就……)."},{"kieu":"xep","manh":["这个小区","有小花园、球场","，","甚至","还有","一个超市"],"dap":["这个小区有小花园、球场，甚至还有一个超市。"],"goiY":"Khu này có vườn hoa, sân bóng, thậm chí còn có một siêu thị.","giai":"Liệt kê: 甚至 trước mục cuối."},{"kieu":"xep","manh":["他","忙得","甚至","连饭","都","忘了吃"],"dap":["他忙得甚至连饭都忘了吃。"],"goiY":"Anh ấy bận đến mức thậm chí quên cả ăn cơm.","giai":"V得 + 甚至连……都……"},{"kieu":"dungsai","cau":"甚至在中国寄快递很快。","dung":false,"sua":"在中国寄快递特别快，甚至上午寄出下午就收到了。","giai":"甚至 không mở đầu câu; phần sau 甚至 phải vượt dự đoán."},{"kieu":"dungsai","cau":"他中文说得很好，甚至能看懂中文报纸。","dung":true,"giai":"Đúng: đọc hiểu báo là mức cao hơn nói tốt."},{"kieu":"dungsai","cau":"他每天起得很早，甚至七点起床。","dung":false,"sua":"他每天起得很早，甚至五点就起床了。","giai":"Phần sau 甚至 phải nổi bật hơn hẳn; 7 giờ không “sớm” đến mức bất ngờ, thêm 就……了 nhấn mạnh."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 29)","huongDan":"Hoàn thành câu với 「甚至」, dùng từ trong ngoặc","cau":[{"kieu":"vandung","de":"＿＿＿，＿＿＿上午寄出下午就收到了。（快递）","goiY":"Dùng từ 「快递」: ở Trung Quốc gửi chuyển phát nhanh rất nhanh, thậm chí …","mau":"在中国寄快递特别快，甚至","can":[["快递"],["甚至"]]},{"kieu":"vandung","de":"这家咖啡店很有名，＿＿＿。（名人）","goiY":"Dùng từ 「名人」: thậm chí nhiều người nổi tiếng cũng đến uống cà phê","mau":"甚至很多名人都会来喝咖啡","can":[["甚至"],["名人"]]},{"kieu":"vandung","de":"他太了解我了，＿＿＿，他就知道我想做什么。（说话）","goiY":"Dùng từ 「说话」: thậm chí tôi còn chưa nói gì","mau":"甚至我还没说话","can":[["甚至"],["说话"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Ở Trung Quốc mọi người đều dùng điện thoại trả tiền, thậm chí mua một chai nước cũng quét mã.","dap":["在中国大家都用手机支付，甚至买一瓶水也扫码。","在中国大家都用手机付钱，甚至买一瓶水也要扫码。","在中国大家都用手机支付，甚至买一瓶水都扫码。"],"giai":"甚至 + phần bất ngờ + 也 / 都."},{"kieu":"dich","vn":"Anh ấy bận lắm, thậm chí cuối tuần cũng phải đi làm.","dap":["他很忙，甚至周末也要上班。","他非常忙，甚至周末都要上班。","他太忙了，甚至周末也得上班。"],"giai":"甚至 + 周末也……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một điều làm em bất ngờ khi dùng điện thoại ở Trung Quốc hoặc Việt Nam, có dùng 「甚至」","mau":"在中国网购特别方便，有时候甚至晚上订的东西，第二天早上就送到了。","can":[["甚至"]]}]}]},{"so":"4","ten":"承接复句“……，于是……”","tenVn":"Câu phức nối tiếp 「……，于是……」 — …, thế là …","cauTruc":["Việc / tình hình 1，于是 + (chủ ngữ) + việc 2","于是 đứng đầu vế sau; có thể thêm 就: 于是……就……"],"giaiThich":"Hai vế kể các hành động / sự việc nối tiếp nhau theo thứ tự; 「于是」 đặt ở đầu vế sau. Giữa hai vế có quan hệ trước – sau và quan hệ logic: việc trước dẫn đến việc sau (“thế là, vì thế mà”). Lưu ý cho người Việt: 1) 于是 dùng để KỂ việc ĐÃ xảy ra, nên KHÔNG dùng trong câu mệnh lệnh / lời khuyên (✗ 天冷了，于是你多穿点儿衣服 → ✓ 所以你多穿点儿衣服吧); 2) 于是 không đứng ở vế đầu. Phân biệt: 所以 nhấn mạnh nguyên nhân – kết quả; 于是 nhấn mạnh hành động tiếp theo xảy ra ngay sau đó.","viDu":[{"zh":"在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心。","py":"Zài tígōng zhèxiē xìnxī shí, wǒmen yě huì dānxīn: wǒ de gèrén xìnxī néngfǒu dédào bǎohù? Yúshì, yǒurén zài wǎngshang shuōchū le zìjǐ de dānxīn.","vn":"Khi cung cấp những thông tin này, chúng ta cũng lo: thông tin cá nhân của mình liệu có được bảo vệ không? Thế là có người nói ra nỗi lo của mình trên mạng."},{"zh":"她从小就想当医生，于是上大学时就选择了学医。","py":"Tā cóng xiǎo jiù xiǎng dāng yīshēng, yúshì shàng dàxué shí jiù xuǎnzé le xué yī.","vn":"Cô ấy từ nhỏ đã muốn làm bác sĩ, thế là lên đại học liền chọn học y."},{"zh":"最近总感冒，于是他决定病好后就开始锻炼身体。","py":"Zuìjìn zǒng gǎnmào, yúshì tā juédìng bìng hǎo hòu jiù kāishǐ duànliàn shēntǐ.","vn":"Dạo này hay bị cảm, thế là anh ấy quyết định khỏi bệnh sẽ bắt đầu tập thể dục."},{"zh":"房东向我介绍了房子里的东西，我很满意，于是当天就租下来了。","py":"Fángdōng xiàng wǒ jièshào le fángzi lǐ de dōngxi, wǒ hěn mǎnyì, yúshì dàngtiān jiù zū xiàlai le.","vn":"Chủ nhà giới thiệu đồ đạc trong nhà, tôi rất hài lòng, thế là thuê luôn trong ngày. (ôn 房东, 租 – Bài 2)"}],"loi":[{"sai":"于是我想喝咖啡，我去了咖啡馆。","why":"于是 đứng đầu vế SAU, không đứng ở vế đầu.","dung":"我想喝咖啡，于是去了咖啡馆。"},{"sai":"明天会下雨，于是你带上伞吧。","why":"于是 kể việc đã xảy ra, không dùng với câu khuyên / mệnh lệnh.","dung":"明天会下雨，所以你带上伞吧。"},{"sai":"他于是很累，就回家休息了。","why":"于是 nối việc tiếp theo, không đặt trước nguyên nhân.","dung":"他很累，于是就回家休息了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我们担心个人信息能否得到保护，","有人在网上说出了自己的担心。"],"dap":[["于是"]],"chon":["于是","甚至","不仅"],"goiY":"“… thế là có người nói ra nỗi lo trên mạng.”","giai":"于是 đứng đầu vế sau."},{"kieu":"dien","phan":["她从小就想当医生，于是上大学时就选择了学","。"],"dap":[["医"]],"chon":["医","法律","技术"],"goiY":"“… thế là lên đại học chọn học y.”","giai":"学医 = học y; 当医生 ôn Bài 1."},{"kieu":"dien","phan":["最近总感冒，于是他决定病好后就开始","身体。"],"dap":[["锻炼"]],"chon":["锻炼","保护","改变"],"goiY":"“… quyết định khỏi bệnh sẽ tập thể dục.”","giai":"锻炼身体 = rèn luyện thân thể (HSK 3)."},{"kieu":"dien","phan":["大家都不说话，于是我","不想说话了。"],"dap":[["也"]],"chon":["也","才","再"],"goiY":"“… thế là tôi cũng không muốn nói nữa.”","giai":"于是 + chủ ngữ + 也……"},{"kieu":"dien","phan":["在十字路口等了半个小时，他们也没来，","我就一个人去图书馆了。"],"dap":[["于是"]],"chon":["于是","而且","甚至"],"goiY":"“… thế là tôi đi thư viện một mình.” (综合练习 3)","giai":"于是……就……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","很累","，","于是","就","回家","休息了"],"dap":["我很累，于是就回家休息了。"],"goiY":"Tôi rất mệt, thế là về nhà nghỉ.","giai":"……，于是就……"},{"kieu":"xep","manh":["他","不熟悉路","，","于是","向","一位同学","问路"],"dap":["他不熟悉路，于是向一位同学问路。"],"goiY":"Anh ấy không thạo đường, thế là hỏi đường một bạn học.","giai":"于是 + 向 + ai + V."},{"kieu":"xep","manh":["手机没电了","，","于是","我","用现金","结了账"],"dap":["手机没电了，于是我用现金结了账。"],"goiY":"Điện thoại hết pin, thế là tôi trả bằng tiền mặt.","giai":"于是 + chủ ngữ 我 + V."},{"kieu":"dungsai","cau":"于是天黑了，我们回家了。","dung":false,"sua":"天黑了，于是我们回家了。","giai":"于是 đứng đầu vế sau."},{"kieu":"dungsai","cau":"他想学好中文，于是来中国留学了。","dung":true,"giai":"Đúng: việc trước dẫn đến việc sau, đã xảy ra."},{"kieu":"dungsai","cau":"天冷了，于是你多穿点儿衣服吧。","dung":false,"sua":"天冷了，你多穿点儿衣服吧。","giai":"Câu khuyên → không dùng 于是 (có thể dùng 所以)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 31)","huongDan":"Hoàn thành câu, dùng 「于是」","cau":[{"kieu":"vandung","de":"弟弟找到了一个新工作，但离家远，＿＿＿。","goiY":"Thế là cậu ấy thuê nhà gần công ty (ôn 租 – Bài 2)","mau":"于是他就在公司附近租了一个房子","can":[["于是"]]},{"kieu":"vandung","de":"我昨天一天都在看书，很累，＿＿＿。","goiY":"Thế là buổi tối ra ngoài vận động một lúc","mau":"于是晚上我就出门活动了一会儿","can":[["于是"]]},{"kieu":"vandung","de":"大家都不说话，＿＿＿。","goiY":"Thế là tôi cũng không muốn nói nữa","mau":"于是我也不想说话了","can":[["于是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi không biết dùng WeChat, thế là bạn Trung Quốc dạy tôi.","dap":["我不会用微信，于是中国朋友教我。","我不会用微信，于是中国朋友就教我怎么用。","我不会用微信，于是我的中国朋友教了我。"],"giai":"……，于是……"},{"kieu":"dich","vn":"Mua online quá tiện, thế là cô ấy hay tiêu tiền lung tung.","dap":["网购太方便了，于是她常常乱花钱。","网购太方便了，于是她经常乱花钱。"],"giai":"于是 + chủ ngữ + V; từ mới 网购, 乱."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể lại một chuyện đã xảy ra với em khi dùng điện thoại (quên mật khẩu, hết pin, lạc đường…), có dùng 「……，于是……」","mau":"上个星期我忘了手机密码，于是去手机店请人帮忙。","can":[["于是"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-4.html"] = [{"so":"1","ten":"可能补语“动词+得/不+了”","tenVn":"Bổ ngữ khả năng 「V + 得了 / 不了」 — làm được / không làm được","cauTruc":["Động từ + 得了 (liǎo) → làm được","Động từ + 不了 (liǎo) → không làm được","Từ ly hợp: 上网 → 上不了网 · 出门 → 出不了门","Câu hỏi: V得了吗？/ V得了V不了？"],"giaiThich":"「得了」「不了」 đặt sau động từ, hoặc chen vào giữa từ ly hợp (上网 → 上不了网), tạo thành bổ ngữ khả năng, cho biết hành động / kết quả CÓ THỂ thực hiện được hay không. Chú ý: 了 ở đây đọc liǎo, không phải le! Hai nghĩa hay gặp: (1) điều kiện cho phép làm hay không (没有信号 → 上不了网; 生病 → 去不了); (2) số lượng có “xử lý” hết được không (菜不多 → 吃得了). Thể khẳng định 得了 chủ yếu dùng trong câu hỏi và câu trả lời. Đây là bổ ngữ khả năng “chung nhất” — so với bổ ngữ khả năng đã học ở HSK 3 (看得懂, 听不清楚, 买不到) thì 了 không nói rõ kết quả cụ thể, chỉ nói “làm nổi / không làm nổi”. Phân biệt 不能: 不能 có thể là “không được phép”; V不了 nhấn mạnh vì điều kiện khách quan mà không làm được.","viDu":[{"zh":"手机没有信号，上不了网，买不了地铁票了。","py":"Shǒujī méiyǒu xìnhào, shàng bu le wǎng, mǎi bu le dìtiě piào le.","vn":"Điện thoại không có sóng, không lên mạng được, không mua được vé tàu điện ngầm nữa."},{"zh":"她刚才给我发信息，说她今天来不了了。","py":"Tā gāngcái gěi wǒ fā xìnxī, shuō tā jīntiān lái bu liǎo le.","vn":"Cô ấy vừa nhắn tin cho tôi, nói hôm nay cô ấy không đến được nữa."},{"zh":"明天的足球比赛，你们班男生参加得了吗？","py":"Míngtiān de zúqiú bǐsài, nǐmen bān nánshēng cānjiā de liǎo ma?","vn":"Trận bóng đá ngày mai, các bạn nam lớp em có tham gia được không?"},{"zh":"要是明天下大雨，运动会就开不了了。","py":"Yàoshi míngtiān xià dàyǔ, yùndònghuì jiù kāi bu liǎo le.","vn":"Nếu mai mưa to thì đại hội thể thao không tổ chức được nữa. (ôn 要是……就…… – Bài 1)"}],"loi":[{"sai":"我明天不了去。","why":"不了 phải đặt SAU động từ.","dung":"我明天去不了。"},{"sai":"手机没有信号，上网不了。","why":"上网 là từ ly hợp: 不了 chen vào giữa 上 và 网.","dung":"手机没有信号，上不了网。"},{"sai":"他病了，明天不能来不了。","why":"Không dùng 不能 cùng với V不了 (phủ định hai lần).","dung":"他病了，明天来不了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["手机没有信号，上","网。"],"dap":[["不了"]],"chon":["不了","得了","不能"],"goiY":"“Điện thoại không có sóng, không lên mạng được.”","giai":"上网 là từ ly hợp → 上不了网."},{"kieu":"dien","phan":["她刚才给我发信息，说她今天来","了。"],"dap":[["不了"]],"chon":["不了","得了","没有"],"goiY":"“Hôm nay cô ấy không đến được nữa.”","giai":"来不了 = không đến được; 了 cuối câu báo sự thay đổi."},{"kieu":"dien","phan":["明天的足球比赛，你们班男生参加","吗？"],"dap":[["得了"]],"chon":["得了","了得","得不"],"goiY":"“… có tham gia được không?”","giai":"Hỏi khả năng: V + 得了 + 吗？"},{"kieu":"dien","phan":["咱们点的菜不多，吃","。"],"dap":[["得了"]],"chon":["得了","不了","了"],"goiY":"“Món gọi không nhiều, ăn hết được.”","giai":"菜不多 → 吃得了 (ăn hết được)."},{"kieu":"dien","phan":["我的钱包丢了，买","地铁票了。"],"dap":[["不了"]],"chon":["不了","得了","不能"],"goiY":"“Mất ví rồi, không mua được vé tàu điện ngầm.”","giai":"买不了 + tân ngữ."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["手机","没有信号","，","我","上不了","网"],"dap":["手机没有信号，我上不了网。"],"goiY":"Điện thoại không có sóng, tôi không lên mạng được.","giai":"上 + 不了 + 网."},{"kieu":"xep","manh":["明天","你","来得了","来不了","？"],"dap":["明天你来得了来不了？","你明天来得了来不了？"],"goiY":"Mai bạn có đến được không?","giai":"Câu hỏi chính phản: V得了V不了？"},{"kieu":"xep","manh":["这么多","菜","，","咱们","吃得了","吗","？"],"dap":["这么多菜，咱们吃得了吗？"],"goiY":"Nhiều món thế này, chúng mình ăn hết được không?","giai":"V得了吗？"},{"kieu":"dungsai","cau":"我今天有点儿事，去不了你家了。","dung":true,"giai":"Đúng: 去不了 + nơi chốn + 了."},{"kieu":"dungsai","cau":"雨太大了，我们出门不了。","dung":false,"sua":"雨太大了，我们出不了门。","giai":"出门 là từ ly hợp: 出不了门."},{"kieu":"dungsai","cau":"他病了，明天不能来不了。","dung":false,"sua":"他病了，明天来不了。","giai":"Bỏ 不能 — không phủ định hai lần."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 37)","huongDan":"Hoàn thành đối thoại, có dùng 「V + 得了 / 不了」","cau":[{"kieu":"vandung","de":"A：咱们点的菜多不多？ B：＿＿＿。","goiY":"Trả lời: không nhiều, chúng mình ăn hết được (V得了)","mau":"不多，咱们吃得了","can":[["得了"]]},{"kieu":"vandung","de":"A：老师，我病了，＿＿＿。 B：好的，那你在家好好休息。","goiY":"Xin phép thầy: hôm nay em không đi (học) được (V不了)","mau":"今天去不了了","can":[["不了"]]},{"kieu":"vandung","de":"A：我突然有点儿事，＿＿＿。 B：好，你需要什么就告诉我，我帮你买。","goiY":"Nói: không đi siêu thị được nữa (V不了)","mau":"去不了超市了","can":[["不了"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Điện thoại tôi hết pin rồi, không quét mã được.","dap":["我的手机没电了，扫不了码。","我的手机没电了，扫不了码了。"],"giai":"扫码 là từ ly hợp → 扫不了码."},{"kieu":"dich","vn":"Bài tập nhiều thế này, một ngày bạn làm xong được không?","dap":["这么多作业，你一天做得了吗？","作业这么多，你一天做得了吗？"],"giai":"V得了吗？ hỏi khả năng hoàn thành."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần em gặp rắc rối (hết pin, quên ví, mất sóng…), có dùng 「V不了」","mau":"那天我的手机没电了，打不了电话，也扫不了码，最后是一位路人帮了我。","can":[["不了"]]}]}]},{"so":"2","ten":"连词“再说”","tenVn":"Liên từ 「再说」 — vả lại, hơn nữa","cauTruc":["Lý do / tình huống 1，再说 + lý do / tình huống 2","……，再说 (+ chủ ngữ) + 也 / 还 + ……"],"giaiThich":"Liên từ 「再说」 dùng sau khi đã nêu một lý do hoặc tình huống, để BỔ SUNG thêm một lý do / tình huống nữa — giống “vả lại, hơn nữa, với lại” trong tiếng Việt. Hai lý do cùng hướng về một kết luận (别去超市了 ← 太晚了 + 还在下雨). Vế sau hay có 也, 还. Mang màu khẩu ngữ, rất hay dùng khi khuyên nhủ, từ chối, giải thích. Phân biệt: (1) 再说 động từ = “để sau hãy nói / tính” (这件事明天再说吧); (2) 而且 cũng là “hơn nữa” nhưng nối ý tăng tiến trong cùng câu, dùng được cả văn viết; 再说 thiên về đưa thêm LÝ DO khi nói chuyện và đứng đầu phân câu sau. Ý trái ngược thì không dùng 再说 mà dùng 不过 / 但是 (Bài 2).","viDu":[{"zh":"我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","py":"Wǒ tí zhe zhèxiē dōngxi jiùsuàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù ā.","vn":"Cháu xách mấy thứ này coi như tập thể dục rồi, vả lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau mà."},{"zh":"今天太晚了，别去超市了，再说外面还在下雨呢。","py":"Jīntiān tài wǎn le, bié qù chāoshì le, zàishuō wàimian hái zài xiàyǔ ne.","vn":"Hôm nay muộn quá rồi, đừng đi siêu thị nữa, vả lại ngoài trời vẫn đang mưa."},{"zh":"你就跟我们一起参加活动吧。你今天正好有时间，再说人多也更热闹。","py":"Nǐ jiù gēn wǒmen yìqǐ cānjiā huódòng ba. Nǐ jīntiān zhènghǎo yǒu shíjiān, zàishuō rén duō yě gèng rènao.","vn":"Bạn đi tham gia hoạt động cùng bọn mình đi. Hôm nay bạn vừa hay rảnh, vả lại đông người cũng vui hơn."},{"zh":"你别担心，我一个人去就是了，再说那儿离我家也不远。","py":"Nǐ bié dānxīn, wǒ yí gè rén qù jiùshì le, zàishuō nàr lí wǒ jiā yě bù yuǎn.","vn":"Bạn đừng lo, tôi đi một mình là được, vả lại chỗ đó cũng không xa nhà tôi. (ôn ×就是了 – Bài 2)"}],"loi":[{"sai":"今天太晚了，再说我们别去超市了。","why":"再说 dẫn ra LÝ DO bổ sung, không dẫn ra kết luận / đề nghị.","dung":"今天太晚了，别去超市了，再说外面还在下雨呢。"},{"sai":"再说外面下雨，今天太晚了。","why":"再说 đứng ở vế SAU, sau khi đã có lý do thứ nhất.","dung":"今天太晚了，再说外面还在下雨。"},{"sai":"这家饭馆的菜很好吃，再说很贵。","why":"Hai ý phải cùng chiều; ý trái ngược dùng 不过 / 但是.","dung":"这家饭馆的菜很好吃，不过有点儿贵。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我提着这些东西就算锻炼身体了，","邻居之间就是要互相帮助啊。"],"dap":[["再说"]],"chon":["再说","不过","于是"],"goiY":"“… vả lại hàng xóm với nhau phải giúp nhau.”","giai":"再说 bổ sung lý do thứ hai."},{"kieu":"dien","phan":["今天太晚了，别去超市了，再说外面还在下雨","。"],"dap":[["呢"]],"chon":["呢","吗","吧"],"goiY":"“… vả lại ngoài trời vẫn đang mưa đấy.”","giai":"还在 + V + 呢: sự việc đang tiếp diễn (HSK 2/3)."},{"kieu":"dien","phan":["你今天正好有时间，再说人多","更热闹。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… vả lại đông người cũng vui hơn.”","giai":"Vế 再说 hay có 也 / 还."},{"kieu":"dien","phan":["我提着这些东西就","锻炼身体了。"],"dap":[["算"]],"chon":["算","像","变"],"goiY":"“… coi như là tập thể dục rồi.” (ôn từ mới)","giai":"就算……了 = coi như là."},{"kieu":"dien","phan":["别买这件了，太贵了，","你已经有很多衣服了。"],"dap":[["再说"]],"chon":["再说","不过","甚至"],"goiY":"“… vả lại bạn đã có nhiều áo rồi.”","giai":"Hai lý do cùng chiều (đắt + đã có nhiều) → 再说."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["今天","太晚了","，","再说","外面","还在下雨呢"],"dap":["今天太晚了，再说外面还在下雨呢。"],"goiY":"Hôm nay muộn quá rồi, vả lại ngoài trời vẫn đang mưa.","giai":"Lý do 1，再说 + lý do 2."},{"kieu":"xep","manh":["这个房子","离学校很近","，","再说","房租","也不贵"],"dap":["这个房子离学校很近，再说房租也不贵。"],"goiY":"Căn nhà này gần trường, vả lại tiền thuê cũng không đắt.","giai":"再说 + chủ ngữ + 也 + …"},{"kieu":"dungsai","cau":"咱们打车去吧，时间不多了，再说东西也很多。","dung":true,"giai":"Đúng: hai lý do cùng chiều (ít thời gian + nhiều đồ) → đi taxi."},{"kieu":"dungsai","cau":"这件衣服很漂亮，再说太贵了，我不买了。","dung":false,"sua":"这件衣服很漂亮，不过太贵了，我不买了。","giai":"Hai ý trái chiều → dùng 不过 (Bài 2 · điểm 2)."},{"kieu":"dungsai","cau":"再说外面很冷，你别出去了。","dung":false,"sua":"已经很晚了，再说外面很冷，你别出去了。","giai":"再说 không mở đầu khi chưa có lý do thứ nhất."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 39)","huongDan":"Viết câu trả lời của B, có dùng 「再说」","cau":[{"kieu":"vandung","de":"A：你今天还出门吗？ B：＿＿＿。","goiY":"Trả lời không ra ngoài nữa, nêu 2 lý do: muộn rồi + vẫn đang mưa","mau":"不出门了。今天太晚了，再说外面还在下雨呢","can":[["再说"]]},{"kieu":"vandung","de":"A：咱们要在这个小区租房子吗？ B：＿＿＿。","goiY":"Khuyên xem chỗ khác: khu này không yên tĩnh lắm + tiền thuê hơi cao","mau":"再看看别的吧。这个小区不太安静，再说房租也有点儿高","can":[["再说"]]},{"kieu":"vandung","de":"A：你觉得这条裤子怎么样？买不买？ B：＿＿＿。","goiY":"Khuyên mua: quần khá đẹp + giá cũng hợp lý","mau":"买吧。这条裤子挺好看的，再说价格也很合适啊","can":[["再说"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chúng mình đi tàu điện ngầm đi, nhanh, vả lại cũng không đắt.","dap":["咱们坐地铁去吧，很快，再说也不贵。","我们坐地铁去吧，很快，再说也不贵。"],"giai":"Lý do 1，再说 + 也 + lý do 2."},{"kieu":"dich","vn":"Đừng khách sáo, việc này rất đơn giản, vả lại hàng xóm với nhau nên giúp đỡ lẫn nhau.","dap":["别客气，这件事很简单，再说邻居之间应该互相帮助。","不客气，这件事很简单，再说邻居之间应该互相帮助。"],"giai":"再说 + từ mới 之间, 互相."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Khuyên bạn chọn một cách đi lại (xe đạp / tàu điện ngầm…), nêu 2 lý do, có dùng 「再说」","mau":"你骑自行车去学校吧，不算远，再说还能锻炼身体。","can":[["再说"]]}]}]},{"so":"3","ten":"并列复句“既……，又/也……”","tenVn":"Câu phức song song 「既……，又 / 也……」 — vừa … vừa …","cauTruc":["Chủ ngữ + 既 + A，又 + B","Chủ ngữ + 既 + A，也 + B","既 + A，又 + B，还 + C (ba ý)"],"giaiThich":"「既……，又 / 也……」 nối tính từ, động từ hoặc cụm từ, biểu thị cùng lúc có hai (hoặc nhiều) tính chất / tình huống — “vừa … vừa …”, “đã … lại …”. 既 và 又 / 也 đều là phó từ: đứng SAU chủ ngữ, TRƯỚC động từ / tính từ. 既……又…… hay nối hai thành phần ngắn, cân đối (既好吃又便宜); 既……也…… hay dùng khi vế sau là cụm động từ dài hơn (既能提高中文水平，也能学到历史知识). Muốn thêm ý thứ ba thì dùng 还 (既方便，又能锻炼身体，还能保护环境). So với 又……又…… (HSK 3) thì 既……又…… trang trọng hơn một chút. Các ý phải CÙNG CHIỀU (cùng tốt hoặc cùng xấu) — ý trái ngược dùng 不过 / 但是.","viDu":[{"zh":"她觉得这样既方便，又能锻炼身体，还能保护环境。","py":"Tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng.","vn":"Cô ấy thấy như vậy vừa tiện, vừa rèn luyện được thân thể, lại còn bảo vệ được môi trường."},{"zh":"这家饭馆的菜既好吃，又便宜。","py":"Zhè jiā fànguǎn de cài jì hǎochī, yòu piányi.","vn":"Món ăn ở nhà hàng này vừa ngon vừa rẻ."},{"zh":"我很喜欢这门课程，既能提高中文水平，也能学到历史知识。","py":"Wǒ hěn xǐhuan zhè mén kèchéng, jì néng tígāo Zhōngwén shuǐpíng, yě néng xuédào lìshǐ zhīshi.","vn":"Tôi rất thích môn học này, vừa nâng cao được trình độ tiếng Trung, cũng học được kiến thức lịch sử."},{"zh":"这个工作既能学到很多知识，又能认识很多朋友，不过有点儿辛苦。","py":"Zhège gōngzuò jì néng xuédào hěn duō zhīshi, yòu néng rènshi hěn duō péngyou, búguò yǒudiǎnr xīnkǔ.","vn":"Công việc này vừa học được nhiều kiến thức, vừa quen được nhiều bạn, có điều hơi vất vả. (ôn ……，不过…… – Bài 2)"}],"loi":[{"sai":"既他聪明，又他努力。","why":"既 / 又 đứng SAU chủ ngữ, không đứng trước chủ ngữ.","dung":"他既聪明又努力。"},{"sai":"这家饭馆的菜既好吃，又很贵。","why":"Hai ý phải cùng chiều; ý trái ngược dùng 不过 / 但是.","dung":"这家饭馆的菜很好吃，不过很贵。"},{"sai":"我既喜欢唱歌，还喜欢跳舞。","why":"Vế thứ hai dùng 又 / 也; 还 chỉ dùng cho ý thứ ba.","dung":"我既喜欢唱歌，也喜欢跳舞。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["她觉得这样","方便，又能锻炼身体。"],"dap":[["既"]],"chon":["既","也","还"],"goiY":"“Cô ấy thấy như vậy vừa tiện, vừa …”","giai":"Vế đầu dùng 既."},{"kieu":"dien","phan":["这家饭馆的菜既好吃，","便宜。"],"dap":[["又"]],"chon":["又","再","就"],"goiY":"“… vừa ngon vừa rẻ.”","giai":"既……又……"},{"kieu":"dien","phan":["我很喜欢这门课程，既能提高中文水平，","能学到历史知识。"],"dap":[["也"]],"chon":["也","都","才"],"goiY":"“… cũng học được kiến thức lịch sử.”","giai":"既……也…… (vế sau là cụm động từ)."},{"kieu":"dien","phan":["她觉得骑车既方便，又能锻炼身体，","能保护环境。"],"dap":[["还"]],"chon":["还","既","就"],"goiY":"“… lại còn bảo vệ được môi trường.”","giai":"Ý thứ ba dùng 还."},{"kieu":"dien","phan":["电动车速度快，价格不高，","也很方便。"],"dap":[["充电"]],"chon":["充电","速度","力气"],"goiY":"“… sạc điện cũng rất tiện.” (ôn từ mới)","giai":"充电 = sạc điện."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这家","饭馆的菜","既","好吃","又","便宜"],"dap":["这家饭馆的菜既好吃又便宜。"],"goiY":"Món ăn ở nhà hàng này vừa ngon vừa rẻ.","giai":"Chủ ngữ + 既 + A + 又 + B."},{"kieu":"xep","manh":["骑自行车","既","能锻炼身体","，","也","能保护环境"],"dap":["骑自行车既能锻炼身体，也能保护环境。"],"goiY":"Đi xe đạp vừa rèn luyện thân thể, cũng bảo vệ được môi trường.","giai":"既……也……"},{"kieu":"dungsai","cau":"他既是我的老师，也是我的朋友。","dung":true,"giai":"Đúng: 既是……也是……"},{"kieu":"dungsai","cau":"既他会说汉语，又他会说英语。","dung":false,"sua":"他既会说汉语，又会说英语。","giai":"既 / 又 đứng sau chủ ngữ."},{"kieu":"dungsai","cau":"这件衣服既漂亮，又不好看。","dung":false,"sua":"这件衣服既漂亮，又便宜。","giai":"Hai ý mâu thuẫn — phải cùng chiều."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 41)","huongDan":"Hoàn thành câu, dùng 「既……，又 / 也……」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"我想买一辆电动车，因为＿＿＿。","goiY":"Dùng 「力气、速度」: đỡ tốn sức + tốc độ nhanh","mau":"既省力气，速度又快","can":[["既"],["又","也"]]},{"kieu":"vandung","de":"我常来这个公园跑步，这里＿＿＿。","goiY":"Dùng 「安静、漂亮」","mau":"既安静又漂亮","can":[["既"],["又","也"]]},{"kieu":"vandung","de":"我喜欢住在学校里面，＿＿＿。","goiY":"Dùng 「方便、安全」: đi học tiện + an toàn","mau":"因为既上课方便，又很安全","can":[["既"],["又","也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Xe điện vừa nhanh vừa rẻ, nên ngày càng thịnh hành.","dap":["电动车既快又便宜，所以越来越流行。","电动车既快，又便宜，所以越来越流行。"],"giai":"既……又…… + 流行."},{"kieu":"dich","vn":"Đi tàu điện ngầm vừa không bị tắc đường, vừa tiết kiệm được thời gian.","dap":["坐地铁既不堵车，又能省时间。","坐地铁既不堵车，也能省时间。"],"giai":"既……又 / 也…… + 省."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giới thiệu cách đi lại em thích nhất, có dùng 「既……，又 / 也……」","mau":"我最喜欢坐地铁，既快又准时，也不用担心堵车。","can":[["既"],["又","也"]]}]}]},{"so":"4","ten":"固定短语“来得及/来不及”","tenVn":"Cụm cố định 「来得及 / 来不及」 — kịp / không kịp","cauTruc":["(还) 来得及 + V → còn kịp làm","来不及 + V (+ 了) → không kịp làm","没来得及 + V → (đã) không kịp làm (việc đã qua)","……，来得及吗？/ 来得及来不及？"],"giaiThich":"「来得及」 = còn thời gian, có thể làm kịp / đuổi kịp; 「来不及」 = vì thời gian gấp gáp mà không thể làm kịp. Phía sau thường là động từ (来得及吃早饭, 来不及通知大家), hoặc đứng cuối câu (9点出发来得及吗？). Việc ĐÃ xảy ra mà không kịp làm → 没来得及 + V (✗ 没来不及). Thực ra đây là bổ ngữ khả năng cố định của 来 + 及 (kịp), cấu tạo giống V得了 / V不了 ở điểm 1. Mẹo cho người Việt: “kịp” = 来得及, “không kịp” = 来不及, “đã không kịp / chưa kịp” = 没来得及.","viDu":[{"zh":"没来得及吃早饭的人在这里就能买到热包子和牛奶等。","py":"Méi láidejí chī zǎofàn de rén zài zhèli jiù néng mǎidào rè bāozi hé niúnǎi děng.","vn":"Người không kịp ăn sáng ở đây có thể mua được bánh bao nóng, sữa…"},{"zh":"你现在才告诉我，我来不及通知大家了。","py":"Nǐ xiànzài cái gàosu wǒ, wǒ láibují tōngzhī dàjiā le.","vn":"Bây giờ bạn mới nói với tôi, tôi không kịp thông báo cho mọi người nữa rồi."},{"zh":"中午12点的飞机，咱们9点出发来得及吗？","py":"Zhōngwǔ 12 diǎn de fēijī, zánmen 9 diǎn chūfā láidejí ma?","vn":"Máy bay 12 giờ trưa, chúng ta 9 giờ xuất phát có kịp không?"},{"zh":"他早上起晚了，没来得及吃早饭，甚至连脸都没洗。","py":"Tā zǎoshang qǐwǎn le, méi láidejí chī zǎofàn, shènzhì lián liǎn dōu méi xǐ.","vn":"Sáng nay anh ấy dậy muộn, không kịp ăn sáng, thậm chí mặt cũng chưa rửa. (ôn 甚至 – Bài 3)"}],"loi":[{"sai":"我昨天没来不及吃早饭。","why":"Việc đã qua mà không kịp làm nói 没来得及, không nói 没来不及.","dung":"我昨天没来得及吃早饭。"},{"sai":"时间太晚了，我不来得及坐地铁。","why":"Phủ định là 来不及, không phải 不来得及.","dung":"时间太晚了，我来不及坐地铁了。"},{"sai":"还有一个小时，来得及了。","why":"Khẳng định còn kịp chỉ cần 来得及 (không thêm 了); 来不及了 mới hay có 了.","dung":"还有一个小时，来得及。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["没","吃早饭的人在这里就能买到热包子。"],"dap":[["来得及"]],"chon":["来得及","来不及","不来及"],"goiY":"“Người không kịp ăn sáng …”","giai":"没来得及 + V (✗ 没来不及)."},{"kieu":"dien","phan":["你现在才告诉我，我","通知大家了。"],"dap":[["来不及"]],"chon":["来不及","来得及","没来得及"],"goiY":"“… tôi không kịp thông báo cho mọi người nữa.”","giai":"来不及 + V + 了."},{"kieu":"dien","phan":["中午12点的飞机，咱们9点出发","吗？"],"dap":[["来得及"]],"chon":["来得及","来不及了","没来得及"],"goiY":"“… 9 giờ xuất phát có kịp không?”","giai":"Hỏi: ……来得及吗？"},{"kieu":"dien","phan":["别着急，还有15分钟，咱们来得及吃","。"],"dap":[["早饭"]],"chon":["早饭","速度","乘客"],"goiY":"“… kịp ăn sáng.”","giai":"来得及 + V + O."},{"kieu":"dien","phan":["时间太晚了，你","坐地铁回去了，就住在我们这儿吧。"],"dap":[["来不及"]],"chon":["来不及","来得及","没来得及"],"goiY":"“… bạn không kịp đi tàu điện ngầm về nữa …”","giai":"来不及 + V + 了."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["还有","半个小时","，","咱们","来得及","吃早饭"],"dap":["还有半个小时，咱们来得及吃早饭。"],"goiY":"Còn nửa tiếng, chúng mình kịp ăn sáng.","giai":"来得及 + V."},{"kieu":"xep","manh":["我","早上","没来得及","吃早饭","就","去上班了"],"dap":["我早上没来得及吃早饭就去上班了。"],"goiY":"Sáng nay tôi chưa kịp ăn sáng đã đi làm rồi.","giai":"没来得及 + V + 就……了."},{"kieu":"dungsai","cau":"现在出发还来得及。","dung":true,"giai":"Đúng: 还来得及 = vẫn còn kịp."},{"kieu":"dungsai","cau":"昨天我没来不及跟你说再见。","dung":false,"sua":"昨天我没来得及跟你说再见。","giai":"Việc đã qua: 没来得及."},{"kieu":"dungsai","cau":"飞机十点起飞，现在已经九点半了，来得及不了。","dung":false,"sua":"飞机十点起飞，现在已经九点半了，来不及了。","giai":"Phủ định là 来不及, không có 来得及不了."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 43)","huongDan":"Hoàn thành câu, dùng 「来得及 / 来不及」","cau":[{"kieu":"vandung","de":"别着急，还有15分钟，咱们＿＿＿。","goiY":"Nói: chúng mình vẫn kịp ăn sáng","mau":"来得及吃早饭","can":[["来得及"]]},{"kieu":"vandung","de":"时间太晚了，你＿＿＿，就住在我们这儿吧。","goiY":"Nói: bạn không kịp đi tàu điện ngầm về nữa","mau":"来不及坐地铁回去了","can":[["来不及"]]},{"kieu":"vandung","de":"你自己去吃午饭吧，我还要准备下午的会议材料，＿＿＿。","goiY":"Nói: tôi không kịp đi ăn nữa","mau":"来不及去吃饭了","can":[["来不及"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Sáng nay tôi dậy muộn, không kịp ăn sáng.","dap":["今天早上我起晚了，没来得及吃早饭。","我今天早上起晚了，没来得及吃早饭。"],"giai":"Việc đã qua → 没来得及 + V."},{"kieu":"dich","vn":"Phim 8 giờ bắt đầu, bây giờ đi còn kịp không?","dap":["电影八点开始，现在去还来得及吗？","电影8点开始，现在去来得及吗？"],"giai":"……，来得及吗？"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần em suýt muộn / không kịp làm gì, có dùng 「来得及 / 来不及 / 没来得及」","mau":"上周一我起晚了，没来得及吃早饭，不过在地铁站买了包子，上课还来得及。","can":[["来得及","来不及"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-5.html"] = [{"so":"1","ten":"范围副词“至少”","tenVn":"Phó từ phạm vi 「至少」 — ít nhất, tối thiểu","cauTruc":["至少 + số lượng / thời gian","Chủ ngữ + 至少 + (要 / 能 / 会) + động từ + số lượng","……，不过 / 但 + 至少 + …… (ít ra thì cũng …)"],"giaiThich":"「至少」 biểu thị thời gian, số lượng, mức độ… KHÔNG THẤP HƠN một giới hạn nhỏ nhất (≥ mức đó). Vị trí: đứng sau chủ ngữ, TRƯỚC động từ hoặc trước cụm số lượng: 至少两个月 / 至少要选三门课. Cách dùng thứ hai: khi điều khác chưa được như ý, 「至少」 nêu ra cái “ít ra cũng được”: 旧是旧，不过至少很干净 (cũ thì cũ, nhưng ít ra cũng sạch). Mẹo cho người Việt: tiếng Việt hay nói “hai tiếng là ít nhất”, “ít nhất” để cuối câu — tiếng Trung KHÔNG được để 至少 ở cuối câu. Trái nghĩa: 最多 (nhiều nhất).","viDu":[{"zh":"家月，你来中国至少两个月了，习惯吃中餐了吗？","py":"Jiāyuè, nǐ lái Zhōngguó zhìshǎo liǎng gè yuè le, xíguàn chī zhōngcān le ma?","vn":"Gia Nguyệt, cháu sang Trung Quốc ít nhất cũng hai tháng rồi, đã quen ăn món Trung chưa?"},{"zh":"每年至少有两百名留学生来我校学习中文专业。","py":"Měinián zhìshǎo yǒu liǎngbǎi míng liúxuéshēng lái wǒ xiào xuéxí Zhōngwén zhuānyè.","vn":"Mỗi năm có ít nhất hai trăm du học sinh đến trường chúng tôi học chuyên ngành tiếng Trung."},{"zh":"我们虽然没有见过面，但至少在网上聊过很多次，也算比较熟悉了。","py":"Wǒmen suīrán méiyǒu jiàn guò miàn, dàn zhìshǎo zài wǎngshang liáo guò hěn duō cì, yě suàn bǐjiào shúxi le.","vn":"Tuy chúng tôi chưa gặp mặt, nhưng ít ra cũng đã trò chuyện trên mạng nhiều lần, coi như khá quen rồi."},{"zh":"这个房子旧是旧，不过至少很干净。","py":"Zhège fángzi jiù shì jiù, búguò zhìshǎo hěn gānjìng.","vn":"Căn nhà này cũ thì cũ, nhưng ít ra cũng rất sạch sẽ. (ôn ×是×，不过…… — Bài 3 · điểm 1)"}],"loi":[{"sai":"我每天学习两个小时至少。","why":"Không để 至少 cuối câu như tiếng Việt; 至少 đứng trước động từ / số lượng.","dung":"我每天至少学习两个小时。"},{"sai":"至少他有三十岁了。","why":"Thường đặt 至少 sau chủ ngữ, trước vị ngữ.","dung":"他至少有三十岁了。"},{"sai":"他至少的朋友有十个。","why":"至少 là phó từ, không làm định ngữ với 的.","dung":"他至少有十个朋友。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["家月，你来中国","两个月了，习惯吃中餐了吗？"],"dap":[["至少"]],"chon":["至少","专门","任何"],"goiY":"“Cháu sang Trung Quốc ít nhất hai tháng rồi …”","giai":"至少 + cụm thời gian."},{"kieu":"dien","phan":["每年至少","两百名留学生来我校学习中文专业。"],"dap":[["有"]],"chon":["有","是","在"],"goiY":"“Mỗi năm có ít nhất hai trăm du học sinh …”","giai":"至少 + 有 + số lượng."},{"kieu":"dien","phan":["我们虽然没有见过面，","至少在网上聊过很多次。"],"dap":[["但"]],"chon":["但","就","于是"],"goiY":"“Tuy chưa gặp mặt, nhưng ít ra cũng đã trò chuyện trên mạng nhiều lần.”","giai":"虽然……，但至少…… — ôn 虽然……但是…… (HSK 3)."},{"kieu":"dien","phan":["骑电动车至少","快十分钟。"],"dap":[["能"]],"chon":["能","敢","够"],"goiY":"“Đi xe đạp điện ít nhất cũng nhanh được mười phút.”","giai":"至少 + 能 + V + số lượng."},{"kieu":"dien","phan":["这个房子旧是旧，","至少很干净。"],"dap":[["不过"]],"chon":["不过","因为","要是"],"goiY":"“Cũ thì cũ, nhưng ít ra cũng sạch.” (ôn Bài 3)","giai":"×是×，不过至少…… — ôn Bài 3 · điểm 1."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","每天","至少","学习","两个小时"],"dap":["我每天至少学习两个小时。"],"goiY":"Mỗi ngày tôi học ít nhất hai tiếng.","giai":"Chủ ngữ + thời gian + 至少 + V + thời lượng."},{"kieu":"xep","manh":["研究生一年级","至少","要","选","三门课"],"dap":["研究生一年级至少要选三门课。"],"goiY":"Năm nhất cao học phải chọn ít nhất ba môn.","giai":"至少 + 要 + V + số lượng."},{"kieu":"xep","manh":["这个","房子","旧是旧","，","不过","至少","很干净"],"dap":["这个房子旧是旧，不过至少很干净。"],"goiY":"Căn nhà này cũ thì cũ, nhưng ít ra cũng sạch.","giai":"Ôn ×是×，不过…… + 至少."},{"kieu":"dungsai","cau":"我每天睡觉八个小时至少。","dung":false,"sua":"我每天至少睡八个小时。","giai":"至少 không đứng cuối câu."},{"kieu":"dungsai","cau":"每年至少有两百名留学生来我校学习。","dung":true,"giai":"Đúng: 至少 + 有 + số lượng."},{"kieu":"dungsai","cau":"他至少的朋友有十个。","dung":false,"sua":"他至少有十个朋友。","giai":"至少 là phó từ, không thêm 的 làm định ngữ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 49)","huongDan":"Viết câu trả lời của B, có dùng 至少","cau":[{"kieu":"vandung","de":"A：这个房子是不是有点儿旧？ B：旧是旧，不过＿＿＿。","goiY":"Thừa nhận nhà cũ, rồi nêu một điểm “ít ra cũng …” (ôn ×是×，不过…… — Bài 3)","mau":"至少很干净","can":[["至少"]]},{"kieu":"vandung","de":"A：老师，我刚入学，不知道应该选几门课。 B：研究生一年级的时候，＿＿＿。","goiY":"Nói số môn tối thiểu phải chọn (至少要……)","mau":"至少要选三门课","can":[["至少"]]},{"kieu":"vandung","de":"A：你现在怎么不坐公交车，每天骑电动车了？ B：骑电动车＿＿＿，我早上就不用太早出发了。","goiY":"Nói đi xe điện nhanh hơn ít nhất bao nhiêu phút","mau":"至少能快十分钟","can":[["至少"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Muốn học giỏi tiếng Trung, mỗi ngày ít nhất phải học một tiếng.","dap":["要想学好中文，每天至少要学习一个小时。","要想学好中文，每天至少要学一个小时。","想学好中文，每天至少要学习一个小时。"],"giai":"至少 + 要 + V + thời lượng."},{"kieu":"dich","vn":"Tôi đã đến Bắc Kinh ít nhất năm lần rồi.","dap":["我至少来过北京五次了。","我至少去过北京五次了。","我至少来过五次北京了。"],"giai":"至少 + V过 + số lần."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu nói về thói quen ăn uống / học tập của em, có dùng 「至少」","mau":"我每天至少喝八杯水，至少吃一次水果。","can":[["至少"]]}]}]},{"so":"2","ten":"副词/动词“够”","tenVn":"Phó từ / Động từ 「够」 — thật là …; đủ","cauTruc":["Phó từ: 够 + tính từ + 的 (thật là …, … thật đấy)","Động từ: danh từ + 够 / 不够 (đủ / không đủ)","不够 + tính từ (chưa đủ …)"],"giaiThich":"「够」 có hai từ loại. (1) PHÓ TỪ: biểu thị mức độ cao, thường dùng trong khung cố định 「够……的」, mang sắc thái cảm thán của khẩu ngữ: 你的中文水平够高的 = trình độ tiếng Trung của cậu cao thật đấy. Đừng quên 的 ở cuối! (2) ĐỘNG TỪ: số lượng đáp ứng đủ nhu cầu, hoặc đạt tới một tiêu chuẩn / mức độ: 四个菜够不够？/ 时间不够. Dạng 「不够 + tính từ」 = chưa đủ … (还不够甜 = vẫn chưa đủ ngọt). Phát âm: 不够 đọc búgòu (biến điệu của 不). Mẹo phân biệt: câu khẳng định 「够 + Adj + 的」 → khen / than “thật là”; còn 够 / 不够 đứng sau danh từ → “đủ / không đủ”.","viDu":[{"zh":"你的中文水平够高的，这都听懂了！","py":"Nǐ de Zhōngwén shuǐpíng gòu gāo de, zhè dōu tīngdǒng le!","vn":"Trình độ tiếng Trung của cậu cao thật đấy, câu này mà cũng nghe hiểu!"},{"zh":"明天请家月和李文来家里吃饭，四个菜够不够？","py":"Míngtiān qǐng Jiāyuè hé Lǐ Wén lái jiāli chīfàn, sì gè cài gòu búgòu?","vn":"Mai mời Gia Nguyệt và Lý Văn đến nhà ăn cơm, bốn món có đủ không?"},{"zh":"我尝了一下，还不够甜，再加一点儿糖吧。","py":"Wǒ cháng le yíxià, hái búgòu tián, zài jiā yìdiǎnr táng ba.","vn":"Tôi nếm thử rồi, vẫn chưa đủ ngọt, thêm chút đường nữa đi."},{"zh":"今天的菜够丰富的，我们四个人肯定吃不了。","py":"Jīntiān de cài gòu fēngfù de, wǒmen sì gè rén kěndìng chī bu liǎo.","vn":"Đồ ăn hôm nay phong phú thật đấy, bốn người chúng ta chắc chắn ăn không hết. (ôn V不了 — Bài 4 · điểm 1)"}],"loi":[{"sai":"你的中文水平够高。","why":"Phó từ 够 ở câu khẳng định cần 的 cuối câu: 够……的.","dung":"你的中文水平够高的。"},{"sai":"这个箱子够不大。","why":"Phủ định là 不够 + tính từ: 不 đứng trước 够.","dung":"这个箱子不够大。"},{"sai":"我的钱不足够买这本书。","why":"Khẩu ngữ dùng 不够 (+ V), không nói 不足够.","dung":"我的钱不够买这本书。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["你的中文水平","高的，这都听懂了！"],"dap":[["够"]],"chon":["够","不够","至少"],"goiY":"“Trình độ tiếng Trung của cậu cao thật đấy!”","giai":"够 + Adj + 的 = thật là …"},{"kieu":"dien","phan":["我尝了一下，还","甜，再加一点儿糖吧。"],"dap":[["不够"]],"chon":["不够","够","至少"],"goiY":"“Vẫn chưa đủ ngọt, thêm chút đường đi.”","giai":"不够 + Adj = chưa đủ …"},{"kieu":"dien","phan":["明天请家月和李文来家里吃饭，四个菜","？"],"dap":[["够不够"]],"chon":["够不够","够没够","不够够"],"goiY":"“Bốn món có đủ không?”","giai":"Câu hỏi chính phản: 够不够."},{"kieu":"dien","phan":["今天的天气够冷","，多穿点儿衣服吧。"],"dap":[["的"]],"chon":["的","了","吗"],"goiY":"“Hôm nay trời lạnh thật đấy, mặc thêm áo vào.”","giai":"Khung cố định 够……的."},{"kieu":"dien","phan":["完成这个工作需要三天，现在只有两天，时间","。"],"dap":[["不够"]],"chon":["不够","够的","至少"],"goiY":"“… thời gian không đủ.”","giai":"N + 不够 (động từ)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你家","房子","够","大","的"],"dap":["你家房子够大的。"],"goiY":"Nhà bạn to thật đấy.","giai":"够 + Adj + 的."},{"kieu":"xep","manh":["这个","箱子","不够大","，","放不下","这么多东西"],"dap":["这个箱子不够大，放不下这么多东西。"],"goiY":"Cái thùng này không đủ to, không để vừa nhiều đồ thế.","giai":"不够 + Adj + bổ ngữ khả năng 放不下."},{"kieu":"xep","manh":["我","尝了一下","，","还","不够","甜"],"dap":["我尝了一下，还不够甜。"],"goiY":"Tôi nếm thử rồi, vẫn chưa đủ ngọt.","giai":"还 + 不够 + Adj."},{"kieu":"dungsai","cau":"这个箱子够不大，放不下这么多东西。","dung":false,"sua":"这个箱子不够大，放不下这么多东西。","giai":"Phủ định: 不够 + Adj."},{"kieu":"dungsai","cau":"你的中文水平够高的，这都听懂了！","dung":true,"giai":"Đúng: 够……的 cảm thán."},{"kieu":"dungsai","cau":"我们只有两个人，三个菜够了。","dung":true,"giai":"Đúng: 够 làm động từ — đủ (số lượng)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 51)","huongDan":"Hoàn thành đối thoại, có dùng 够 / 不够","cau":[{"kieu":"vandung","de":"A：这个箱子＿＿＿，放不下这么多东西。 B：那我再看看有没有别的箱子。","goiY":"Thùng không đủ to (不够 + Adj)","mau":"不够大","can":[["够"]]},{"kieu":"vandung","de":"A：你家房子＿＿＿，不仅有上下两层，还有一个小花园。 B：我买房的时候就想着要能住下一家五口人。","goiY":"Khen nhà to thật (够……的); ôn 不仅……还…… (Bài 3)","mau":"够大的","can":[["够"]]},{"kieu":"vandung","de":"A：完成这个工作需要三天，现在只有两天，时间＿＿＿。 B：那我再去跟经理说一下。","goiY":"Thời gian không đủ (động từ 够)","mau":"不够","can":[["够"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Món này vẫn chưa đủ cay, cho thêm chút ớt nữa đi.","dap":["这道菜还不够辣，再放一点儿辣椒吧。","这道菜还不够辣，再加一点儿辣椒吧。","这个菜还不够辣，再放一点儿辣椒吧。"],"giai":"不够 + Adj; từ mới 辣椒."},{"kieu":"dich","vn":"Hôm nay trời nóng thật đấy!","dap":["今天天气够热的！","今天的天气够热的！","今天够热的！"],"giai":"够 + Adj + 的."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu khen hoặc than về một món ăn / nhà hàng, có dùng 「够……的」 hoặc 「不够」","mau":"这家饭店的菜够好吃的，不过就是有点儿贵。","can":[["够"]]}]}]},{"so":"3","ten":"固定格式“各×各的”","tenVn":"Cấu trúc cố định 「各×各的」 — ai … nấy, mỗi người tự …","cauTruc":["各 + động từ + 各 + 的 (+ danh từ)","Chủ ngữ số nhiều (大家 / 我们 / 他们) + (就) + 各 V 各的"],"giaiThich":"「各×各的」 (× thường là động từ đơn âm tiết) biểu thị MỖI NGƯỜI ĐỘC LẬP làm cùng một loại việc, không ảnh hưởng nhau: 各付各的 = ai trả phần nấy, 各忙各的 = ai bận việc nấy, 各看各的书 = ai đọc sách nấy. Chủ ngữ phải chỉ nhiều người (大家, 我们, 他们). Động từ lặp lại giống nhau ở hai vế. Tiếng Việt có cách nói rất giống: “ai … nấy”, “mỗi người … phần mình”. Văn hóa: giới trẻ Trung Quốc ngày nay khi đi ăn với bạn bè hay 各付各的 (còn gọi là AA制), chuyển khoản qua điện thoại cho người trả trước.","viDu":[{"zh":"大家觉得还是各付各的更合适。","py":"Dàjiā juéde háishi gè fù gè de gèng héshì.","vn":"Mọi người thấy vẫn là ai trả phần nấy thì hợp hơn."},{"zh":"到了办公室，大家就开始各忙各的了。","py":"Dào le bàngōngshì, dàjiā jiù kāishǐ gè máng gè de le.","vn":"Đến văn phòng, mọi người liền bắt đầu ai bận việc nấy."},{"zh":"在图书馆里，大家都很安静，各看各的书。","py":"Zài túshūguǎn lǐ, dàjiā dōu hěn ānjìng, gè kàn gè de shū.","vn":"Trong thư viện, mọi người đều rất yên lặng, ai đọc sách nấy."},{"zh":"他们想买的东西不一样，于是到了商场以后就各买各的了。","py":"Tāmen xiǎng mǎi de dōngxi bù yíyàng, yúshì dào le shāngchǎng yǐhòu jiù gè mǎi gè de le.","vn":"Họ muốn mua những thứ khác nhau, thế là đến trung tâm thương mại liền mỗi người mua một kiểu. (ôn 于是 — Bài 3 · điểm 4)"}],"loi":[{"sai":"我各付各的。","why":"Chủ ngữ phải là nhiều người.","dung":"我们各付各的。"},{"sai":"大家各付自己的。","why":"Cấu trúc cố định lặp lại 各 + cùng động từ: 各V各的.","dung":"大家各付各的。"},{"sai":"他们各的吃各的。","why":"Không có 的 sau 各 thứ nhất; 的 chỉ ở cuối.","dung":"他们各吃各的。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["大家觉得还是各付","的更合适。"],"dap":[["各"]],"chon":["各","自己","每"],"goiY":"“… vẫn là ai trả phần nấy thì hợp hơn.”","giai":"各 + V + 各 + 的."},{"kieu":"dien","phan":["到了办公室，大家就开始各","各的了。"],"dap":[["忙"]],"chon":["忙","付","坐"],"goiY":"“… ai bận việc nấy.”","giai":"各忙各的."},{"kieu":"dien","phan":["在图书馆里，大家都很安静，各看各的","。"],"dap":[["书"]],"chon":["书","饭","菜"],"goiY":"“… ai đọc sách nấy.”","giai":"各V各的 + danh từ."},{"kieu":"dien","phan":["他们口味不同，","就各吃各的。"],"dap":[["于是"]],"chon":["于是","甚至","不仅"],"goiY":"“Khẩu vị họ khác nhau, thế là mỗi người ăn phần mình.” (ôn Bài 3)","giai":"于是 nối kết quả — Bài 3 · điểm 4."},{"kieu":"dien","phan":["他们想买的东西不一样，到了商场以后就各买","了。"],"dap":[["各的"]],"chon":["各的","自己","他的"],"goiY":"“… mỗi người mua một kiểu.”","giai":"各买各的."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["大家","觉得","还是","各付各的","更合适"],"dap":["大家觉得还是各付各的更合适。"],"goiY":"Mọi người thấy vẫn là ai trả phần nấy thì hợp hơn.","giai":"还是……更合适 + 各付各的."},{"kieu":"xep","manh":["到了","办公室","，","大家","就","开始","各忙各的了"],"dap":["到了办公室，大家就开始各忙各的了。"],"goiY":"Đến văn phòng, mọi người bắt đầu ai bận việc nấy.","giai":"Chủ ngữ số nhiều + 就 + 各V各的."},{"kieu":"xep","manh":["老师","说完","以后","，","大家","就","各做各的"],"dap":["老师说完以后，大家就各做各的。"],"goiY":"Thầy nói xong, mọi người ai làm bài nấy.","giai":"……以后，大家就各V各的."},{"kieu":"dungsai","cau":"我各吃各的。","dung":false,"sua":"我们各吃各的。","giai":"Chủ ngữ phải là nhiều người."},{"kieu":"dungsai","cau":"在图书馆里，大家都很安静，各看各的书。","dung":true,"giai":"Đúng: 各看各的 + 书."},{"kieu":"dungsai","cau":"他们各的做各的。","dung":false,"sua":"他们各做各的。","giai":"Không có 的 sau 各 thứ nhất."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 53)","huongDan":"Hoàn thành câu, có dùng 各×各的","cau":[{"kieu":"vandung","de":"他们想买的东西不一样，到了商场以后就＿＿＿。","goiY":"Mỗi người đi mua đồ của mình","mau":"各买各的了","can":[["各"]]},{"kieu":"vandung","de":"他们虽然住在一起，但是口味不同，＿＿＿。","goiY":"Vì khẩu vị khác nhau nên mỗi người ăn phần mình","mau":"所以就各吃各的","can":[["各"]]},{"kieu":"vandung","de":"老师说完作业怎么做以后，大家就＿＿＿，不再说话了。","goiY":"Ai làm bài của người nấy","mau":"各做各的","can":[["各"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bạn bè đi ăn với nhau, chúng tôi thường ai trả phần nấy.","dap":["朋友一起吃饭，我们一般各付各的。","和朋友聚餐，我们一般各付各的。","朋友聚餐的时候，我们常常各付各的。"],"giai":"各付各的 + từ mới 聚餐."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu kể về em và bạn cùng phòng / gia đình, có dùng 「各×各的」","mau":"我和同屋的口味不一样，所以周末我们常常各做各的饭。","can":[["各"]]}]}]},{"so":"4","ten":"介词“等”","tenVn":"Giới từ 「等」 — đợi đến khi, chờ đến lúc","cauTruc":["等 + sự việc / thời gian + (以后 / 后)，(chủ ngữ) + 再 / 就 + động từ","等 + sự việc + 的时候，chủ ngữ + 已经 + động từ + 了"],"giaiThich":"Trong bài này 「等」 là GIỚI TỪ, nghĩa là 「等到」 (đợi đến khi), dùng để dẫn ra THỜI ĐIỂM hoặc ĐIỀU KIỆN cho hành động ở vế sau. Hay gặp: 等……(以后)，再…… (đợi … xong rồi mới …); 等……，就…… (đợi đến khi … thì …); 等……的时候，已经……了 (đến lúc … thì đã … rồi — thường diễn tả sự muộn màng, tiếc nuối). Phân biệt ba chữ 等: động từ “chờ” (我等你), giới từ “đợi đến khi” (bài này), trợ từ “vân vân” (苹果、香蕉等). Mẹo cho người Việt: gặp câu “đợi … rồi mới …”, “chờ đến khi … thì …” → nghĩ ngay tới 等……再 / 就……; 等 luôn đứng ĐẦU vế câu.","viDu":[{"zh":"如果聚餐时有老人，年轻人要等老人坐下后再坐。","py":"Rúguǒ jùcān shí yǒu lǎorén, niánqīngrén yào děng lǎorén zuòxia hòu zài zuò.","vn":"Nếu bữa tiệc có người già, người trẻ phải đợi người già ngồi xuống rồi mới ngồi."},{"zh":"等我写完作业，再跟你出去玩。","py":"Děng wǒ xiěwán zuòyè, zài gēn nǐ chūqu wán.","vn":"Đợi tớ làm xong bài tập rồi tớ đi chơi với cậu."},{"zh":"等我们到火车站的时候，火车已经开走了。","py":"Děng wǒmen dào huǒchēzhàn de shíhou, huǒchē yǐjīng kāizǒu le.","vn":"Đến lúc chúng tôi tới ga thì tàu đã chạy mất rồi."},{"zh":"等我们赶到电影院的时候，已经来不及了。","py":"Děng wǒmen gǎndào diànyǐngyuàn de shíhou, yǐjīng láibují le.","vn":"Đợi đến lúc chúng tôi chạy tới rạp thì đã không kịp nữa rồi. (ôn 来不及 — Bài 4 · điểm 4)"}],"loi":[{"sai":"我写完作业等，再跟你出去玩。","why":"等 đứng ĐẦU vế câu, trước sự việc phải đợi.","dung":"等我写完作业，再跟你出去玩。"},{"sai":"等我写完作业，我又跟你出去玩。","why":"Việc chưa xảy ra ở vế sau dùng 再 (rồi mới), không dùng 又.","dung":"等我写完作业，再跟你出去玩。"},{"sai":"等我们到火车站，火车开走了。","why":"“Đến lúc … thì đã …” cần 的时候 và 已经……了.","dung":"等我们到火车站的时候，火车已经开走了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["如果聚餐时有老人，年轻人要","老人坐下后再坐。"],"dap":[["等"]],"chon":["等","在","从"],"goiY":"“… người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","giai":"等 + sự việc + 后，再 + V."},{"kieu":"dien","phan":["等我写完作业，","跟你出去玩。"],"dap":[["再"]],"chon":["再","又","还"],"goiY":"“Đợi tớ làm xong bài rồi mới đi chơi với cậu.”","giai":"等……，再…… (việc chưa xảy ra)."},{"kieu":"dien","phan":["等我们到火车站的时候，火车","开走了。"],"dap":[["已经"]],"chon":["已经","正在","马上"],"goiY":"“… tàu đã chạy mất rồi.”","giai":"等……的时候，已经……了."},{"kieu":"dien","phan":["别着急，等我忙完了","去找你。"],"dap":[["就"]],"chon":["就","才","也"],"goiY":"“Đừng vội, đợi tớ xong việc thì sẽ đi tìm cậu.”","giai":"等……，就…… (đáp án gợi ý của sách)."},{"kieu":"dien","phan":["","我们赶到的时候，已经来不及了。"],"dap":[["等"]],"chon":["等","随着","要是"],"goiY":"“Đến lúc chúng tôi chạy tới thì đã không kịp rồi.” (ôn Bài 4)","giai":"等……的时候 + 来不及 (Bài 4 · điểm 4)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["等","我","写完作业","，","再","跟你","出去玩"],"dap":["等我写完作业，再跟你出去玩。"],"goiY":"Đợi tớ làm xong bài tập rồi đi chơi với cậu.","giai":"等……，再……"},{"kieu":"xep","manh":["年轻人","要","等","老人","坐下后","再坐"],"dap":["年轻人要等老人坐下后再坐。"],"goiY":"Người trẻ phải đợi người già ngồi xuống rồi mới ngồi.","giai":"Chủ ngữ + 要 + 等 + sự việc + 后 + 再 + V."},{"kieu":"dungsai","cau":"我写完作业等，再跟你出去玩。","dung":false,"sua":"等我写完作业，再跟你出去玩。","giai":"等 đứng đầu vế câu."},{"kieu":"dungsai","cau":"等我们到火车站的时候，火车已经开走了。","dung":true,"giai":"Đúng: 等……的时候，已经……了."},{"kieu":"dungsai","cau":"等你办了信用卡以后，你又能先花钱再还钱了。","dung":false,"sua":"等你办了信用卡以后，你就能先花钱再还钱了。","giai":"Kết quả khi điều kiện đạt được dùng 就, không dùng 又."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 55)","huongDan":"Hoàn thành câu, có dùng giới từ 等","cau":[{"kieu":"vandung","de":"别着急，＿＿＿就去找你。","goiY":"Đợi đến khi tớ làm xong việc","mau":"等我忙完了","can":[["等"]]},{"kieu":"vandung","de":"＿＿＿，你就能先花钱再还钱了。","goiY":"Đợi đến khi bạn làm thẻ tín dụng (信用卡 xìnyòngkǎ)","mau":"等你办了信用卡以后","can":[["等"]]},{"kieu":"vandung","de":"＿＿＿，走路十分钟就到公司了。","goiY":"Đợi đến khi tôi chuyển vào nhà mới","mau":"等我搬进新家以后","can":[["等"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đợi mọi người đến đủ rồi chúng ta mới bắt đầu ăn.","dap":["等大家都到了，我们再开始吃。","等大家都来了，我们再开始吃饭。","等大家都到了以后，我们再开始吃饭。","等大家都到了，我们再开始吃饭。"],"giai":"等……，再……"},{"kieu":"dich","vn":"Đợi tôi tốt nghiệp xong, tôi sẽ về nước làm giáo viên.","dap":["等我毕业以后，就回国当老师。","等我毕业了，就回国当老师。","等我毕业以后，我就回国当老师。"],"giai":"等……，就…… + 当 (Bài 1)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu nói về kế hoạch của em, có dùng 「等……，再 / 就……」","mau":"等我的中文达到HSK四级水平，就去中国读硕士。","can":[["等"],["再","就"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-6.html"] = [{"so":"1","ten":"形容词“厉害”","tenVn":"Tính từ 「厉害」 làm bổ ngữ mức độ — … dữ dội, … kinh khủng","cauTruc":["Động từ + 得 + (phó từ 很 / 太 / 特别) + 厉害","Tính từ + 得 + 厉害"],"giaiThich":"「厉害」 đặt sau động từ hoặc tính từ, nối bằng 「得」, biểu thị MỨC ĐỘ RẤT CAO — giống “… dữ dội / … kinh khủng / … quá chừng” trong tiếng Việt. Hay dùng cho cảm giác khó chịu hoặc hiện tượng mạnh: 疼得厉害, 咳得很厉害, 辣得厉害, 风刮得很厉害. Nếu động từ có tân ngữ thì lặp lại động từ: 咳嗽，咳得很厉害; 跑步跑多了. Mẹo cho người Việt: “đau lắm” → 很疼; “đau dữ lắm, đau kinh khủng” → 疼得厉害 (mạnh hơn). Trước 厉害 có thể thêm 很 / 太 / 特别, nhưng KHÔNG đặt 很 trước động từ / tính từ chính (✗ 很疼得厉害). Phân biệt: 厉害 làm vị ngữ một mình (你真厉害！) lại mang nghĩa “giỏi, đỉnh”.","viDu":[{"zh":"我还发烧，一直咳嗽，咳得很厉害。","py":"Wǒ hái fāshāo, yìzhí késou, ké de hěn lìhai.","vn":"Tớ còn sốt nữa, ho suốt, ho dữ lắm."},{"zh":"我昨天跑步跑多了，今天腿疼得厉害。","py":"Wǒ zuótiān pǎobù pǎo duō le, jīntiān tuǐ téng de lìhai.","vn":"Hôm qua tôi chạy bộ nhiều quá, hôm nay chân đau dữ dội."},{"zh":"这道菜辣得厉害，我吃了一口就不敢再吃了。","py":"Zhè dào cài là de lìhai, wǒ chī le yì kǒu jiù bù gǎn zài chī le.","vn":"Món này cay kinh khủng, tôi ăn một miếng là không dám ăn nữa."},{"zh":"我肚子疼得厉害，不仅吃不下饭，甚至连水都喝不了。","py":"Wǒ dùzi téng de lìhai, bùjǐn chī bu xià fàn, shènzhì lián shuǐ dōu hē bu liǎo.","vn":"Bụng tôi đau dữ dội, không những không ăn nổi cơm, thậm chí nước cũng không uống được. (ôn 不仅、甚至 – Bài 3; V不了 – Bài 4)"}],"loi":[{"sai":"我很疼得厉害。","why":"厉害 đã chỉ mức độ cao; 很 chỉ đặt trước 厉害, không đặt trước động từ / tính từ chính.","dung":"我疼得很厉害。"},{"sai":"他咳嗽得厉害很。","why":"Phó từ 很 đứng TRƯỚC 厉害, không đứng sau.","dung":"他咳嗽得很厉害。"},{"sai":"我跑步得很多，腿很厉害。","why":"Động từ có tân ngữ (跑步) phải lặp động từ; và cái “dữ dội” là cơn đau: 疼得厉害.","dung":"我跑步跑多了，腿疼得很厉害。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我还发烧，一直咳嗽，咳得很","。"],"dap":[["厉害"]],"chon":["厉害","有效","按时"],"goiY":"“… ho dữ lắm.”","giai":"V + 得 + 很 + 厉害."},{"kieu":"dien","phan":["我昨天跑步跑多了，今天腿疼","厉害。"],"dap":[["得"]],"chon":["得","的","地"],"goiY":"“… hôm nay chân đau dữ dội.”","giai":"Bổ ngữ mức độ nối bằng 得."},{"kieu":"dien","phan":["这道菜辣得","，我吃了一口就不敢再吃了。"],"dap":[["厉害"]],"chon":["厉害","好吃","一点儿"],"goiY":"“Món này cay kinh khủng …”","giai":"Adj + 得 + 厉害."},{"kieu":"dien","phan":["外面风刮","很厉害，咱们等会儿再走吧。"],"dap":[["得"]],"chon":["得","了","着"],"goiY":"“Gió thổi mạnh lắm, đợi lát nữa hãy đi.”","giai":"刮 + 得 + 很厉害."},{"kieu":"dien","phan":["我看你病得很厉害，","去医院看看吧。"],"dap":[["赶快"]],"chon":["赶快","偶尔","按时"],"goiY":"“… mau đi bệnh viện khám đi.” (ôn từ mới)","giai":"赶快 + V: giục làm ngay."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","肚子","疼","得","很厉害"],"dap":["我肚子疼得很厉害。"],"goiY":"Bụng tôi đau dữ dội.","giai":"Adj + 得 + 很厉害."},{"kieu":"xep","manh":["他","咳嗽","咳","得","特别厉害"],"dap":["他咳嗽咳得特别厉害。"],"goiY":"Anh ấy ho rất dữ.","giai":"Động từ có tân ngữ → lặp động từ."},{"kieu":"xep","manh":["今天","冷","得","厉害","，","多穿点儿衣服"],"dap":["今天冷得厉害，多穿点儿衣服。"],"goiY":"Hôm nay lạnh kinh khủng, mặc thêm áo vào.","giai":"Adj + 得 + 厉害."},{"kieu":"dungsai","cau":"这道菜辣得很厉害，我不敢吃。","dung":true,"giai":"Đúng: Adj + 得 + 很厉害."},{"kieu":"dungsai","cau":"我很疼得厉害。","dung":false,"sua":"我疼得很厉害。","giai":"很 đứng trước 厉害, không đứng trước 疼."},{"kieu":"dungsai","cau":"他咳嗽得厉害很。","dung":false,"sua":"他咳嗽得很厉害。","giai":"Phó từ 很 đứng trước 厉害."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 61)","huongDan":"Viết phần còn thiếu của B, có dùng 「……得（很）厉害」","cau":[{"kieu":"vandung","de":"A：外面刮风了，咱们是现在走还是过一会儿再走？ B：我看＿＿＿，咱们等会儿再走吧。","goiY":"Nói: gió thổi rất mạnh (刮……得很厉害)","mau":"风刮得很厉害","can":[["厉害"],["得"]]},{"kieu":"vandung","de":"A：我已经咳嗽好几天了，今天还有点儿发烧。 B：我看你＿＿＿，快去医院看看吧。","goiY":"Nói: bạn ốm nặng lắm (病得……厉害)","mau":"病得很厉害","can":[["厉害"],["得"]]},{"kieu":"vandung","de":"A：你怎么了？哪儿不舒服吗？ B：我刚吃完冰激凌，现在＿＿＿。","goiY":"Nói: bây giờ đau bụng dữ dội (肚子……)","mau":"肚子疼得厉害","can":[["厉害"],["得"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Hôm qua tôi ngủ muộn quá, hôm nay đầu đau dữ dội.","dap":["昨天我睡得太晚了，今天头疼得厉害。","我昨天睡得太晚了，今天头疼得很厉害。"],"giai":"头 + 疼 + 得 + (很) + 厉害."},{"kieu":"dich","vn":"Món này cay kinh khủng, có điều tôi vẫn ăn được.","dap":["这道菜辣得厉害，不过我吃得了。","这个菜辣得很厉害，不过我还吃得了。"],"giai":"辣得厉害 + ôn 不过 (Bài 2) và V得了 (Bài 4)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần em bị ốm, có dùng 「V / Adj + 得 + 厉害」","mau":"上个月我感冒了，咳嗽咳得很厉害，晚上都睡不好觉。","can":[["厉害"],["得"]]}]}]},{"so":"2","ten":"固定格式“（没）有什么（好）×的”","tenVn":"Cấu trúc cố định 「(没)有什么(好)×的」 — có gì mà phải …, chẳng có gì (đáng) …","cauTruc":["(A 跟 B) + 有什么 + 好 + động từ + 的 (câu hỏi tu từ)","没有什么 + (好) + động từ / tính từ + 的","没有什么 + 不 + động từ (不敢 / 不能…) + 的"],"giaiThich":"Cấu trúc này biểu thị KHÔNG CẦN THIẾT làm việc gì, hoặc không có lý do để có cảm giác / trạng thái nào đó. 「有什么好……的」 là câu hỏi tu từ (không cần trả lời) = “có gì mà phải …”; 「没有什么（好）……的」 là câu trần thuật = “chẳng có gì phải / đáng …”. 「好」 ở đây = “đáng, cần” (đáng để làm), sau nó là động từ: 好客气, 好担心, 好买, 好打扫. Không có 好 thì sau có thể là tính từ: 没有什么奇怪的. Thêm 「不」: 没有什么不敢的 = chẳng có gì là không dám. Mẹo cho người Việt: thấy “có gì mà phải khách sáo / lo / sợ” → 有什么好客气 / 担心 / 怕的. Dùng khi gạt đi lời cảm ơn, an ủi người khác, hoặc chê nhẹ (没有什么好看的). Nhớ: chữ 「的」 cuối câu là BẮT BUỘC.","viDu":[{"zh":"你跟我有什么好客气的。","py":"Nǐ gēn wǒ yǒu shénme hǎo kèqi de.","vn":"Cậu với tớ thì có gì mà phải khách sáo."},{"zh":"这种事在网上有很多，没有什么奇怪的。","py":"Zhè zhǒng shì zài wǎngshang yǒu hěn duō, méiyǒu shénme qíguài de.","vn":"Chuyện kiểu này trên mạng có nhiều lắm, chẳng có gì lạ cả."},{"zh":"我觉得这家商场里的东西都很一般，没有什么好买的。","py":"Wǒ juéde zhè jiā shāngchǎng lǐ de dōngxi dōu hěn yìbān, méiyǒu shénme hǎo mǎi de.","vn":"Tôi thấy đồ trong trung tâm thương mại này đều bình thường, chẳng có gì đáng mua."},{"zh":"考试并不难，没有什么好担心的，再说你已经准备得很好了。","py":"Kǎoshì bìng bù nán, méiyǒu shénme hǎo dānxīn de, Zàishuō nǐ yǐjīng zhǔnbèi de hěn hǎo le.","vn":"Kỳ thi thật ra không khó, chẳng có gì phải lo, hơn nữa bạn đã chuẩn bị rất tốt rồi. (ôn 并 – Bài 2; 再说 – Bài 4)"}],"loi":[{"sai":"你跟我有什么好客气。","why":"Thiếu 的 cuối câu — đây là cấu trúc cố định.","dung":"你跟我有什么好客气的。"},{"sai":"我没有什么好担心。","why":"Thiếu 的.","dung":"我没有什么好担心的。"},{"sai":"这种事没有什么奇怪的吗？","why":"Câu trần thuật 没有什么……的 không thêm 吗; muốn hỏi tu từ thì dùng 有什么……的？","dung":"这种事有什么奇怪的？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["你跟我有什么好","的。"],"dap":[["客气"]],"chon":["客气","厉害","严重"],"goiY":"“Cậu với tớ có gì mà phải khách sáo.”","giai":"有什么好 + V + 的."},{"kieu":"dien","phan":["这种事在网上有很多，没有什么奇怪","。"],"dap":[["的"]],"chon":["的","了","吗"],"goiY":"“… chẳng có gì lạ cả.”","giai":"Cuối câu bắt buộc có 的."},{"kieu":"dien","phan":["这家商场里的东西都很一般，没有什么","买的。"],"dap":[["好"]],"chon":["好","很","太"],"goiY":"“… chẳng có gì đáng mua.”","giai":"好 + V = đáng để làm."},{"kieu":"dien","phan":["我得的只是小感冒，没有什么好","的。"],"dap":[["担心"]],"chon":["担心","放心","高兴"],"goiY":"“Tớ chỉ bị cảm nhẹ, chẳng có gì phải lo.”","giai":"没有什么好担心的."},{"kieu":"dien","phan":["前天刚打扫过，还很干净，","什么好打扫的。"],"dap":[["没有"]],"chon":["没有","不是","不"],"goiY":"“… chẳng có gì phải dọn.”","giai":"Phủ định dùng 没有什么, không dùng 不什么."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["咱们","是","好朋友","，","没有什么","好","客气","的"],"dap":["咱们是好朋友，没有什么好客气的。"],"goiY":"Chúng mình là bạn thân, chẳng có gì phải khách sáo.","giai":"没有什么 + 好 + V + 的."},{"kieu":"xep","manh":["这个问题","很简单","，","有什么","好","讨论","的"],"dap":["这个问题很简单，有什么好讨论的？","这个问题很简单，有什么好讨论的。"],"goiY":"Vấn đề này đơn giản lắm, có gì mà phải bàn.","giai":"有什么好 + V + 的: hỏi tu từ."},{"kieu":"dungsai","cau":"你跟我有什么好客气的。","dung":true,"giai":"Đúng: câu hỏi tu từ, gạt đi lời cảm ơn."},{"kieu":"dungsai","cau":"这部电影很一般，没有什么好看。","dung":false,"sua":"这部电影很一般，没有什么好看的。","giai":"Thiếu 的 cuối câu."},{"kieu":"dungsai","cau":"考试很简单，没有什么好紧张的。","dung":true,"giai":"Đúng: 没有什么好 + V + 的."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 63)","huongDan":"Viết phần còn thiếu của B, có dùng 「（没）有什么（好）×的」","cau":[{"kieu":"vandung","de":"A：你怎么这么快就打扫完房间了？ B：前天刚打扫过，还很干净，＿＿＿。","goiY":"Nói: chẳng có gì phải dọn","mau":"没有什么好打扫的","can":[["没有什么","没什么"],["的"]]},{"kieu":"vandung","de":"A：你的病严重吗？我特别担心。 B：放心吧，我得的只是小感冒，＿＿＿。","goiY":"Nói: chẳng có gì phải lo","mau":"没有什么好担心的","can":[["没有什么","没什么"],["的"]]},{"kieu":"vandung","de":"A：你敢一个人看这个电影吗？我陪你一起看吧。 B：谢谢你，＿＿＿。","goiY":"Nói: chẳng có gì là không dám (没有什么不……的)","mau":"没有什么不敢的","can":[["没有什么","没什么"],["的"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chúng ta là bạn bè, có gì mà phải khách sáo.","dap":["我们是朋友，有什么好客气的。","咱们是朋友，有什么好客气的？"],"giai":"有什么好客气的."},{"kieu":"dich","vn":"Bộ phim này rất bình thường, chẳng có gì đáng xem.","dap":["这部电影很一般，没有什么好看的。","这个电影很一般，没什么好看的。"],"giai":"没有什么好看的."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em sắp thi HSK 4 và rất lo; hãy an ủi bạn bằng 「没有什么好……的」, kèm một lý do","mau":"你准备得那么好，没有什么好担心的，再说离考试还有一个月，来得及。","can":[["什么"],["的"]]}]}]},{"so":"3","ten":"频率副词“偶尔”","tenVn":"Phó từ tần suất 「偶尔」 — thỉnh thoảng, lâu lâu mới","cauTruc":["Chủ ngữ + 偶尔 + (才 / 会 / 也) + động từ","平时 / 一般 / 经常……，偶尔（才 / 也）……"],"giaiThich":"「偶尔」 cho biết hành động / tình huống xảy ra RẤT ÍT LẦN. Hay dùng theo cặp đối lập: vế trước nói việc thường làm (一般, 平时, 经常), vế sau nói việc lâu lâu mới làm (偶尔才…… / 偶尔会…… / 偶尔也……). 「才」 nhấn mạnh “hiếm khi”, 「也」 nhấn mạnh “cũng có lúc”. Vị trí: trước động từ (sau chủ ngữ hoặc đầu câu), KHÔNG đứng sau động từ. Thang tần suất: 总是 > 经常 > 有时候 > 偶尔 > 从来不. Hán Việt “ngẫu nhĩ”; đừng nhầm với 偶然 (ngẫu nhiên, tình cờ). Chú ý động từ li hợp: 生一次病 (không nói 生病一次).","viDu":[{"zh":"她告诉医生，自己平时身体不错，偶尔才会生一次病。","py":"Tā gàosu yīshēng, zìjǐ píngshí shēntǐ búcuò, ǒu'ěr cái huì shēng yí cì bìng.","vn":"Cô ấy nói với bác sĩ rằng bình thường mình khá khỏe, lâu lâu mới ốm một lần."},{"zh":"他经常在家看电影，偶尔才去电影院看。","py":"Tā jīngcháng zài jiā kàn diànyǐng, ǒu'ěr cái qù diànyǐngyuàn kàn.","vn":"Anh ấy hay xem phim ở nhà, thỉnh thoảng mới ra rạp xem."},{"zh":"我一般都在学校食堂吃饭，偶尔会跟朋友一起出去吃。","py":"Wǒ yìbān dōu zài xuéxiào shítáng chīfàn, ǒu'ěr huì gēn péngyou yìqǐ chūqu chī.","vn":"Tôi thường ăn ở nhà ăn của trường, thỉnh thoảng đi ăn ngoài với bạn."},{"zh":"我和室友平时各做各的饭，偶尔才一起出去吃。","py":"Wǒ hé shìyǒu píngshí gè zuò gè de fàn, ǒu'ěr cái yìqǐ chūqu chī.","vn":"Tôi và bạn cùng phòng bình thường ai nấu cơm nấy, thỉnh thoảng mới cùng ra ngoài ăn. (ôn 各V各的 – Bài 5 · điểm 3)"}],"loi":[{"sai":"我吃偶尔辣的菜。","why":"偶尔 đứng trước động từ.","dung":"我偶尔吃辣的菜。"},{"sai":"他偶尔经常去图书馆。","why":"偶尔 và 经常 trái nghĩa, không dùng chung.","dung":"他偶尔去图书馆。"},{"sai":"她偶尔才生病一次。","why":"生病 là động từ li hợp: số lần chen vào giữa.","dung":"她偶尔才生一次病。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["她平时身体不错，","才会生一次病。"],"dap":[["偶尔"]],"chon":["偶尔","经常","总是"],"goiY":"“… lâu lâu mới ốm một lần.”","giai":"偶尔 + 才: hiếm khi."},{"kieu":"dien","phan":["他经常在家看电影，偶尔","去电影院看。"],"dap":[["才"]],"chon":["才","就","都"],"goiY":"“… thỉnh thoảng mới ra rạp.”","giai":"偶尔才 + V."},{"kieu":"dien","phan":["我一般都在学校食堂吃饭，","会跟朋友一起出去吃。"],"dap":[["偶尔"]],"chon":["偶尔","一直","按时"],"goiY":"“… thỉnh thoảng đi ăn ngoài với bạn.”","giai":"一般……，偶尔……"},{"kieu":"dien","phan":["我喜欢吃辣的菜，不过偶尔","想吃点儿甜的。"],"dap":[["也"]],"chon":["也","才","就"],"goiY":"“… có điều thỉnh thoảng cũng muốn ăn đồ ngọt.”","giai":"偶尔也 = cũng có lúc."},{"kieu":"dien","phan":["医生让她回家以后","吃药，多喝水，多休息。"],"dap":[["按时"]],"chon":["按时","偶尔","光"],"goiY":"“… uống thuốc đúng giờ.” (phân biệt với 偶尔)","giai":"Uống thuốc phải 按时, không thể 偶尔."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","一般","坐地铁","，","偶尔","才","打车"],"dap":["我一般坐地铁，偶尔才打车。"],"goiY":"Tôi thường đi tàu điện ngầm, thỉnh thoảng mới đi taxi.","giai":"一般……，偶尔才……"},{"kieu":"xep","manh":["他","平时","不喝酒","，","偶尔","会","喝一点儿"],"dap":["他平时不喝酒，偶尔会喝一点儿。"],"goiY":"Bình thường anh ấy không uống rượu, thỉnh thoảng uống một chút.","giai":"偶尔会 + V."},{"kieu":"dungsai","cau":"我吃偶尔辣的菜。","dung":false,"sua":"我偶尔吃辣的菜。","giai":"偶尔 đứng trước động từ."},{"kieu":"dungsai","cau":"她身体很好，偶尔才生一次病。","dung":true,"giai":"Đúng: 偶尔才 + 生一次病."},{"kieu":"dungsai","cau":"他每天都偶尔去跑步。","dung":false,"sua":"他偶尔去跑步。","giai":"每天都 (ngày nào cũng) mâu thuẫn với 偶尔."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 65)","huongDan":"Hoàn thành câu với 「偶尔」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"我一般坐公交车，＿＿＿来学校。（自行车）","goiY":"Thỉnh thoảng đạp xe đạp","mau":"偶尔骑自行车","can":[["偶尔"],["自行车"]]},{"kieu":"vandung","de":"我喜欢吃辣的菜，不过＿＿＿。（甜）","goiY":"Thỉnh thoảng cũng muốn ăn chút đồ ngọt","mau":"偶尔也想吃点儿甜的","can":[["偶尔"],["甜"]]},{"kieu":"vandung","de":"我一般在网上买东西，＿＿＿。（商场）","goiY":"Thỉnh thoảng mới đến trung tâm thương mại mua","mau":"偶尔才去商场买","can":[["偶尔"],["商场"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi thường học ở thư viện, thỉnh thoảng mới học ở ký túc xá.","dap":["我经常在图书馆学习，偶尔才在宿舍学习。","我一般在图书馆学习，偶尔才在宿舍学习。"],"giai":"经常 / 一般……，偶尔才……"},{"kieu":"dich","vn":"Anh ấy rất ít khi ốm, thỉnh thoảng mới bị cảm một lần.","dap":["他很少生病，偶尔才感冒一次。","他很少生病，偶尔才会感冒一次。"],"giai":"偶尔才 + V + 一次."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể thói quen của em: việc thường làm và việc thỉnh thoảng mới làm, có dùng 「一般……，偶尔……」","mau":"我一般在家做饭，偶尔才去饭馆吃，因为在家做饭既便宜又健康。","can":[["偶尔"]]}]}]},{"so":"4","ten":"目的复句“……，好……”","tenVn":"Câu phức mục đích 「……，好……」 — …, để (tiện / dễ) …","cauTruc":["Vế 1 (việc làm)，(chủ ngữ / trạng ngữ) + 好 + vế 2 (mục đích)"],"giaiThich":"Vế trước nói một hành động / tình huống, vế sau bắt đầu bằng 「好」 nói MỤC ĐÍCH: làm việc ở vế trước ĐỂ việc ở vế sau dễ dàng / có thể thực hiện. 「好」 ở đây = “để, để tiện” (≈ 以便 trong văn viết), đứng ngay trước động từ của vế sau; nếu vế sau có chủ ngữ hoặc trạng ngữ thời gian thì 好 đứng sau chúng: 以后有什么事好联系我; 明天好陪你出去玩. So sánh với 为了 (HSK 3): 为了 nêu mục đích ở ĐẦU câu (为了……，……), còn 好 nêu mục đích ở CUỐI câu. Mẹo cho người Việt: “…, để còn …” → ……，好……. Chú ý 好 này đọc hǎo, không mang nghĩa “tốt”, và cũng khác 好好 (cẩn thận, chăm chỉ).","viDu":[{"zh":"医生有时还会做一些检查，好给出合适的治疗方法。","py":"Yīshēng yǒushí hái huì zuò yìxiē jiǎnchá, hǎo gěichū héshì de zhìliáo fāngfǎ.","vn":"Bác sĩ có lúc còn làm một số xét nghiệm, để đưa ra cách điều trị phù hợp."},{"zh":"你们先了解一下情况，好做出决定。","py":"Nǐmen xiān liǎojiě yíxià qíngkuàng, hǎo zuòchū juédìng.","vn":"Các bạn tìm hiểu tình hình trước đã, để còn ra quyết định."},{"zh":"我把电话号码告诉你，以后有什么事好联系我。","py":"Wǒ bǎ diànhuà hàomǎ gàosu nǐ, yǐhòu yǒu shénme shì hǎo liánxì wǒ.","vn":"Tôi cho bạn số điện thoại, sau này có việc gì thì tiện liên lạc với tôi."},{"zh":"你早点儿出发，好来得及去机场接朋友。","py":"Nǐ zǎodiǎnr chūfā, hǎo láidejí qù jīchǎng jiē péngyou.","vn":"Bạn xuất phát sớm một chút, để kịp ra sân bay đón bạn. (ôn 来得及 – Bài 4 · điểm 4)"}],"loi":[{"sai":"好让他们放心，我每天给家人打电话。","why":"Vế 好 nêu mục đích luôn đứng SAU vế chỉ việc làm.","dung":"我每天给家人打电话，好让他们放心。"},{"sai":"我把电话号码告诉你，好以后有什么事联系我。","why":"好 phải đứng ngay trước động từ chỉ mục đích (联系), sau trạng ngữ 以后有什么事.","dung":"我把电话号码告诉你，以后有什么事好联系我。"},{"sai":"你们先了解一下情况，好好做出决定。","why":"好好 = “cho tốt, cẩn thận”, khác 好 chỉ mục đích; muốn nói “để ra quyết định” chỉ dùng một 好.","dung":"你们先了解一下情况，好做出决定。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["医生有时还会做一些检查，","给出合适的治疗方法。"],"dap":[["好"]],"chon":["好","就","才"],"goiY":"“… để đưa ra cách điều trị phù hợp.”","giai":"……，好 + V (mục đích)."},{"kieu":"dien","phan":["你们先了解一下","，好做出决定。"],"dap":[["情况"]],"chon":["情况","过程","结果"],"goiY":"“Các bạn tìm hiểu tình hình trước …”","giai":"了解 + 情况."},{"kieu":"dien","phan":["我把电话号码告诉你，以后有什么事","联系我。"],"dap":[["好"]],"chon":["好","再","又"],"goiY":"“… sau này có việc gì thì tiện liên lạc với tôi.”","giai":"好 đứng ngay trước động từ 联系."},{"kieu":"dien","phan":["我每天都给家人打电话，好","他们放心。"],"dap":[["让"]],"chon":["让","被","把"],"goiY":"“… để họ yên tâm.”","giai":"好 + 让 + ai + Adj."},{"kieu":"dien","phan":["在中国看病要先","，然后再去找医生。"],"dap":[["挂号"]],"chon":["挂号","打针","收费"],"goiY":"“Khám bệnh ở Trung Quốc phải lấy số trước …” (ôn từ mới)","giai":"先挂号，然后再看病."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你","早点儿","睡","，","明天","好","早起"],"dap":["你早点儿睡，明天好早起。"],"goiY":"Bạn ngủ sớm đi, để mai còn dậy sớm.","giai":"Trạng ngữ 明天 + 好 + V."},{"kieu":"xep","manh":["请","留下","你的地址","，","我们","好","给你寄东西"],"dap":["请留下你的地址，我们好给你寄东西。"],"goiY":"Xin để lại địa chỉ, để chúng tôi tiện gửi đồ cho bạn.","giai":"Chủ ngữ 我们 + 好 + V."},{"kieu":"dungsai","cau":"我把电话号码告诉你，以后有什么事好联系我。","dung":true,"giai":"Đúng: 好 đứng trước 联系."},{"kieu":"dungsai","cau":"好让他们放心，我每天给家人打电话。","dung":false,"sua":"我每天给家人打电话，好让他们放心。","giai":"Vế 好 (mục đích) đặt sau."},{"kieu":"dungsai","cau":"你先在大厅休息，我去排队挂号，好节省时间。","dung":true,"giai":"Đúng: vế cuối 好 + V nêu mục đích."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 67)","huongDan":"Hoàn thành câu, dùng 「……，好……」","cau":[{"kieu":"vandung","de":"我每天都给家人打电话，＿＿＿。","goiY":"Mục đích: để gia đình yên tâm","mau":"好让他们放心","can":[["好"]]},{"kieu":"vandung","de":"你要早点儿准备好材料，＿＿＿。","goiY":"Mục đích: để trước cuộc họp đưa giám đốc xem","mau":"好在开会前给经理看一下","can":[["好"]]},{"kieu":"vandung","de":"我今天就把工作做完，明天＿＿＿。","goiY":"Mục đích: để mai đi chơi với bạn","mau":"好陪你出去玩","can":[["好"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bạn mang theo hộ chiếu, để tiện đi lấy số.","dap":["你带上护照，好去挂号。","你把护照带上，好去挂号。"],"giai":"……，好 + V."},{"kieu":"dich","vn":"Tôi ghi lại các bước nấu món ăn, để lần sau dễ làm.","dap":["我把做菜的过程写下来，下次好做。","我把做菜的过程记下来，下次好做。"],"giai":"Trạng ngữ 下次 + 好 + V."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói một việc em chuẩn bị trước khi đi khám bệnh hoặc đi du lịch và mục đích của nó, có dùng 「……，好……」","mau":"去医院以前，我先在网上挂了号，好不用排队，再说也能节省很多时间。","can":[["好"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-7.html"] = [{"so":"1","ten":"固定格式“在……方面”","tenVn":"Cấu trúc cố định 「在……方面」 — về mặt …, trong lĩnh vực …","cauTruc":["在 + danh từ / cụm danh từ + 方面，+ nhận xét / câu hỏi","Chủ ngữ + 在 + N + 方面 + (很 / 比较 / 还不太) + tính từ / động từ"],"giaiThich":"「在……方面」 dùng để GIỚI HẠN phạm vi, lĩnh vực đang bàn: “về mặt …, xét về …”. Giữa 在 và 方面 thường là danh từ hai âm tiết hoặc cụm danh từ: 内容, 时间安排, 生活, 学习, 价格, 语言交流… Vị trí: đứng ĐẦU câu (sau có dấu phẩy) hoặc sau chủ ngữ, TRƯỚC vị ngữ. Mẹo cho người Việt: tiếng Việt hay nói “anh ấy giỏi VỀ MẶT học tập” (cụm “về mặt” đứng sau), nhưng tiếng Trung phải đưa lên trước: 他在学习方面很好. Từ 方面 các em đã gặp ở Bài 1 (từ mới) và trong 一方面……，另一方面…… (Bài 1 · điểm 4) — cấu trúc đó dùng để liệt kê HAI mặt, còn 在……方面 chỉ khoanh vùng MỘT mặt. Không thêm 上 sau 方面 (✗ 在学习方面上).","viDu":[{"zh":"在内容方面，您觉得有需要改的吗？","py":"Zài nèiróng fāngmiàn, nín juéde yǒu xūyào gǎi de ma?","vn":"Về mặt nội dung, chị thấy có chỗ nào cần sửa không ạ?"},{"zh":"在时间安排方面，你可以再想一想。","py":"Zài shíjiān ānpái fāngmiàn, nǐ kěyǐ zài xiǎng yi xiǎng.","vn":"Về mặt sắp xếp thời gian, bạn có thể nghĩ thêm một chút."},{"zh":"他才来中国两个月，在生活方面，还不太习惯。","py":"Tā cái lái Zhōngguó liǎng gè yuè, zài shēnghuó fāngmiàn, hái bú tài xíguàn.","vn":"Anh ấy mới đến Trung Quốc có hai tháng, về mặt sinh hoạt vẫn chưa quen lắm."},{"zh":"要是在生活方面有什么困难，就及时告诉我。","py":"Yàoshi zài shēnghuó fāngmiàn yǒu shénme kùnnan, jiù jíshí gàosu wǒ.","vn":"Nếu về mặt sinh hoạt có khó khăn gì thì báo tôi ngay nhé. (ôn 要是……就…… – Bài 1 · điểm 2)"}],"loi":[{"sai":"他很努力在学习方面。","why":"Bắt chước trật tự tiếng Việt “chăm chỉ về mặt học tập”; tiếng Trung đặt 在……方面 TRƯỚC vị ngữ.","dung":"他在学习方面很努力。"},{"sai":"在生活方面上，他还不太习惯。","why":"Thừa 上 — đã có 方面 thì không thêm 上 (lẫn với 在……上).","dung":"在生活方面，他还不太习惯。"},{"sai":"在方面内容，您觉得有需要改的吗？","why":"Danh từ phải đứng GIỮA 在 và 方面.","dung":"在内容方面，您觉得有需要改的吗？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","内容方面，您觉得有需要改的吗？"],"dap":[["在"]],"chon":["在","从","对"],"goiY":"“Về mặt nội dung, chị thấy có chỗ nào cần sửa không?”","giai":"Cấu trúc cố định: 在 + N + 方面."},{"kieu":"dien","phan":["在时间安排","，你可以再想一想。"],"dap":[["方面"]],"chon":["方面","一方面","地方"],"goiY":"“Về mặt sắp xếp thời gian …”","giai":"在……方面 khoanh vùng một mặt; 一方面 dùng khi liệt kê hai mặt (Bài 1)."},{"kieu":"dien","phan":["他才来中国两个月，在生活方面，还不太","。"],"dap":[["习惯"]],"chon":["习惯","经验","产品"],"goiY":"“… về mặt sinh hoạt vẫn chưa quen lắm.”","giai":"不太习惯 = chưa quen lắm."},{"kieu":"dien","phan":["在价格方面，网购","比商店便宜。"],"dap":[["往往"]],"chon":["往往","及时","提前"],"goiY":"“Về mặt giá cả, mua trên mạng thường rẻ hơn cửa hàng.” (ôn 往往 – Bài 4)","giai":"往往 = thường thường (theo quy luật)."},{"kieu":"dien","phan":["我儿子在学习方面","很好。"],"dap":[["表现"]],"chon":["表现","效果","内容"],"goiY":"“Con trai tôi về mặt học tập thể hiện rất tốt.” (ôn 表现 – Bài 1)","giai":"表现很好 = biểu hiện / thể hiện tốt."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["在","内容","方面","，","您","觉得","有需要改的吗"],"dap":["在内容方面，您觉得有需要改的吗？"],"goiY":"Về mặt nội dung, chị thấy có chỗ nào cần sửa không?","giai":"在 + N + 方面 đứng đầu câu."},{"kieu":"xep","manh":["她","在","工作","方面","既","细心","又","认真"],"dap":["她在工作方面既细心又认真。"],"goiY":"Về mặt công việc, cô ấy vừa cẩn thận vừa nghiêm túc.","giai":"Chủ ngữ + 在……方面 + vị ngữ; ôn 既……又…… (Bài 4)."},{"kieu":"xep","manh":["在","生活","方面","，","他","还","不太习惯"],"dap":["在生活方面，他还不太习惯。","他在生活方面还不太习惯。"],"goiY":"Về mặt sinh hoạt, anh ấy vẫn chưa quen lắm.","giai":"在……方面 đứng đầu câu hoặc sau chủ ngữ."},{"kieu":"dungsai","cau":"他在交流方面能力很强。","dung":true,"giai":"Đúng: 在交流方面 đứng trước vị ngữ."},{"kieu":"dungsai","cau":"她很细心在工作方面。","dung":false,"sua":"她在工作方面很细心。","giai":"在……方面 phải đứng TRƯỚC vị ngữ 很细心."},{"kieu":"dungsai","cau":"在学习方面上，他的表现很好。","dung":false,"sua":"在学习方面，他的表现很好。","giai":"Không thêm 上 sau 方面."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 73)","huongDan":"Viết câu trả lời của B, có dùng 「在……方面」","cau":[{"kieu":"vandung","de":"A：你建议我去医院的国际部看病吗？ B：＿＿＿。","goiY":"Nói hai mặt: về mặt giao tiếp ngôn ngữ thì tiện hơn; nhưng về mặt giá cả thì đắt hơn","mau":"在语言交流方面，去国际部看病更方便；但是在价格方面，在国际部看病也更贵","can":[["在"],["方面"]]},{"kieu":"vandung","de":"A：为什么现在很多人都喜欢骑电动车？ B：＿＿＿。","goiY":"Giải thích: xe điện tiện về mặt sạc điện (ôn 电动车, 充电 – Bài 4)","mau":"因为电动车在充电方面是很方便的","can":[["在"],["方面"]]},{"kieu":"vandung","de":"A：老师，我儿子最近在学校的表现怎么样？ B：＿＿＿。","goiY":"Khen: về mặt học tập, cậu bé thể hiện rất tốt","mau":"在学习方面，他的表现很好","can":[["在"],["方面"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Về mặt nội dung, bản kế hoạch này chẳng có gì phải sửa.","dap":["在内容方面，这个计划书没有什么好改的。","在内容方面，这个计划没有什么好改的。","这个计划书在内容方面没有什么好改的。"],"giai":"在……方面 + 没有什么好×的 (Bài 6 · điểm 2)."},{"kieu":"dich","vn":"Về mặt giá cả, mua trên mạng thường rẻ hơn ở cửa hàng.","dap":["在价格方面，网购往往比商店便宜。","在价格方面，网购往往比在商店买便宜。","在价格方面，网购一般比商店便宜。"],"giai":"在价格方面 + 往往 (Bài 4) + câu so sánh 比."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nhận xét một người bạn / đồng nghiệp: về mặt nào giỏi, về mặt nào còn cần cố gắng — dùng 「在……方面」","mau":"我的同事在工作方面很细心，不过在交流方面还需要多努力。","can":[["在"],["方面"]]}]}]},{"so":"2","ten":"因果复句“既然……，就……”","tenVn":"Câu phức nhân quả 「既然……，就……」 — đã … thì …","cauTruc":["既然 + tiền đề (sự thật đã biết)，(chủ ngữ) + 就 / 也 / 还 + kết luận","Chủ ngữ + 既然 + tiền đề，就 + kết luận (lời khuyên, đề nghị, quyết định)"],"giaiThich":"Vế trước nêu một TIỀN ĐỀ — sự thật đã xảy ra hoặc hai bên đều đã biết; vế sau là KẾT LUẬN suy ra từ tiền đề đó, thường là lời khuyên, đề nghị, quyết định (hay kết thúc bằng 吧). Tiếng Việt: “đã … thì …”. So sánh: 因为……所以…… kể nguyên nhân → kết quả khách quan; 既然 nhấn mạnh “sự thật đã như thế rồi thì nên …”. 要是 / 如果……就…… (Bài 1) là GIẢ THIẾT, việc chưa xảy ra: ✗ 既然明天下雨 → ✓ 要是明天下雨. Phó từ 就 đứng SAU chủ ngữ vế sau: 既然大家都同意，我们就这么做吧. Đừng nhầm 既然 với 既……又…… (Bài 4 · điểm 3).","viDu":[{"zh":"既然出差时间不长，就要安排好时间，多获得有用的信息。","py":"Jìrán chūchāi shíjiān bù cháng, jiù yào ānpái hǎo shíjiān, duō huòdé yǒuyòng de xìnxī.","vn":"Đã đi công tác không lâu thì phải sắp xếp thời gian cho tốt, thu được nhiều thông tin hữu ích."},{"zh":"既然大家都同意，我们就这么做吧。","py":"Jìrán dàjiā dōu tóngyì, wǒmen jiù zhème zuò ba.","vn":"Mọi người đã đồng ý cả thì chúng ta làm như vậy đi."},{"zh":"既然你们已经决定了，就不要再改了。","py":"Jìrán nǐmen yǐjīng juédìng le, jiù búyào zài gǎi le.","vn":"Các bạn đã quyết định rồi thì đừng sửa nữa."},{"zh":"既然来不及了，我们就坐出租车去吧。","py":"Jìrán láibují le, wǒmen jiù zuò chūzūchē qù ba.","vn":"Đã không kịp nữa rồi thì chúng ta đi taxi thôi. (ôn 来不及 – Bài 4 · điểm 4)"}],"loi":[{"sai":"既然明天下雨，我们就不去了。","why":"既然 dùng cho sự thật ĐÃ biết; việc chưa chắc xảy ra là giả thiết → 要是 / 如果.","dung":"要是明天下雨，我们就不去了。"},{"sai":"既然大家都同意，就我们这么做吧。","why":"就 là phó từ, đứng SAU chủ ngữ của vế sau.","dung":"既然大家都同意，我们就这么做吧。"},{"sai":"既然你不舒服，所以回家休息吧。","why":"既然 đi với 就 / 也 / 还, không đi với 所以.","dung":"既然你不舒服，就回家休息吧。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","出差时间不长，就要安排好时间。"],"dap":[["既然"]],"chon":["既然","虽然","不但"],"goiY":"“Đã đi công tác không lâu thì …”","giai":"既然……，就……: tiền đề → kết luận."},{"kieu":"dien","phan":["既然大家都同意，我们","这么做吧。"],"dap":[["就"]],"chon":["就","才","都"],"goiY":"“… thì chúng ta làm như vậy đi.”","giai":"就 đứng sau chủ ngữ 我们."},{"kieu":"dien","phan":["既然你们已经决定了，就不要再","了。"],"dap":[["改"]],"chon":["改","谈","管理"],"goiY":"“… thì đừng sửa nữa.”","giai":"不要再改了 = đừng sửa nữa."},{"kieu":"dien","phan":["既然你有这方面的","，就给我们介绍一下吧。"],"dap":[["经验"]],"chon":["经验","产品","市场"],"goiY":"“Bạn đã có kinh nghiệm về mặt này thì giới thiệu cho chúng tôi đi.”","giai":"有……方面的经验."},{"kieu":"dien","phan":["既然","了，我们就坐出租车去吧。"],"dap":[["来不及"]],"chon":["来不及","来得及","来不了"],"goiY":"“Đã không kịp nữa thì đi taxi thôi.” (ôn Bài 4)","giai":"来不及 = không kịp (thời gian)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["既然","大家","都同意","，","我们","就","这么做吧"],"dap":["既然大家都同意，我们就这么做吧。"],"goiY":"Mọi người đã đồng ý cả thì chúng ta làm như vậy đi.","giai":"既然……，Sub + 就……"},{"kieu":"xep","manh":["既然","你","不舒服","，","就","回家","休息吧"],"dap":["既然你不舒服，就回家休息吧。","你既然不舒服，就回家休息吧。"],"goiY":"Bạn đã không khỏe thì về nhà nghỉ đi.","giai":"既然 có thể đứng trước hoặc sau chủ ngữ."},{"kieu":"xep","manh":["既然","出差时间","不长","，","就要","安排好","时间"],"dap":["既然出差时间不长，就要安排好时间。"],"goiY":"Đã đi công tác không lâu thì phải sắp xếp thời gian cho tốt.","giai":"Câu trong bài khoá 2."},{"kieu":"dungsai","cau":"既然你已经决定了，我也不说什么了。","dung":true,"giai":"Đúng: vế sau có thể dùng 也."},{"kieu":"dungsai","cau":"既然他生病了，所以没来上课。","dung":false,"sua":"因为他生病了，所以没来上课。","giai":"Kể nguyên nhân – kết quả khách quan dùng 因为……所以……; vế sau của 既然 là kết luận / đề nghị."},{"kieu":"dungsai","cau":"既然下雨了，就咱们不出去了吧。","dung":false,"sua":"既然下雨了，咱们就不出去了吧。","giai":"就 đứng sau chủ ngữ 咱们."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 75)","huongDan":"Viết câu trả lời của B theo mẫu 「既然……，就……」","cau":[{"kieu":"vandung","de":"A：老师，我有点儿不舒服。 B：＿＿＿，＿＿＿。","goiY":"Đã không khỏe thì về nhà nghỉ đi","mau":"既然不舒服，就回家休息吧","can":[["既然"],["就"]]},{"kieu":"vandung","de":"A：外面下雨了，咱们还出去吗？ B：＿＿＿，＿＿＿。","goiY":"Đã mưa rồi thì thôi không ra ngoài","mau":"既然下雨了，就不出去了吧","can":[["既然"],["就"]]},{"kieu":"vandung","de":"A：我觉得这个工作没什么发展机会。 B：＿＿＿，＿＿＿。","goiY":"Đã không có cơ hội phát triển thì đổi việc khác đi","mau":"既然没有发展机会，就换一个工作吧","can":[["既然"],["就"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đã đến rồi thì ngồi thêm một lúc nữa đi.","dap":["既然来了，就再坐一会儿吧。","你既然来了，就再坐一会儿吧。","既然来了，就多坐一会儿吧。"],"giai":"既然……，就…… + 吧 (lời mời, đề nghị)."},{"kieu":"dich","vn":"Đã không có cơ hội phát triển thì đổi một công việc khác đi.","dap":["既然没有发展机会，就换一个工作吧。","既然没有发展机会，就换一份工作吧。","既然没什么发展机会，就换一个工作吧。"],"giai":"Đáp án gợi ý của sách; 一份工作 (lượng từ 份 – từ mới)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em nói vừa thi xong. Hãy đưa ra một đề nghị bằng 「既然……，就……」","mau":"既然考完试了，我们就出去好好玩儿一天吧。","can":[["既然"],["就"]]}]}]},{"so":"3","ten":"固定格式“拿……来说”","tenVn":"Cấu trúc cố định 「拿……来说」 — lấy … mà nói, ví dụ như …","cauTruc":["Câu nhận định chung。拿 + ví dụ cụ thể + 来说，+ câu nói rõ ví dụ","拿 + danh từ / cụm động từ (和客户交流 / 购物 / 吃饭) + 来说，……"],"giaiThich":"「拿……来说」 dùng để đưa ra MỘT ví dụ, một mặt cụ thể nhằm làm rõ nhận định chung vừa nói. Thường câu trước là nhận định khái quát (现在的生活很方便 / 南北方的生活习惯不同), câu sau mở bằng 拿……来说 rồi phân tích chi tiết. Giữa 拿 và 来说 là danh từ hoặc cụm động từ. Tiếng Việt: “lấy … mà nói / như … chẳng hạn”. So sánh: 比如 (HSK 3) liệt kê ví dụ ngắn gọn; 拿……来说 dẫn một ví dụ rồi nói kỹ. Đừng nhầm với 对……来说 (Bài 2 có câu 对白家月来说): “đối với ai mà nói” — nêu góc nhìn, cảm nhận của một người (对我来说，汉字很难). Không bỏ 来 (✗ 拿购物说).","viDu":[{"zh":"拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","py":"Ná hé kèhù jiāoliú láishuō, suīrán tā néng bǎ chǎnpǐn de yōu quēdiǎn shuō de hěn qīngchu, dàn shíjì xiàoguǒ bìng bù lǐxiǎng.","vn":"Lấy việc trao đổi với khách hàng mà nói, tuy cô ấy nói rất rõ ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế chẳng lý tưởng chút nào."},{"zh":"现在的生活很方便。拿购物来说，人们不出门就能买到想要的东西。","py":"Xiànzài de shēnghuó hěn fāngbiàn. Ná gòuwù láishuō, rénmen bù chūmén jiù néng mǎidào xiǎng yào de dōngxi.","vn":"Cuộc sống bây giờ rất tiện. Lấy mua sắm mà nói, người ta không ra khỏi nhà cũng mua được thứ mình muốn."},{"zh":"在中国，南北方的生活习惯不同。拿吃饭来说，一般南方人更爱吃米饭。","py":"Zài Zhōngguó, nán běifāng de shēnghuó xíguàn bùtóng. Ná chīfàn láishuō, yìbān nánfāngrén gèng ài chī mǐfàn.","vn":"Ở Trung Quốc, thói quen sinh hoạt miền Nam và miền Bắc khác nhau. Lấy chuyện ăn uống mà nói, người miền Nam thường thích ăn cơm hơn."},{"zh":"我们班同学各有各的爱好。拿我来说，我最喜欢看电影。","py":"Wǒmen bān tóngxué gè yǒu gè de àihào. Ná wǒ láishuō, wǒ zuì xǐhuan kàn diànyǐng.","vn":"Các bạn lớp tôi mỗi người một sở thích. Lấy tôi làm ví dụ, tôi thích xem phim nhất. (ôn 各×各的 – Bài 5 · điểm 3)"}],"loi":[{"sai":"拿购物说，人们不出门就能买到想要的东西。","why":"Thiếu 来 — cấu trúc cố định là 拿……来说.","dung":"拿购物来说，人们不出门就能买到想要的东西。"},{"sai":"拿我来说，汉字很难。","why":"Muốn nói “đối với tôi (cảm nhận của tôi)” → dùng 对……来说; 拿……来说 dùng để dẫn ví dụ cho một nhận định chung.","dung":"对我来说，汉字很难。"},{"sai":"拿吃饭来说，在中国南北方的生活习惯不同。","why":"Câu nhận định chung nên đứng TRƯỚC, ví dụ 拿……来说 đứng sau để làm rõ.","dung":"在中国，南北方的生活习惯不同。拿吃饭来说，一般南方人更爱吃米饭。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["现在的生活很方便。","购物来说，人们不出门就能买到想要的东西。"],"dap":[["拿"]],"chon":["拿","对","把"],"goiY":"“Lấy mua sắm mà nói …”","giai":"Dẫn ví dụ → 拿……来说."},{"kieu":"dien","phan":["在中国，南北方的生活习惯不同。拿吃饭来","，一般南方人更爱吃米饭。"],"dap":[["说"]],"chon":["说","看","想"],"goiY":"“Lấy chuyện ăn uống mà nói …”","giai":"Cấu trúc cố định 拿……来说."},{"kieu":"dien","phan":["她也遇到了一些困难。拿和客户","来说，实际效果并不理想。"],"dap":[["交流"]],"chon":["交流","产品","效果"],"goiY":"“Lấy việc trao đổi với khách hàng mà nói …”","giai":"Giữa 拿 và 来说 có thể là cụm động từ: 和客户交流."},{"kieu":"dien","phan":["网购有很多优点。拿","来说，今天买的东西明天就能收到。"],"dap":[["速度"]],"chon":["速度","能力","基础"],"goiY":"“Lấy tốc độ mà nói, hôm nay mua mai đã nhận.” (ôn 速度 – Bài 4)","giai":"Ví dụ về ưu điểm “tốc độ” của mua hàng trên mạng."},{"kieu":"dien","phan":["这个小区很不错。拿","来说，到处都是花，还种了很多树。"],"dap":[["环境"]],"chon":["环境","房租","经验"],"goiY":"“Lấy môi trường mà nói, đâu cũng có hoa …” (ôn Bài 2)","giai":"Hoa, cây → nói về 环境."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["拿","吃饭","来说","，","一般","南方人","更爱吃","米饭"],"dap":["拿吃饭来说，一般南方人更爱吃米饭。"],"goiY":"Lấy chuyện ăn uống mà nói, người miền Nam thường thích ăn cơm hơn.","giai":"拿 + N + 来说，……"},{"kieu":"xep","manh":["拿","购物","来说","，","人们","不出门","就能","买到想要的东西"],"dap":["拿购物来说，人们不出门就能买到想要的东西。"],"goiY":"Lấy mua sắm mà nói, người ta không ra khỏi nhà cũng mua được thứ mình muốn.","giai":"Ví dụ của sách."},{"kieu":"xep","manh":["拿","我","来说","，","我","每天","至少","学习两个小时"],"dap":["拿我来说，我每天至少学习两个小时。"],"goiY":"Lấy tôi làm ví dụ, mỗi ngày tôi học ít nhất hai tiếng.","giai":"拿 + người + 来说; ôn 至少 (Bài 5)."},{"kieu":"dungsai","cau":"这家饭馆的菜很好吃。拿水煮鱼来说，又香又辣。","dung":true,"giai":"Đúng: nhận định chung trước, ví dụ 拿……来说 sau (水煮鱼 – Bài 5)."},{"kieu":"dungsai","cau":"我们班同学经常互相帮助。拿学习说，大家经常一起研究难题。","dung":false,"sua":"我们班同学经常互相帮助。拿学习来说，大家经常一起研究难题。","giai":"Thiếu 来."},{"kieu":"dungsai","cau":"拿我来说，这个问题太难了。","dung":false,"sua":"对我来说，这个问题太难了。","giai":"Nói cảm nhận của một người → 对……来说."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 77)","huongDan":"Hoàn thành câu, dùng 「拿……来说」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"我很喜欢这个小区。＿＿＿。（环境）","goiY":"Lấy môi trường làm ví dụ: đâu cũng có hoa, trồng nhiều cây, rất đẹp","mau":"拿环境来说，这里到处都是花，还种了很多树，很漂亮","can":[["拿"],["来说"],["环境"]]},{"kieu":"vandung","de":"现在快递的速度很快。＿＿＿。（网购）","goiY":"Lấy mua hàng trên mạng làm ví dụ: hôm nay mua, mai đã nhận","mau":"拿网购来说，今天买的东西明天就能收到","can":[["拿"],["来说"],["网购"]]},{"kieu":"vandung","de":"我们班同学之间经常互相帮助。＿＿＿。（学习）","goiY":"Lấy việc học làm ví dụ: mọi người thường cùng nhau nghiên cứu bài khó","mau":"拿学习来说，大家经常一起研究不会的难题","can":[["拿"],["来说"],["学习"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Giao thông thành phố này rất thuận tiện. Lấy tàu điện ngầm mà nói, đi đâu cũng tiện.","dap":["这个城市的交通很方便。拿地铁来说，去哪儿都很方便。","这个城市的交通很方便。拿地铁来说，去哪儿都方便。"],"giai":"Nhận định chung + 拿……来说 + ví dụ."},{"kieu":"dich","vn":"Lớp nào cũng có ưu điểm. Lấy lớp chúng tôi mà nói, các bạn thường xuyên giúp đỡ lẫn nhau.","dap":["每个班都有优点。拿我们班来说，同学之间经常互相帮助。","每个班都有优点。拿我们班来说，同学们经常互相帮助。"],"giai":"优点 (từ mới) + ôn 之间, 互相 (Bài 4)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói một nhận định về quê hương / thành phố của em, rồi dùng 「拿……来说」 đưa ra một ví dụ","mau":"河内的小吃特别多。拿早餐来说，有河粉、面包、米线，又便宜又好吃。","can":[["拿"],["来说"]]}]}]},{"so":"4","ten":"兼语句“主语+使+宾语+动词短语”","tenVn":"Câu kiêm ngữ 「Chủ ngữ + 使 + tân ngữ + cụm động từ」 — A khiến (làm cho) B …","cauTruc":["Chủ ngữ (sự việc / nguyên nhân) + 使 + tân ngữ (người / vật) + động từ / tính từ / cụm động từ","…… + 使 + B + 受到影响 / 变得 + Adj / 更 + V……"],"giaiThich":"Câu kiêm ngữ: tân ngữ của 使 ĐỒNG THỜI là chủ ngữ của động từ phía sau (使 + 我们 + 更了解客户 → “chúng tôi” vừa bị tác động, vừa là người “hiểu”). Câu này nói một tình huống, nguyên nhân (换工作, 这个新方法, 这次调查…) làm cho người / sự vật THAY ĐỔI hoặc có KẾT QUẢ nào đó. Tiếng Việt: “… khiến / làm cho …”. 使 trang trọng, hay dùng trong văn viết; khẩu ngữ thường dùng 让. Lưu ý: (1) 使 không dùng khi “sai bảo, nhờ ai làm gì” — câu trong bài khoá 2 là 经理让我下周去上海出差, không phải 使; (2) ngay sau 使 phải có tân ngữ (✗ 使变得简单); (3) phủ định đặt 不 / 没 trước 使; trợ động từ 会 / 可能 / 可以 cũng đặt trước 使: 可能会使健康受到影响. Người Việt hay dịch “làm cho” thành 做 — sai, phải dùng 使 / 让.","viDu":[{"zh":"如果总是换工作，可能会使自己的发展受到影响。","py":"Rúguǒ zǒngshì huàn gōngzuò, kěnéng huì shǐ zìjǐ de fāzhǎn shòudào yǐngxiǎng.","vn":"Nếu cứ đổi việc mãi thì có thể khiến sự phát triển của bản thân bị ảnh hưởng."},{"zh":"这个新方法使工作变得更加简单了。","py":"Zhège xīn fāngfǎ shǐ gōngzuò biànde gèngjiā jiǎndān le.","vn":"Phương pháp mới này khiến công việc trở nên đơn giản hơn."},{"zh":"参加这些交流活动使留学生更快适应了大学生活。","py":"Cānjiā zhèxiē jiāoliú huódòng shǐ liúxuéshēng gèng kuài shìyìng le dàxué shēnghuó.","vn":"Tham gia những hoạt động giao lưu này giúp du học sinh nhanh chóng thích nghi với cuộc sống đại học."},{"zh":"随着网购的发展，快递使人们的生活更加方便了。","py":"Suízhe wǎnggòu de fāzhǎn, kuàidì shǐ rénmen de shēnghuó gèngjiā fāngbiàn le.","vn":"Cùng với sự phát triển của mua sắm trên mạng, chuyển phát nhanh khiến cuộc sống của mọi người tiện lợi hơn. (ôn 随着 – Bài 1 · điểm 3, 更加 – Bài 4)"}],"loi":[{"sai":"经理使我下周去上海出差。","why":"Sai bảo, giao việc dùng 让 / 叫; 使 chỉ “khiến cho” (nguyên nhân → kết quả).","dung":"经理让我下周去上海出差。"},{"sai":"这个新方法使变得工作更加简单了。","why":"Ngay sau 使 phải là tân ngữ: 使 + 工作 + 变得……","dung":"这个新方法使工作变得更加简单了。"},{"sai":"他的话做我很高兴。","why":"Dịch máy móc “làm cho” thành 做; “làm cho / khiến” phải dùng 使 (hoặc 让).","dung":"他的话使我很高兴。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["这个新方法","工作变得更加简单了。"],"dap":[["使"]],"chon":["使","被","把"],"goiY":"“Phương pháp mới khiến công việc đơn giản hơn.”","giai":"A + 使 + B + 变得 + Adj."},{"kieu":"dien","phan":["如果总是换工作，可能会使自己的发展","影响。"],"dap":[["受到"]],"chon":["受到","得到","收到"],"goiY":"“… khiến sự phát triển của bản thân bị ảnh hưởng.”","giai":"受到影响 = bị ảnh hưởng."},{"kieu":"dien","phan":["参加这些交流活动使留学生更快","了大学生活。"],"dap":[["适应"]],"chon":["适应","进入","积累"],"goiY":"“… giúp du học sinh nhanh chóng thích nghi với cuộc sống đại học.” (ôn 适应 – Bài 1)","giai":"适应 + 生活 / 环境."},{"kieu":"dien","phan":["长时间不休息可能会使","受到影响。"],"dap":[["健康"]],"chon":["健康","效果","能力"],"goiY":"“Lâu không nghỉ ngơi có thể khiến sức khỏe bị ảnh hưởng.”","giai":"Đáp án gợi ý của sách."},{"kieu":"dien","phan":["和同事多交流可以使你更快适应新的工作","。"],"dap":[["环境"]],"chon":["环境","产品","内容"],"goiY":"“… thích nghi với môi trường làm việc mới.”","giai":"工作环境 = môi trường làm việc."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这个","新方法","使","工作","变得","更加简单了"],"dap":["这个新方法使工作变得更加简单了。"],"goiY":"Phương pháp mới này khiến công việc trở nên đơn giản hơn.","giai":"Chủ ngữ + 使 + tân ngữ + 变得 + Adj."},{"kieu":"xep","manh":["这次","市场调查","使","我们","更了解","客户的想法"],"dap":["这次市场调查使我们更了解客户的想法。"],"goiY":"Lần khảo sát thị trường này giúp chúng tôi hiểu suy nghĩ của khách hàng hơn.","giai":"我们 vừa là tân ngữ của 使 vừa là chủ ngữ của 了解."},{"kieu":"xep","manh":["网购","使","人们的生活","更加","方便了"],"dap":["网购使人们的生活更加方便了。"],"goiY":"Mua sắm trên mạng khiến cuộc sống của mọi người tiện hơn.","giai":"使 + B + 更加 + Adj (ôn Bài 3, 4)."},{"kieu":"dungsai","cau":"这个消息使大家都很高兴。","dung":true,"giai":"Đúng: sự việc (消息) khiến mọi người vui."},{"kieu":"dungsai","cau":"老师使我们写一篇作文。","dung":false,"sua":"老师让我们写一篇作文。","giai":"Giao việc, sai bảo dùng 让, không dùng 使."},{"kieu":"dungsai","cau":"这次出差使积累了很多经验。","dung":false,"sua":"这次出差使我积累了很多经验。","giai":"Sau 使 phải có tân ngữ (我)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 79)","huongDan":"Hoàn thành câu, dùng 「主语 + 使 + 宾语 + 动词短语」","cau":[{"kieu":"vandung","de":"和同事多交流＿＿＿。","goiY":"Kết quả: giúp bạn nhanh thích nghi với môi trường làm việc mới","mau":"可以使你更快适应新的工作环境","can":[["使"]]},{"kieu":"vandung","de":"长时间不休息＿＿＿。","goiY":"Kết quả: có thể khiến sức khỏe bị ảnh hưởng","mau":"可能会使健康受到影响","can":[["使"]]},{"kieu":"vandung","de":"这次市场调查＿＿＿。","goiY":"Kết quả: giúp chúng tôi hiểu rõ hơn suy nghĩ thật sự của khách hàng","mau":"使我们更了解客户真正的想法","can":[["使"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Thường xuyên thức khuya sẽ khiến sức khỏe bị ảnh hưởng.","dap":["经常熬夜会使健康受到影响。","经常晚睡会使健康受到影响。","经常熬夜会使身体受到影响。"],"giai":"会 + 使 + B + 受到影响."},{"kieu":"dich","vn":"Chuyến công tác lần này giúp tôi tích lũy được không ít kinh nghiệm.","dap":["这次出差使我积累了不少经验。","这次出差使我积累了很多经验。"],"giai":"出差, 积累, 经验 (từ mới) + 使."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một việc / một thói quen đã làm em thay đổi, dùng 「……使……」","mau":"学中文使我认识了很多中国朋友，也使我更了解中国文化。","can":[["使"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-8.html"] = [{"so":"1","ten":"条件复句“不管……，都/也……”","tenVn":"Câu phức điều kiện 「不管……，都/也……」 — bất kể …, đều / cũng …","cauTruc":["不管 + điều kiện / tình huống / sự thay đổi，(Chủ ngữ) + 都 / 也 + kết quả","Sau 不管: từ để hỏi (谁 / 什么 / 哪儿 / 怎么 / 多 + Adj) · A还是B · Adj不Adj / V不V"],"giaiThich":"Vế trước nêu một điều kiện CÓ THỂ thay đổi (đi đâu, ai, thế nào, to hay nhỏ…), vế sau nói kết quả KHÔNG thay đổi — giống tiếng Việt “bất kể / dù … thì cũng …”. Hai điều bắt buộc: (1) sau 不管 phải là một cụm có từ để hỏi (谁, 什么, 哪儿, 怎么, 多冷…) hoặc dạng lựa chọn (大还是小, 下不下雨) — không đặt một sự thật cụ thể sau 不管 (✗ 不管下雨 → ✓ 不管下不下雨); (2) vế sau phải có 都 hoặc 也, đứng SAU chủ ngữ. Mẹo phân biệt: 虽然 + sự thật đã biết (虽然天气很冷 — trời đúng là lạnh), còn 不管 + điều kiện bất kỳ (不管天气多冷 — lạnh mấy cũng vậy). 不管 khẩu ngữ hơn 无论 (wúlùn, văn viết, sẽ học sau).","viDu":[{"zh":"不管去哪儿，能放松的地方都行。","py":"Bùguǎn qù nǎr, néng fàngsōng de dìfang dōu xíng.","vn":"Đi đâu cũng được, miễn là nơi có thể thư giãn."},{"zh":"不管有什么想法，你都要说出来，让我们知道。","py":"Bùguǎn yǒu shénme xiǎngfǎ, nǐ dōu yào shuō chūlai, ràng wǒmen zhīdao.","vn":"Bất kể có suy nghĩ gì, bạn cũng phải nói ra cho chúng tôi biết."},{"zh":"不管遇到多大困难，我们也要坚持，最后一定能完成任务。","py":"Bùguǎn yùdào duōdà kùnnan, wǒmen yě yào jiānchí, zuìhòu yídìng néng wánchéng rènwu.","vn":"Dù gặp khó khăn lớn đến đâu, chúng ta cũng phải kiên trì, cuối cùng nhất định sẽ hoàn thành nhiệm vụ."},{"zh":"不管多忙，我每天也至少学一个小时汉语。","py":"Bùguǎn duō máng, wǒ měitiān yě zhìshǎo xué yí gè xiǎoshí Hànyǔ.","vn":"Dù bận đến đâu, mỗi ngày tôi cũng học tiếng Trung ít nhất một tiếng. (ôn 至少 – Bài 5 · điểm 1)"}],"loi":[{"sai":"不管下雨，我们都去爬长城。","why":"Sau 不管 phải là điều kiện chưa xác định (dạng V不V / từ để hỏi), không dùng sự thật cụ thể.","dung":"不管下不下雨，我们都去爬长城。"},{"sai":"不管去哪儿，能放松的地方行。","why":"Vế sau thiếu 都 / 也.","dung":"不管去哪儿，能放松的地方都行。"},{"sai":"不管天气多冷，都他去跑步。","why":"都 / 也 là phó từ, phải đứng SAU chủ ngữ.","dung":"不管天气多冷，他都去跑步。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","去哪儿，能放松的地方都行。"],"dap":[["不管"]],"chon":["不管","虽然","因为"],"goiY":"“Đi đâu cũng được, miễn là nơi có thể thư giãn.”","giai":"不管 + từ để hỏi (哪儿)，都……"},{"kieu":"dien","phan":["不管有什么想法，你","要说出来。"],"dap":[["都"]],"chon":["都","就","才"],"goiY":"“Bất kể có suy nghĩ gì, bạn cũng phải nói ra.”","giai":"Vế sau của 不管 dùng 都 / 也."},{"kieu":"dien","phan":["不管天气","，他每天都去跑步。"],"dap":[["好不好"]],"chon":["好不好","很好","不好"],"goiY":"“Bất kể thời tiết tốt hay không …”","giai":"Sau 不管 dùng dạng lựa chọn Adj不Adj, không dùng 很好 (sự thật xác định)."},{"kieu":"dien","phan":["不管遇到多大困难，我们","要坚持。"],"dap":[["也"]],"chon":["也","还","再"],"goiY":"“Dù gặp khó khăn lớn đến đâu, chúng ta cũng phải kiên trì.”","giai":"都 / 也 đứng sau chủ ngữ 我们."},{"kieu":"dien","phan":["不管","忙，他每个星期都至少锻炼两次。"],"dap":[["多"]],"chon":["多","很","太"],"goiY":"“Dù bận đến đâu …” (ôn 至少 – Bài 5)","giai":"不管 + 多 + Adj = dù … đến đâu."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["不管","这个房子","大还是小","，","我","都要租"],"dap":["不管这个房子大还是小，我都要租。"],"goiY":"Bất kể căn nhà này to hay nhỏ, tôi cũng thuê.","giai":"不管 + A还是B，Sub + 都……"},{"kieu":"xep","manh":["不管","谁","来","，","你","都","要告诉我"],"dap":["不管谁来，你都要告诉我。"],"goiY":"Bất kể ai đến, bạn cũng phải báo cho tôi.","giai":"不管 + 谁 (từ để hỏi)."},{"kieu":"xep","manh":["不管","去哪儿","旅游","，","她","都","戴着这顶帽子"],"dap":["不管去哪儿旅游，她都戴着这顶帽子。"],"goiY":"Dù đi du lịch ở đâu, cô ấy cũng đội chiếc mũ này.","giai":"Từ mới 戴, 帽子 + 不管……都……"},{"kieu":"dungsai","cau":"不管明天下不下雨，我们都去参观故宫。","dung":true,"giai":"Đúng: 不管 + V不V，Sub + 都……"},{"kieu":"dungsai","cau":"不管天气很热，他也戴着帽子。","dung":false,"sua":"不管天气多热，他都戴着帽子。","giai":"Sau 不管 không dùng sự thật xác định 很热 → dùng 多热."},{"kieu":"dungsai","cau":"不管有什么问题，都你可以问我。","dung":false,"sua":"不管有什么问题，你都可以问我。","giai":"都 đứng sau chủ ngữ 你."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 85)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「不管……，都/也……」","cau":[{"kieu":"vandung","de":"A：这个房子不太大，你还租吗？ B：不管这个房子大还是小，我＿＿＿，因为这里离我的公司最近。","goiY":"Nói rằng dù thế nào cũng thuê (vế sau có 都)","mau":"都要租","can":[["都","也"]]},{"kieu":"vandung","de":"A：外边雨特别大，你们还去看电影吗？ B：票都买了，所以＿＿＿，我们都＿＿＿。","goiY":"Dù mưa to đến đâu, chúng tôi cũng đi xem phim","mau":"不管雨下得有多大，要去看电影","can":[["不管"]]},{"kieu":"vandung","de":"A：时间不早了，你还要回家吃晚饭吗？ B：＿＿＿，＿＿＿。","goiY":"Dù muộn thế nào, tôi cũng về nhà ăn tối","mau":"不管多晚，我都要回家吃晚饭","can":[["不管"],["都","也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bất kể đi đâu, chỉ cần thư giãn được là được.","dap":["不管去哪儿，能放松就行。","不管去哪里，能放松就行。","不管去哪儿，能放松的地方都行。"],"giai":"不管 + từ để hỏi，……都 / 就行."},{"kieu":"dich","vn":"Dù công việc bận đến đâu, cuối tuần anh ấy cũng đi ngoại ô thư giãn.","dap":["不管工作多忙，周末他都去郊区放松。","不管工作多忙，他周末都去郊区放松。","不管工作多忙，周末他也去郊区放松。"],"giai":"不管 + 多 + Adj，Sub + 都 / 也……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói về một thói quen mà em không bao giờ bỏ, dùng 「不管……，都/也……」","mau":"不管学习多紧张，我每天晚上都要跑步半个小时。","can":[["不管"],["都","也"]]}]}]},{"so":"2","ten":"假设复句“……，否则……”","tenVn":"Câu phức giả thiết 「……，否则……」 — …, nếu không thì …","cauTruc":["Vế 1 (yêu cầu / lời khuyên / điều kiện)，否则 + vế 2 (hậu quả nếu vế 1 không thực hiện)","否则 = 如果不……，就……"],"giaiThich":"Vế trước đưa ra một yêu cầu, lời khuyên hoặc điều kiện; vế sau mở đầu bằng 「否则」 nói HẬU QUẢ sẽ xảy ra nếu vế trước KHÔNG được thực hiện — giống tiếng Việt “…, nếu không thì / bằng không …”. Mẹo cho người Việt: đọc 否则 thành “如果不这样” là hiểu ngay: 快吃药吧，否则病好不了 = uống thuốc đi, nếu không uống thì bệnh không khỏi. Lưu ý: 否则 luôn đứng ĐẦU vế SAU (sau dấu phẩy), không đứng đầu cả câu; vế sau thường có 就 / 会 / 要 và là kết quả không mong muốn. Khẩu ngữ hay nói 要不 / 要不然 với nghĩa tương tự.","viDu":[{"zh":"还是别给自己太大压力，否则，失去健康就不值得了。","py":"Háishi bié gěi zìjǐ tài dà yālì, fǒuzé, shīqù jiànkāng jiù bù zhídé le.","vn":"Tốt hơn đừng tự tạo áp lực quá lớn, nếu không mất sức khỏe thì chẳng đáng."},{"zh":"今晚早点儿睡吧，否则明天早上起不来，又该迟到了。","py":"Jīnwǎn zǎodiǎnr shuì ba, fǒuzé míngtiān zǎoshang qǐ bu lái, yòu gāi chídào le.","vn":"Tối nay ngủ sớm chút đi, nếu không sáng mai dậy không nổi, lại đi muộn mất."},{"zh":"吃不完的菜要放进冰箱，否则很容易坏。","py":"Chī bu wán de cài yào fàngjìn bīngxiāng, fǒuzé hěn róngyì huài.","vn":"Đồ ăn không ăn hết phải cho vào tủ lạnh, nếu không rất dễ hỏng."},{"zh":"我们得马上出发，否则就来不及了。","py":"Wǒmen děi mǎshàng chūfā, fǒuzé jiù láibují le.","vn":"Chúng ta phải xuất phát ngay, nếu không sẽ không kịp. (ôn 来不及 – Bài 4 · điểm 4)"}],"loi":[{"sai":"否则明天起不来，今晚早点儿睡吧。","why":"否则 đứng ở đầu vế SAU, sau lời khuyên.","dung":"今晚早点儿睡吧，否则明天起不来。"},{"sai":"快吃药吧，否则你的病会好了。","why":"Vế sau của 否则 là hậu quả xấu (nếu KHÔNG làm), không phải kết quả tốt.","dung":"快吃药吧，否则你的病就好不了了。"},{"sai":"如果你不早点儿睡，否则明天会累。","why":"否则 đã mang nghĩa “如果不”, không dùng cùng 如果……不…….","dung":"你早点儿睡吧，否则明天会很累。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["还是别给自己太大压力，","，失去健康就不值得了。"],"dap":[["否则"]],"chon":["否则","因此","不过"],"goiY":"“… nếu không mất sức khỏe thì chẳng đáng.”","giai":"Lời khuyên，否则 + hậu quả."},{"kieu":"dien","phan":["吃不完的菜要放进冰箱，否则很容易","。"],"dap":[["坏"]],"chon":["坏","好","新鲜"],"goiY":"“… nếu không rất dễ hỏng.”","giai":"Vế sau của 否则 là hậu quả xấu."},{"kieu":"dien","phan":["今晚早点儿睡吧，否则明天早上","。"],"dap":[["起不来"]],"chon":["起不来","起得来","起来了"],"goiY":"“… nếu không sáng mai dậy không nổi.” (ôn bổ ngữ khả năng – Bài 4)","giai":"起不来 = không dậy nổi."},{"kieu":"dien","phan":["外出记得戴帽子，","会被太阳晒得头疼。"],"dap":[["否则"]],"chon":["否则","所以","并"],"goiY":"“Ra ngoài nhớ đội mũ, nếu không sẽ bị nắng làm đau đầu.”","giai":"否则 đứng đầu vế sau."},{"kieu":"dien","phan":["我们得马上出发，否则就","了。"],"dap":[["来不及"]],"chon":["来不及","来得及","不来"],"goiY":"“… nếu không sẽ không kịp.” (ôn Bài 4 · điểm 4)","giai":"来不及 = không kịp."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["别","熬夜了","，","否则","身体","会","受不了的"],"dap":["别熬夜了，否则身体会受不了的。"],"goiY":"Đừng thức khuya nữa, nếu không cơ thể sẽ không chịu nổi đâu.","giai":"Lời khuyên，否则 + hậu quả (ôn V不了 – Bài 4)."},{"kieu":"xep","manh":["快","走吧","，","否则","我们","就要","迟到了"],"dap":["快走吧，否则我们就要迟到了。"],"goiY":"Đi nhanh lên, nếu không chúng ta sẽ bị muộn.","giai":"否则……就要……了."},{"kieu":"xep","manh":["带上","雨伞","，","否则","下雨","就","麻烦了"],"dap":["带上雨伞，否则下雨就麻烦了。"],"goiY":"Mang ô theo, nếu không trời mưa thì phiền lắm.","giai":"否则 + điều kiện + 就 + hậu quả."},{"kieu":"dungsai","cau":"你得按时吃饭，否则对身体不好。","dung":true,"giai":"Đúng: yêu cầu，否则 + hậu quả xấu."},{"kieu":"dungsai","cau":"否则会感冒，你多穿点儿衣服。","dung":false,"sua":"你多穿点儿衣服，否则会感冒。","giai":"否则 đứng ở đầu vế sau."},{"kieu":"dungsai","cau":"多休息吧，否则工作效率会更高。","dung":false,"sua":"多休息吧，否则工作效率会下降。","giai":"Vế sau 否则 phải là hậu quả xấu khi KHÔNG nghỉ ngơi."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 87)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「否则」","cau":[{"kieu":"vandung","de":"A：妈妈，我不想吃药。 B：快吃吧，否则＿＿＿。","goiY":"Nói hậu quả: bệnh sẽ không khỏi được (ôn V不了 – Bài 4)","mau":"你的病就好不了了"},{"kieu":"vandung","de":"A：你们一定要今天下午出发吗？ B：对，＿＿＿。","goiY":"Nêu hậu quả nếu không đi hôm nay: ngày mai đường đông xe","mau":"否则明天路上可能会有很多车","can":[["否则"]]},{"kieu":"vandung","de":"A：咱们吃完饭就出去跑步吧。 B：刚吃完饭应该先休息半小时再运动，＿＿＿。","goiY":"Nói hậu quả: không tốt cho sức khỏe","mau":"否则对身体不好","can":[["否则"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đừng tăng ca nữa, nếu không sức khỏe sẽ bị ảnh hưởng.","dap":["别再加班了，否则健康会受到影响。","别加班了，否则健康会受到影响。","别再加班了，否则身体会受到影响。"],"giai":"Lời khuyên，否则 + hậu quả."},{"kieu":"dich","vn":"Bạn phải nhắc tôi nhé, nếu không tôi nhất định sẽ quên.","dap":["你要提醒我，否则我一定会忘的。","你得提醒我，否则我一定会忘的。","你要提醒我，否则我一定会忘。"],"giai":"提醒 (từ mới) + 否则."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em đang ôn thi, ngày nào cũng thức đến 2 giờ sáng. Hãy khuyên bạn bằng một câu có 「否则」","mau":"你别再熬夜复习了，否则考试的时候会没有精神。","can":[["否则"]]}]}]},{"so":"3","ten":"比较句“跟……相比”","tenVn":"Câu so sánh 「跟……相比」 — so với …","cauTruc":["跟 / 与 + A + 相比，B + 更 / 比较 / Adj + 多了……","(Chủ ngữ +) 跟 + A + 相比，……"],"giaiThich":"「跟……相比」 là cấu trúc so sánh: đặt A (cái được đem ra so) giữa 跟 và 相比, vế sau nói B thế nào so với A — giống tiếng Việt “so với A thì B …”. Giới từ 「跟」 dùng trong khẩu ngữ, hoàn cảnh không trang trọng; văn viết, hoàn cảnh trang trọng thường dùng 「与」 (từ mới bài này): 与去年相比. Vế sau hay có 更 / 比较 / Adj + 多了 / Adj + 一些. Lưu ý cho người Việt: KHÔNG dùng 很 / 非常 ở vế sau (✗ 跟A相比，B很好 → ✓ B更好 / 好多了), vì đây là câu so sánh; và đừng bỏ 相比 ở cuối cụm (✗ 跟一直加班，休息好了效率更高).","viDu":[{"zh":"跟一直加班相比，休息好了再工作，效率更高。","py":"Gēn yìzhí jiābān xiāngbǐ, xiūxi hǎo le zài gōngzuò, xiàolǜ gèng gāo.","vn":"So với tăng ca liên tục, nghỉ ngơi đầy đủ rồi mới làm thì hiệu suất cao hơn."},{"zh":"跟读研究生相比，我更想直接工作。","py":"Gēn dú yánjiūshēng xiāngbǐ, wǒ gèng xiǎng zhíjiē gōngzuò.","vn":"So với học thạc sĩ, tôi muốn đi làm luôn hơn."},{"zh":"跟用现金相比，手机支付更方便些。","py":"Gēn yòng xiànjīn xiāngbǐ, shǒujī zhīfù gèng fāngbiàn xiē.","vn":"So với dùng tiền mặt, thanh toán bằng điện thoại tiện hơn một chút."},{"zh":"跟市区相比，郊区的房子既大又便宜。","py":"Gēn shìqū xiāngbǐ, jiāoqū de fángzi jì dà yòu piányi.","vn":"So với nội thành, nhà ở ngoại ô vừa rộng vừa rẻ. (ôn 既……又…… – Bài 4 · điểm 3)"}],"loi":[{"sai":"跟一直加班，休息好了再工作，效率更高。","why":"Thiếu 相比 ở cuối cụm 跟……","dung":"跟一直加班相比，休息好了再工作，效率更高。"},{"sai":"跟坐地铁相比，打车很贵。","why":"Câu so sánh không dùng 很; dùng 更 / Adj + 多了.","dung":"跟坐地铁相比，打车贵多了。"},{"sai":"相比跟去年，今年来旅游的人更多。","why":"Trật tự đúng: 跟 + A + 相比.","dung":"跟去年相比，今年来旅游的人更多。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["跟一直加班","，休息好了再工作，效率更高。"],"dap":[["相比"]],"chon":["相比","比较","一样"],"goiY":"“So với tăng ca liên tục …”","giai":"跟 + A + 相比."},{"kieu":"dien","phan":["","读研究生相比，我更想直接工作。"],"dap":[["跟"]],"chon":["跟","比","对"],"goiY":"“So với học thạc sĩ …”","giai":"跟……相比 (khẩu ngữ)."},{"kieu":"dien","phan":["跟用现金相比，手机支付","方便些。"],"dap":[["更"]],"chon":["更","很","非常"],"goiY":"“… thanh toán bằng điện thoại tiện hơn.”","giai":"Câu so sánh dùng 更, không dùng 很."},{"kieu":"dien","phan":["","去年相比，今年来这里游玩的人多了一倍。"],"dap":[["与"]],"chon":["与","比","被"],"goiY":"“So với năm ngoái …” (văn viết)","giai":"与……相比: trang trọng, văn viết."},{"kieu":"dien","phan":["跟市区相比，郊区的空气新鲜","。"],"dap":[["多了"]],"chon":["多了","很多","非常"],"goiY":"“… không khí ngoại ô trong lành hơn nhiều.”","giai":"Adj + 多了 = … hơn nhiều."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["跟","坐飞机","相比","，","坐高铁","更","舒服"],"dap":["跟坐飞机相比，坐高铁更舒服。"],"goiY":"So với đi máy bay, đi tàu cao tốc thoải mái hơn.","giai":"跟 + A + 相比，B + 更 + Adj."},{"kieu":"xep","manh":["与","以前","相比","，","他的","工作效率","提高了很多"],"dap":["与以前相比，他的工作效率提高了很多。"],"goiY":"So với trước đây, hiệu suất làm việc của anh ấy đã tăng nhiều.","giai":"与……相比 (văn viết)."},{"kieu":"xep","manh":["跟","在家看电视","相比","，","我","更喜欢","去郊区游玩"],"dap":["跟在家看电视相比，我更喜欢去郊区游玩。"],"goiY":"So với ở nhà xem tivi, tôi thích đi ngoại ô chơi hơn.","giai":"Chủ ngữ 我 đứng ở vế sau."},{"kieu":"dungsai","cau":"跟市区相比，郊区安静多了。","dung":true,"giai":"Đúng: Adj + 多了 trong câu so sánh."},{"kieu":"dungsai","cau":"跟去年相比，今年的夏天非常热。","dung":false,"sua":"跟去年相比，今年的夏天更热。","giai":"Câu so sánh dùng 更, không dùng 非常."},{"kieu":"dungsai","cau":"跟一直学习，休息一下效率更高。","dung":false,"sua":"跟一直学习相比，休息一下效率更高。","giai":"Thiếu 相比."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 89)","huongDan":"Hoàn thành câu với 「跟……相比」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"跟在家里看电视相比，＿＿＿。（大自然）","goiY":"Em thích ra ngoài thiên nhiên đi dạo hơn","mau":"我更喜欢去大自然里走走","can":[["大自然"]]},{"kieu":"vandung","de":"＿＿＿，我更爱读和历史有关的书。（法律）","goiY":"So với sách liên quan đến pháp luật …","mau":"跟和法律有关的书相比","can":[["跟","与","和"],["相比"],["法律"]]},{"kieu":"vandung","de":"＿＿＿相比，第一份工作更重要的是积累经验。（工资）","goiY":"So với lương cao hay thấp …","mau":"跟工资高低","can":[["跟","与","和"],["工资"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"So với đi taxi, đi tàu điện ngầm rẻ hơn nhiều.","dap":["跟打车相比，坐地铁便宜多了。","跟打车相比，乘坐地铁便宜多了。","与打车相比，坐地铁便宜多了。"],"giai":"跟……相比，B + Adj + 多了."},{"kieu":"dich","vn":"So với nội thành, ngoại ô có núi có sông, phong cảnh đẹp hơn.","dap":["跟市区相比，郊区有山有水，风景更美。","与市区相比，郊区有山有水，风景更美。","跟市区相比，郊区有山有水，风景更美丽。"],"giai":"跟……相比 + 有A有B (điểm 4)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"So sánh hai cách thư giãn (ở nhà / đi chơi xa, xem phim / đi bộ…) bằng 「跟……相比」","mau":"跟在家玩手机相比，去公园走走更能让人放松。","can":[["相比"]]}]}]},{"so":"4","ten":"固定短语“有A有B”","tenVn":"Cụm cố định 「有A有B」 — có A có B","cauTruc":["有 + A + 有 + B (A, B thường là từ đơn âm tiết, ít khi hai âm tiết)","A và B liên quan / gần nghĩa (有山有水) hoặc trái nghĩa (有大有小)"],"giaiThich":"「有A有B」 là cụm cố định, nghĩa đen “có A có B”, dùng để miêu tả sự phong phú, đầy đủ, đa dạng. A và B phần lớn là từ một âm tiết (山 – 水, 说 – 笑, 大 – 小), số ít là hai âm tiết (有伤心有快乐). Về nghĩa, A và B thường liên quan, gần nghĩa (有山有水 — có núi có sông → cảnh đẹp; 有说有笑 — vừa nói vừa cười → vui vẻ) hoặc trái nghĩa (有大有小, 有男有女 → đủ loại). Cả cụm thường làm vị ngữ hoặc đứng sau nơi chốn. Mẹo: tiếng Việt cũng có “có nói có cười”, “có trên có dưới” — rất dễ nhớ! Lưu ý: hai chữ 有 đều không được bỏ, và không thêm 和 vào giữa (✗ 有山和有水).","viDu":[{"zh":"郊区有山有水，还有很多农家乐。","py":"Jiāoqū yǒu shān yǒu shuǐ, hái yǒu hěn duō nóngjiālè.","vn":"Ngoại ô có núi có sông, lại còn có nhiều nông gia lạc."},{"zh":"超市里的苹果有大有小，有红有绿，看起来都非常好吃。","py":"Chāoshì lǐ de píngguǒ yǒu dà yǒu xiǎo, yǒu hóng yǒu lǜ, kànqǐlai dōu fēicháng hǎochī.","vn":"Táo trong siêu thị có quả to quả nhỏ, có quả đỏ quả xanh, trông đều rất ngon."},{"zh":"春天，公园里到处都是人，有男有女，有大人有孩子，特别热闹。","py":"Chūntiān, gōngyuán lǐ dàochù dōu shì rén, yǒu nán yǒu nǚ, yǒu dàrén yǒu háizi, tèbié rènao.","vn":"Mùa xuân, trong công viên đâu đâu cũng là người, có nam có nữ, có người lớn có trẻ con, vô cùng náo nhiệt."},{"zh":"拿我们班来说，同学有南方人有北方人，各说各的方言。","py":"Ná wǒmen bān láishuō, tóngxué yǒu nánfāngrén yǒu běifāngrén, gè shuō gè de fāngyán.","vn":"Lấy lớp chúng tôi làm ví dụ, bạn học có người miền Nam có người miền Bắc, ai nói phương ngữ nấy. (ôn 拿……来说 – Bài 7 · điểm 3, 各×各的 – Bài 5)"}],"loi":[{"sai":"郊区有山和有水。","why":"Cụm cố định không thêm 和 vào giữa.","dung":"郊区有山有水。"},{"sai":"他们在一起有说笑，特别开心。","why":"Phải có đủ hai chữ 有.","dung":"他们在一起有说有笑，特别开心。"},{"sai":"超市里的苹果有大有好。","why":"A và B phải cùng loại nghĩa (gần nghĩa hoặc trái nghĩa): 大 – 小.","dung":"超市里的苹果有大有小。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["郊区有山有","，还有很多农家乐。"],"dap":[["水"]],"chon":["水","人","车"],"goiY":"“Ngoại ô có núi có sông …”","giai":"有山有水 — cặp gần nghĩa, chỉ cảnh đẹp."},{"kieu":"dien","phan":["超市里的苹果有大有","，有红有绿。"],"dap":[["小"]],"chon":["小","多","好"],"goiY":"“… có quả to quả nhỏ …”","giai":"有大有小 — cặp trái nghĩa."},{"kieu":"dien","phan":["公园里到处都是人，有男有","，特别热闹。"],"dap":[["女"]],"chon":["女","老","人"],"goiY":"“… có nam có nữ …”","giai":"有男有女."},{"kieu":"dien","phan":["他们在一起有说有","，特别开心。"],"dap":[["笑"]],"chon":["笑","听","哭"],"goiY":"“Họ ở cùng nhau nói nói cười cười …”","giai":"有说有笑 = vừa nói vừa cười, vui vẻ."},{"kieu":"dien","phan":["这家饭馆的菜有","有辣，大家都能找到喜欢的。"],"dap":[["甜"]],"chon":["甜","饭","好"],"goiY":"“Món ăn có món ngọt có món cay …” (ôn từ Bài 5)","giai":"有甜有辣 — hai vị khác nhau."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["小花园里","有花","有草","，","非常","漂亮"],"dap":["小花园里有花有草，非常漂亮。"],"goiY":"Khu vườn nhỏ có hoa có cỏ, rất đẹp.","giai":"Nơi chốn + 有A有B."},{"kieu":"xep","manh":["我们班的同学","有男","有女","，","有大","有小"],"dap":["我们班的同学有男有女，有大有小。"],"goiY":"Bạn học lớp tôi có nam có nữ, có lớn có nhỏ.","giai":"Hai cụm 有A有B nối tiếp."},{"kieu":"xep","manh":["生活","总是","有苦","有甜","的"],"dap":["生活总是有苦有甜的。"],"goiY":"Cuộc sống lúc nào cũng có đắng có ngọt.","giai":"有苦有甜 — trái nghĩa."},{"kieu":"dungsai","cau":"这个地方有山有水，景色十分美丽。","dung":true,"giai":"Đúng: 有山有水 + từ mới 景色, 十分, 美丽."},{"kieu":"dungsai","cau":"市场里的水果有大和有小。","dung":false,"sua":"市场里的水果有大有小。","giai":"Không thêm 和."},{"kieu":"dungsai","cau":"大家在一起有说笑，特别热闹。","dung":false,"sua":"大家在一起有说有笑，特别热闹。","giai":"Thiếu chữ 有 thứ hai."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 91)","huongDan":"Hoàn thành câu với 「有A有B」","cau":[{"kieu":"vandung","de":"小花园里＿＿＿，非常漂亮。","goiY":"Trong vườn có hoa có cỏ","mau":"有花有草","can":[["有"]]},{"kieu":"vandung","de":"他们在一起＿＿＿，特别开心。","goiY":"Họ nói nói cười cười","mau":"有说有笑","can":[["有"]]},{"kieu":"vandung","de":"每个人的生活都不是一直顺顺利利的，总是＿＿＿。","goiY":"Có lúc buồn có lúc vui","mau":"有伤心有快乐","can":[["有"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Ngoại ô có núi có sông, ăn, chơi, ở đều rất tiện.","dap":["郊区有山有水，吃、玩、住都十分方便。","郊区有山有水，吃、玩、住都很方便。","郊区有山有水，吃玩住都十分方便。"],"giai":"有A有B + 十分 (từ mới)."},{"kieu":"dich","vn":"Trong công viên có người lớn có trẻ con, vô cùng náo nhiệt.","dap":["公园里有大人有孩子，十分热闹。","公园里有大人有孩子，特别热闹。","公园里有大人有孩子，非常热闹。"],"giai":"A, B hai âm tiết: 有大人有孩子."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giới thiệu một nơi ở quê em (chợ, công viên, khu du lịch…) bằng 「有A有B」","mau":"我老家的市场有大有小，卖的水果有红有绿，每天都特别热闹。","can":[["有"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-9.html"] = [{"so":"1","ten":"紧缩复句“不……也……”","tenVn":"Câu phức rút gọn 「不……也……」 — không … cũng (vẫn) …","cauTruc":["(Sub) + 不 + V1 + (Sub2) + 也 + (能 / 会) + V2 / Adj","Nghĩa: 即使不 + V1，也 + kết quả (dù không làm A, kết quả B vẫn chắc chắn)"],"giaiThich":"「紧缩复句」 (câu phức rút gọn) là câu phức được “nén” lại: hai vế dính liền thành một câu, không có dấu phẩy và bỏ bớt liên từ. 「不……也……」 = 即使不……，也……: dù trong điều kiện PHỦ ĐỊNH (không làm việc A) thì kết quả ở sau VẪN chắc chắn như vậy. Rất hay dùng trong khẩu ngữ. Mẹo cho người Việt: dịch thẳng “không … cũng …” — 我不说你也懂 = em không nói anh cũng hiểu. Lưu ý: (1) 也 là phó từ, đứng SAU chủ ngữ vế sau và TRƯỚC động từ (✗ 我不说也你懂 → ✓ 我不说你也懂); (2) phải có 也 — thiếu 也 câu thành nghĩa khác hẳn; (3) vế sau có thể khẳng định (也懂, 也能考好) hoặc phủ định (也不饿, 也不累); (4) khác với 也不……也不…… (cả hai đều không).","viDu":[{"zh":"我不说你也懂我在想什么。","py":"Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme.","vn":"Em không nói anh cũng hiểu em đang nghĩ gì."},{"zh":"他不复习也能考出好成绩。","py":"Tā bú fùxí yě néng kǎo chū hǎo chéngjì.","vn":"Cậu ấy không ôn cũng thi được điểm cao."},{"zh":"我很清楚他为什么生气，不问我也知道。","py":"Wǒ hěn qīngchu tā wèishénme shēngqì, bú wèn wǒ yě zhīdao.","vn":"Tôi biết rõ vì sao anh ấy giận, không hỏi tôi cũng biết."},{"zh":"这个题太简单了，不复习也做得了。","py":"Zhège tí tài jiǎndān le, bú fùxí yě zuò de liǎo.","vn":"Bài này dễ quá, không ôn cũng làm được. (ôn V得了 – Bài 4 · điểm 1)"}],"loi":[{"sai":"我不说也你懂。","why":"也 là phó từ: đứng sau chủ ngữ vế sau (你), trước động từ.","dung":"我不说你也懂。"},{"sai":"他不复习能考出好成绩。","why":"Thiếu 也 → không còn nghĩa “dù không … vẫn …”.","dung":"他不复习也能考出好成绩。"},{"sai":"不用地图，但是我也能找到。","why":"Câu rút gọn không dùng 但是; nén gọn thành một câu 不……也…….","dung":"不用地图我也能找到。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我不说你","懂我在想什么。"],"dap":[["也"]],"chon":["也","就","还"],"goiY":"“Em không nói anh cũng hiểu em đang nghĩ gì.”","giai":"不……也……: dù không nói, kết quả vẫn là hiểu."},{"kieu":"dien","phan":["他不","也能考出好成绩。"],"dap":[["复习"]],"chon":["复习","错过","祝"],"goiY":"“Cậu ấy không ôn cũng thi được điểm cao.”","giai":"不 + V1 (复习) + 也 + kết quả."},{"kieu":"dien","phan":["我很清楚他为什么生气，","问我也知道。"],"dap":[["不"]],"chon":["不","没","别"],"goiY":"“… không hỏi tôi cũng biết.”","giai":"Mẫu cố định dùng 不 ở vế đầu."},{"kieu":"dien","phan":["这条路我走过很多次了，不用手机","能找到。"],"dap":[["也"]],"chon":["也","才","再"],"goiY":"“Đường này tôi đi nhiều lần rồi, không dùng điện thoại cũng tìm được.”","giai":"不用……也能…… = không cần … cũng có thể …"},{"kieu":"dien","phan":["我中午吃得太饱了，晚上不吃饭也不","。"],"dap":[["饿"]],"chon":["饿","饱","累"],"goiY":"“Trưa ăn no quá, tối không ăn cũng không đói.”","giai":"Vế sau có thể là phủ định: 也不饿."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","不说","你","也","懂"],"dap":["我不说你也懂。"],"goiY":"Em không nói anh cũng hiểu.","giai":"Sub1 + 不 + V1 + Sub2 + 也 + V2."},{"kieu":"xep","manh":["他","不","复习","也能","考出","好成绩"],"dap":["他不复习也能考出好成绩。"],"goiY":"Cậu ấy không ôn cũng thi được điểm cao.","giai":"不 + V1 + 也能 + V2."},{"kieu":"xep","manh":["这件事","不问","我","也","知道"],"dap":["这件事不问我也知道。"],"goiY":"Chuyện này không hỏi tôi cũng biết.","giai":"Chủ ngữ vế sau (我) đứng trước 也."},{"kieu":"dungsai","cau":"你不告诉我，我也知道你在想什么。","dung":true,"giai":"Đúng: 不……也…… (có thể có dấu phẩy khi chủ ngữ hai vế khác nhau)."},{"kieu":"dungsai","cau":"我不说也你懂。","dung":false,"sua":"我不说你也懂。","giai":"也 phải đứng sau chủ ngữ 你."},{"kieu":"dungsai","cau":"不用地图，但是我也能找到。","dung":false,"sua":"不用地图我也能找到。","giai":"Câu rút gọn không dùng 但是."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 97)","huongDan":"Hoàn thành đối thoại, có dùng 「不……也……」","cau":[{"kieu":"vandung","de":"A：昨天你怎么没吃晚饭？ B：我中午吃得太饱了，晚上＿＿＿也不饿。","goiY":"Trưa ăn no quá, tối không ăn cơm cũng không đói","mau":"不吃饭","can":[["不"]]},{"kieu":"vandung","de":"A：你不用查一下地址吗？ B：＿＿＿，我上个月刚去过，还记得。","goiY":"Không tra cũng tìm được (vì tháng trước vừa đến)","mau":"不查也能找到","can":[["不"],["也"]]},{"kieu":"vandung","de":"A：你中午不休息一会儿吗？ B：我早上喝了一杯咖啡，＿＿＿。","goiY":"Đã uống cà phê nên không nghỉ cũng được","mau":"不休息也行","can":[["不"],["也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Em không nói anh cũng hiểu em đang nghĩ gì.","dap":["我不说你也懂我在想什么。","我不说你也知道我在想什么。"],"giai":"Sub1 + 不 + V + Sub2 + 也 + V."},{"kieu":"dich","vn":"Bài này dễ quá, không ôn cũng làm được.","dap":["这个题太简单了，不复习也做得了。","这道题太简单了，不复习也做得了。","这个题太简单了，不复习也能做。"],"giai":"不复习也 + V得了 (ôn Bài 4 · điểm 1)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn thân hiểu em đến mức nào? Dùng 「不……也……」 kể một ví dụ","mau":"我和她是十年的好朋友了，我不说她也知道我想要什么。","can":[["不"],["也"]]}]}]},{"so":"2","ten":"转折复句“尽管……，但是/可是……”","tenVn":"Câu phức chuyển ngoặt 「尽管……，但是 / 可是……」 — mặc dù …, nhưng …","cauTruc":["尽管 + A (sự thật)，但是 / 可是 + B (kết quả, tình huống trái ngược)","Sub + 尽管 + A，但是 / 可是 + (Sub) + 还是 / 也 + B"],"giaiThich":"「尽管」 nghĩa như 「虽然」 (tuy, mặc dù): dẫn ra một tình huống có THẬT; vế sau dùng 「但是 / 可是」 đưa ra tình huống hoặc kết quả NGƯỢC lại — thường thêm 还是 / 也 để nhấn mạnh “vẫn”. 尽管 có thể đứng trước hoặc sau chủ ngữ vế đầu (他们尽管…… / 尽管他们……). Mẹo cho người Việt: tiếng Việt cũng nói “mặc dù … nhưng …”, nên cứ giữ đủ cặp 尽管……，但是……. Lưu ý: (1) vế sau KHÔNG dùng 所以 (nhân quả là 由于……，所以…… – Bài 2); (2) phân biệt với 不管 (Bài 8): 尽管 + một sự thật cụ thể (尽管下雨 = mưa thật rồi), còn 不管 + điều kiện bất kỳ (不管下不下雨 / 不管多忙) và vế sau dùng 都 / 也; (3) 还是 là phó từ, đứng sau chủ ngữ vế sau (但是他还是……).","viDu":[{"zh":"他们尽管性格不同，但是有很多共同爱好。","py":"Tāmen jǐnguǎn xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào.","vn":"Họ tuy tính cách khác nhau nhưng có rất nhiều sở thích chung."},{"zh":"尽管时间紧张、压力很大，但是他们还是完成了任务。","py":"Jǐnguǎn shíjiān jǐnzhāng, yālì hěn dà, dànshì tāmen háishi wánchéng le rènwu.","vn":"Mặc dù thời gian gấp, áp lực lớn, nhưng họ vẫn hoàn thành nhiệm vụ."},{"zh":"尽管她已经很累了，可是还是很耐心地给女儿读睡前故事。","py":"Jǐnguǎn tā yǐjīng hěn lèi le, kěshì háishi hěn nàixīn de gěi nǚ'ér dú shuì qián gùshi.","vn":"Mặc dù đã rất mệt, nhưng cô ấy vẫn kiên nhẫn đọc truyện trước giờ ngủ cho con gái."},{"zh":"尽管她的中文水平还不太高，但是至少能用中文买东西、问路了。","py":"Jǐnguǎn tā de Zhōngwén shuǐpíng hái bú tài gāo, dànshì zhìshǎo néng yòng Zhōngwén mǎi dōngxi, wènlù le.","vn":"Mặc dù trình độ tiếng Trung của cô ấy chưa cao lắm, nhưng ít nhất đã có thể dùng tiếng Trung mua đồ, hỏi đường. (ôn 至少 – Bài 5 · điểm 1)"}],"loi":[{"sai":"尽管下雨，所以我们还是去了。","why":"尽管 (nhượng bộ) không đi với 所以 (nhân quả).","dung":"尽管下雨，但是我们还是去了。"},{"sai":"尽管天气怎么样，我都去跑步。","why":"Điều kiện bất kỳ (怎么样) phải dùng 不管……都……; 尽管 chỉ đi với một sự thật cụ thể.","dung":"不管天气怎么样，我都去跑步。"},{"sai":"尽管很累，但是还是他完成了工作。","why":"还是 là phó từ, đứng SAU chủ ngữ 他.","dung":"尽管很累，但是他还是完成了工作。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["他们","性格不同，但是有很多共同爱好。"],"dap":[["尽管"]],"chon":["尽管","由于","不管"],"goiY":"“Họ tuy tính cách khác nhau nhưng …”","giai":"尽管……，但是…… (chuyển ngoặt)."},{"kieu":"dien","phan":["尽管时间紧张、压力很大，","他们还是完成了任务。"],"dap":[["但是"]],"chon":["但是","所以","而且"],"goiY":"“… nhưng họ vẫn hoàn thành nhiệm vụ.”","giai":"Vế sau của 尽管 dùng 但是 / 可是."},{"kieu":"dien","phan":["尽管她已经很累了，可是","很耐心地给女儿读睡前故事。"],"dap":[["还是"]],"chon":["还是","才","就"],"goiY":"“… nhưng vẫn kiên nhẫn đọc truyện cho con.”","giai":"可是 + 还是: nhấn mạnh “vẫn”."},{"kieu":"dien","phan":["","他已经在中国住了五年，但是还是不太习惯吃辣的。"],"dap":[["尽管"]],"chon":["尽管","不管","既然"],"goiY":"“Mặc dù đã sống ở Trung Quốc năm năm, nhưng vẫn chưa quen ăn cay.” (phân biệt 不管 – Bài 8, 既然 – Bài 7)","giai":"Sự thật cụ thể + kết quả trái chiều → 尽管."},{"kieu":"dien","phan":["尽管工作很忙，但是他对家庭很","，从来没忘过孩子的生日。"],"dap":[["负责"]],"chon":["负责","积极","浪漫"],"goiY":"“Mặc dù công việc bận, nhưng anh ấy rất có trách nhiệm với gia đình …”","giai":"对……负责 = có trách nhiệm với …"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["尽管","很久没见了","，","但是","大家","还是","感觉很熟悉"],"dap":["尽管很久没见了，但是大家还是感觉很熟悉。"],"goiY":"Mặc dù lâu lắm không gặp, nhưng mọi người vẫn thấy rất thân quen.","giai":"尽管……，但是 + Sub + 还是……"},{"kieu":"xep","manh":["他","尽管","工作很忙","，","可是","每天","都给女朋友打电话"],"dap":["他尽管工作很忙，可是每天都给女朋友打电话。","尽管他工作很忙，可是每天都给女朋友打电话。"],"goiY":"Anh ấy tuy công việc rất bận nhưng ngày nào cũng gọi cho bạn gái.","giai":"尽管 đứng trước hoặc sau chủ ngữ đều được."},{"kieu":"xep","manh":["尽管","我","很喜欢那台电脑","，","但是","最后","还是没有买"],"dap":["尽管我很喜欢那台电脑，但是最后还是没有买。","我尽管很喜欢那台电脑，但是最后还是没有买。"],"goiY":"Mặc dù tôi rất thích chiếc máy tính đó, nhưng cuối cùng vẫn không mua.","giai":"Đáp án tham khảo của sách (bài tập 3)."},{"kieu":"dungsai","cau":"尽管雨下得很大，但是比赛还是按时开始了。","dung":true,"giai":"Đúng: mưa to (sự thật) — trận đấu vẫn bắt đầu đúng giờ."},{"kieu":"dungsai","cau":"尽管他生病了，所以没来上课。","dung":false,"sua":"由于他生病了，所以没来上课。","giai":"Quan hệ nhân quả → 由于……，所以…… (Bài 2)."},{"kieu":"dungsai","cau":"尽管你说什么，我都不相信。","dung":false,"sua":"不管你说什么，我都不相信。","giai":"Điều kiện bất kỳ (什么) → 不管……都…… (Bài 8)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 99)","huongDan":"Hoàn thành đối thoại, có dùng 「尽管……，但是 / 可是……」","cau":[{"kieu":"vandung","de":"A：今天和老同学的聚餐怎么样？ B：尽管很久没见了，＿＿＿。","goiY":"Nhưng mọi người vẫn thấy rất thân quen","mau":"但是大家还是感觉很熟悉","can":[["但是","可是"]]},{"kieu":"vandung","de":"A：你们坐上飞机了吧？ B：是的，＿＿＿，但是我们最后还是坐上了飞机。","goiY":"Mặc dù thời gian hơi gấp","mau":"尽管时间有一些紧张","can":[["尽管"]]},{"kieu":"vandung","de":"A：你最后买那台电脑了吗？ B：＿＿＿，＿＿＿。","goiY":"Mặc dù rất thích chiếc máy tính đó, nhưng cuối cùng vẫn không mua","mau":"尽管我很喜欢那台电脑，但是最后还是没有买","can":[["尽管"],["但是","可是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung.","dap":["尽管他们性格不同，但是有很多共同爱好。","他们尽管性格不同，但是有很多共同爱好。","尽管他们性格不同，可是有很多共同爱好。"],"giai":"尽管……，但是 / 可是…… + từ mới 性格, 共同."},{"kieu":"dich","vn":"Mặc dù đã học tiếng Trung hai năm, nhưng tôi vẫn xem không hiểu phim Trung Quốc.","dap":["尽管我已经学了两年中文，但是还是看不懂中国电影。","尽管我学了两年中文，但是还是看不懂中国电影。","我尽管已经学了两年中文，可是还是看不懂中国电影。"],"giai":"但是 + 还是 + V不懂."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể về một người bạn / người thân: dù có khoảng cách hay khác biệt, tình cảm vẫn tốt. Dùng 「尽管……，但是 / 可是……」","mau":"尽管我和好朋友住在不同的城市，但是我们每个星期都在网上聊天儿，感情一直很好。","can":[["尽管"],["但是","可是"]]}]}]},{"so":"3","ten":"指示代词“此”","tenVn":"Đại từ chỉ thị 「此」 — này, đây (văn viết, trang trọng)","cauTruc":["此 + (lượng từ) + N: 此次、此人、此项工作 (= 这次 / 这个人 / 这项工作)","Giới từ + 此: 对此 (về việc này)、从此 (từ đó)、因此 (vì vậy)、在此 (tại đây)"],"giaiThich":"「此」 là đại từ chỉ thị, nghĩa như 「这 / 这个」 (này, đây), nhưng mang sắc thái VĂN VIẾT, TRANG TRỌNG — hay gặp trong thông báo, tin tức, bài phát biểu, biển báo (此处禁止停车 – cấm đỗ xe tại đây). Cách dùng: (1) 此 + lượng từ + danh từ: 此次 (lần này), 此项 (hạng mục này), 此人 (người này); (2) đứng sau giới từ: 对此 (về việc này), 从此 (từ đó — từ mới bài này), 因此 (vì vậy), 在此 (tại đây, nhân đây); (3) cụm cố định: 此时 (lúc này), 此生 (đời này), 此地 (nơi này). Mẹo cho người Việt: 此 đọc Hán Việt là “thử”, như trong “bỉ thử” (彼此 – bên kia bên này). Lưu ý: nói chuyện thân mật hằng ngày vẫn dùng 这; 此 không đứng một mình làm chủ ngữ trong khẩu ngữ (✗ 此是我的书 → ✓ 这是我的书); 从此 nghĩa là “từ đó VỀ SAU”, không đi với 以前.","viDu":[{"zh":"此次出差，让两人熟悉了起来，从此成了好朋友。","py":"Cǐ cì chūchāi, ràng liǎng rén shúxi le qǐlai, cóngcǐ chéng le hǎo péngyou.","vn":"Chuyến công tác lần này khiến hai người trở nên thân quen, từ đó thành bạn tốt."},{"zh":"此人聪明、有能力，一定能顺利完成任务。","py":"Cǐ rén cōngming, yǒu nénglì, yídìng néng shùnlì wánchéng rènwu.","vn":"Người này thông minh, có năng lực, nhất định có thể hoàn thành tốt nhiệm vụ."},{"zh":"此材料很重要，必须直接交给他。","py":"Cǐ cáiliào hěn zhòngyào, bìxū zhíjiē jiāogěi tā.","vn":"Tài liệu này rất quan trọng, phải giao tận tay anh ấy."},{"zh":"此次比赛不仅吸引了很多留学生，甚至还有不少中国学生来参加。","py":"Cǐ cì bǐsài bùjǐn xīyǐn le hěn duō liúxuéshēng, shènzhì hái yǒu bùshǎo Zhōngguó xuésheng lái cānjiā.","vn":"Cuộc thi lần này không chỉ thu hút nhiều lưu học sinh, thậm chí còn có không ít sinh viên Trung Quốc đến tham gia. (ôn 不仅, 甚至 – Bài 3)"}],"loi":[{"sai":"你看，此是我新买的手机。","why":"Khẩu ngữ: 此 không làm chủ ngữ một mình như 这.","dung":"你看，这是我新买的手机。"},{"sai":"妈妈，此菜真好吃！","why":"Nói chuyện thân mật trong nhà mà dùng 此 nghe rất cứng, như đọc văn bản — dùng 这.","dung":"妈妈，这个菜真好吃！"},{"sai":"从此以前，他每天都跑步。","why":"从此 = từ đó VỀ SAU, không đi với 以前.","dung":"从此以后，他每天都跑步。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","次出差，让两人熟悉了起来。"],"dap":[["此"]],"chon":["此","那","哪"],"goiY":"“Chuyến công tác lần này khiến hai người thân quen.”","giai":"此次 = 这次 (văn viết)."},{"kieu":"dien","phan":["此人聪明、有能力，一定能顺利完成","。"],"dap":[["任务"]],"chon":["任务","印象","日子"],"goiY":"“… nhất định hoàn thành tốt nhiệm vụ.”","giai":"完成任务 = hoàn thành nhiệm vụ."},{"kieu":"dien","phan":["此材料很重要，必须直接","给他。"],"dap":[["交"]],"chon":["交","让","叫"],"goiY":"“Tài liệu này rất quan trọng, phải giao tận tay anh ấy.”","giai":"交给 + người = giao cho ai."},{"kieu":"dien","phan":["他们一起出了次差，","成了好朋友。"],"dap":[["从此"]],"chon":["从此","从来","当时"],"goiY":"“… từ đó thành bạn tốt.”","giai":"从此 = từ mốc đó về sau."},{"kieu":"dien","phan":["关于此次活动，大家有任何问题都可以问我，我对","负责。"],"dap":[["此"]],"chon":["此","这儿","那儿"],"goiY":"“… tôi chịu trách nhiệm về việc này.” (ôn 任何 – Bài 1)","giai":"对此负责 = chịu trách nhiệm về việc này."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["此次","出差","让","两人","熟悉了起来"],"dap":["此次出差让两人熟悉了起来。"],"goiY":"Chuyến công tác lần này khiến hai người thân quen.","giai":"此次 + N làm chủ ngữ."},{"kieu":"xep","manh":["此项","工作","由","你","负责"],"dap":["此项工作由你负责。"],"goiY":"Công việc này do bạn phụ trách.","giai":"此 + lượng từ 项 + N; 由 + người + 负责."},{"kieu":"xep","manh":["我们","对此","都","很满意"],"dap":["我们对此都很满意。"],"goiY":"Chúng tôi đều rất hài lòng về việc này.","giai":"对此 = 对这件事."},{"kieu":"dungsai","cau":"此人做事积极，工作负责，大家都很喜欢他。","dung":true,"giai":"Đúng: 此人 = 这个人 (trang trọng)."},{"kieu":"dungsai","cau":"你看，此是我新买的手机。","dung":false,"sua":"你看，这是我新买的手机。","giai":"Khẩu ngữ dùng 这 làm chủ ngữ."},{"kieu":"dungsai","cau":"从此以前，他再也没迟到过。","dung":false,"sua":"从此以后，他再也没迟到过。","giai":"从此 đi với 以后."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 101)","huongDan":"Hoàn thành câu, dùng 「此」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"此项（xiàng, item）工作交给你，＿＿＿。（负责）","goiY":"Hy vọng bạn có thể chịu trách nhiệm về việc này","mau":"希望你能对此负责","can":[["此"],["负责"]]},{"kieu":"vandung","de":"很幸运此生＿＿＿，＿＿＿。（错过）","goiY":"Rất may đời này gặp được em, anh nhất định không bỏ lỡ em","mau":"能遇见你，我一定不会错过你","can":[["错过"]]},{"kieu":"vandung","de":"＿＿＿地点是校图书馆。（活动）","goiY":"Địa điểm của hoạt động lần này","mau":"此次活动的","can":[["此"],["活动"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chuyến công tác lần này khiến hai người trở nên thân quen, từ đó thành bạn tốt.","dap":["此次出差让两人熟悉了起来，从此成了好朋友。","此次出差，让两人熟悉了起来，从此成了好朋友。"],"giai":"此次 + 从此 (từ mới)."},{"kieu":"dich","vn":"Người này vừa thông minh vừa có trách nhiệm, việc này giao cho anh ấy là được.","dap":["此人既聪明又负责，这件事交给他就是了。","此人又聪明又负责，这件事交给他就是了。"],"giai":"此人 + 既……又…… (Bài 4) + 就是了 (Bài 2)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Viết một câu thông báo trang trọng cho lớp (thời gian, địa điểm hoạt động), dùng 「此次」 hoặc 「对此」","mau":"此次中文比赛的时间是下周五下午，地点是学校图书馆，欢迎大家积极参加。","can":[["此"]]}]}]},{"so":"4","ten":"时间副词“从来”","tenVn":"Phó từ thời gian 「从来」 — từ trước đến nay (luôn / chưa từng)","cauTruc":["从来 + 不 + V / Adj (thói quen, nguyên tắc: trước giờ không bao giờ)","从来 + 没(有) + V + 过 (chưa từng trải qua)","从来 + 都 + 是 / V…… (khẳng định: từ trước đến nay luôn …)"],"giaiThich":"「从来」 nghĩa là từ quá khứ đến hiện tại luôn như vậy, chưa hề thay đổi. Chủ yếu dùng trong câu PHỦ ĐỊNH: 从来不 + V (thói quen, nguyên tắc, ý muốn: 他从来不喝酒) và 从来没(有) + V + 过 (chưa từng trải qua: 我从来没见过). Đôi khi dùng trong câu khẳng định, thường kèm 都: 爱从来都是相互尊重. Mẹo cho người Việt: “trước giờ không bao giờ …” → 从来不……; “chưa từng … bao giờ” → 从来没……过. Lưu ý: (1) 从来 đứng TRƯỚC 不 / 没 (✗ 不从来); (2) 从来没 thường có 过 sau động từ; (3) 从来 nói cả một quãng dài đến hiện tại, không dùng cho một lần cụ thể (✗ 昨天我从来没去); (4) phân biệt 从此 (từ mốc đó về sau) và 从来 (từ trước đến nay).","viDu":[{"zh":"爱，从来都是相互尊重、理解与支持，不是吗？","py":"Ài, cónglái dōu shì xiānghù zūnzhòng, lǐjiě yǔ zhīchí, bú shì ma?","vn":"Tình yêu, từ trước đến nay luôn là tôn trọng, thấu hiểu và ủng hộ lẫn nhau, không phải sao?"},{"zh":"我从来没见过这个颜色的花，它叫什么名字啊？","py":"Wǒ cónglái méi jiàn guò zhège yánsè de huā, tā jiào shénme míngzi a?","vn":"Tôi chưa từng thấy loài hoa màu này, nó tên là gì vậy?"},{"zh":"我从来不喜欢一个人旅游，每次都要和家人或朋友一起去。","py":"Wǒ cónglái bù xǐhuan yí gè rén lǚyóu, měi cì dōu yào hé jiārén huò péngyou yìqǐ qù.","vn":"Tôi trước giờ không thích đi du lịch một mình, lần nào cũng phải đi cùng gia đình hoặc bạn bè."},{"zh":"不管工作多忙，他从来没忘过妈妈的生日。","py":"Bùguǎn gōngzuò duō máng, tā cónglái méi wàng guò māma de shēngrì.","vn":"Bất kể công việc bận đến đâu, anh ấy chưa bao giờ quên sinh nhật mẹ. (ôn 不管 – Bài 8 · điểm 1)"}],"loi":[{"sai":"我从来没见这个颜色的花。","why":"从来没 + V nói kinh nghiệm “chưa từng” → cần 过.","dung":"我从来没见过这个颜色的花。"},{"sai":"昨天他从来没来上课。","why":"从来 nói cả quãng thời gian đến nay, không đi với một thời điểm cụ thể (昨天).","dung":"昨天他没来上课。"},{"sai":"他不从来喝酒。","why":"从来 đứng TRƯỚC 不.","dung":"他从来不喝酒。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["爱，","都是相互尊重、理解与支持，不是吗？"],"dap":[["从来"]],"chon":["从来","从此","当时"],"goiY":"“Tình yêu, từ trước đến nay luôn là …”","giai":"从来都是 = từ trước đến nay luôn là."},{"kieu":"dien","phan":["我从来没见","这个颜色的花，它叫什么名字啊？"],"dap":[["过"]],"chon":["过","了","着"],"goiY":"“Tôi chưa từng thấy loài hoa màu này.”","giai":"从来没 + V + 过."},{"kieu":"dien","phan":["我从来","喜欢一个人旅游，每次都要和家人或朋友一起去。"],"dap":[["不"]],"chon":["不","没","别"],"goiY":"“Tôi trước giờ không thích đi du lịch một mình.”","giai":"Sở thích, thói quen → 从来不."},{"kieu":"dien","phan":["他工作很负责，从来","迟到过。"],"dap":[["没"]],"chon":["没","不","别"],"goiY":"“… chưa từng đến muộn.”","giai":"Có 过 → 从来没 + V + 过."},{"kieu":"dien","phan":["他这个人很","，从来不说假话。"],"dap":[["实在"]],"chon":["实在","浪漫","积极"],"goiY":"“Anh ấy là người rất thật thà, trước giờ không nói dối.”","giai":"实在 = thật thà (từ mới bài khoá 3)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","从来","没","去过","长城"],"dap":["我从来没去过长城。"],"goiY":"Tôi chưa từng đến Vạn Lý Trường Thành.","giai":"从来没 + V + 过 + O."},{"kieu":"xep","manh":["他","从来","不","喝","咖啡"],"dap":["他从来不喝咖啡。"],"goiY":"Anh ấy trước giờ không uống cà phê.","giai":"从来不 + V: thói quen."},{"kieu":"xep","manh":["爱","从来","都是","相互","支持的"],"dap":["爱从来都是相互支持的。"],"goiY":"Tình yêu từ trước đến nay luôn là ủng hộ lẫn nhau.","giai":"Khẳng định: 从来都是……"},{"kieu":"dungsai","cau":"我从来没吃过这么好吃的巧克力。","dung":true,"giai":"Đúng: 从来没 + V + 过."},{"kieu":"dungsai","cau":"她不从来迟到。","dung":false,"sua":"她从来不迟到。","giai":"从来 đứng trước 不."},{"kieu":"dungsai","cau":"上个星期六我从来没去公园。","dung":false,"sua":"上个星期六我没去公园。","giai":"Một thời điểm cụ thể không dùng 从来."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 103)","huongDan":"Hoàn thành câu, có dùng 「从来」","cau":[{"kieu":"vandung","de":"她性格很好，＿＿＿。","goiY":"Trước giờ không vì chuyện nhỏ mà giận","mau":"从来不因为小事生气","can":[["从来"]]},{"kieu":"vandung","de":"我住的地方离公司很近，＿＿＿。","goiY":"Nên trước giờ chưa bao giờ đến muộn","mau":"所以从来都不迟到","can":[["从来"]]},{"kieu":"vandung","de":"这个习惯他一直坚持到现在，＿＿＿。","goiY":"Chưa từng ngừng lần nào","mau":"从来没有停过","can":[["从来"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi chưa từng xem bộ phim này, nghe nói rất hay.","dap":["我从来没看过这个电影，听说很精彩。","我从来没看过这部电影，听说很精彩。","我从来没看过这个电影，听说很好看。"],"giai":"从来没 + V + 过 + từ mới 精彩."},{"kieu":"dich","vn":"Anh ấy trước giờ không nói dối, bạn cứ yên tâm là được.","dap":["他从来不说假话，你放心就是了。","他从来不说谎，你放心就是了。"],"giai":"从来不 + 就是了 (ôn Bài 2 · điểm 1)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một thói quen “trước giờ không bao giờ” hoặc một việc “chưa từng làm” của em, dùng 「从来不 / 从来没……过」","mau":"我从来不在晚上十二点以后睡觉，因为我觉得睡够了第二天才有精神。","can":[["从来"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-10.html"] = [{"so":"1","ten":"固定格式“说什么/怎么（着）也得×”","tenVn":"Cấu trúc cố định 「说什么 / 怎么(着) 也得×」 — dù thế nào cũng phải …","cauTruc":["(Chủ ngữ) + 说什么 + 也得 + V / cụm động từ","(Chủ ngữ) + 怎么（着）+ 也得 + V / cụm động từ"],"giaiThich":"Cấu trúc cố định 「说什么/怎么（着）也得×」 biểu thị nhất định phải, bằng mọi giá phải làm việc ×, thường dùng trong KHẨU NGỮ. Ở đây 说什么 / 怎么着 không còn nghĩa “nói gì / thế nào” nữa, cả cụm giống tiếng Việt “nói gì thì nói / dù thế nào đi nữa … cũng phải …”. Chữ 得 đọc děi (= phải), không đọc de. Vị trí: đứng sau chủ ngữ (hoặc sau trạng ngữ thời gian), trước động từ: 我明天说什么也得…… / 这次怎么着也得……. Muốn nói “nhất quyết KHÔNG” thì dùng 说什么也不 + V (他说什么也不去), không nói ✗ 也得不. So sánh: 不管怎么样都要…… (Bài 8 · điểm 1) cùng ý, nhưng 说什么也得 ngắn gọn, khẩu ngữ, giọng quyết tâm mạnh hơn.","viDu":[{"zh":"更重要的是，说什么也得穿上厚一点儿的衣服。","py":"Gèng zhòngyào de shì, shuō shénme yě děi chuānshang hòu yìdiǎnr de yīfu.","vn":"Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."},{"zh":"假期还有两天就结束了，我明天说什么也得把作业做完。","py":"Jiàqī hái yǒu liǎng tiān jiù jiéshù le, wǒ míngtiān shuō shénme yě děi bǎ zuòyè zuòwán.","vn":"Kỳ nghỉ còn hai ngày nữa là hết, ngày mai dù thế nào tôi cũng phải làm xong bài tập."},{"zh":"我很后悔上次没参加这个活动，这次怎么着也得去。","py":"Wǒ hěn hòuhuǐ shàng cì méi cānjiā zhège huódòng, zhè cì zěnmezhe yě děi qù.","vn":"Tôi rất hối hận lần trước không tham gia hoạt động này, lần này dù thế nào cũng phải đi."},{"zh":"不管工作多忙，春节我说什么也得回家。","py":"Bùguǎn gōngzuò duō máng, Chūnjié wǒ shuō shénme yě děi huíjiā.","vn":"Dù công việc bận đến đâu, Tết tôi nhất định phải về nhà. (ôn 不管……都…… – Bài 8 · điểm 1)"}],"loi":[{"sai":"我说什么得去。","why":"Thiếu 也 — cấu trúc cố định là 说什么 + 也 + 得.","dung":"我说什么也得去。"},{"sai":"他说什么也得不去。","why":"Muốn nói “nhất quyết không” thì dùng 说什么也不 + V.","dung":"他说什么也不去。"},{"sai":"我得说什么也去。","why":"说什么 / 怎么着 + 也 đứng TRƯỚC 得 + V.","dung":"我说什么也得去。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["更重要的是，说什么","穿上厚一点儿的衣服。"],"dap":[["也得"]],"chon":["也得","就得","才得"],"goiY":"“… dù thế nào cũng phải mặc áo dày một chút.”","giai":"Cấu trúc cố định: 说什么 + 也得 + V."},{"kieu":"dien","phan":["假期还有两天就结束了，我明天","也得把作业做完。"],"dap":[["说什么"]],"chon":["说什么","为什么","什么时候"],"goiY":"“Ngày mai dù thế nào tôi cũng phải làm xong bài tập.”","giai":"说什么也得 = dù thế nào cũng phải."},{"kieu":"dien","phan":["我很后悔上次没参加这个活动，这次怎么","也得去。"],"dap":[["着"]],"chon":["着","了","过"],"goiY":"“Lần này dù thế nào cũng phải đi.”","giai":"怎么着也得 (着 = zhe)."},{"kieu":"dien","phan":["这么低的温度，你说什么也得多穿点儿，","会冻坏的。"],"dap":[["否则"]],"chon":["否则","所以","而且"],"goiY":"“… nếu không sẽ rét cóng đấy.” (ôn 否则 – Bài 8)","giai":"……，否则…… = nếu không thì …"},{"kieu":"dien","phan":["冬天去哈尔滨，说什么也得穿上","一点儿的衣服。"],"dap":[["厚"]],"chon":["厚","低","暖和"],"goiY":"“… phải mặc quần áo dày một chút.”","giai":"厚一点儿的衣服 = áo dày hơn một chút."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","明天","说什么","也得","把作业","做完"],"dap":["我明天说什么也得把作业做完。","明天我说什么也得把作业做完。"],"goiY":"Ngày mai dù thế nào tôi cũng phải làm xong bài tập.","giai":"Chủ ngữ + thời gian + 说什么也得 + V."},{"kieu":"xep","manh":["这次","我","怎么着","也得","去","哈尔滨","看雪"],"dap":["这次我怎么着也得去哈尔滨看雪。","我这次怎么着也得去哈尔滨看雪。"],"goiY":"Lần này dù thế nào tôi cũng phải đi Cáp Nhĩ Tân ngắm tuyết.","giai":"怎么着也得 + V."},{"kieu":"xep","manh":["不管","多忙","，","春节","我","说什么也得","回家"],"dap":["不管多忙，春节我说什么也得回家。","不管多忙，我春节说什么也得回家。"],"goiY":"Dù bận đến đâu, Tết tôi nhất định phải về nhà.","giai":"Ôn 不管 (Bài 8) + 说什么也得."},{"kieu":"dungsai","cau":"妈妈生病了，我说什么也得回去看看她。","dung":true,"giai":"Đúng: 说什么也得 + V, biểu thị nhất định phải."},{"kieu":"dungsai","cau":"他说什么也得不去。","dung":false,"sua":"他说什么也不去。","giai":"Phủ định: 说什么也不 + V."},{"kieu":"dungsai","cau":"我说什么得去参加这个活动。","dung":false,"sua":"我说什么也得去参加这个活动。","giai":"Thiếu 也."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 109)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「说什么/怎么（着）也得×」","cau":[{"kieu":"vandung","de":"A：你要出去跑步吗？ B：是的，我已经好几天没运动了，今天＿＿＿。","goiY":"Hôm nay dù thế nào cũng phải ra ngoài vận động một chút","mau":"说什么也得出去活动活动","can":[["也得"]]},{"kieu":"vandung","de":"A：我这个蛋糕做得不好吃，你别吃了。 B：那怎么行？这是你专门为我做的，＿＿＿。","goiY":"Bánh làm riêng cho mình — dù thế nào cũng phải nếm thử","mau":"我怎么着也得尝尝","can":[["也得"]]},{"kieu":"vandung","de":"A：火车票和飞机票都卖完了，我们只能坐汽车回家过年了。 B：那也行。我们平时没时间，过年＿＿＿。","goiY":"Ngày thường không có thời gian, Tết dù thế nào cũng phải về nhà","mau":"怎么着也得回家","can":[["也得"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Ngày mai dù thế nào tôi cũng phải dậy sớm một chút.","dap":["明天我说什么也得早点儿起床。","我明天说什么也得早点儿起床。","明天我怎么着也得早点儿起床。","我明天怎么着也得早点儿起床。","明天我说什么也得早一点儿起床。"],"giai":"Thời gian + 说什么也得 + V."},{"kieu":"dich","vn":"Mùa đông đến Cáp Nhĩ Tân, dù thế nào cũng phải mặc quần áo dày.","dap":["冬天去哈尔滨，说什么也得穿厚衣服。","冬天来哈尔滨，说什么也得穿厚衣服。","冬天去哈尔滨，怎么着也得穿厚衣服。","冬天去哈尔滨，说什么也得穿厚一点儿的衣服。"],"giai":"说什么也得 + 穿厚衣服 (从课文1)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một việc năm nay em nhất định phải làm (và vì sao), dùng 「说什么/怎么（着）也得」","mau":"今年我说什么也得通过汉语水平考试四级，所以每天都要学习两个小时中文。","can":[["也得"]]}]}]},{"so":"2","ten":"固定短语“有的是”","tenVn":"Cụm từ cố định 「有的是」 — có thừa, có khối, thiếu gì","cauTruc":["(Chủ ngữ / Nơi chốn) + 有的是 + Danh từ","有的是 + 的-cụm (好吃的、好喝的…)"],"giaiThich":"Cụm từ cố định 「有的是」 thường dùng trong KHẨU NGỮ, biểu thị có rất nhiều, nhiều đến mức không cần lo — giống tiếng Việt “có thừa, có khối, thiếu gì”. Sau 有的是 là danh từ hoặc cụm “…的” (好吃的、好喝的). Rất hay dùng để TRẤN AN: 别急，以后有的是机会 (đừng vội, sau này thiếu gì cơ hội). Lưu ý cho người Việt: (1) 有的是 đã có nghĩa “rất nhiều” nên KHÔNG thêm 很多 / 很 (✗ 有的是很多钱); (2) không đi với số lượng cụ thể (✗ 有的是三件衣服); (3) đừng nhầm với 有的 (một số): 有的人喜欢冬天 = có người thích mùa đông. Ôn liên hệ: 够 (Bài 5) = đủ; 有的是 = thừa.","viDu":[{"zh":"没问题，受得了，我有的是厚衣服。","py":"Méi wèntí, shòu de liǎo, wǒ yǒudeshì hòu yīfu.","vn":"Không sao, chịu được, áo dày tớ có thừa."},{"zh":"过年时，家里有的是好吃的、好喝的，孩子们特别开心。","py":"Guònián shí, jiāli yǒudeshì hǎochī de, hǎohē de, háizimen tèbié kāixīn.","vn":"Dịp Tết, trong nhà đồ ăn thức uống ngon có khối, bọn trẻ vui lắm."},{"zh":"这个市场特别大，有的是水果和菜，你想买什么菜都能买到。","py":"Zhège shìchǎng tèbié dà, yǒudeshì shuǐguǒ hé cài, nǐ xiǎng mǎi shénme cài dōu néng mǎidào.","vn":"Chợ này rất to, rau quả nhiều vô kể, bạn muốn mua rau gì cũng mua được."},{"zh":"别着急，时间有的是，再说我们还来得及。","py":"Bié zháojí, shíjiān yǒudeshì, Zàishuō wǒmen hái láidejí.","vn":"Đừng vội, thời gian còn thừa, hơn nữa chúng ta vẫn kịp mà. (ôn 再说, 来得及 – Bài 4)"}],"loi":[{"sai":"我有的是很多厚衣服。","why":"有的是 đã mang nghĩa “rất nhiều”, không thêm 很多.","dung":"我有的是厚衣服。"},{"sai":"他有的是三本词典。","why":"Không đi với số lượng cụ thể.","dung":"他有的是词典。"},{"sai":"这里很有的是水果。","why":"Không thêm 很 trước 有的是.","dung":"这里有的是水果。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["没问题，受得了，我","厚衣服。"],"dap":[["有的是"]],"chon":["有的是","有的","是有"],"goiY":"“Không sao, áo dày tớ có thừa.”","giai":"有的是 + N = có rất nhiều."},{"kieu":"dien","phan":["过年时，家里有的是","的、好喝的，孩子们特别开心。"],"dap":[["好吃"]],"chon":["好吃","很多","多少"],"goiY":"“Đồ ăn ngon, đồ uống ngon có khối.”","giai":"有的是 + 好吃的、好喝的."},{"kieu":"dien","phan":["这个市场特别大，有的是水果和菜，你想买什么菜","能买到。"],"dap":[["都"]],"chon":["都","才","再"],"goiY":"“… muốn mua rau gì cũng mua được.”","giai":"什么……都…… (đại từ phiếm chỉ, HSK 3)."},{"kieu":"dien","phan":["别着急，以后有的是","，这次没申请到也没关系。"],"dap":[["机会"]],"chon":["机会","误会","社会"],"goiY":"“Đừng vội, sau này thiếu gì cơ hội.”","giai":"以后有的是机会 = sau này còn nhiều cơ hội."},{"kieu":"dien","phan":["这么冷的天气你","得了吗？——没问题，我有的是厚衣服。"],"dap":[["受"]],"chon":["受","冻","举"],"goiY":"“Trời lạnh thế này cậu chịu nổi không?” (ôn V得了 – Bài 4)","giai":"受得了 / 受不了."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","有的是","时间","，","可以","陪你","去"],"dap":["我有的是时间，可以陪你去。"],"goiY":"Tôi có thừa thời gian, có thể đi cùng bạn.","giai":"有的是 + N; 陪 (Bài 6)."},{"kieu":"xep","manh":["广州的","鲜花市场","里","有的是","花"],"dap":["广州的鲜花市场里有的是花。"],"goiY":"Chợ hoa tươi ở Quảng Châu hoa nhiều vô kể.","giai":"Nơi chốn + 有的是 + N."},{"kieu":"xep","manh":["别","担心","，","以后","有的是","机会"],"dap":["别担心，以后有的是机会。"],"goiY":"Đừng lo, sau này thiếu gì cơ hội.","giai":"Dùng để trấn an."},{"kieu":"dungsai","cau":"我们学校有的是外国留学生。","dung":true,"giai":"Đúng: nơi chốn + 有的是 + N."},{"kieu":"dungsai","cau":"我有的是很多钱。","dung":false,"sua":"我有的是钱。","giai":"Không thêm 很多 sau 有的是."},{"kieu":"dungsai","cau":"图书馆里有的是五本中文书。","dung":false,"sua":"图书馆里有的是中文书。","giai":"有的是 không đi với số lượng cụ thể."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 111–112)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「有的是」","cau":[{"kieu":"vandung","de":"A：今天上午你能陪孩子出去玩吗？ B：没问题，我＿＿＿。","goiY":"Tôi có thừa thời gian","mau":"有的是时间","can":[["有的是"]]},{"kieu":"vandung","de":"A：我的房子都一个多月了还没租出去呢。 B：别急，你的房子位置好，一定＿＿＿。","goiY":"Chắc chắn có rất nhiều người muốn thuê (ôn 租 – Bài 2)","mau":"有的是人想租","can":[["有的是"]]},{"kieu":"vandung","de":"A：我这次没有申请到出国交流的机会。 B：没事，＿＿＿。","goiY":"Sau này còn nhiều cơ hội (ôn 申请, 交流 – Bài 1)","mau":"以后有的是机会","can":[["有的是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đừng lo, ở Cáp Nhĩ Tân quần áo dày có thừa, muốn mua thì mua.","dap":["别担心，哈尔滨有的是厚衣服，想买就买。","别担心，哈尔滨有的是厚衣服，你想买就买。","别担心，在哈尔滨有的是厚衣服，想买就买。"],"giai":"Nơi chốn + 有的是 + N."},{"kieu":"dich","vn":"Thời gian còn thừa, chúng ta vẫn kịp.","dap":["时间有的是，我们还来得及。","有的是时间，我们还来得及。","我们有的是时间，还来得及。"],"giai":"有的是 + 来得及 (ôn Bài 4 · điểm 4)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giới thiệu quê em có rất nhiều thứ gì đó (hoa quả, món ăn, cảnh đẹp…), dùng 「有的是」","mau":"我的老家在越南南方，那里有的是水果，一年四季都能吃到新鲜的，欢迎你来玩儿。","can":[["有的是"]]}]}]},{"so":"3","ten":"连词“而”","tenVn":"Liên từ 「而」 — còn, mà, nhưng; (vì …) mà …","cauTruc":["(1) Chuyển ngoặt / đối lập: A……，而 B……（ý trái ngược）","(2) Nối tiếp: Adj / V + 而 + Adj / V（ý tiếp nối, bổ sung）","(3) Nhân quả: 因为 / 由于 + nguyên nhân + 而 + kết quả"],"giaiThich":"Liên từ 「而」 nối động từ, tính từ, cụm từ hoặc phân câu, có nhiều nghĩa; bài này học 3 cách dùng. (1) CHUYỂN NGOẶT: hai thành phần mà 而 nối có ý TRÁI NGƯỢC nhau — thường dùng khi so sánh hai đối tượng: 广州基本上没有冬天，而哈尔滨的冬天…… — dịch “còn / trong khi đó / nhưng”. (2) NỐI TIẾP: nối hai thành phần cùng chiều, ý tiếp nối nhau: 紧张而兴奋 (căng thẳng mà hào hứng), 热情而积极 — dịch “mà, và”. (3) NHÂN QUẢ: phía trước là nguyên nhân (thường có 因为 / 由于), phía sau 而 là kết quả: 因为天气暖和而吸引了很多游客 — dịch “vì … mà …”. 而 mang màu sắc VĂN VIẾT. Lưu ý cho người Việt: 而 không nối hai danh từ (dùng 和); 而 đứng đầu vế sau, TRƯỚC chủ ngữ; đừng nhầm 而 với 而且 (hơn nữa — tăng tiến, Bài 3 · 不仅……而且……).","viDu":[{"zh":"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","py":"Guǎngzhōu jīběn shàng méiyǒu dōngtiān, ér Hā'ěrbīn de dōngtiān yìbān huì cóng shíyuè kāishǐ, dào dì èr nián de sān sì yuè cái jiéshù.","vn":"Quảng Châu gần như không có mùa đông, còn mùa đông Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tháng Ba, tháng Tư năm sau mới kết thúc."},{"zh":"在这个紧张而兴奋的日子里，我们都走出教室，为运动员们加油。","py":"Zài zhège jǐnzhāng ér xīngfèn de rìzi lǐ, wǒmen dōu zǒuchū jiàoshì, wèi yùndòngyuánmen jiāyóu.","vn":"Trong những ngày căng thẳng mà hào hứng này, chúng tôi đều ra khỏi lớp, cổ vũ cho các vận động viên. (兴奋 xīngfèn = hào hứng)"},{"zh":"冬天，这个城市因为天气暖和而吸引了很多游客。","py":"Dōngtiān, zhège chéngshì yīnwèi tiānqì nuǎnhuo ér xīyǐn le hěn duō yóukè.","vn":"Mùa đông, thành phố này vì thời tiết ấm áp mà thu hút rất nhiều du khách."},{"zh":"跟北方相比，南方冬天比较暖和，而北方冬天冷得让人受不了。","py":"Gēn běifāng xiāngbǐ, nánfāng dōngtiān bǐjiào nuǎnhuo, ér běifāng dōngtiān lěng de ràng rén shòubuliǎo.","vn":"So với miền Bắc, mùa đông miền Nam khá ấm, còn mùa đông miền Bắc lạnh đến mức không chịu nổi. (ôn 跟……相比 – Bài 8 · điểm 3)"}],"loi":[{"sai":"我喜欢苹果而香蕉。","why":"而 không nối hai danh từ — dùng 和.","dung":"我喜欢苹果和香蕉。"},{"sai":"广州冬天很暖和，哈尔滨而特别冷。","why":"而 đứng ĐẦU vế sau, trước chủ ngữ.","dung":"广州冬天很暖和，而哈尔滨特别冷。"},{"sai":"他不仅聪明，而很努力。","why":"Ý tăng tiến “không chỉ … mà còn” dùng 而且, không dùng 而.","dung":"他不仅聪明，而且很努力。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["广州基本上没有冬天，","哈尔滨的冬天一般会从十月开始。"],"dap":[["而"]],"chon":["而","和","跟"],"goiY":"“Quảng Châu gần như không có mùa đông, còn Cáp Nhĩ Tân …”","giai":"Đối lập hai đối tượng → 而 (和 / 跟 chỉ nối danh từ)."},{"kieu":"dien","phan":["在这个紧张","兴奋的日子里，我们都走出教室，为运动员们加油。"],"dap":[["而"]],"chon":["而","也","就"],"goiY":"“Trong những ngày căng thẳng mà hào hứng này …”","giai":"Adj + 而 + Adj (nối tiếp)."},{"kieu":"dien","phan":["冬天，这个城市因为天气暖和而","了很多游客。"],"dap":[["吸引"]],"chon":["吸引","引起","举办"],"goiY":"“… vì thời tiết ấm mà thu hút nhiều du khách.”","giai":"因为……而 + kết quả; 吸引游客 = thu hút du khách."},{"kieu":"dien","phan":["哈尔滨方言和普通话听起来比较像，而广州方言和普通话","较大。"],"dap":[["差别"]],"chon":["差别","气候","方言"],"goiY":"“… còn tiếng Quảng Châu khác tiếng phổ thông khá nhiều.”","giai":"差别较大 = khác biệt khá lớn."},{"kieu":"dien","phan":["学校","天气不好而取消了运动会。"],"dap":[["由于"]],"chon":["由于","虽然","如果"],"goiY":"“Trường do thời tiết xấu mà huỷ đại hội thể thao.” (ôn 由于 – Bài 2)","giai":"由于 / 因为 + nguyên nhân + 而 + kết quả."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["南方","冬天","很暖和","，","而","北方","冬天","很冷"],"dap":["南方冬天很暖和，而北方冬天很冷。"],"goiY":"Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.","giai":"A……，而 B…… (đối lập)."},{"kieu":"xep","manh":["她","表现得","热情","而","积极"],"dap":["她表现得热情而积极。"],"goiY":"Cô ấy thể hiện nhiệt tình và tích cực.","giai":"Adj + 而 + Adj; 表现 (Bài 1)."},{"kieu":"xep","manh":["校园","因为","放寒假","而","变得","十分安静"],"dap":["校园因为放寒假而变得十分安静。"],"goiY":"Sân trường vì nghỉ đông mà trở nên rất yên tĩnh.","giai":"因为……而…… (nhân quả)."},{"kieu":"dungsai","cau":"哥哥喜欢安静，而弟弟喜欢热闹。","dung":true,"giai":"Đúng: 而 nối hai vế đối lập."},{"kieu":"dungsai","cau":"我买了牛奶而面包。","dung":false,"sua":"我买了牛奶和面包。","giai":"而 không nối hai danh từ."},{"kieu":"dungsai","cau":"他因为生病了，而所以没来上课。","dung":false,"sua":"他因为生病而没来上课。","giai":"因为……而…… đã có ý nhân quả, không thêm 所以."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 114)","huongDan":"Hoàn thành câu, dùng 「而」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"今天＿＿＿，下午三点才结束。（气温）","goiY":"Câu sách: 今天＿＿特别高，＿＿，下午三点才结束 — viết: nhiệt độ hôm nay đặc biệt cao, mà chúng tôi còn phải tham gia hoạt động ngoài trời","mau":"的气温特别高，而我们还要在外面参加活动","can":[["而"],["气温"]]},{"kieu":"vandung","de":"他＿＿＿，客户对他非常满意。（表现）","goiY":"Anh ấy thể hiện nhiệt tình và tích cực (客户 kèhù = khách hàng)","mau":"表现得热情而积极","can":[["而"],["表现"]]},{"kieu":"vandung","de":"热闹的校园因为放寒假＿＿＿。（安静）","goiY":"Vì nghỉ đông mà trở nên rất yên tĩnh","mau":"而变得十分安静","can":[["而"],["安静"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.","dap":["南方冬天很暖和，而北方冬天很冷。","南方的冬天很暖和，而北方的冬天很冷。","南方冬天很暖和，而北方很冷。"],"giai":"A……，而 B…… (đối lập)."},{"kieu":"dich","vn":"Thành phố này vì có nhiều hoa mà được gọi là “Thành phố hoa”.","dap":["这个城市因为花多而叫“花城”。","这个城市因为有很多花而叫“花城”。","这个城市因为花很多而被叫做“花城”。","这个城市因为花多而被叫做“花城”。"],"giai":"因为……而…… (nhân quả)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"So sánh quê em với một thành phố khác (khí hậu, đồ ăn, tiếng nói…), dùng 「而」","mau":"我的老家在越南南方，一年四季都很热，而河内冬天比较冷，有时候气温只有十度左右。","can":[["而"]]}]}]},{"so":"4","ten":"频率副词“再次”","tenVn":"Phó từ tần suất 「再次」 — lại một lần nữa, lần thứ hai","cauTruc":["再次 + V / cụm động từ","Chủ ngữ + (thời gian) + 再次 + V"],"giaiThich":"Phó từ tần suất 「再次」 đứng TRƯỚC động từ, biểu thị lần thứ hai, thêm một lần nữa. Mang sắc thái trang trọng, hay gặp trong văn viết, thư, thông báo, phát biểu: 再次感谢您的支持！ So sánh với những từ đã học: 再 (HSK 2) thường dùng cho việc CHƯA xảy ra (明天再来); 又 (HSK 3) dùng cho việc ĐÃ lặp lại (他又迟到了); còn 再次 dùng được cho cả việc đã xảy ra (我们再次开展了……活动) lẫn việc sắp làm (我计划再次去哈尔滨). Lưu ý cho người Việt: đã có 再次 thì không thêm 又 (✗ 又再次 — thừa); 再次 không đứng sau động từ (✗ 见面再次); 了 đặt sau động từ chứ không sau 再次 (✗ 再次了检查).","viDu":[{"zh":"今年的“世界环境日”，我们再次开展“绿色生活”活动。","py":"Jīnnián de “shìjiè huánjìng rì”, wǒmen zàicì kāizhǎn “lǜsè shēnghuó” huódòng.","vn":"Ngày Môi trường Thế giới năm nay, chúng ta lại một lần nữa phát động hoạt động “Sống xanh”."},{"zh":"我去年冬天去过一次哈尔滨，很喜欢那里的雪；今年冬天，我计划再次去哈尔滨看雪。","py":"Wǒ qùnián dōngtiān qù guò yí cì Hā'ěrbīn, hěn xǐhuan nàli de xuě; jīnnián dōngtiān, wǒ jìhuà zàicì qù Hā'ěrbīn kàn xuě.","vn":"Mùa đông năm ngoái tôi đã đi Cáp Nhĩ Tân một lần, rất thích tuyết ở đó; mùa đông năm nay, tôi định đi Cáp Nhĩ Tân ngắm tuyết lần nữa."},{"zh":"再次感谢您的支持与关心！","py":"Zàicì gǎnxiè nín de zhīchí yǔ guānxīn!","vn":"Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!"},{"zh":"尽管上次没有成功，但是他还是决定再次试一试。","py":"Jǐnguǎn shàng cì méiyǒu chénggōng, dànshì tā háishi juédìng zàicì shì yi shì.","vn":"Dù lần trước không thành công, nhưng anh ấy vẫn quyết định thử thêm lần nữa. (ôn 尽管……但是…… – Bài 9 · điểm 2)"}],"loi":[{"sai":"我们再次了见面。","why":"了 đặt sau động từ, không đặt ngay sau 再次.","dung":"我们再次见面了。"},{"sai":"他昨天又再次迟到了。","why":"又 và 再次 cùng nghĩa “lại” — chỉ dùng một từ.","dung":"他昨天再次迟到了。"},{"sai":"我们见面再次。","why":"再次 là phó từ, phải đứng TRƯỚC động từ.","dung":"我们再次见面。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["今年的“世界环境日”，我们","开展“绿色生活”活动。"],"dap":[["再次"]],"chon":["再次","从来","偶尔"],"goiY":"“… chúng ta lại một lần nữa phát động hoạt động “Sống xanh”.”","giai":"再次 + V."},{"kieu":"dien","phan":["今年冬天，我计划再次去哈尔滨","雪。"],"dap":[["看"]],"chon":["看","见","冻"],"goiY":"“… tôi định lại đi Cáp Nhĩ Tân ngắm tuyết.”","giai":"看雪 = ngắm tuyết."},{"kieu":"dien","phan":["","感谢您的支持与关心！"],"dap":[["再次"]],"chon":["再次","再说","此外"],"goiY":"“Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!”","giai":"再次感谢 — câu trang trọng cuối thư, phát biểu."},{"kieu":"dien","phan":["他出门前再次","了一下行李，看看东西都带好了没有。"],"dap":[["检查"]],"chon":["检查","举办","开展"],"goiY":"“Trước khi ra khỏi nhà anh ấy kiểm tra lại hành lý lần nữa.”","giai":"再次 + 检查."},{"kieu":"dien","phan":["尽管上次没有成功，","他还是决定再次试一试。"],"dap":[["但是"]],"chon":["但是","而且","所以"],"goiY":"“Dù lần trước không thành công, nhưng anh ấy vẫn …” (ôn Bài 9)","giai":"尽管……但是……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["欢迎","您","再次","来","我们这里","旅游"],"dap":["欢迎您再次来我们这里旅游。"],"goiY":"Chào mừng ngài lại đến chỗ chúng tôi du lịch.","giai":"再次 + 来."},{"kieu":"xep","manh":["再次","见到","老同学","，","大家","都特别高兴"],"dap":["再次见到老同学，大家都特别高兴。"],"goiY":"Gặp lại bạn học cũ, mọi người đều đặc biệt vui.","giai":"再次 + 见到."},{"kieu":"xep","manh":["学校","再次","举办了","垃圾分类","活动"],"dap":["学校再次举办了垃圾分类活动。"],"goiY":"Trường lại tổ chức hoạt động phân loại rác.","giai":"再次 + V了 (việc đã xảy ra)."},{"kieu":"dungsai","cau":"下个月我们会再次开展环保活动。","dung":true,"giai":"Đúng: 再次 dùng cho việc sắp làm."},{"kieu":"dungsai","cau":"他又再次忘了带钥匙。","dung":false,"sua":"他再次忘了带钥匙。","giai":"又 và 再次 trùng nghĩa — bỏ 又."},{"kieu":"dungsai","cau":"我们再次了检查行李。","dung":false,"sua":"我们再次检查了行李。","giai":"了 đặt sau động từ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 116)","huongDan":"Hoàn thành câu, có dùng 「再次」","cau":[{"kieu":"vandung","de":"欢迎您＿＿＿。","goiY":"Chào mừng ngài lại đến chỗ chúng tôi du lịch","mau":"再次来我们这里旅游","can":[["再次"]]},{"kieu":"vandung","de":"＿＿＿老同学，大家都特别高兴。","goiY":"Gặp lại bạn học cũ","mau":"再次见到","can":[["再次"]]},{"kieu":"vandung","de":"他出门前＿＿＿，看看东西都带好了没有。","goiY":"Kiểm tra lại hành lý một lần nữa","mau":"再次检查了一下行李","can":[["再次"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Một lần nữa cảm ơn sự giúp đỡ của mọi người!","dap":["再次感谢大家的帮助！","再次谢谢大家的帮助！"],"giai":"再次感谢 — trang trọng."},{"kieu":"dich","vn":"Năm sau tôi định lại đi Quảng Châu lần nữa.","dap":["明年我打算再次去广州。","我明年打算再次去广州。","明年我计划再次去广州。","我明年计划再次去广州。"],"giai":"Thời gian + 打算 / 计划 + 再次 + V."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể về một nơi em muốn quay lại lần nữa và lý do, dùng 「再次」","mau":"我去年去过一次云南，那里的气候特别舒服，明年寒假我想再次去那儿旅游。","can":[["再次"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-11.html"] = [{"so":"1","ten":"让步复句“即使……，也……”","tenVn":"Câu phức nhượng bộ 「即使……，也……」 — cho dù …, cũng …","cauTruc":["即使 + giả thiết (thường bất lợi / cực đoan)，(chủ ngữ) + 也 + kết quả không đổi","Chủ ngữ + 即使 + giả thiết，也 + ……"],"giaiThich":"Đây là câu phức NHƯỢNG BỘ: vế trước nêu một GIẢ THIẾT — thường là tình huống bất lợi hoặc cực đoan (mưa to, tuổi cao, rất khó…); vế sau nói kết quả KHÔNG thay đổi, không bị ảnh hưởng. 「即使」 ≈ “cho dù, dù cho, ngay cả khi”; vế sau bắt buộc có 「也」, đặt sau chủ ngữ, trước động từ (✗ 也我 → ✓ 我也). 即使 có thể đứng trước hoặc sau chủ ngữ vế đầu. Hay gặp 即使 + 再 + tính từ (即使再忙, 即使再累). Phân biệt cho người Việt: 虽然……但是…… (HSK 3) và 尽管……但是…… (Bài 9) nói SỰ THẬT đã có; 即使……也…… thường nói GIẢ THIẾT (chưa xảy ra / giả sử): 虽然下雨了 (đang mưa thật) — 即使下雨 (giả sử có mưa). Vì vậy 即使 KHÔNG đi với 但是. So với 不管……都/也…… (Bài 8): 不管 + điều kiện có lựa chọn / đại từ nghi vấn (不管多忙, 不管下不下雨); 即使 + một giả thiết cụ thể (即使很忙). Gần nghĩa với dạng rút gọn 不……也…… (Bài 9) nhưng đầy đủ và rõ ràng hơn.","viDu":[{"zh":"有些人即使年龄大了，也坚持去老年班学习。","py":"Yǒuxiē rén jíshǐ niánlíng dà le, yě jiānchí qù lǎoniánbān xuéxí.","vn":"Có những người dù tuổi đã cao vẫn kiên trì đi học lớp người cao tuổi."},{"zh":"即使明天下大雨，我们也会按时出发。","py":"Jíshǐ míngtiān xià dàyǔ, wǒmen yě huì ànshí chūfā.","vn":"Cho dù ngày mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ."},{"zh":"即使大家都说很难，我也要试一试。","py":"Jíshǐ dàjiā dōu shuō hěn nán, wǒ yě yào shì yi shì.","vn":"Cho dù mọi người đều nói rất khó, tôi cũng muốn thử một lần."},{"zh":"即使工作再忙，他每天也至少看半个小时书。","py":"Jíshǐ gōngzuò zài máng, tā měitiān yě zhìshǎo kàn bàn gè xiǎoshí shū.","vn":"Cho dù công việc bận đến mấy, mỗi ngày anh ấy cũng đọc sách ít nhất nửa tiếng. (ôn 至少 – Bài 5 · điểm 1)"}],"loi":[{"sai":"即使明天下大雨，我们会按时出发。","why":"Thiếu 也 ở vế sau — 即使 phải đi với 也.","dung":"即使明天下大雨，我们也会按时出发。"},{"sai":"即使大家都说很难，也我要试一试。","why":"也 là phó từ, đứng SAU chủ ngữ, trước động từ.","dung":"即使大家都说很难，我也要试一试。"},{"sai":"即使昨天下了大雨，但是比赛没有停。","why":"Việc đã xảy ra thật + 但是 → dùng 虽然 / 尽管……但是……; 即使 không đi với 但是.","dung":"虽然昨天下了大雨，但是比赛没有停。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["有些人","年龄大了，也坚持去老年班学习。"],"dap":[["即使"]],"chon":["即使","虽然","因为"],"goiY":"“Có những người dù tuổi đã cao vẫn kiên trì …”","giai":"Vế sau có 也 → vế trước dùng 即使 (giả thiết nhượng bộ)."},{"kieu":"dien","phan":["即使明天下大雨，我们","会按时出发。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“Cho dù mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.”","giai":"即使……，(Sub) + 也 + V."},{"kieu":"dien","phan":["即使年龄大了，爷爷也","去老年班学电脑。"],"dap":[["坚持"]],"chon":["坚持","羡慕","散步"],"goiY":"“Dù tuổi đã cao, ông vẫn kiên trì đi học máy tính.”","giai":"坚持 + V = kiên trì làm gì."},{"kieu":"dien","phan":["即使工作再忙，他也","每周给家里打一次电话。"],"dap":[["至少"]],"chon":["至少","甚至","从来"],"goiY":"“… mỗi tuần anh ấy cũng gọi về nhà ít nhất một lần.” (ôn 至少 – Bài 5)","giai":"至少 + V + số lượng = ít nhất."},{"kieu":"dien","phan":["","不在一个学校了，我们也要经常联系。"],"dap":[["即使"]],"chon":["即使","由于","随着"],"goiY":"“Cho dù không học cùng trường nữa, chúng ta cũng phải thường xuyên liên lạc.”","giai":"Giả thiết bất lợi + 也 → 即使."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["即使","明天","下大雨","，","我们","也会","按时出发"],"dap":["即使明天下大雨，我们也会按时出发。"],"goiY":"Cho dù ngày mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.","giai":"即使 + giả thiết，Sub + 也 + V."},{"kieu":"xep","manh":["即使","缺水","，","门前的花","也","长得","很好"],"dap":["即使缺水，门前的花也长得很好。"],"goiY":"Cho dù thiếu nước, hoa trước cửa vẫn mọc rất tốt.","giai":"也 đứng sau chủ ngữ 门前的花."},{"kieu":"xep","manh":["他","即使","再忙","，","也","会","坚持锻炼身体"],"dap":["他即使再忙，也会坚持锻炼身体。","即使再忙，他也会坚持锻炼身体。"],"goiY":"Anh ấy cho dù bận đến mấy cũng kiên trì rèn luyện thân thể.","giai":"即使 + 再 + Adj，也……"},{"kieu":"dungsai","cau":"即使大家都说很难，我也要试一试。","dung":true,"giai":"Đúng: 即使……，Sub + 也……"},{"kieu":"dungsai","cau":"即使昨天下了大雨，但是比赛没有停。","dung":false,"sua":"虽然昨天下了大雨，但是比赛没有停。","giai":"Sự thật đã xảy ra + 但是 → 虽然……但是……"},{"kieu":"dungsai","cau":"即使你不去，我去。","dung":false,"sua":"即使你不去，我也去。","giai":"Thiếu 也."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 3)","huongDan":"Hoàn thành đối thoại, có dùng 「即使……，也……」","cau":[{"kieu":"vandung","de":"A：门前的花长得真不错！ B：是的，即使缺（quē, thiếu）水，＿＿＿。","goiY":"Nói: hoa vẫn mọc rất tốt (也……)","mau":"它们也长得很好","can":[["也"]]},{"kieu":"vandung","de":"A：即使不在一个学校了，＿＿＿。 B：当然！平时没时间，假期也要多聚聚。","goiY":"A nói: chúng ta vẫn phải thường xuyên liên lạc, gặp nhau (也……)","mau":"我们也要经常联系、经常见面","can":[["也"]]},{"kieu":"vandung","de":"A：任务这么重，你们能完成吗？ B：＿＿＿，＿＿＿。","goiY":"Khẳng định: cho dù ngày nào cũng phải tăng ca, cũng nhất định hoàn thành đúng hạn","mau":"即使每天加班，我们也一定会按时完成","can":[["即使"],["也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cho dù tuổi đã cao, ông tôi vẫn kiên trì đi học lớp người cao tuổi.","dap":["即使年龄大了，我爷爷也坚持去老年班学习。","我爷爷即使年龄大了，也坚持去老年班学习。"],"giai":"即使……，Sub + 也 + 坚持……"},{"kieu":"dich","vn":"Cho dù ngày mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.","dap":["即使明天下大雨，我们也会准时出发。","即使明天下大雨，我们也会按时出发。"],"giai":"即使……也…… + từ mới 准时."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về quyết tâm học tiếng Trung của em, có dùng 「即使……也……」","mau":"即使工作再忙，我也要每天留出一个小时学习中文。","can":[["即使"],["也"]]}]}]},{"so":"2","ten":"让步复句“就是……，也……”","tenVn":"Câu phức nhượng bộ 「就是……，也……」 — cho dù …, cũng … (khẩu ngữ)","cauTruc":["就是 + giả thiết cực đoan / điều kiện nhượng bộ，(chủ ngữ) + 也 + kết quả / thái độ không đổi","Chủ ngữ + 就是 + ……，也 + ……"],"giaiThich":"「就是」 ở đây là LIÊN TỪ, nghĩa giống 「即使」 (cho dù, kể cả), nhưng mang màu sắc KHẨU NGỮ — rất hay dùng khi nói chuyện. Vế trước nêu một giả thiết cực đoan hoặc điều kiện nhượng bộ; vế sau (có 也) nói kết quả vẫn không đổi, hoặc vẫn giữ một thái độ, hành động nào đó. Hay đi với 再 + tính từ: 就是再忙 / 再累 / 再贵，也……. Văn viết, trang trọng → 即使; nói chuyện → 就是. ⚠ Đừng nhầm các 「就是」 đã học: ×就是了 (Bài 2 – cuối câu: cứ … là được); ……×是×，就是…… (Bài 3 – vế sau: chỉ có điều); 就是 đứng một mình tỏ ý đồng tình (Bài 10 – đúng thế); 就是 = chính là (他就是李教授). Mẹo nhận biết: 就是 ở vế ĐẦU + 也 ở vế SAU → “cho dù … cũng …”.","viDu":[{"zh":"我就是不在教室，也可以学习中文，和同学一起练口语。","py":"Wǒ jiùshì bú zài jiàoshì, yě kěyǐ xuéxí Zhōngwén, hé tóngxué yìqǐ liàn kǒuyǔ.","vn":"Mình cho dù không ở lớp cũng có thể học tiếng Trung, luyện nói cùng các bạn."},{"zh":"锻炼身体很重要，就是再忙，也要坚持运动。","py":"Duànliàn shēntǐ hěn zhòngyào, jiùshì zài máng, yě yào jiānchí yùndòng.","vn":"Rèn luyện thân thể rất quan trọng, cho dù bận đến mấy cũng phải kiên trì tập thể thao."},{"zh":"明天开会需要这份材料，我就是今晚不睡觉，也要把它改完。","py":"Míngtiān kāihuì xūyào zhè fèn cáiliào, wǒ jiùshì jīnwǎn bú shuìjiào, yě yào bǎ tā gǎi wán.","vn":"Mai họp cần tài liệu này, tôi dù đêm nay không ngủ cũng phải sửa xong nó."},{"zh":"就是明天下大雨，我说什么也得去机场接你。","py":"Jiùshì míngtiān xià dàyǔ, wǒ shuō shénme yě děi qù jīchǎng jiē nǐ.","vn":"Cho dù mai mưa to, tôi nhất định phải ra sân bay đón bạn. (ôn 说什么也得× – Bài 10 · điểm 1)"}],"loi":[{"sai":"就是再忙，我要坚持运动。","why":"Thiếu 也 ở vế sau.","dung":"就是再忙，我也要坚持运动。"},{"sai":"我就是不在教室，就可以学习中文。","why":"Vế sau dùng 也 (kết quả không đổi), không dùng 就.","dung":"我就是不在教室，也可以学习中文。"},{"sai":"他就是不来，我们开会也。","why":"也 là phó từ, đứng trước động từ.","dung":"他就是不来，我们也开会。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我","不在教室，也可以学习中文，和同学一起练口语。"],"dap":[["就是"]],"chon":["就是","就是了","只要"],"goiY":"“Mình cho dù không ở lớp cũng có thể học tiếng Trung …”","giai":"就是 (liên từ) ở vế đầu + 也 ở vế sau."},{"kieu":"dien","phan":["锻炼身体很重要，就是再忙，","要坚持运动。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… cho dù bận đến mấy cũng phải kiên trì tập thể thao.”","giai":"就是再 + Adj，也……"},{"kieu":"dien","phan":["明天开会需要这份材料，我就是今晚不睡觉，也要把它","完。"],"dap":[["改"]],"chon":["改","留","弹"],"goiY":"“… dù đêm nay không ngủ cũng phải sửa xong nó.”","giai":"把 + O + 改完 (ôn câu chữ 把)."},{"kieu":"dien","phan":["就是不在一个城市，我们也可以在","上见面。"],"dap":[["线上"]],"chon":["线上","线下","网友"],"goiY":"“Cho dù không ở cùng thành phố, chúng ta vẫn có thể gặp nhau trực tuyến.”","giai":"在线上 + V = trực tuyến."},{"kieu":"dien","phan":["课上没听明白也没关系，就是没有老师，课后也能看","记录自学。"],"dap":[["视频"]],"chon":["视频","分数","口语"],"goiY":"“… cho dù không có thầy, sau giờ học vẫn có thể xem video ghi lại để tự học.”","giai":"视频记录 = video ghi lại."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["就是","再忙","，","也","要","坚持运动"],"dap":["就是再忙，也要坚持运动。"],"goiY":"Cho dù bận đến mấy cũng phải kiên trì tập thể thao.","giai":"就是再 + Adj，也 + V."},{"kieu":"xep","manh":["我","就是","今晚不睡觉","，","也要","把材料","改完"],"dap":["我就是今晚不睡觉，也要把材料改完。"],"goiY":"Tôi dù đêm nay không ngủ cũng phải sửa xong tài liệu.","giai":"Sub + 就是……，也要 + 把……"},{"kieu":"xep","manh":["就是","下大雨","，","我们","也得","去"],"dap":["就是下大雨，我们也得去。"],"goiY":"Cho dù mưa to, chúng ta cũng phải đi.","giai":"也得 (děi) = cũng phải."},{"kieu":"dungsai","cau":"就是再贵，我就买。","dung":false,"sua":"就是再贵，我也买。","giai":"Vế sau của 就是 phải dùng 也."},{"kieu":"dungsai","cau":"就是他是我的好朋友，我也不能帮他做这种事。","dung":true,"giai":"Đúng: 就是 + một câu, vế sau 也 + phủ định."},{"kieu":"dungsai","cau":"他就是不来，我们开会也。","dung":false,"sua":"他就是不来，我们也开会。","giai":"也 đứng trước động từ 开会."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 5–6)","huongDan":"Hoàn thành đối thoại, có dùng 「就是……，也……」","cau":[{"kieu":"vandung","de":"A：经理不来，我们怎么办呢？ B：经理就是不来，＿＿＿。","goiY":"Nói: chúng ta vẫn họp đúng giờ (也……)","mau":"我们也要按时开会","can":[["也"]]},{"kieu":"vandung","de":"A：外边下小雨呢，我们还去吗？ B：＿＿＿，我们也得去。","goiY":"Nêu giả thiết cực đoan hơn: cho dù mưa to","mau":"就是下大雨","can":[["就是"]]},{"kieu":"vandung","de":"A：李教授不在北京，这个问题咱们怎么解决呢？ B：＿＿＿，＿＿＿。咱们可以和他在线上交流。","goiY":"Nói: cho dù giáo sư không ở Bắc Kinh, ông ấy cũng giúp chúng ta giải quyết được","mau":"他就是不在北京，也能帮咱们解决","can":[["就是"],["也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cho dù bận đến mấy, cuối tuần tôi cũng sẽ dành thời gian đi dạo cùng ông bà.","dap":["就是再忙，周末我也会留出时间陪爷爷奶奶散步。","就是再忙，我周末也会留出时间陪爷爷奶奶散步。"],"giai":"就是再忙，……也…… + từ mới 留, 散步."},{"kieu":"dich","vn":"Cho dù không có thầy cô, chúng ta cũng có thể tự học trên mạng.","dap":["就是没有老师，我们也可以在网上自学。","就是没有老师，我们也能在网上自学。"],"giai":"就是……，Sub + 也 + 可以 / 能……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em ngại học online vì không có thầy ở bên. Hãy động viên bạn bằng một câu có 「就是……也……」","mau":"就是老师不在你旁边，你也能在网上找到很多资料自学。","can":[["就是"],["也"]]}]}]},{"so":"3","ten":"并列复句“不是……，而是……”","tenVn":"Câu phức song song 「不是……，而是……」 — không phải …, mà là …","cauTruc":["(Chủ ngữ) + 不是 + A，而是 + B (phủ định A, khẳng định B)","……的目的 / 原因 + 不是……，而是……"],"giaiThich":"Câu phức song song: PHỦ ĐỊNH vế trước, KHẲNG ĐỊNH vế sau, nhấn mạnh sự khác biệt hoặc đối lập giữa hai vế — “không phải là A, mà là B”. A và B nên cùng loại (cùng là động từ, cùng là cụm danh từ, cùng là lý do…) để đối chiếu rõ: 不是想喝茶，而是想喝水. 「而是」 là một khối, không bỏ 是 (✗ 不是……，而……). Liên hệ bài cũ: 而 (Bài 10 · điểm 3) nối hai vế tương phản; 不是……而是…… là khuôn cố định, ý “sửa lại cho đúng” mạnh hơn. ⚠ Người Việt hay nhầm với 不但 / 不仅……而且…… (Bài 3): “không những … mà còn …” → cả A và B đều đúng; còn 不是……而是…… → A SAI, B mới ĐÚNG. Hay dùng để giải thích nguyên nhân thật: 我不是不想去，而是……","viDu":[{"zh":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","py":"Jiàoyù de mùdì bú shì ràng háizi kǎo gāofēn, érshì bāngzhù háizi yǎngchéng hǎo xíguàn.","vn":"Mục đích của giáo dục không phải là để con thi được điểm cao, mà là giúp con hình thành thói quen tốt."},{"zh":"我不是想喝茶，而是想喝水。","py":"Wǒ bú shì xiǎng hē chá, érshì xiǎng hē shuǐ.","vn":"Tôi không phải muốn uống trà, mà là muốn uống nước."},{"zh":"我放学后不是直接回家，而是先去超市买笔。","py":"Wǒ fàngxué hòu bú shì zhíjiē huíjiā, érshì xiān qù chāoshì mǎi bǐ.","vn":"Tan học tôi không về thẳng nhà, mà là đi siêu thị mua bút trước."},{"zh":"我不是不想去，而是实在来不及了。","py":"Wǒ bú shì bù xiǎng qù, érshì shízai láibují le.","vn":"Không phải tôi không muốn đi, mà là thực sự không kịp nữa rồi. (ôn 来不及 – Bài 4 · điểm 4)"}],"loi":[{"sai":"我不是想喝茶，而想喝水。","why":"Phải là 而是, không bỏ 是.","dung":"我不是想喝茶，而是想喝水。"},{"sai":"他不仅想喝茶，而是想喝水。","why":"不仅 đi với 而且 / 还 (cả hai đều đúng); phủ định A khẳng định B thì dùng 不是……而是…….","dung":"他不是想喝茶，而是想喝水。"},{"sai":"不是我放学后直接回家，而是先去超市买笔。","why":"Hai vế phải cân đối: 不是 và 而是 cùng đứng sau chủ ngữ, trước phần được so sánh.","dung":"我放学后不是直接回家，而是先去超市买笔。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["教育的目的不是让孩子考高分，","帮助孩子养成好习惯。"],"dap":[["而是"]],"chon":["而是","而且","还是"],"goiY":"“… không phải là để con thi điểm cao, mà là giúp con hình thành thói quen tốt.”","giai":"不是……，而是…… (phủ định – khẳng định)."},{"kieu":"dien","phan":["我","想喝茶，而是想喝水。"],"dap":[["不是"]],"chon":["不是","不仅","没有"],"goiY":"“Tôi không phải muốn uống trà, mà là muốn uống nước.”","giai":"而是 đi với 不是; 不仅 đi với 而且."},{"kieu":"dien","phan":["他学钢琴不是为了","，而是因为真的喜欢。"],"dap":[["分数"]],"chon":["分数","礼貌","资料"],"goiY":"“Cậu ấy học piano không phải vì điểm số, mà vì thật sự thích.”","giai":"Hai vế đều nêu lý do: 为了…… / 因为……"},{"kieu":"dien","phan":["他们不是在聊天儿，而是在开线上","。"],"dap":[["会议"]],"chon":["会议","视频","网页"],"goiY":"“Họ không phải đang tán gẫu, mà là đang họp trực tuyến.”","giai":"开会议 / 线上会议 = họp trực tuyến."},{"kieu":"dien","phan":["孩子不开心，不是因为学习太难，而是因为","太大。"],"dap":[["压力"]],"chon":["压力","目的","做法"],"goiY":"“Con không vui không phải vì học quá khó, mà vì áp lực quá lớn.” (ôn từ 压力 – Bài 1)","giai":"压力大 = áp lực lớn."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","不是","想喝茶","，","而是","想喝水"],"dap":["我不是想喝茶，而是想喝水。"],"goiY":"Tôi không phải muốn uống trà, mà là muốn uống nước.","giai":"不是 A，而是 B — A, B cùng loại."},{"kieu":"xep","manh":["教育的目的","不是","让孩子考高分","，","而是","帮助孩子","养成好习惯"],"dap":["教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。"],"goiY":"Mục đích của giáo dục không phải là để con thi điểm cao, mà là giúp con hình thành thói quen tốt.","giai":"……的目的不是……，而是……"},{"kieu":"xep","manh":["他","不是","在玩游戏","，","而是","在练口语"],"dap":["他不是在玩游戏，而是在练口语。"],"goiY":"Cậu ấy không phải đang chơi game, mà là đang luyện nói.","giai":"在 + V: đang làm gì; hai vế cân đối."},{"kieu":"dungsai","cau":"我放学后不是直接回家，而是先去超市买笔。","dung":true,"giai":"Đúng: 不是 / 而是 cùng đứng trước phần so sánh."},{"kieu":"dungsai","cau":"教育的目的不是让孩子考高分，而且帮助孩子养成好习惯。","dung":false,"sua":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","giai":"不是 đi với 而是, không đi với 而且."},{"kieu":"dungsai","cau":"我不是不想去，而实在来不及了。","dung":false,"sua":"我不是不想去，而是实在来不及了。","giai":"Không bỏ 是 trong 而是."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 8)","huongDan":"Hoàn thành câu, dùng 「不是……，而是……」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"他们不是在聊天儿，＿＿＿。（线上会议）","goiY":"Nói việc họ thật sự đang làm: họp trực tuyến","mau":"而是在开线上会议","can":[["而是"],["线上会议"]]},{"kieu":"vandung","de":"他＿＿＿，而是在练口语。（游戏）","goiY":"Phủ định: cậu ấy không phải đang chơi game","mau":"不是在玩游戏","can":[["不是"],["游戏"]]},{"kieu":"vandung","de":"＿＿＿，而是＿＿＿。（礼貌）","goiY":"Tự đặt cả câu: cậu ấy không chào không phải vì vô lễ, mà vì quá căng thẳng","mau":"他不是没有礼貌，而是太紧张了，忘了打招呼","can":[["不是"],["而是"],["礼貌"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi học tiếng Trung không phải vì công việc, mà là vì thích văn hóa Trung Quốc.","dap":["我学中文不是因为工作，而是因为喜欢中国文化。","我学中文不是为了工作，而是因为喜欢中国文化。"],"giai":"不是因为……，而是因为…… (hai vế cùng nêu lý do)."},{"kieu":"dich","vn":"Mục đích của giáo dục không phải là điểm số, mà là giúp trẻ hình thành thói quen tốt.","dap":["教育的目的不是分数，而是帮助孩子养成好习惯。","教育的目的不是为了分数，而是帮助孩子养成好习惯。"],"giai":"目的 + 不是……，而是…… + từ mới 分数, 养成."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói quan niệm “thành công” của em, có dùng 「不是……，而是……」","mau":"我觉得成功不是有很多钱，而是每天都能做自己喜欢的事情。","can":[["不是"],["而是"]]}]}]},{"so":"4","ten":"固定短语“就是说”","tenVn":"Cụm cố định 「就是说」 — tức là, nghĩa là, nói cách khác","cauTruc":["Câu A，就是说，câu B (giải thích lại / nói rõ hơn câu A)","……，也就是说，……"],"giaiThich":"「就是说」 là cụm cố định, đặt GIỮA hai câu: câu sau GIẢI THÍCH THÊM, nói lại câu trước bằng một cách khác cho rõ hơn, cụ thể hơn — giống tiếng Việt “tức là, nghĩa là, nói cách khác”. Thường có dấu phẩy trước và sau. Có thể nói 「也就是说」 (hơi trang trọng hơn). Trong hội thoại, người nghe cũng dùng 「就是说……？」 / 「你的意思是……？」 để hỏi lại cho chắc. ⚠ Câu sau 就是说 phải cùng ý với câu trước (diễn đạt lại, rút ra hệ quả trực tiếp), không đưa ra một ý mới không liên quan. Không nhầm với 就是 (chính là) + 说 (nói): 他就是说了一句话 (anh ấy chỉ nói đúng một câu).","viDu":[{"zh":"人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。","py":"Rén yào yìzhí jiānchí xuéxí, jiùshì shuō, xuéxí shì rén yìshēng de shìqing, yào huó dào lǎo xuédào lǎo.","vn":"Con người phải luôn kiên trì học tập, nghĩa là học tập là việc cả đời, phải sống đến già học đến già."},{"zh":"别着急写，就是说，别着急动笔，想好后再写。","py":"Bié zháojí xiě, jiùshì shuō, bié zháojí dòng bǐ, xiǎnghǎo hòu zài xiě.","vn":"Đừng vội viết, tức là đừng vội đặt bút, nghĩ kỹ rồi hãy viết."},{"zh":"这份工作的工资是根据你工作的完成情况来发的，就是说，你完成得越多，工资越高。","py":"Zhè fèn gōngzuò de gōngzī shì gēnjù nǐ gōngzuò de wánchéng qíngkuàng lái fā de, jiùshì shuō, nǐ wánchéng de yuè duō, gōngzī yuè gāo.","vn":"Lương công việc này trả theo mức độ hoàn thành công việc của bạn, nghĩa là bạn hoàn thành càng nhiều thì lương càng cao."},{"zh":"这家图书馆二十四小时开门，就是说，不管什么时候你都可以来看书。","py":"Zhè jiā túshūguǎn èr shísì xiǎoshí kāimén, jiùshì shuō, bùguǎn shénme shíhou nǐ dōu kěyǐ lái kànshū.","vn":"Thư viện này mở cửa 24 giờ, tức là bất kể lúc nào bạn cũng có thể đến đọc sách. (ôn 不管……都…… – Bài 8 · điểm 1)"}],"loi":[{"sai":"就是说，学习是人一生的事情，人要一直坚持学习。","why":"就是说 đứng GIỮA, sau câu cần giải thích, không mở đầu đoạn.","dung":"人要一直坚持学习，就是说，学习是人一生的事情。"},{"sai":"别着急写，就是说，你要快点儿写。","why":"Câu sau mâu thuẫn với câu trước — 就是说 phải nói lại CÙNG một ý.","dung":"别着急写，就是说，别着急动笔，想好后再写。"},{"sai":"明天下雨，就是说，我们去公园吧。","why":"Câu sau không phải là giải thích / hệ quả của câu trước.","dung":"明天会下雨，就是说，我们不能去公园了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["人要一直坚持学习，","，学习是人一生的事情。"],"dap":[["就是说"]],"chon":["就是说","就是了","不是说"],"goiY":"“Con người phải luôn kiên trì học tập, nghĩa là …”","giai":"就是说 đứng giữa, giải thích lại câu trước."},{"kieu":"dien","phan":["别着急写，就是说，别着急动","，想好后再写。"],"dap":[["笔"]],"chon":["笔","脑","心"],"goiY":"“Đừng vội viết, tức là đừng vội đặt bút …”","giai":"动笔 = đặt bút viết."},{"kieu":"dien","phan":["工资是根据你工作的完成情况来发的，就是说，你完成得","多，工资越高。"],"dap":[["越"]],"chon":["越","更","最"],"goiY":"“… nghĩa là bạn hoàn thành càng nhiều thì lương càng cao.”","giai":"越……越…… (HSK 3)."},{"kieu":"dien","phan":["“学而不厌”的意思是人要一直坚持学习，就是说，要活到老","到老。"],"dap":[["学"]],"chon":["学","活","教"],"goiY":"“… tức là phải sống đến già học đến già.”","giai":"活到老学到老."},{"kieu":"dien","phan":["图书馆二十四小时开门，就是说，","什么时候你都可以去看书。"],"dap":[["不管"]],"chon":["不管","即使","虽然"],"goiY":"“… tức là bất kể lúc nào bạn cũng có thể đi đọc sách.” (ôn 不管 – Bài 8)","giai":"不管 + đại từ nghi vấn + 都……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["人","要","一直坚持学习","，","就是说","，","学习是人一生的事情"],"dap":["人要一直坚持学习，就是说，学习是人一生的事情。"],"goiY":"Con người phải luôn kiên trì học tập, nghĩa là học tập là việc cả đời.","giai":"Câu A，就是说，câu B."},{"kieu":"xep","manh":["别着急写","，","就是说","，","想好后","再写"],"dap":["别着急写，就是说，想好后再写。"],"goiY":"Đừng vội viết, tức là nghĩ kỹ rồi hãy viết.","giai":"就是说 + giải thích cụ thể."},{"kieu":"xep","manh":["明天放假","，","就是说","，","我们","不用","去学校了"],"dap":["明天放假，就是说，我们不用去学校了。"],"goiY":"Ngày mai được nghỉ, tức là chúng ta không phải đến trường.","giai":"就是说 + hệ quả trực tiếp."},{"kieu":"dungsai","cau":"他会说英语、法语和中文，就是说，他会三种语言。","dung":true,"giai":"Đúng: câu sau nói lại cùng ý bằng cách khác."},{"kieu":"dungsai","cau":"明天下雨，就是说，我们去公园吧。","dung":false,"sua":"明天会下雨，就是说，我们不能去公园了。","giai":"Câu sau phải là giải thích / hệ quả của câu trước."},{"kieu":"dungsai","cau":"这家店二十四小时开门，就是说，晚上它不开门。","dung":false,"sua":"这家店二十四小时开门，就是说，什么时候去都可以。","giai":"Câu sau mâu thuẫn với câu trước."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 9)","huongDan":"Hoàn thành câu, có dùng 「就是说」","cau":[{"kieu":"vandung","de":"他想了想才回答，就是说，＿＿＿。","goiY":"Giải thích lại: anh ấy đã suy nghĩ kỹ rồi mới trả lời, không phải trả lời bừa","mau":"他不是随便回答的，而是认真考虑过的"},{"kieu":"vandung","de":"＿＿＿，＿＿＿，我们要注意学习方法。","goiY":"Nêu một câu (học giỏi không chỉ dựa vào thời gian học dài), rồi 就是说","mau":"学习时间长不一定学得好，就是说","can":[["就是说"]]},{"kieu":"vandung","de":"＿＿＿，＿＿＿，休息好，你的病才能快点儿好起来。","goiY":"Nêu lời bác sĩ dặn (mấy hôm nay đừng đi làm), rồi 就是说","mau":"医生说你这几天不能去上班，就是说","can":[["就是说"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cửa hàng này mở cửa 24 giờ, nghĩa là lúc nào bạn cũng có thể đến.","dap":["这家店二十四小时开门，就是说，你什么时候都可以来。","这家店二十四小时开门，就是说，你什么时候来都可以。"],"giai":"就是说 + đại từ nghi vấn phiếm chỉ 什么时候都……"},{"kieu":"dich","vn":"Lớp học số có thể chụp ảnh điểm danh, tức là giáo sư không cần gọi tên từng người nữa.","dap":["数字教室可以拍照点名，就是说，教授不用一个个叫名字了。","数字教室可以拍照点名，就是说，教授不用一个一个叫名字了。"],"giai":"就是说 + từ mới 数字, 点名, 教授."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giải thích câu 「活到老学到老」 cho một người bạn, có dùng 「就是说」","mau":"“活到老学到老”，就是说，不管多大年龄，人都要坚持学习。","can":[["就是说"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-12.html"] = [{"so":"1","ten":"固定短语“不怎么”","tenVn":"Cụm cố định 「不怎么」 — không … lắm; ít khi","cauTruc":["不怎么 + tính từ / động từ tâm lý (= 不太、不很: không … lắm)","不怎么 + động từ hành động (= 不常: ít khi làm)"],"giaiThich":"「不怎么」 biểu thị MỨC ĐỘ THẤP, nghĩa là 「不太、不很、不常」. Đi với tính từ / động từ tâm lý → “không … lắm”: 不怎么适合 (không hợp lắm), 不怎么喜欢 (không thích lắm). Đi với động từ hành động → “ít khi”: 不怎么出去玩 (ít khi đi chơi). Giọng mềm mỏng, lịch sự hơn 「不」 — rất hay dùng khi nhận xét khéo (như Dương Đồng Lạc chê màu áo). ⚠️ Đừng nhầm trật tự: 「怎么不……？」 = sao lại không …? (hỏi lý do). 「不怎么样」 = chẳng ra sao. Việc cụ thể đã xảy ra thì phủ định bằng 没 (✗ 昨天不怎么去).","viDu":[{"zh":"样子不错，就是颜色好像不怎么适合她。","py":"Yàngzi búcuò, jiùshì yánsè hǎoxiàng bù zěnme shìhé tā.","vn":"Kiểu dáng không tệ, chỉ là màu sắc hình như không hợp với mẹ lắm."},{"zh":"他总是在图书馆看书，不怎么出去玩。","py":"Tā zǒngshì zài túshūguǎn kànshū, bù zěnme chūqu wán.","vn":"Cậu ấy lúc nào cũng đọc sách ở thư viện, ít khi ra ngoài chơi."},{"zh":"我爱吃饺子、包子，不怎么喜欢吃米饭。","py":"Wǒ ài chī jiǎozi, bāozi, bù zěnme xǐhuan chī mǐfàn.","vn":"Tôi thích ăn sủi cảo, bánh bao, không thích ăn cơm lắm."},{"zh":"这儿的冬天不怎么冷，不过风有点儿大。","py":"Zhèr de dōngtiān bù zěnme lěng, búguò fēng yǒudiǎnr dà.","vn":"Mùa đông ở đây không lạnh lắm, có điều gió hơi to. (ôn 不过 — Bài 2 · điểm 2)"}],"loi":[{"sai":"这件衣服不怎么很好看。","why":"不怎么 đã mang nghĩa “không … lắm”, không thêm 很 / 太 nữa.","dung":"这件衣服不怎么好看。"},{"sai":"他怎么不喜欢吃米饭。（muốn nói: anh ấy không thích ăn cơm lắm）","why":"怎么不 = sao lại không (câu hỏi lý do); muốn nói mức độ thấp phải đặt 不 trước 怎么.","dung":"他不怎么喜欢吃米饭。"},{"sai":"我昨天不怎么去上课。","why":"不怎么 nói thói quen / mức độ chung; một việc cụ thể đã xảy ra thì dùng 没.","dung":"我昨天没去上课。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["样子不错，就是颜色好像","适合她。"],"dap":[["不怎么"]],"chon":["不怎么","怎么不","不什么"],"goiY":"“Chỉ là màu hình như không hợp với mẹ lắm.”","giai":"不怎么 + động từ 适合 = không hợp lắm."},{"kieu":"dien","phan":["他总是在图书馆看书，","出去玩。"],"dap":[["不怎么"]],"chon":["不怎么","怎么","很少的"],"goiY":"“… ít khi ra ngoài chơi.”","giai":"不怎么 + động từ hành động = ít khi."},{"kieu":"dien","phan":["我爱吃饺子、包子，不怎么","吃米饭。"],"dap":[["喜欢"]],"chon":["喜欢","多","很"],"goiY":"“… không thích ăn cơm lắm.”","giai":"不怎么 + động từ tâm lý 喜欢."},{"kieu":"dien","phan":["今天不怎么","，不用穿毛衣了。"],"dap":[["冷"]],"chon":["冷","伤心","热闹"],"goiY":"“Hôm nay không lạnh lắm, không cần mặc áo len nữa.” (ôn từ 毛衣)","giai":"不怎么 + tính từ."},{"kieu":"dien","phan":["A：你常去体育馆打球吗？ B：","去，最近太忙了。"],"dap":[["不怎么"]],"chon":["不怎么","怎么不","没怎么样"],"goiY":"“Ít khi đi, dạo này bận quá.”","giai":"Trả lời câu hỏi về tần suất: 不怎么去 = ít khi đi."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["颜色","好像","不怎么","适合","她"],"dap":["颜色好像不怎么适合她。"],"goiY":"Màu sắc hình như không hợp với cô ấy lắm.","giai":"好像 + 不怎么 + V."},{"kieu":"xep","manh":["他","总是","在图书馆","看书","，","不怎么","出去玩"],"dap":["他总是在图书馆看书，不怎么出去玩。"],"goiY":"Cậu ấy lúc nào cũng đọc sách ở thư viện, ít khi ra ngoài chơi.","giai":"不怎么 đứng trước động từ."},{"kieu":"xep","manh":["我","最近","不怎么","去","体育馆","打球"],"dap":["我最近不怎么去体育馆打球。"],"goiY":"Dạo này tôi ít khi đến nhà thi đấu chơi bóng.","giai":"Trạng ngữ thời gian 最近 + 不怎么 + V."},{"kieu":"dungsai","cau":"这件衣服不怎么很好看。","dung":false,"sua":"这件衣服不怎么好看。","giai":"Không dùng 很 sau 不怎么."},{"kieu":"dungsai","cau":"我不怎么喜欢喝咖啡，更喜欢喝茶。","dung":true,"giai":"Đúng: 不怎么 + 喜欢."},{"kieu":"dungsai","cau":"我昨天不怎么去上课。","dung":false,"sua":"我昨天没去上课。","giai":"Việc cụ thể đã xảy ra → phủ định bằng 没."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 15)","huongDan":"Hoàn thành đối thoại, có dùng 不怎么","cau":[{"kieu":"vandung","de":"A：今天天气怎么样了？ B：挺不错的，＿＿＿。","goiY":"Nói hôm nay không lạnh lắm nữa (不怎么 + tính từ)","mau":"不怎么冷了","can":[["不怎么"]]},{"kieu":"vandung","de":"A：你看起来好像＿＿＿。 B：是的，＿＿＿。","goiY":"A: trông bạn có vẻ không vui lắm; B: đúng vậy, lần này thi không tốt lắm (dùng 不怎么 ở cả hai chỗ trống)","mau":"不怎么高兴；这次考试考得不怎么好","can":[["不怎么"]]},{"kieu":"vandung","de":"A：你常去体育馆打球吗？ B：＿＿＿。","goiY":"Trả lời: ít khi đi, và nói lý do","mau":"不怎么去，我最近工作太忙了","can":[["不怎么"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chiếc áo len này kiểu dáng đẹp, chỉ là chất lượng không tốt lắm.","dap":["这件毛衣样子很好看，就是质量不怎么好。","这件毛衣样子不错，就是质量不怎么好。"],"giai":"……，就是…… (Bài 3) + 不怎么 + tính từ."},{"kieu":"dich","vn":"Ông tôi ít khi xem tivi, thích ra công viên đi dạo hơn.","dap":["我爷爷不怎么看电视，更喜欢去公园散步。"],"giai":"不怎么 + V = ít khi."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về thói quen của một người trong gia đình em, có dùng 「不怎么」","mau":"我妈妈不怎么喜欢逛商场，她更喜欢在网上买东西。","can":[["不怎么"]]}]}]},{"so":"2","ten":"双重否定","tenVn":"Phủ định kép — 不是不 / 不能不 / 不得不: khẳng định với giọng mạnh hơn","cauTruc":["不是不 + V / adj (không phải là không … → thật ra là có …)","不能不 + V (không thể không … → nhất định phải)","不得不 + V (buộc phải, đành phải)"],"giaiThich":"Hai lần phủ định = KHẲNG ĐỊNH, nhưng giọng mạnh hơn câu khẳng định bình thường. Mỗi dạng có sắc thái riêng: 「不是不……」 dùng để thanh minh, giải thích (他也不是不知道自己错了 = nó biết mình sai đấy chứ); 「不能不……」 = nhất định phải, vì trách nhiệm / tình cảm (你又是班长，不能不来); 「不得不……」 = buộc phải, đành phải, vì hoàn cảnh ép, không muốn cũng phải làm (飞机不能起飞，爸爸不得不改变计划). Ngoài ra còn 「没有……不……」: 没有人不喜欢他 (không ai không thích anh ấy = ai cũng thích). ⚠️ Phân biệt với 「不是A，而是B」 (Bài 11): phủ định A, khẳng định B — còn 「不是不A」 lại khẳng định A.","viDu":[{"zh":"他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","py":"Tā yě bú shì bù zhīdao zìjǐ cuò le, wǒ pīpíng tā yǐhòu, tā mǎshàng shuō fàngxué huílai jiù xiàng nǎinai dàoqiàn.","vn":"Nó cũng không phải là không biết mình sai, em phê bình xong là nó nói ngay tan học về sẽ xin lỗi bà."},{"zh":"今天是我们毕业后第一次同学聚餐，你又是班长，不能不来啊！","py":"Jīntiān shì wǒmen bìyè hòu dì yí cì tóngxué jùcān, nǐ yòu shì bānzhǎng, bù néng bu lái a!","vn":"Hôm nay là buổi họp lớp đầu tiên sau khi tốt nghiệp, cậu lại là lớp trưởng, không thể không đến đâu nhé!"},{"zh":"由于天气不好，飞机不能起飞，爸爸不得不改变计划，明天再去上海。","py":"Yóuyú tiānqì bù hǎo, fēijī bù néng qǐfēi, bàba bùdébù gǎibiàn jìhuà, míngtiān zài qù Shànghǎi.","vn":"Do thời tiết xấu, máy bay không thể cất cánh, bố đành phải thay đổi kế hoạch, mai mới đi Thượng Hải. (ôn 由于 — Bài 2 · điểm 4)"},{"zh":"即使工作再忙，妈妈的生日我也不能不回家。","py":"Jíshǐ gōngzuò zài máng, māma de shēngrì wǒ yě bù néng bù huíjiā.","vn":"Dù công việc có bận đến đâu, sinh nhật mẹ tôi cũng không thể không về nhà. (ôn 即使……也…… — Bài 11 · điểm 1)"}],"loi":[{"sai":"今天是班长的生日聚会，我不能来不。","why":"Trật tự đúng là 不能不 + V.","dung":"今天是班长的生日聚会，我不能不来。"},{"sai":"他病了，不得不不去上班。","why":"Sau 不得不 là động từ khẳng định (việc buộc phải LÀM); muốn nói “đành nghỉ” thì dùng 请假.","dung":"他病了，不得不请假。"},{"sai":"我不得不喜欢这件毛衣。","why":"不得不 = buộc phải (bất đắc dĩ), không đi với cảm xúc thích / ghét; muốn nhấn mạnh “ai cũng thích” dùng 没有人不…….","dung":"这件毛衣太好看了，没有人不喜欢。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["他也","不知道自己错了，只是不好意思说。"],"dap":[["不是"]],"chon":["不是","不能","不得"],"goiY":"“Nó cũng không phải không biết mình sai, chỉ là ngại nói.”","giai":"不是不 + V: thanh minh, giải thích."},{"kieu":"dien","phan":["今天是毕业后第一次同学聚餐，你又是班长，","来啊！"],"dap":[["不能不"]],"chon":["不能不","不能","不来不"],"goiY":"“… cậu lại là lớp trưởng, không thể không đến!”","giai":"不能不 + V = nhất định phải."},{"kieu":"dien","phan":["由于天气不好，飞机不能起飞，爸爸","改变计划。"],"dap":[["不得不"]],"chon":["不得不","不是不","不怎么"],"goiY":"“… bố đành phải thay đổi kế hoạch.”","giai":"Hoàn cảnh ép buộc → 不得不."},{"kieu":"dien","phan":["我不是不想参加，","实在没有时间。"],"dap":[["是"]],"chon":["是","就","也"],"goiY":"“Tôi không phải không muốn tham gia, mà là thật sự không có thời gian.”","giai":"不是不……，是…… (cũng có thể nói 而是)."},{"kieu":"dien","phan":["爷爷奶奶年纪大了，我们","好好照顾他们。"],"dap":[["不能不"]],"chon":["不能不","不是不","不怎么"],"goiY":"“Ông bà lớn tuổi rồi, chúng ta không thể không chăm sóc chu đáo.”","giai":"Trách nhiệm, tình cảm → 不能不."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","也","不是","不知道","自己错了"],"dap":["他也不是不知道自己错了。"],"goiY":"Nó cũng không phải không biết mình sai.","giai":"不是 + 不知道."},{"kieu":"xep","manh":["你","是班长","，","不能不","来","啊"],"dap":["你是班长，不能不来啊。"],"goiY":"Cậu là lớp trưởng, không thể không đến.","giai":"不能不 + V."},{"kieu":"xep","manh":["因为","下大雨","，","我们","不得不","改变","计划"],"dap":["因为下大雨，我们不得不改变计划。"],"goiY":"Vì mưa to, chúng tôi buộc phải thay đổi kế hoạch.","giai":"Chủ ngữ + 不得不 + V."},{"kieu":"dungsai","cau":"这件事我不得不告诉他。","dung":true,"giai":"Đúng: buộc phải nói cho anh ấy biết."},{"kieu":"dungsai","cau":"他病了，不得不不去上班。","dung":false,"sua":"他病了，不得不请假。","giai":"Sau 不得不 là động từ khẳng định."},{"kieu":"dungsai","cau":"我不是不想去，是实在没有时间。","dung":true,"giai":"Đúng: 不是不想去 = muốn đi chứ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 17–18)","huongDan":"Hoàn thành đối thoại, có dùng phủ định kép (不是不 / 不能不 / 不得不)","cau":[{"kieu":"vandung","de":"A：家里的东西太多了，＿＿＿。 B：是啊，搬家是很不容易。","goiY":"Nói lần chuyển nhà này buộc phải bỏ bớt một số đồ (不得不……)","mau":"这次搬家，我们不得不扔掉一些","can":[["不得不","不能不"]]},{"kieu":"vandung","de":"A：这么重要的活动你不参加吗？ B：＿＿＿，是实在没有时间。","goiY":"Thanh minh: không phải tôi không muốn tham gia (不是不……)","mau":"我不是不想参加","can":[["不是不"]]},{"kieu":"vandung","de":"A：你们学校真大啊！楼与楼之间距离那么远。 B：是啊，为了能准时上课，＿＿＿。","goiY":"Nói việc buộc phải làm để đến lớp đúng giờ (不得不……)","mau":"我们不得不骑自行车去上课","can":[["不得不","不能不"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Không phải tôi không muốn giúp bạn, mà là tôi thật sự không có thời gian.","dap":["我不是不想帮你，是我实在没有时间。","我不是不想帮你，而是我实在没有时间。","我不是不想帮你，而是实在没有时间。"],"giai":"不是不……，(而)是…… — kết hợp Bài 11 · điểm 3."},{"kieu":"dich","vn":"Vì trời mưa to, chúng tôi đành phải ở nhà.","dap":["因为下大雨，我们不得不待在家里。","因为雨下得很大，我们不得不待在家里。"],"giai":"不得不 + 待在家里 (từ mới 待 dāi)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về một việc em buộc phải làm hoặc không thể không làm vì gia đình, có dùng phủ định kép","mau":"妈妈生病了，我不得不请假回家照顾她。","can":[["不得不","不能不","不是不"]]}]}]},{"so":"3","ten":"条件复句“无论……，都/也……”","tenVn":"Câu phức điều kiện 「无论……，都/也……」 — dù … (thế nào) … cũng …","cauTruc":["无论 + từ nghi vấn (什么 / 谁 / 哪儿 / 怎么 / 多 + tính từ)……，(chủ ngữ) + 都 / 也……","无论 + A 还是 B / 是不是……，(chủ ngữ) + 都 / 也……"],"giaiThich":"Nêu rằng trong BẤT KỲ điều kiện nào, kết quả cũng không thay đổi. Vì “bất kỳ điều kiện nào” nên sau 「无论」 phải là cụm KHÔNG XÁC ĐỊNH: từ nghi vấn (什么, 谁, 哪儿, 多忙…), phương án chọn lựa (A还是B), hoặc dạng khẳng định–phủ định (下不下雨). 「都 / 也」 đặt sau chủ ngữ vế sau, trước động từ. Tiếng Việt: “dù … thế nào … cũng …”, “bất kể”. So sánh: 「不管……都……」 (Bài 8) nghĩa giống hệt, khẩu ngữ hơn; 「即使……也……」 (Bài 11) nêu MỘT giả thiết cụ thể (即使下雨也去), còn 无论 bao trùm MỌI trường hợp (无论下不下雨都去).","viDu":[{"zh":"杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。","py":"Yáng Tónglè hěn guānxīn fùmǔ, wúlùn píngshí gōngzuò yǒu duō máng, tā měi gè zhōumò dōu huì gěi fùmǔ dǎdiànhuà.","vn":"Dương Đồng Lạc rất quan tâm bố mẹ, dù ngày thường công việc bận đến đâu, cuối tuần nào anh ấy cũng gọi điện cho bố mẹ."},{"zh":"只要你努力了，无论你考多少分，你在我们眼里都是最优秀的。","py":"Zhǐyào nǐ nǔlì le, wúlùn nǐ kǎo duōshao fēn, nǐ zài wǒmen yǎn lǐ dōu shì zuì yōuxiù de.","vn":"Chỉ cần con đã cố gắng, dù con thi được bao nhiêu điểm, trong mắt bố mẹ con vẫn là giỏi nhất."},{"zh":"无论你遇到什么困难，我都会在你身边。","py":"Wúlùn nǐ yùdào shénme kùnnan, wǒ dōu huì zài nǐ shēnbiān.","vn":"Dù em gặp khó khăn gì, anh cũng sẽ ở bên cạnh em."},{"zh":"无论天气怎么样，爷爷每天都去公园跑步，从来没停过。","py":"Wúlùn tiānqì zěnmeyàng, yéye měitiān dōu qù gōngyuán pǎobù, cónglái méi tíng guò.","vn":"Dù thời tiết thế nào, ngày nào ông cũng ra công viên chạy bộ, chưa từng ngừng. (ôn 从来 — Bài 9 · điểm 4)"}],"loi":[{"sai":"无论明天下雨，我们都去爬山。","why":"Sau 无论 phải là cụm không xác định (từ nghi vấn, A还是B, V不V), không phải một điều kiện cụ thể.","dung":"无论明天下不下雨，我们都去爬山。"},{"sai":"无论你去哪儿，我跟你去。","why":"Vế sau thiếu 都 / 也.","dung":"无论你去哪儿，我都跟你去。"},{"sai":"无论多忙，都他每天给父母打电话。","why":"都 đứng sau chủ ngữ, ngay trước động từ.","dung":"无论多忙，他每天都给父母打电话。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","平时工作有多忙，他每个周末都会给父母打电话。"],"dap":[["无论"]],"chon":["无论","虽然","因为"],"goiY":"“Dù ngày thường công việc bận đến đâu …”","giai":"无论 + 多 + tính từ."},{"kieu":"dien","phan":["无论你考多少分，你在我们眼里","是最优秀的。"],"dap":[["都"]],"chon":["都","就","才"],"goiY":"“… trong mắt bố mẹ con đều là giỏi nhất.”","giai":"无论……，都……"},{"kieu":"dien","phan":["无论你去","，都要给家里打个电话。"],"dap":[["哪儿"]],"chon":["哪儿","北京","那儿"],"goiY":"“Dù con đi đâu cũng phải gọi điện về nhà.”","giai":"Sau 无论 dùng từ nghi vấn 哪儿, không dùng địa điểm cụ thể."},{"kieu":"dien","phan":["无论刮风","下雨，爷爷每天都去公园跑步。"],"dap":[["还是"]],"chon":["还是","或者","和"],"goiY":"“Dù gió hay mưa …”","giai":"无论 A 还是 B (không dùng 或者)."},{"kieu":"dien","phan":["无论遇到什么事，","不要着急。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“Dù gặp chuyện gì cũng đừng sốt ruột.”","giai":"无论……，也 + phủ định."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["无论","工作","多忙","，","他","都","给父母","打电话"],"dap":["无论工作多忙，他都给父母打电话。"],"goiY":"Dù công việc bận đến đâu, anh ấy cũng gọi điện cho bố mẹ.","giai":"无论 + 多忙，chủ ngữ + 都 + V."},{"kieu":"xep","manh":["无论","你","去哪儿","，","我","都","跟你去"],"dap":["无论你去哪儿，我都跟你去。"],"goiY":"Dù em đi đâu, anh cũng đi cùng em.","giai":"无论 + 哪儿."},{"kieu":"xep","manh":["无论","刮风","还是","下雨","，","他","都","坚持跑步"],"dap":["无论刮风还是下雨，他都坚持跑步。"],"goiY":"Dù gió hay mưa, ông ấy vẫn kiên trì chạy bộ.","giai":"无论 A 还是 B，都……"},{"kieu":"dungsai","cau":"无论明天下雨，我们都去。","dung":false,"sua":"无论明天下不下雨，我们都去。","giai":"Sau 无论 cần dạng không xác định: 下不下雨."},{"kieu":"dungsai","cau":"无论你多大，在父母眼里你都是孩子。","dung":true,"giai":"Đúng: 无论 + 多大，都……"},{"kieu":"dungsai","cau":"无论你去哪儿，我跟你去。","dung":false,"sua":"无论你去哪儿，我都跟你去。","giai":"Vế sau phải có 都 / 也."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 20)","huongDan":"Hoàn thành câu, dùng 无论……，都/也…… và từ trong ngoặc","cau":[{"kieu":"vandung","de":"她很爱读书，＿＿＿，都要带上一本书。（待）","goiY":"Dùng từ 「待」 (dāi): dù ở ngoài bao lâu","mau":"无论在外面待多长时间","can":[["无论"],["待"]]},{"kieu":"vandung","de":"父亲无论多忙，周末＿＿＿。（陪）","goiY":"Dùng từ 「陪」: cuối tuần đều ở bên / đưa cả nhà đi chơi","mau":"都会陪我们去公园玩","can":[["都","也"],["陪"]]},{"kieu":"vandung","de":"＿＿＿，我都相信我们能成功。（条件）","goiY":"Dùng từ 「条件」: dù điều kiện khó khăn thế nào","mau":"无论条件多么困难","can":[["无论","不管"],["条件"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Dù bận đến đâu, cuối tuần nào anh ấy cũng gọi điện cho bố mẹ.","dap":["无论多忙，他每个周末都给父母打电话。","无论多忙，他每个周末都会给父母打电话。"],"giai":"无论 + 多忙，chủ ngữ + 每个周末 + 都……"},{"kieu":"dich","vn":"Dù em gặp khó khăn gì, bất cứ lúc nào cũng có thể bàn bạc với bố mẹ.","dap":["无论你遇到什么困难，任何时候都可以和父母商量。","无论遇到什么困难，你任何时候都可以和父母商量。"],"giai":"无论……什么…… + ôn 任何……都…… (Bài 1 · điểm 1)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về việc em (hoặc người thân) luôn làm cho gia đình, có dùng 「无论……，都/也……」","mau":"无论学习多忙，我每天晚上都给妈妈打一个电话。","can":[["无论"],["都","也"]]}]}]},{"so":"4","ten":"固定格式“为了……而……”","tenVn":"Cấu trúc cố định 「为了……而……」 — vì (để) … mà …","cauTruc":["(Chủ ngữ +) 为了 + mục đích / mục tiêu + 而 + hành động","Chủ ngữ + (都 / 正) 在 + 为了…… + 而 + V(着)"],"giaiThich":"「为了……」 nêu MỤC ĐÍCH hoặc MỤC TIÊU; 「而……」 là HÀNH ĐỘNG được thực hiện để đạt mục đích đó. Cả cụm là MỘT mệnh đề, thường không ngắt dấu phẩy trước 而; chủ ngữ đứng trước 为了 (父母担心她为了节约时间而不好好吃饭). Tiếng Việt dịch rất khớp: “vì … mà …”. Sắc thái trang trọng, văn viết hơn 「为了……，……」 (HSK 3). ⚠️ Phân biệt: 「因为……而……」 nêu NGUYÊN NHÂN (因为生病而请假); 「……，好……」 (Bài 6) nêu mục đích ở vế SAU; 「而」 ở Bài 10 là liên từ nối hai vế tương phản / tiếp nối.","viDu":[{"zh":"父母总是担心她为了节约时间而不好好吃饭。","py":"Fùmǔ zǒngshì dānxīn tā wèile jiéyuē shíjiān ér bù hǎohāo chīfàn.","vn":"Bố mẹ luôn lo cô ấy vì tiết kiệm thời gian mà không ăn uống tử tế."},{"zh":"我们都在为了生活幸福而努力工作着。","py":"Wǒmen dōu zài wèile shēnghuó xìngfú ér nǔlì gōngzuò zhe.","vn":"Chúng ta đều đang nỗ lực làm việc vì một cuộc sống hạnh phúc."},{"zh":"他们为了保护环境而拒绝使用纸杯。","py":"Tāmen wèile bǎohù huánjìng ér jùjué shǐyòng zhǐ bēi.","vn":"Họ từ chối dùng cốc giấy để bảo vệ môi trường."},{"zh":"她为了照顾生病的母亲而搬回了老家，好每天陪在母亲身边。","py":"Tā wèile zhàogu shēngbìng de mǔqīn ér bān huí le lǎojiā, hǎo měitiān péi zài mǔqīn shēnbiān.","vn":"Cô ấy vì chăm sóc mẹ bị bệnh mà chuyển về quê, để ngày ngày ở bên mẹ. (ôn ……，好…… — Bài 6 · điểm 4)"}],"loi":[{"sai":"为了节约时间，而他不好好吃饭。","why":"Chủ ngữ đứng trước 为了; 而 đứng ngay trước hành động, không ngắt câu kiểu này.","dung":"他为了节约时间而不好好吃饭。"},{"sai":"我们为了生活幸福而。","why":"Sau 而 bắt buộc phải có hành động.","dung":"我们为了生活幸福而努力工作。"},{"sai":"他为了而努力学习考上大学。","why":"Mục đích đặt GIỮA 为了 và 而, hành động đặt SAU 而.","dung":"他为了考上大学而努力学习。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["父母总是担心她为了节约时间","不好好吃饭。"],"dap":[["而"]],"chon":["而","就","才"],"goiY":"“… vì tiết kiệm thời gian mà không ăn uống tử tế.”","giai":"为了…… + 而 + hành động."},{"kieu":"dien","phan":["我们都在","生活幸福而努力工作着。"],"dap":[["为了"]],"chon":["为了","因为","随着"],"goiY":"“Chúng ta đều đang nỗ lực làm việc vì cuộc sống hạnh phúc.”","giai":"为了 nêu mục đích (khác 因为 nêu nguyên nhân)."},{"kieu":"dien","phan":["他们为了保护环境而","使用纸杯。"],"dap":[["拒绝"]],"chon":["拒绝","允许","商量"],"goiY":"“… từ chối dùng cốc giấy.”","giai":"Hành động sau 而: 拒绝使用."},{"kieu":"dien","phan":["","让食物新鲜，父亲选择了城里最快的快递。"],"dap":[["为了"]],"chon":["为了","无论","因为"],"goiY":"“Để đồ ăn tươi ngon, bố chọn chuyển phát nhanh nhất.”","giai":"为了……，…… (dạng có dấu phẩy, HSK 3)."},{"kieu":"dien","phan":["她为了照顾生病的母亲而","在老家。"],"dap":[["待"]],"chon":["待","挂","脱"],"goiY":"“Cô ấy vì chăm sóc mẹ bị bệnh mà ở lại quê.” (ôn từ mới 待 dāi)","giai":"而 + 待在 + nơi."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我们","都在","为了","生活幸福","而","努力工作着"],"dap":["我们都在为了生活幸福而努力工作着。"],"goiY":"Chúng ta đều đang nỗ lực làm việc vì cuộc sống hạnh phúc.","giai":"Chủ ngữ + 都在 + 为了…… + 而 + V着."},{"kieu":"xep","manh":["他们","为了","保护环境","而","拒绝","使用纸杯"],"dap":["他们为了保护环境而拒绝使用纸杯。"],"goiY":"Họ từ chối dùng cốc giấy để bảo vệ môi trường.","giai":"为了 + mục đích + 而 + hành động."},{"kieu":"xep","manh":["他","为了","去中国留学","而","努力","学中文"],"dap":["他为了去中国留学而努力学中文。"],"goiY":"Cậu ấy vì muốn sang Trung Quốc du học mà chăm chỉ học tiếng Trung.","giai":"Bài tập SGK câu 2."},{"kieu":"dungsai","cau":"为了节约时间，而他不好好吃饭。","dung":false,"sua":"他为了节约时间而不好好吃饭。","giai":"Chủ ngữ trước 为了; 而 ngay trước hành động."},{"kieu":"dungsai","cau":"她为了参加比赛而每天练习三个小时。","dung":true,"giai":"Đúng: 为了 + mục đích + 而 + hành động."},{"kieu":"dungsai","cau":"我为了考试而。","dung":false,"sua":"我为了考试而努力复习。","giai":"Sau 而 phải có hành động."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 21)","huongDan":"Hoàn thành câu, dùng 为了……而……","cau":[{"kieu":"vandung","de":"我为了这次比赛＿＿＿。","goiY":"Nói hành động em làm để chuẩn bị cuộc thi (而 + hành động)","mau":"而每天坚持练习三个小时","can":[["而"]]},{"kieu":"vandung","de":"他＿＿＿而努力学中文。","goiY":"Nêu mục đích học tiếng Trung (为了 + mục đích)","mau":"为了去中国留学","can":[["为了"]]},{"kieu":"vandung","de":"＿＿＿努力练习。","goiY":"Nêu chủ ngữ + mục đích: vận động viên muốn đạt thành tích tốt (为了……而)","mau":"运动员们为了在比赛中取得好成绩而","can":[["为了"],["而"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bố mẹ luôn lo cô ấy vì tiết kiệm thời gian mà không ăn uống tử tế.","dap":["父母总是担心她为了节约时间而不好好吃饭。"],"giai":"为了…… + 而 + 不好好吃饭."},{"kieu":"dich","vn":"Họ đang nỗ lực làm việc vì một cuộc sống hạnh phúc.","dap":["他们正在为了生活幸福而努力工作。","他们正在为了幸福的生活而努力工作。","他们都在为了生活幸福而努力工作着。"],"giai":"正在 + 为了…… + 而 + V."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu nói về việc bố mẹ em đã làm vì gia đình, có dùng 「为了……而……」","mau":"我爸爸为了让我们过上好日子而每天努力工作。","can":[["为了"],["而"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-13.html"] = [{"so":"1","ten":"固定格式“怎么都/也+不/没……”","tenVn":"Cấu trúc 「怎么都 / 也 + 不 / 没……」 — thế nào cũng không …, mãi mà không …","cauTruc":["怎么 + 都 / 也 + 不 + V (+ bổ ngữ) — ý chí / khả năng: 怎么都不出来, 怎么也睡不着","怎么 + 都 / 也 + 没 + V (+ 到 / 着) — việc đã xảy ra: 怎么都没找到","(Ngạc nhiên) 怎么也没想到 + ……"],"giaiThich":"Diễn tả đã nghĩ đủ mọi cách, cố gắng hết sức mà vẫn KHÔNG đạt được kết quả; đôi khi dùng để bày tỏ ngạc nhiên, không ngờ (怎么也没想到这么大). 「怎么都」 = 「无论怎么做都」 — giống ý 无论……都 (Bài 12 · điểm 3) nhưng gọn hơn. Chọn 不 hay 没: 不 cho ý muốn / khả năng (它怎么都不出来 – nó nhất định không ra; 怎么也睡不着 – mãi không ngủ được), 没 cho việc đã xảy ra (怎么都没找到 – tìm mãi không thấy). Hay đi với bổ ngữ khả năng V不了 / V不到 / V不出来 (Bài 4 · điểm 1). Mẹo cho người Việt: “mãi mà không …”, “thế nào cũng không …” → 怎么都 / 也 + 不 / 没. Phân biệt với 说什么 / 怎么（着）也得 (Bài 10 · điểm 1): đó là KHẲNG ĐỊNH quyết tâm “dù thế nào cũng phải”, còn đây là PHỦ ĐỊNH “thế nào cũng không”.","viDu":[{"zh":"我知道北京野生动物园很大，可怎么也没想到这么大！","py":"Wǒ zhīdao Běijīng yěshēng dòngwùyuán hěn dà, kě zěnme yě méi xiǎngdào zhème dà!","vn":"Anh biết Công viên Động vật hoang dã Bắc Kinh rất rộng, nhưng thế nào cũng không ngờ lại rộng đến thế!"},{"zh":"她在包里找了半天，怎么都没找到，真奇怪。","py":"Tā zài bāo lǐ zhǎo le bàntiān, zěnme dōu méi zhǎodào, zhēn qíguài.","vn":"Cô ấy lục trong túi nửa ngày mà tìm mãi không thấy, lạ thật."},{"zh":"我们想看那只熊猫，在动物园等了两个多小时，可是它怎么都不出来。","py":"Wǒmen xiǎng kàn nà zhī xióngmāo, zài dòngwùyuán děng le liǎng gè duō xiǎoshí, kěshì tā zěnme dōu bù chūlai.","vn":"Chúng tôi muốn xem con gấu trúc đó, đợi ở vườn thú hơn hai tiếng mà nó nhất định không chịu ra."},{"zh":"不管我怎么劝，他怎么都不愿意去医院。","py":"Bùguǎn wǒ zěnme quàn, tā zěnme dōu bú yuànyì qù yīyuàn.","vn":"Dù tôi khuyên thế nào, anh ấy cũng nhất quyết không chịu đi bệnh viện. (ôn 不管……, Bài 8 · điểm 1)"}],"loi":[{"sai":"我怎么都找到不我的手机。","why":"Phủ định của bổ ngữ khả năng: V + 不 + kết quả (找不到), không phải 找到不.","dung":"我怎么都找不到我的手机。"},{"sai":"我在包里找了半天，怎么都没找不到。","why":"没 và 不 không dùng chồng lên nhau: hoặc 怎么都没找到 (đã xảy ra), hoặc 怎么都找不到 (không thể).","dung":"我在包里找了半天，怎么都没找到。"},{"sai":"我怎么都想起来不他的名字。","why":"Bổ ngữ khả năng của 想起来 là 想不起来; tân ngữ đặt sau.","dung":"我怎么都想不起来他的名字。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["她在包里找了半天，","都没找到，真奇怪。"],"dap":[["怎么"]],"chon":["怎么","什么","哪儿"],"goiY":"“… tìm mãi mà không thấy, lạ thật.”","giai":"怎么 + 都 + 没 + V到."},{"kieu":"dien","phan":["我知道北京野生动物园很大，可怎么","没想到这么大！"],"dap":[["也"]],"chon":["也","还","就"],"goiY":"“… nhưng thế nào cũng không ngờ lại rộng đến thế!”","giai":"怎么也没想到 = không ngờ (ngạc nhiên)."},{"kieu":"dien","phan":["我们等了两个多小时，可是那只熊猫怎么都","出来。"],"dap":[["不"]],"chon":["不","没","别"],"goiY":"“… nhưng con gấu trúc đó nhất định không chịu ra.”","giai":"Ý muốn của con vật (không chịu) → 不."},{"kieu":"dien","phan":["昨天晚上太热了，我怎么也睡","着。"],"dap":[["不"]],"chon":["不","没","得"],"goiY":"“Tối qua nóng quá, tôi trằn trọc mãi không ngủ được.”","giai":"Bổ ngữ khả năng 睡不着."},{"kieu":"dien","phan":["这道题太难了，我做了好久，怎么都做","出来。"],"dap":[["不"]],"chon":["不","没","得"],"goiY":"“… làm mãi mà không ra.”","giai":"Bổ ngữ khả năng 做不出来."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["她","在包里","找了半天","，","怎么","都","没找到"],"dap":["她在包里找了半天，怎么都没找到。"],"goiY":"Cô ấy lục trong túi nửa ngày mà tìm mãi không thấy.","giai":"V了半天，怎么都没 + V到."},{"kieu":"xep","manh":["我","怎么","也","想不起来","他的名字"],"dap":["我怎么也想不起来他的名字。"],"goiY":"Tôi thế nào cũng không nhớ ra tên anh ấy.","giai":"怎么也 + V不起来."},{"kieu":"xep","manh":["我","知道","这里很大","，","可","怎么也","没想到","这么大"],"dap":["我知道这里很大，可怎么也没想到这么大。"],"goiY":"Tôi biết ở đây rộng, nhưng không ngờ lại rộng thế này.","giai":"可 + 怎么也没想到 (ngạc nhiên)."},{"kieu":"dungsai","cau":"我怎么都找到不我的手机。","dung":false,"sua":"我怎么都找不到我的手机。","giai":"Phải là bổ ngữ khả năng 找不到."},{"kieu":"dungsai","cau":"那只熊猫怎么都不出来，我们只好走了。","dung":true,"giai":"Đúng: 怎么都 + 不 + V (con vật không chịu ra)."},{"kieu":"dungsai","cau":"他怎么都没睡不着。","dung":false,"sua":"他怎么都睡不着。","giai":"没 và 不 không đi chung; dùng bổ ngữ khả năng 睡不着."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 28)","huongDan":"Viết phần còn thiếu của A, có dùng 怎么都 / 也 + 不 / 没……","cau":[{"kieu":"vandung","de":"A：我一直想买这种茶，去店里买了几次，＿＿＿。 B：最近天热，买这种茶的人太多了。","goiY":"Nói: đi mấy lần mà thế nào cũng không mua được","mau":"可是怎么都没买到","can":[["怎么"],["都","也"],["没","不"]]},{"kieu":"vandung","de":"A：我想了半天，＿＿＿。 B：你们好长时间没见了，突然想不起来他叫什么也能理解。","goiY":"Nói: nghĩ mãi mà không nhớ ra anh ấy tên là gì","mau":"怎么也想不起来他叫什么名字","can":[["怎么"],["都","也"],["不","没"]]},{"kieu":"vandung","de":"A：这道题太难了，我做了好久，＿＿＿。 B：是吗？我来试试，看能不能做出来。","goiY":"Nói: làm mãi mà thế nào cũng không làm ra","mau":"怎么都做不出来","can":[["怎么"],["都","也"],["不","没"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi gọi cho anh ấy mấy lần, thế nào cũng không gọi được.","dap":["我给他打了好几次电话，怎么都打不通。","我给他打了好几次电话，怎么也打不通。"],"giai":"怎么都 / 也 + V不通 (bổ ngữ khả năng)."},{"kieu":"dich","vn":"Tôi biết kỳ thi này khó, nhưng thế nào cũng không ngờ lại khó đến vậy.","dap":["我知道这次考试很难，可怎么也没想到这么难。","我知道这次考试很难，可是怎么都没想到这么难。"],"giai":"怎么也没想到 + 这么 + Adj (ngạc nhiên)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần em cố mãi mà không làm được một việc, có dùng 「怎么都 / 也 + 不 / 没……」","mau":"昨天晚上我找了半天，怎么也想不起来把钥匙放在哪儿了。","can":[["怎么"],["都","也"]]}]}]},{"so":"2","ten":"固定格式“一+量词+比+一+量词”","tenVn":"Cấu trúc 「一 + lượng từ + 比 + 一 + lượng từ」 — cái sau hơn cái trước, ngày càng …","cauTruc":["一 + lượng từ + 比 + 一 + lượng từ + tính từ","Lượng từ thời gian (天 / 年 / 次): 一天比一天热 — ngày càng (theo thời gian)","Lượng từ chỉ người / vật (个 / 件 / 只): 一个比一个漂亮 — cái nào cũng … hơn cái nào"],"giaiThich":"Dùng để so sánh hai hay nhiều sự vật, nhấn mạnh cái sau có mức độ CAO HƠN cái trước. Thường đi với tính từ: 一 + lượng từ + 比 + 一 + lượng từ + tính từ. Hai cách hiểu: (1) lượng từ thời gian (天, 年, 次) → mức độ tăng dần theo thời gian, gần nghĩa 越来越 (HSK 3): 天气一天比一天热 = trời ngày càng nóng; (2) lượng từ chỉ người / vật (个, 件, 只, 道…) → so nhiều đối tượng, cái nào cũng hơn cái nào = tất cả đều rất …: 这些杯子一个比一个漂亮. Lưu ý: hai lượng từ phải GIỐNG nhau, đều đi với 一; tính từ đứng trần (không thêm 很, 非常, 多了).","viDu":[{"zh":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。","py":"Zài Zhōngguó, měinián Zhōngqiūjié dōu huì jǔbàn hěn duō huódòng, érqiě zhè jǐ nián yì nián bǐ yì nián rènao.","vn":"Ở Trung Quốc, năm nào Trung thu cũng tổ chức nhiều hoạt động, mà mấy năm nay năm sau còn náo nhiệt hơn năm trước."},{"zh":"夏天快到了，天气也一天比一天热。","py":"Xiàtiān kuài dào le, tiānqì yě yì tiān bǐ yì tiān rè.","vn":"Mùa hè sắp đến, trời cũng ngày một nóng hơn."},{"zh":"这家店里的杯子一个比一个漂亮，我都不知道选哪个了。","py":"Zhè jiā diàn lǐ de bēizi yí gè bǐ yí gè piàoliang, wǒ dōu bù zhīdao xuǎn nǎge le.","vn":"Cốc trong cửa hàng này cái nào cũng đẹp hơn cái nào, tôi chẳng biết chọn cái nào nữa."},{"zh":"随着经济的发展，人们的生活一年比一年好。","py":"Suízhe jīngjì de fāzhǎn, rénmen de shēnghuó yì nián bǐ yì nián hǎo.","vn":"Cùng với sự phát triển kinh tế, đời sống mọi người năm sau tốt hơn năm trước. (ôn 随着, Bài 1 · điểm 3)"}],"loi":[{"sai":"天气一天比一天很热。","why":"Sau cấu trúc này tính từ đứng trần, không thêm 很 / 非常.","dung":"天气一天比一天热。"},{"sai":"他的中文一天比两天好。","why":"Hai vế phải cùng là 一 + cùng một lượng từ.","dung":"他的中文一天比一天好。"},{"sai":"这些杯子一个比一个漂亮多了。","why":"Không thêm 多了 / 得多 (đó là câu 比 thường: A比B + Adj + 多了).","dung":"这些杯子一个比一个漂亮。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["夏天快到了，天气也一天比一","热。"],"dap":[["天"]],"chon":["天","年","个"],"goiY":"“… trời cũng ngày một nóng hơn.”","giai":"Hai lượng từ giống nhau: 一天比一天."},{"kieu":"dien","phan":["这家店里的杯子一个","一个漂亮，我都不知道选哪个了。"],"dap":[["比"]],"chon":["比","跟","和"],"goiY":"“Cốc ở đây cái nào cũng đẹp hơn cái nào.”","giai":"一个 + 比 + 一个 + Adj."},{"kieu":"dien","phan":["这几年，中秋节的活动一年比一年","。"],"dap":[["热闹"]],"chon":["热闹","很热闹","热闹多了"],"goiY":"“… năm sau náo nhiệt hơn năm trước.”","giai":"Tính từ đứng trần, không thêm 很 / 多了."},{"kieu":"dien","phan":["他们兄弟三个，一","比一个高。"],"dap":[["个"]],"chon":["个","天","次"],"goiY":"“Ba anh em nhà họ, người sau cao hơn người trước.”","giai":"So người → lượng từ 个."},{"kieu":"dien","phan":["随着经济的发展，人们的生活","好。"],"dap":[["一年比一年"]],"chon":["一年比一年","一年比两年","一年一年"],"goiY":"“… đời sống năm sau tốt hơn năm trước.” (ôn 随着)","giai":"一年比一年 + Adj."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["天气","一天","比","一天","冷","了"],"dap":["天气一天比一天冷了。"],"goiY":"Trời ngày một lạnh hơn rồi.","giai":"一天比一天 + Adj + 了 (thay đổi)."},{"kieu":"xep","manh":["这几年","中秋节","一年","比","一年","热闹"],"dap":["这几年中秋节一年比一年热闹。"],"goiY":"Mấy năm nay Trung thu năm sau náo nhiệt hơn năm trước.","giai":"Chủ ngữ + 一年比一年 + Adj."},{"kieu":"xep","manh":["这儿的","衣服","一件","比","一件","漂亮"],"dap":["这儿的衣服一件比一件漂亮。"],"goiY":"Quần áo ở đây bộ nào cũng đẹp hơn bộ nào.","giai":"Lượng từ 件 cho quần áo."},{"kieu":"dungsai","cau":"天气一天比一天很热。","dung":false,"sua":"天气一天比一天热。","giai":"Không thêm 很 trước tính từ."},{"kieu":"dungsai","cau":"我们班的同学一个比一个努力。","dung":true,"giai":"Đúng: so nhiều người, ai cũng chăm chỉ."},{"kieu":"dungsai","cau":"他的中文一天比两天好。","dung":false,"sua":"他的中文一天比一天好。","giai":"Hai vế đều là 一 + cùng lượng từ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 30)","huongDan":"Hoàn thành câu trả lời của B, dùng 一 + lượng từ + 比 + 一 + lượng từ","cau":[{"kieu":"vandung","de":"A：这儿的衣服怎么样？ B：很不错，可以说，＿＿＿漂亮。","goiY":"Quần áo bộ nào cũng đẹp hơn bộ nào (lượng từ 件)","mau":"一件比一件","can":[["一件比一件"]]},{"kieu":"vandung","de":"A：你那里的天气怎么样？ B：现在进入冬天了，＿＿＿。","goiY":"Trời ngày một lạnh hơn (一天比一天)","mau":"天气一天比一天冷","can":[["一天比一天"]]},{"kieu":"vandung","de":"A：他们中文学得怎么样？ B：不错，感觉＿＿＿。","goiY":"Người nào cũng giỏi hơn người nào (一个比一个)","mau":"他们一个比一个说得好","can":[["一个比一个"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Từ khi đến Trung Quốc, tiếng Trung của tôi ngày một tốt hơn.","dap":["来中国以后，我的中文一天比一天好。","来到中国以后，我的中文一天比一天好。"],"giai":"一天比一天 + Adj."},{"kieu":"dich","vn":"Những món mẹ nấu, món nào cũng ngon hơn món nào.","dap":["妈妈做的菜一个比一个好吃。","妈妈做的菜一道比一道好吃。"],"giai":"一个 / 一道 + 比 + 一个 / 一道 + 好吃."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt câu nói về sự thay đổi của quê em / thành phố em mấy năm gần đây, có dùng 「一年比一年……」","mau":"这几年，我的家乡一年比一年漂亮，来旅游的人也越来越多。","can":[["一年比一年","一天比一天"]]}]}]},{"so":"3","ten":"用“大约”“左右”表示概数","tenVn":"Dùng 「大约」「左右」 biểu thị số ước lượng — khoảng, chừng","cauTruc":["大约 + thời gian / số lượng (đứng TRƯỚC): 大约七点","Thời gian / số lượng + 左右 (đứng SAU): 五点左右","Chỉ dùng một trong hai: 大约七点 hoặc 七点左右"],"giaiThich":"「大约」「左右」 biểu thị sự ước chừng, không chắc chắn, có nhiều cách dùng; bài này học cách dùng với từ chỉ thời gian để nói thời gian ước lượng. 「大约」 (phó từ) đứng TRƯỚC từ chỉ thời gian: 大约七点; 「左右」 (danh từ) đứng SAU: 五点左右. Cả cụm thường làm trạng ngữ đứng trước động từ: 早上五点左右他们就坐上了高铁. Cũng dùng được với số lượng: 大约三十个人, 三十岁左右, 一米七左右. Bẫy cho người Việt: tiếng Việt luôn nói “khoảng” TRƯỚC số, nên học sinh hay nói ✗ 左右五点 — nhớ: 左右 luôn đứng SAU. Trong văn nói vẫn nghe 大约七点左右, nhưng nên tránh vì lặp nghĩa.","viDu":[{"zh":"早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。","py":"Zǎoshang wǔ diǎn zuǒyòu tāmen jiù zuòshang le gāotiě, dàyuē qī diǎn jiù láidào le érzi gōngzuò de chéngshì.","vn":"Khoảng năm giờ sáng họ đã lên tàu cao tốc, chừng bảy giờ đã đến thành phố nơi con trai làm việc."},{"zh":"我中午十二点左右到你们学校，和大家一起去食堂吃饭。","py":"Wǒ zhōngwǔ shí èr diǎn zuǒyòu dào nǐmen xuéxiào, hé dàjiā yìqǐ qù shítáng chīfàn.","vn":"Khoảng mười hai giờ trưa tôi đến trường các bạn, rồi cùng mọi người đi nhà ăn."},{"zh":"昨天飞机晚点，我晚上大约十点半才到家。","py":"Zuótiān fēijī wǎndiǎn, wǒ wǎnshang dàyuē shí diǎn bàn cái dào jiā.","vn":"Hôm qua máy bay bị trễ, tối tôi khoảng mười giờ rưỡi mới về đến nhà."},{"zh":"要是路上不堵车，我们大约一个小时就能到。","py":"Yàoshi lùshang bù dǔchē, wǒmen dàyuē yí gè xiǎoshí jiù néng dào.","vn":"Nếu đường không tắc, chúng ta khoảng một tiếng là tới. (ôn 要是……就……, Bài 1 · điểm 2)"}],"loi":[{"sai":"左右五点我们见面吧。","why":"左右 đứng SAU số / thời gian.","dung":"五点左右我们见面吧。"},{"sai":"我们七点大约到。","why":"大约 đứng TRƯỚC số / thời gian.","dung":"我们大约七点到。"},{"sai":"大约七点左右我们出发。","why":"Dùng 大约 hoặc 左右 là đủ, dùng cả hai bị lặp nghĩa.","dung":"大约七点我们出发。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["早上五点","他们就坐上了高铁。"],"dap":[["左右"]],"chon":["左右","大约","大概"],"goiY":"“Khoảng năm giờ sáng họ đã lên tàu cao tốc.”","giai":"Sau thời gian dùng 左右."},{"kieu":"dien","phan":["他们","七点就来到了儿子工作的城市。"],"dap":[["大约"]],"chon":["大约","左右","以后"],"goiY":"“Chừng bảy giờ họ đã đến thành phố …”","giai":"Trước thời gian dùng 大约."},{"kieu":"dien","phan":["我中午十二点","到你们学校。"],"dap":[["左右"]],"chon":["左右","大约","刚才"],"goiY":"“Khoảng mười hai giờ trưa tôi đến trường các bạn.”","giai":"Thời gian + 左右."},{"kieu":"dien","phan":["昨天飞机晚点，我晚上","十点半才到家。"],"dap":[["大约"]],"chon":["大约","左右","已经"],"goiY":"“… tối khoảng mười giờ rưỡi mới về đến nhà.”","giai":"大约 + thời gian + 才."},{"kieu":"dien","phan":["从这儿到景区坐车要一个小时","。"],"dap":[["左右"]],"chon":["左右","大约","以后"],"goiY":"“Từ đây đến khu du lịch đi xe mất khoảng một tiếng.”","giai":"Thời đoạn + 左右."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我们","大约","七点","在剧院门口","见面"],"dap":["我们大约七点在剧院门口见面。"],"goiY":"Chúng ta khoảng bảy giờ gặp nhau ở cổng nhà hát.","giai":"Chủ ngữ + 大约 + thời gian + nơi chốn + V."},{"kieu":"xep","manh":["他","每天","晚上","十一点左右","睡觉"],"dap":["他每天晚上十一点左右睡觉。"],"goiY":"Tối nào anh ấy cũng đi ngủ khoảng mười một giờ.","giai":"Thời gian + 左右 + V."},{"kieu":"xep","manh":["这个城市","大约","有","一千万","人"],"dap":["这个城市大约有一千万人。"],"goiY":"Thành phố này có khoảng mười triệu người.","giai":"大约 + 有 + số lượng."},{"kieu":"dungsai","cau":"左右八点我们出发吧。","dung":false,"sua":"八点左右我们出发吧。","giai":"左右 đứng sau thời gian."},{"kieu":"dungsai","cau":"他看起来三十岁左右。","dung":true,"giai":"Đúng: số tuổi + 左右."},{"kieu":"dungsai","cau":"我们七点大约到。","dung":false,"sua":"我们大约七点到。","giai":"大约 đứng trước thời gian."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 32)","huongDan":"Hoàn thành câu, dùng 大约 hoặc 左右 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"咱们＿＿＿门口见吧，然后一起进去看演出。（剧院）","goiY":"Hẹn khoảng bảy giờ tối ở cổng nhà hát (dùng 「剧院」 + 左右 / 大约)","mau":"晚上七点左右在剧院","can":[["剧院"],["左右","大约"]]},{"kieu":"vandung","de":"这只老虎＿＿＿。（出现）","goiY":"Con hổ này khoảng bốn giờ chiều mỗi ngày sẽ xuất hiện ở bìa rừng (dùng 「出现」 + 左右 / 大约)","mau":"每天下午四点左右会出现在树林旁边","can":[["出现"],["左右","大约"]]},{"kieu":"vandung","de":"我们明天晚上＿＿＿，＿＿＿。（千万）","goiY":"Khoảng tám giờ xuất phát, dặn bạn nhất định đừng đến muộn (dùng 「千万」 + 大约 / 左右)","mau":"大约八点出发，你千万别迟到","can":[["千万"],["大约","左右"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Khoảng tám giờ sáng mai chúng ta xuất phát, đừng đến muộn nhé.","dap":["明天早上八点左右我们出发，别迟到。","明天早上大约八点我们出发，别迟到。","我们明天早上大约八点出发，别迟到。"],"giai":"八点左右 / 大约八点."},{"kieu":"dich","vn":"Từ nhà tôi đến trường đi bộ mất khoảng hai mươi phút.","dap":["从我家到学校走路要二十分钟左右。","从我家到学校走路大约要二十分钟。"],"giai":"Thời đoạn + 左右 / 大约 + 要 + thời đoạn."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể lịch trình một ngày nghỉ lễ của em, dùng cả 「大约」 và 「左右」","mau":"国庆节那天，我早上八点左右起床，大约九点和朋友一起去公园玩。","can":[["大约"],["左右"]]}]}]},{"so":"4","ten":"介词“作为”","tenVn":"Giới từ 「作为」 — với tư cách là, là (một …)","cauTruc":["作为 + danh từ (thân phận / tính chất)，chủ ngữ + vị ngữ","Chủ ngữ + 作为 + danh từ，……"],"giaiThich":"Giới từ 「作为」 nói rõ thân phận của một người hoặc tính chất của một sự vật. Nó KHÔNG đứng một mình làm thành phần câu được, phải kết hợp với danh từ phía sau: 作为父母, 作为新产品, 作为好朋友. Cụm 作为…… thường đứng đầu câu, và người / vật mang thân phận đó phải chính là chủ ngữ của vế sau (作为老师，我…… — “tôi” là giáo viên). Bẫy cho người Việt: tiếng Việt nói “Là sinh viên, chúng ta …” — tiếng Trung KHÔNG dùng 是 ở đầu câu mà dùng 作为: 作为学生，我们……. Ngoài ra 作为 còn là động từ “coi là”: 把 A 作为 B.","viDu":[{"zh":"作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。","py":"Zuòwéi yì nián lǐ zuì zhòngyào de chuántǒng jiérì, Chūnjié duì Zhōngguórén láishuō yǒuzhe tèbié de yìyì.","vn":"Là ngày lễ truyền thống quan trọng nhất trong năm, Tết đối với người Trung Quốc có ý nghĩa đặc biệt."},{"zh":"作为新产品，这个手机不仅样子好看，价格也不高。","py":"Zuòwéi xīn chǎnpǐn, zhège shǒujī bùjǐn yàngzi hǎokàn, jiàgé yě bù gāo.","vn":"Là sản phẩm mới, chiếc điện thoại này không những kiểu dáng đẹp mà giá cũng không cao."},{"zh":"作为好朋友，我们一直互相关心、互相帮助。","py":"Zuòwéi hǎo péngyou, wǒmen yìzhí hùxiāng guānxīn, hùxiāng bāngzhù.","vn":"Là bạn thân, chúng tôi luôn quan tâm, giúp đỡ lẫn nhau."},{"zh":"作为中国人，即使在国外，他也一定要吃年夜饭。","py":"Zuòwéi Zhōngguórén, jíshǐ zài guówài, tā yě yídìng yào chī niányèfàn.","vn":"Là người Trung Quốc, dù ở nước ngoài anh ấy cũng nhất định phải ăn cơm tất niên. (ôn 即使……也……, Bài 11 · điểm 1)"}],"loi":[{"sai":"是学生，我们应该好好学习。","why":"Đầu câu nói “Là …, …” phải dùng 作为, không dùng 是.","dung":"作为学生，我们应该好好学习。"},{"sai":"作为一名老师，学生们都很喜欢他。","why":"Người mang thân phận “giáo viên” (他) phải làm chủ ngữ vế sau.","dung":"作为一名老师，他很关心学生。"},{"sai":"作为，我支持你。","why":"作为 không đứng một mình, phải có danh từ theo sau.","dung":"作为你的朋友，我支持你。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","一年里最重要的传统节日，春节对中国人来说有着特别的意义。"],"dap":[["作为"]],"chon":["作为","因为","成为"],"goiY":"“Là ngày lễ truyền thống quan trọng nhất trong năm …”","giai":"作为 + N (tính chất của sự vật)."},{"kieu":"dien","phan":["作为新产品，这个手机不仅样子好看，价格","不高。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… giá cũng không cao.” (ôn 不仅……也……)","giai":"不仅……，……也…… (Bài 3 · điểm 2)."},{"kieu":"dien","phan":["作为好朋友，我们一直","关心、互相帮助。"],"dap":[["互相"]],"chon":["互相","一起","自己"],"goiY":"“… luôn quan tâm, giúp đỡ lẫn nhau.”","giai":"互相 + V = lẫn nhau."},{"kieu":"dien","phan":["作为父母，","应该多陪陪孩子。"],"dap":[["我们"]],"chon":["我们","孩子们","老师"],"goiY":"“Là cha mẹ, chúng ta nên ở bên con nhiều hơn.”","giai":"Chủ ngữ vế sau phải là người mang thân phận “cha mẹ”."},{"kieu":"dien","phan":["她","一名医生，每天都很关心病人。"],"dap":[["作为"]],"chon":["作为","对于","关于"],"goiY":"“Là một bác sĩ, ngày nào cô ấy cũng quan tâm bệnh nhân.”","giai":"Chủ ngữ + 作为 + N."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["作为","学生","，","我们","应该","好好学习"],"dap":["作为学生，我们应该好好学习。"],"goiY":"Là học sinh, chúng ta nên học hành chăm chỉ.","giai":"作为 + N，chủ ngữ + V."},{"kieu":"xep","manh":["作为","北京人","，","我","一定要","请你","吃烤鸭"],"dap":["作为北京人，我一定要请你吃烤鸭。"],"goiY":"Là người Bắc Kinh, tôi nhất định phải mời bạn ăn vịt quay.","giai":"作为 + thân phận，我 + ……"},{"kieu":"xep","manh":["作为","中国","最重要的","传统节日","，","春节","有着","特别的意义"],"dap":["作为中国最重要的传统节日，春节有着特别的意义。"],"goiY":"Là ngày lễ truyền thống quan trọng nhất của Trung Quốc, Tết có ý nghĩa đặc biệt.","giai":"作为 + N (tính chất của vật)，chủ ngữ + 有着……"},{"kieu":"dungsai","cau":"是学生，我们应该好好学习。","dung":false,"sua":"作为学生，我们应该好好学习。","giai":"Đầu câu dùng 作为, không dùng 是."},{"kieu":"dungsai","cau":"作为一名老师，学生们都很喜欢他。","dung":false,"sua":"作为一名老师，他很关心学生。","giai":"Người là “giáo viên” (他) phải làm chủ ngữ."},{"kieu":"dungsai","cau":"作为新产品，这个手机的价格不太高。","dung":true,"giai":"Đúng: 作为 + N chỉ tính chất của sự vật."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 34)","huongDan":"Hoàn thành câu, có dùng 作为","cau":[{"kieu":"vandung","de":"作为父母，＿＿＿。","goiY":"Nói trách nhiệm của cha mẹ: nên dành nhiều thời gian ở bên con, quan tâm việc học và cuộc sống của con","mau":"我们应该多陪陪孩子，关心他们的学习和生活","can":[["应该","要"]]},{"kieu":"vandung","de":"＿＿＿，我必须请你尝尝北京烤鸭。","goiY":"Nêu thân phận của mình: là người Bắc Kinh (作为……)","mau":"作为北京人","can":[["作为"]]},{"kieu":"vandung","de":"＿＿＿，我支持你的决定。","goiY":"Nêu thân phận: là bạn thân nhất của cậu (作为……)","mau":"作为你最好的朋友","can":[["作为"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Là người Việt Nam, tôi rất thích Tết.","dap":["作为越南人，我很喜欢过春节。","作为越南人，我很喜欢春节。"],"giai":"作为 + thân phận，我 + ……"},{"kieu":"dich","vn":"Là lớp trưởng, cậu ấy luôn quan tâm đến mọi người.","dap":["作为班长，他一直很关心大家。","作为班长，他总是很关心大家。"],"giai":"作为 + chức vụ，他 + ……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói về trách nhiệm của em với tư cách là con / học sinh / bạn, có dùng 「作为……」","mau":"作为家里的大儿子，我应该多帮爸爸妈妈做家务。","can":[["作为"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-14.html"] = [{"so":"1","ten":"语气副词“究竟”","tenVn":"Phó từ ngữ khí 「究竟」 — rốt cuộc, cuối cùng thì","cauTruc":["Chủ ngữ + 究竟 + câu hỏi có đại từ nghi vấn (什么 / 哪 / 怎么 / 为什么…) (+ 呢)?","Chủ ngữ + 究竟 + V不V / 是A还是B (+ 呢)?","Đại từ nghi vấn làm chủ ngữ: 究竟 + 谁 / 什么 + V?"],"giaiThich":"「究竟」 dùng trong câu hỏi để TRUY HỎI đến cùng: người nói rất muốn biết câu trả lời chính xác (rốt cuộc là …?). Câu có 究竟 phải là câu hỏi có đại từ nghi vấn (什么, 哪, 谁, 怎么, 为什么…), câu hỏi chính phản (V不V) hoặc câu hỏi lựa chọn (是……还是……); cuối câu hay thêm 「呢」 nhưng KHÔNG dùng 「吗」. Vị trí: thường đứng sau chủ ngữ, trước vị ngữ (他究竟去哪里了?); nếu chủ ngữ chính là đại từ nghi vấn thì 究竟 đứng TRƯỚC chủ ngữ (究竟谁去?). 究竟 cũng dùng được trong câu hỏi gián tiếp: 我不知道他究竟去哪儿了. Mẹo cho người Việt: thấy “rốt cuộc … ?” → 究竟 (sau này gặp thêm 到底 ở Bài 18, khẩu ngữ hơn). Bẫy Hán Việt: 究竟 đọc là “cứu cánh” nhưng KHÔNG mang nghĩa “cứu cánh” của tiếng Việt.","viDu":[{"zh":"这里茶叶这么多，究竟买哪种好呢？","py":"Zhèli cháyè zhème duō, jiūjìng mǎi nǎ zhǒng hǎo ne?","vn":"Ở đây nhiều loại trà thế này, rốt cuộc nên mua loại nào đây?"},{"zh":"我一直没找到他，他究竟去哪里了呢？","py":"Wǒ yìzhí méi zhǎodào tā, tā jiūjìng qù nǎlǐ le ne?","vn":"Tôi tìm mãi không thấy anh ấy, rốt cuộc anh ấy đi đâu rồi?"},{"zh":"究竟是对还是错？我现在也不清楚。","py":"Jiūjìng shì duì háishi cuò? Wǒ xiànzài yě bù qīngchu.","vn":"Rốt cuộc là đúng hay sai? Bây giờ tôi cũng không rõ."},{"zh":"无论我怎么问，他都不告诉我究竟发生了什么事。","py":"Wúlùn wǒ zěnme wèn, tā dōu bú gàosu wǒ jiūjìng fāshēng le shénme shì.","vn":"Dù tôi hỏi thế nào, anh ấy cũng không nói cho tôi biết rốt cuộc đã xảy ra chuyện gì. (ôn 无论……都…… – Bài 12 · điểm 3)"}],"loi":[{"sai":"你究竟去吗？","why":"Câu có 究竟 không dùng 吗 — phải là câu hỏi chính phản hoặc có đại từ nghi vấn.","dung":"你究竟去不去？"},{"sai":"谁究竟拿走了我的书？","why":"Chủ ngữ là đại từ nghi vấn (谁) thì 究竟 phải đứng trước nó.","dung":"究竟谁拿走了我的书？"},{"sai":"这件衣服究竟很贵。","why":"究竟 dùng trong câu hỏi để truy hỏi, không dùng trong câu trần thuật khẳng định bình thường.","dung":"这件衣服究竟贵不贵？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["这里茶叶这么多，","买哪种好呢？"],"dap":[["究竟"]],"chon":["究竟","已经","一共"],"goiY":"“… rốt cuộc nên mua loại nào đây?”","giai":"究竟 + câu hỏi có đại từ nghi vấn 哪."},{"kieu":"dien","phan":["我一直没找到他，他究竟去哪里了","？"],"dap":[["呢"]],"chon":["呢","吗","吧"],"goiY":"“… rốt cuộc anh ấy đi đâu rồi?”","giai":"Câu có 究竟 cuối câu dùng 呢, không dùng 吗."},{"kieu":"dien","phan":["你明天究竟去","去？快决定吧！"],"dap":[["不"]],"chon":["不","没","也"],"goiY":"“Mai rốt cuộc cậu có đi hay không?”","giai":"究竟 + V不V (việc tương lai dùng 不)."},{"kieu":"dien","phan":["","是对还是错？我现在也不清楚。"],"dap":[["究竟"]],"chon":["究竟","一定","已经"],"goiY":"“Rốt cuộc là đúng hay sai?”","giai":"究竟 + 是A还是B."},{"kieu":"dien","phan":["这两双鞋，你究竟喜欢","一双？"],"dap":[["哪"]],"chon":["哪","那","这"],"goiY":"“… rốt cuộc cậu thích đôi nào?”","giai":"Câu hỏi phải có đại từ nghi vấn 哪."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你","究竟","想","买","什么","呢"],"dap":["你究竟想买什么呢？"],"goiY":"Rốt cuộc bạn muốn mua gì?","giai":"Chủ ngữ + 究竟 + V + 什么 + 呢."},{"kieu":"xep","manh":["究竟","谁","去","参加","比赛"],"dap":["究竟谁去参加比赛？"],"goiY":"Rốt cuộc ai đi dự thi?","giai":"Chủ ngữ là 谁 → 究竟 đứng trước 谁."},{"kieu":"xep","manh":["我","不知道","他","究竟","为什么","不来"],"dap":["我不知道他究竟为什么不来。"],"goiY":"Tôi không biết rốt cuộc tại sao anh ấy không đến.","giai":"Câu hỏi gián tiếp: 不知道 + chủ ngữ + 究竟 + 为什么."},{"kieu":"dungsai","cau":"你究竟喜欢这件外套吗？","dung":false,"sua":"你究竟喜欢不喜欢这件外套？","giai":"究竟 không đi với 吗 → dùng V不V."},{"kieu":"dungsai","cau":"究竟是谁告诉你的？","dung":true,"giai":"Đúng: 究竟 + 是 + 谁."},{"kieu":"dungsai","cau":"谁究竟是你的老师？","dung":false,"sua":"究竟谁是你的老师？","giai":"究竟 đứng trước đại từ nghi vấn làm chủ ngữ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 40)","huongDan":"Hoàn thành câu hỏi của A, có dùng 「究竟」","cau":[{"kieu":"vandung","de":"A：这件衣服她究竟＿＿＿呢？ B：她说她很喜欢。","goiY":"Hỏi: rốt cuộc cô ấy có thích hay không (câu hỏi chính phản V不V)","mau":"喜欢不喜欢","can":[["不喜欢","喜不喜欢"]]},{"kieu":"vandung","de":"A：你＿＿＿？ B：我快写完了，请再等两天。","goiY":"Hỏi: rốt cuộc khi nào bạn mới viết xong (bản báo cáo / luận văn)","mau":"究竟什么时候能把报告写完","can":[["究竟"]]},{"kieu":"vandung","de":"A：＿＿＿？ B：我还没决定，我再想想吧。","goiY":"Hỏi: hai chiếc điện thoại này, rốt cuộc bạn mua chiếc nào","mau":"这两个手机，你究竟买哪个","can":[["究竟"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Rốt cuộc bạn muốn mua loại trà nào?","dap":["你究竟想买哪种茶叶？","你究竟想买哪种茶？"],"giai":"究竟 + V + 哪种 + N."},{"kieu":"dich","vn":"Rốt cuộc ai đã nói với bạn chuyện này?","dap":["究竟是谁告诉你这件事的？","这件事究竟是谁告诉你的？"],"giai":"究竟 + 是 + 谁 + ……的."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Tự đặt một câu hỏi người bạn đang phân vân khi mua sắm, có dùng 「究竟」","mau":"这两件外套都很好看，你究竟买哪件呢？","can":[["究竟"]]}]}]},{"so":"2","ten":"承接复句“首先……，然后/其次……”","tenVn":"Câu phức nối tiếp 「首先……，然后 / 其次……」 — trước hết …, sau đó / thứ đến …","cauTruc":["首先 + việc 1，然后 (再) + việc 2 — thứ tự thời gian","首先 + điều chính / lý do 1，其次 + điều phụ / lý do 2 — thứ tự chính phụ","Liệt kê dài: 首先……，其次 / 然后……，最后……"],"giaiThich":"Câu phức nối tiếp, biểu thị THỨ TỰ TRƯỚC SAU hoặc PHÂN BIỆT CHÍNH – PHỤ. 「首先……，然后……」: các hành động xảy ra theo thứ tự thời gian — làm việc 1 trước rồi mới đến việc 2 (然后 hay đi với 再). 「首先……，其次……」: liệt kê theo mức độ quan trọng — điều thứ nhất (chính), điều thứ hai (phụ hơn); hay dùng khi nêu lý do, điều kiện, yêu cầu, trình bày ý kiến. 其次 (qícì) = thứ đến, thứ hai là. Có thể thêm 最后 ở vế cuối. Mẹo cho người Việt: “đầu tiên … sau đó …” (thời gian) → 首先……，然后……; “thứ nhất là … thứ hai là …” (các ý, lý do) → 首先……，其次……. Phân biệt 首先 với 先: 首先 đứng được ở đầu câu, trước chủ ngữ, có dấu phẩy (首先，我……), còn 先 chỉ đứng sau chủ ngữ (我先……).","viDu":[{"zh":"首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","py":"Shǒuxiān kàn yàngzi xǐ bu xǐhuan, ránhòu zài kàn zhìliàng zěnmeyàng, jiàgé héshì bù héshì.","vn":"Trước hết xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá có hợp lý không."},{"zh":"遇到问题，首先想想问题为什么出现，然后再积极想办法解决。","py":"Yùdào wèntí, shǒuxiān xiǎngxiang wèntí wèishénme chūxiàn, ránhòu zài jījí xiǎng bànfǎ jiějué.","vn":"Gặp vấn đề, trước hết nghĩ xem vì sao vấn đề xuất hiện, sau đó mới tích cực tìm cách giải quyết."},{"zh":"请大家首先读一遍课文，然后根据课文完成课后练习。","py":"Qǐng dàjiā shǒuxiān dú yí biàn kèwén, ránhòu gēnjù kèwén wánchéng kèhòu liànxí.","vn":"Mời cả lớp trước hết đọc bài khóa một lượt, sau đó dựa vào bài khóa làm bài tập sau bài."},{"zh":"作为班长，我首先要关心同学们，其次要帮老师做好班里的事。","py":"Zuòwéi bānzhǎng, wǒ shǒuxiān yào guānxīn tóngxuémen, qícì yào bāng lǎoshī zuòhǎo bān lǐ de shì.","vn":"Là lớp trưởng, trước hết tôi phải quan tâm các bạn, thứ đến phải giúp thầy cô làm tốt việc của lớp. (ôn 作为 – Bài 13 · điểm 4)"}],"loi":[{"sai":"我首先洗手，其次吃饭。","why":"Hai hành động nối nhau theo thời gian → dùng 然后; 其次 dùng để xếp các ý theo mức độ quan trọng.","dung":"我首先洗手，然后吃饭。"},{"sai":"先，我们去做市场调查。","why":"先 không đứng một mình ở đầu câu trước dấu phẩy; muốn tách riêng như vậy phải dùng 首先.","dung":"首先，我们去做市场调查。"},{"sai":"首先我们去吃饭，然后去看电影，然后去唱歌，然后回家。","why":"Liệt kê nhiều việc mà cứ lặp 然后 thì rườm; việc cuối dùng 最后.","dung":"首先我们去吃饭，然后去看电影，再去唱歌，最后回家。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["首先看样子喜不喜欢，","再看质量怎么样。"],"dap":[["然后"]],"chon":["然后","其次","首先"],"goiY":"“… sau đó mới xem chất lượng thế nào.”","giai":"Thứ tự thời gian: 首先……，然后再……"},{"kieu":"dien","phan":["遇到问题，","想想问题为什么出现，然后再积极想办法解决。"],"dap":[["首先"]],"chon":["首先","最后","其次"],"goiY":"“Gặp vấn đề, trước hết nghĩ xem …”","giai":"Vế đầu dùng 首先."},{"kieu":"dien","phan":["请大家首先读一遍课文，","根据课文完成课后练习。"],"dap":[["然后"]],"chon":["然后","而且","加上"],"goiY":"“… sau đó dựa vào bài khóa làm bài tập.”","giai":"首先……，然后……"},{"kieu":"dien","phan":["我选这份工作，首先是因为喜欢，","是因为离家近。"],"dap":[["其次"]],"chon":["其次","然后","首先"],"goiY":"“… thứ nhất là vì thích, thứ hai là vì gần nhà.”","giai":"Liệt kê lý do (chính – phụ) → 其次."},{"kieu":"dien","phan":["学中文首先要多听，其次要多说，","还要多读多写。"],"dap":[["最后"]],"chon":["最后","首先","究竟"],"goiY":"“… cuối cùng còn phải đọc nhiều viết nhiều.”","giai":"首先……，其次……，最后……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我们","首先","去超市","，","然后","去","银行"],"dap":["我们首先去超市，然后去银行。"],"goiY":"Chúng ta đi siêu thị trước, sau đó đến ngân hàng.","giai":"首先 + V1，然后 + V2."},{"kieu":"xep","manh":["买东西","首先","看质量","，","其次","看价格"],"dap":["买东西首先看质量，其次看价格。"],"goiY":"Mua đồ trước hết xem chất lượng, thứ đến mới xem giá.","giai":"首先……，其次…… (chính – phụ)."},{"kieu":"xep","manh":["请大家","首先","读一遍课文","，","然后","回答问题"],"dap":["请大家首先读一遍课文，然后回答问题。"],"goiY":"Mời mọi người đọc bài khóa một lượt trước, sau đó trả lời câu hỏi.","giai":"首先……，然后……"},{"kieu":"dungsai","cau":"我每天首先起床，其次刷牙。","dung":false,"sua":"我每天首先起床，然后刷牙。","giai":"Thứ tự thời gian → 然后, không dùng 其次."},{"kieu":"dungsai","cau":"首先，我要感谢老师；其次，我要感谢我的家人。","dung":true,"giai":"Đúng: liệt kê các ý theo thứ tự, 首先……；其次……"},{"kieu":"dungsai","cau":"先，我们来介绍一下自己。","dung":false,"sua":"首先，我们来介绍一下自己。","giai":"Đứng đầu câu có dấu phẩy phải là 首先."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 42)","huongDan":"Hoàn thành câu trả lời của B, có dùng 「首先……，然后 / 其次……」","cau":[{"kieu":"vandung","de":"A：请说说你们的计划。 B：我们的计划是，首先去做市场调查，＿＿＿。","goiY":"Sau đó dựa vào kết quả khảo sát quyết định bán mặt hàng gì (ôn 调查 – Bài 7)","mau":"然后根据调查的结果决定卖什么商品","can":[["然后"]]},{"kieu":"vandung","de":"A：你们寒假是怎么安排的？ B：＿＿＿；其次，＿＿＿。","goiY":"Thứ nhất: về nhà đón Tết với bố mẹ; thứ hai: đi du lịch phương Nam vài ngày (ôn 寒假 – Bài 10)","mau":"首先，我们要回家陪父母过春节；其次，我们打算去南方旅游几天","can":[["首先"]]},{"kieu":"vandung","de":"A：能谈谈你为什么觉得自己适合这份工作吗？ B：好的。首先我的专业是儿童教育，＿＿＿。","goiY":"Thứ hai: em rất thích trẻ con và đã có kinh nghiệm làm ở nhà trẻ","mau":"其次我非常喜欢孩子，而且有两年在幼儿园工作的经验","can":[["其次"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Trước hết phải xem mình có thật sự cần không, sau đó mới so sánh giá.","dap":["首先要看自己是不是真正需要，然后再比较价格。","首先要看自己是不是真的需要，然后再比较价格。"],"giai":"首先……，然后再……"},{"kieu":"dich","vn":"Tôi thích căn nhà này: thứ nhất là giao thông thuận tiện, thứ hai là tiền thuê không đắt.","dap":["我喜欢这个房子，首先是交通方便，其次是房租不贵。","我喜欢这套房子，首先是交通方便，其次是房租不贵。"],"giai":"Liệt kê lý do → 首先……，其次……; ôn 房租 (Bài 2)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể các bước em chọn mua một món đồ, có dùng 「首先……，然后……」","mau":"我买东西的时候，首先看质量好不好，然后再看价格合适不合适。","can":[["首先"],["然后","其次"]]}]}]},{"so":"3","ten":"连词“加上”","tenVn":"Liên từ 「加上」 — thêm vào đó, cộng thêm","cauTruc":["Lý do / tình hình 1，加上 + lý do / tình hình 2，(所以 / 使得 / 就) + kết quả","Lý do 1，再加上 + lý do 2，……"],"giaiThich":"「加上」 nối tiếp câu trước, đưa thêm MỘT LÝ DO / ĐIỀU KIỆN NỮA (tiến thêm một bước); câu sau nêu KẾT QUẢ do các lý do đó cùng tạo ra, thường có 所以, 使得, 就…. Hai lý do phải CÙNG CHIỀU, cùng dẫn tới kết quả. Vế 加上 có thể thêm 又 / 再 cho tự nhiên: 加上又是周末, 再加上……. Mẹo cho người Việt: “(lại) thêm vào đó / cộng thêm …, nên …” → 加上. Phân biệt với 而且 (hơn nữa): 而且 chỉ bổ sung thông tin, không bắt buộc có vế kết quả; 加上 thì luôn có vế kết quả phía sau.","viDu":[{"zh":"小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。","py":"Xiǎodiàn suīrán xiǎo, dàn dōngxi shìhé niánqīngrén, jiāshàng diànyuán tàidù yǒuhǎo, shǐde xiǎodiàn de shēngyi yuèláiyuè hǎo.","vn":"Tiệm tuy nhỏ nhưng đồ hợp với người trẻ, thêm vào đó nhân viên lại thân thiện, khiến việc buôn bán của tiệm ngày càng tốt."},{"zh":"虽然这里是郊区，但周围交通很方便，加上房租便宜，所以很多年轻人都在这里租房子。","py":"Suīrán zhèli shì jiāoqū, dàn zhōuwéi jiāotōng hěn fāngbiàn, jiāshàng fángzū piányi, suǒyǐ hěn duō niánqīngrén dōu zài zhèli zū fángzi.","vn":"Tuy đây là vùng ngoại ô nhưng giao thông xung quanh rất thuận tiện, thêm vào đó tiền thuê nhà rẻ, nên nhiều người trẻ thuê nhà ở đây."},{"zh":"他很聪明，加上一直非常努力，所以最后考上了理想的大学。","py":"Tā hěn cōngming, jiāshàng yìzhí fēicháng nǔlì, suǒyǐ zuìhòu kǎoshàng le lǐxiǎng de dàxué.","vn":"Cậu ấy rất thông minh, thêm vào đó lại luôn rất chăm chỉ, nên cuối cùng đã đỗ vào trường đại học mơ ước."},{"zh":"这里离公司很近，走路大约十分钟，加上房租也不贵，所以我决定租这儿的房子。","py":"Zhèli lí gōngsī hěn jìn, zǒulù dàyuē shí fēnzhōng, jiāshàng fángzū yě bú guì, suǒyǐ wǒ juédìng zū zhèr de fángzi.","vn":"Chỗ này gần công ty, đi bộ khoảng mười phút, thêm vào đó tiền thuê cũng không đắt, nên tôi quyết định thuê nhà ở đây. (ôn 大约 – Bài 13 · điểm 3)"}],"loi":[{"sai":"他很聪明，加上一直非常努力。","why":"Thiếu vế kết quả — sau vế 加上 phải có câu nêu kết quả.","dung":"他很聪明，加上一直非常努力，所以考上了理想的大学。"},{"sai":"这件衣服很好看，加上太贵了，所以我买了。","why":"Hai lý do phải cùng chiều dẫn tới kết quả; “quá đắt” ngược chiều với việc “mua”.","dung":"这件衣服很好看，加上不太贵，所以我买了。"},{"sai":"小店的生意越来越好，加上店员态度友好。","why":"Vế 加上 (nguyên nhân) đứng trước, vế kết quả đứng sau.","dung":"东西适合年轻人，加上店员态度友好，所以小店的生意越来越好。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["小店虽然小，但东西适合年轻人，","店员态度友好，使得小店的生意越来越好。"],"dap":[["加上"]],"chon":["加上","首先","对于"],"goiY":"“… thêm vào đó nhân viên thân thiện …”","giai":"加上 đưa thêm một lý do cùng chiều."},{"kieu":"dien","phan":["这里交通很方便，加上房租便宜，","很多年轻人都在这里租房子。"],"dap":[["所以"]],"chon":["所以","但是","虽然"],"goiY":"“… nên nhiều người trẻ thuê nhà ở đây.”","giai":"Vế sau 加上 nêu kết quả, thường có 所以."},{"kieu":"dien","phan":["今天下雨，加上","是周末，路上车特别多。"],"dap":[["又"]],"chon":["又","才","都"],"goiY":"“… lại thêm hôm nay là cuối tuần …”","giai":"加上 + 又 + lý do thêm."},{"kieu":"dien","phan":["这家店东西便宜，再","服务好，顾客越来越多。"],"dap":[["加上"]],"chon":["加上","而且","不光"],"goiY":"“… lại thêm phục vụ tốt …”","giai":"再加上 = lại thêm."},{"kieu":"dien","phan":["这里环境好，加上交通也方便，","很多人想在这儿买房子。"],"dap":[["使得"]],"chon":["使得","但是","虽然"],"goiY":"“… khiến nhiều người muốn mua nhà ở đây.”","giai":"……，加上……，使得 + kết quả (使得 – từ mới bài khoá 3)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这些茶叶","很香","，","加上","在促销","，","我","买了两斤"],"dap":["这些茶叶很香，加上在促销，我买了两斤。"],"goiY":"Trà này rất thơm, thêm vào đó đang khuyến mãi, nên tôi mua hai cân.","giai":"Lý do 1，加上 + lý do 2，kết quả."},{"kieu":"xep","manh":["天气","很冷","，","加上","下雨","，","街上","没什么人"],"dap":["天气很冷，加上下雨，街上没什么人。"],"goiY":"Trời rất lạnh, lại thêm mưa, nên trên phố chẳng có mấy người.","giai":"Hai lý do cùng chiều → một kết quả."},{"kieu":"dungsai","cau":"他很聪明，加上一直非常努力。","dung":false,"sua":"他很聪明，加上一直非常努力，所以考上了理想的大学。","giai":"Thiếu vế kết quả."},{"kieu":"dungsai","cau":"这里环境很好，加上交通方便，所以房子很好卖。","dung":true,"giai":"Đúng: hai lý do cùng chiều + kết quả 所以……"},{"kieu":"dungsai","cau":"这家饭馆的菜很好吃，加上服务员态度很差，所以顾客很多。","dung":false,"sua":"这家饭馆的菜很好吃，加上服务员态度很好，所以顾客很多。","giai":"Lý do sau 加上 phải cùng chiều với lý do trước."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 44)","huongDan":"Hoàn thành câu với 「加上」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"这些茶叶闻着很香，＿＿＿，我一下就买了两斤。（促销）","goiY":"Dùng 「促销」: thêm vào đó cửa hàng đang khuyến mãi","mau":"加上店里正在做促销","can":[["加上"],["促销"]]},{"kieu":"vandung","de":"这个话剧（huàjù, kịch nói）很有名，＿＿＿，来剧院看演出的观众＿＿＿。（超过）","goiY":"Dùng 「超过」: thêm vào đó diễn viên diễn rất hay; khán giả đến xem vượt quá một nghìn người","mau":"加上演员演得特别好，超过了一千人","can":[["加上"],["超过"]]},{"kieu":"vandung","de":"这位售货员很专业，＿＿＿，很快就卖出去了好几个手机。（态度）","goiY":"Dùng 「态度」: thêm vào đó thái độ rất thân thiện","mau":"加上态度也很友好","can":[["加上"],["态度"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tiệm này đồ rẻ, thêm vào đó nhân viên rất thân thiện, nên khách rất đông.","dap":["这家店东西便宜，加上店员很友好，所以顾客很多。","这家店的东西很便宜，加上店员态度很友好，所以顾客很多。"],"giai":"……，加上……，所以……"},{"kieu":"dich","vn":"Hôm nay tôi dậy muộn, thêm vào đó đường lại tắc, nên đã đến muộn.","dap":["今天我起晚了，加上路上又堵车，所以迟到了。","我今天起晚了，加上路上堵车，所以迟到了。"],"giai":"加上 + 又 + lý do thêm; 所以 + kết quả."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giải thích vì sao em thích một cửa hàng / quán ăn, có dùng 「加上」","mau":"学校旁边那家饭馆的菜又好吃又便宜，加上老板很友好，所以同学们都喜欢去。","can":[["加上"]]}]}]},{"so":"4","ten":"介词“对于”","tenVn":"Giới từ 「对于」 — đối với, về","cauTruc":["对于 + đối tượng (người / việc / vật)，chủ ngữ + vị ngữ","Chủ ngữ + 对于 + đối tượng + vị ngữ","对于 + ai + 来说，…… (đối với ai mà nói)"],"giaiThich":"「对于」 dẫn ra ĐỐI TƯỢNG cụ thể (người, việc, vật) mà hành động hoặc thái độ nhắm tới. Cụm 「对于……」 thường đứng ĐẦU câu, trước chủ ngữ, có dấu phẩy, để nêu chủ đề cần bàn; cũng có thể đứng sau chủ ngữ. Phân biệt với 对: chỗ nào dùng 对于 đều thay được bằng 对; nhưng khi nói thái độ, hành động giữa NGƯỜI với NGƯỜI (đối xử với ai, nói với ai: 他对我很好, 对老师说) thì chỉ dùng 对, không dùng 对于. Mẹo cho người Việt: “đối với / về (vấn đề, việc) …, (ai) …” → 对于……，……; còn “đối với tôi mà nói (theo tôi)” phải có 来说: 对我来说 / 对于我来说. Lưu ý: cụm 对于…… không làm chủ ngữ — câu vẫn cần một chủ ngữ riêng.","viDu":[{"zh":"对于想买的东西，她不光看质量，还看价格。","py":"Duìyú xiǎng mǎi de dōngxi, tā bùguāng kàn zhìliàng, hái kàn jiàgé.","vn":"Đối với những thứ muốn mua, cô ấy không chỉ xem chất lượng mà còn xem giá."},{"zh":"对于他的做法，大家都很支持。","py":"Duìyú tā de zuòfǎ, dàjiā dōu hěn zhīchí.","vn":"Đối với cách làm của anh ấy, mọi người đều rất ủng hộ."},{"zh":"对于你们提的这个建议，我们一定好好研究。","py":"Duìyú nǐmen tí de zhège jiànyì, wǒmen yídìng hǎohāo yánjiū.","vn":"Về đề xuất các bạn đưa ra, chúng tôi nhất định sẽ nghiên cứu kỹ."},{"zh":"对于这件事，即使大家都不同意，我也想试一试。","py":"Duìyú zhè jiàn shì, jíshǐ dàjiā dōu bù tóngyì, wǒ yě xiǎng shì yi shì.","vn":"Về chuyện này, cho dù mọi người đều không đồng ý, tôi cũng muốn thử một lần. (ôn 即使……也…… – Bài 11 · điểm 1)"}],"loi":[{"sai":"他对于老师很友好。","why":"Thái độ giữa người với người (đối xử với ai) chỉ dùng 对.","dung":"他对老师很友好。"},{"sai":"对于我，学中文很有意思。","why":"Nêu cảm nhận, góc nhìn của ai phải dùng 对……来说 / 对于……来说.","dung":"对我来说，学中文很有意思。"},{"sai":"对于这个建议很好。","why":"Cụm 对于…… không làm chủ ngữ; câu phải có chủ ngữ riêng.","dung":"对于这个建议，大家都觉得很好。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","想买的东西，她不光看质量，还看价格。"],"dap":[["对于"]],"chon":["对于","加上","首先"],"goiY":"“Đối với những thứ muốn mua …”","giai":"对于 + đối tượng，chủ ngữ + V."},{"kieu":"dien","phan":["对于他的做法，大家都很","。"],"dap":[["支持"]],"chon":["支持","友好","仔细"],"goiY":"“… mọi người đều rất ủng hộ.” (ôn 支持 – Bài 9)","giai":"对于 + việc，ai + 支持."},{"kieu":"dien","phan":["对于你们提的这个建议，我们一定好好","。"],"dap":[["研究"]],"chon":["研究","表示","降价"],"goiY":"“… chúng tôi nhất định nghiên cứu kỹ.”","giai":"对于 + 建议，……研究."},{"kieu":"dien","phan":["他","老师很有礼貌。"],"dap":[["对"]],"chon":["对","对于","关于"],"goiY":"“Cậu ấy rất lễ phép với thầy cô.”","giai":"Thái độ với NGƯỜI → chỉ dùng 对."},{"kieu":"dien","phan":["对于很多年轻人","，买盲盒是一件快乐的事。"],"dap":[["来说"]],"chon":["来说","以后","的话"],"goiY":"“Đối với nhiều bạn trẻ mà nói …”","giai":"对于……来说 = đối với … mà nói."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["对于","这个问题","，","大家","有","什么","看法"],"dap":["对于这个问题，大家有什么看法？"],"goiY":"Về vấn đề này, mọi người có ý kiến gì?","giai":"对于 + N，chủ ngữ + V."},{"kieu":"xep","manh":["对于","顾客的意见","，","我们","一定","好好研究"],"dap":["对于顾客的意见，我们一定好好研究。"],"goiY":"Đối với ý kiến của khách hàng, chúng tôi nhất định nghiên cứu kỹ.","giai":"Cụm 对于 đứng đầu câu."},{"kieu":"dungsai","cau":"她对于孩子很耐心。","dung":false,"sua":"她对孩子很耐心。","giai":"Thái độ với người → 对."},{"kieu":"dungsai","cau":"对于这件事，我还没想好。","dung":true,"giai":"Đúng: 对于 + việc，chủ ngữ + V."},{"kieu":"dungsai","cau":"对于买东西很仔细。","dung":false,"sua":"对于买东西，她很仔细。","giai":"Thiếu chủ ngữ; cụm 对于 không làm chủ ngữ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 46)","huongDan":"Hoàn thành câu, có dùng 「对于」","cau":[{"kieu":"vandung","de":"对于这份工作，＿＿＿？","goiY":"Hỏi suy nghĩ của người nghe về công việc này (có thể thêm 究竟)","mau":"你究竟有什么想法","can":[["什么","怎么","吗","满意"]]},{"kieu":"vandung","de":"＿＿＿，你们觉得怎么样？","goiY":"Nêu đối tượng muốn hỏi ý kiến: kế hoạch chúng tôi đưa ra","mau":"对于我们提的这个计划","can":[["对于"]]},{"kieu":"vandung","de":"＿＿＿购物，你是想＿＿＿，还是＿＿＿？","goiY":"Hỏi về chuyện mua sắm: muốn mua đồ rẻ hay mua đồ chất lượng tốt","mau":"对于购物，你是想买便宜的，还是想买质量好的","can":[["对于"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Về vấn đề này, mọi người có ý kiến gì?","dap":["对于这个问题，大家有什么看法？","对于这个问题，大家有什么意见？"],"giai":"对于 + N đứng đầu câu."},{"kieu":"dich","vn":"Đối với những thứ muốn mua, tôi đều so sánh kỹ rồi mới mua.","dap":["对于想买的东西，我都仔细比较后才买。","对于想买的东西，我都是仔细比较以后才买。"],"giai":"对于……，chủ ngữ + 都 + 仔细比较后才……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói ý kiến của em về việc mua hộp mù / mua đồ giảm giá, có dùng 「对于」","mau":"对于盲盒，我觉得偶尔买一个可以，但是不能买太多，不然就是浪费钱。","can":[["对于"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-15.html"] = [{"so":"1","ten":"固定格式“再也不/没……”","tenVn":"Cấu trúc cố định 「再也不 / 再也没……」 — không bao giờ … nữa / từ đó không … nữa","cauTruc":["(以后) + 再也不 + động từ (+ 了) → từ nay về sau sẽ không bao giờ … nữa (TƯƠNG LAI)","(mốc thời gian + 后 / 以后) + 就 + 再也没 (有) + động từ + 过 (+ 了) → từ đó đến nay không … lại nữa (QUÁ KHỨ → HIỆN TẠI)"],"giaiThich":"「再也不」 nói về TƯƠNG LAI: khẳng định / hứa từ nay sẽ không bao giờ làm việc đó nữa (我以后再也不迟到了). 「再也没」 nói về khoảng thời gian từ một mốc trong QUÁ KHỨ đến BÂY GIỜ: việc đó không xảy ra lần nào nữa; động từ hay kèm 「过」, phía trước thường có mốc thời gian + 就 (期中考试后就再也没见过你了). Mẹo cho người Việt: nghe “không … nữa”, hãy hỏi: đó là lời hứa / dự định về sau → 再也不; còn là kể chuyện đã xảy ra từ đó đến nay → 再也没. Thứ tự luôn là 再也 + 不 / 没 (✗ 不再也). So với 不再 (không … nữa), 再也不 mạnh hơn, mang cảm xúc rõ hơn (hối hận, quyết tâm, tiếc nuối).","viDu":[{"zh":"期中考试后就再也没见过你了。","py":"Qīzhōng kǎoshì hòu jiù zài yě méi jiàn guò nǐ le.","vn":"Từ sau kỳ thi giữa kỳ là không gặp lại cậu nữa."},{"zh":"对不起，我以后再也不迟到了。","py":"Duìbuqǐ, wǒ yǐhòu zài yě bù chídào le.","vn":"Xin lỗi, từ nay em sẽ không bao giờ đến muộn nữa."},{"zh":"我出国以后就再也没给他打过电话。","py":"Wǒ chūguó yǐhòu jiù zài yě méi gěi tā dǎ guò diànhuà.","vn":"Từ khi ra nước ngoài, tôi không gọi điện cho anh ấy lần nào nữa."},{"zh":"毕业以后我们就再也没见过面，我怎么也联系不上他。","py":"Bìyè yǐhòu wǒmen jiù zài yě méi jiàn guò miàn, wǒ zěnme yě liánxì bú shàng tā.","vn":"Từ khi tốt nghiệp chúng tôi không gặp lại nhau nữa, tôi liên lạc thế nào cũng không được. (ôn 怎么也 + 不 — Bài 13)"}],"loi":[{"sai":"我以后再也没迟到了。","why":"Lời hứa về sau (以后) phải dùng 再也不.","dung":"我以后再也不迟到了。"},{"sai":"毕业以后，我再也不见过他。","why":"Kể việc từ quá khứ đến nay, có 过 → dùng 再也没.","dung":"毕业以后，我再也没见过他。"},{"sai":"我不再也去那家饭馆了。","why":"Thứ tự đúng là 再也 + 不 / 没.","dung":"我再也不去那家饭馆了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["期中考试后就再也","见过你了。"],"dap":[["没"]],"chon":["没","不","别"],"goiY":"“Từ sau thi giữa kỳ là không gặp lại cậu nữa.” (quá khứ → nay)","giai":"Có 过, kể việc đã qua → 再也没."},{"kieu":"dien","phan":["对不起，我以后再也","迟到了。"],"dap":[["不"]],"chon":["不","没","还"],"goiY":"“Từ nay em sẽ không bao giờ đến muộn nữa.” (lời hứa)","giai":"以后 + lời hứa → 再也不."},{"kieu":"dien","phan":["我出国以后就","没给他打过电话。"],"dap":[["再也"]],"chon":["再也","也再","还是"],"goiY":"“Từ khi ra nước ngoài, tôi không gọi cho anh ấy nữa.”","giai":"Thứ tự: 再也 + 没."},{"kieu":"dien","phan":["从那天以后，她就再也没给我发过","。"],"dap":[["短信"]],"chon":["短信","细节","答案"],"goiY":"“Từ hôm đó, cô ấy không nhắn tin cho tôi nữa.” (ôn từ mới)","giai":"发短信 = gửi tin nhắn."},{"kieu":"dien","phan":["妈妈，你放心，我","不躺在床上看手机了。"],"dap":[["再也"]],"chon":["再也","再也没","也再"],"goiY":"“Mẹ yên tâm, con sẽ không bao giờ nằm trên giường xem điện thoại nữa.”","giai":"再也 + 不 → lời hứa."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","以后","再也","不","迟到了"],"dap":["我以后再也不迟到了。"],"goiY":"Từ nay tôi sẽ không bao giờ đến muộn nữa.","giai":"以后 + 再也不 + V + 了."},{"kieu":"xep","manh":["毕业以后","，","我们","就","再也没","见过面"],"dap":["毕业以后，我们就再也没见过面。"],"goiY":"Từ khi tốt nghiệp, chúng tôi không gặp lại nhau nữa.","giai":"Mốc thời gian + 就 + 再也没 + V过."},{"kieu":"xep","manh":["搬家以后","，","他","再也没","去过","那个公园"],"dap":["搬家以后，他再也没去过那个公园。"],"goiY":"Từ khi chuyển nhà, anh ấy không đến công viên đó nữa.","giai":"再也没 + V过 + O."},{"kieu":"dungsai","cau":"我保证，以后再也没熬夜了。","dung":false,"sua":"我保证，以后再也不熬夜了。","giai":"Lời hứa về tương lai → 再也不."},{"kieu":"dungsai","cau":"出国以后，我就再也没给他打过电话。","dung":true,"giai":"Đúng: kể việc từ quá khứ đến nay → 再也没……过."},{"kieu":"dungsai","cau":"你放心，我不再也玩游戏了。","dung":false,"sua":"你放心，我再也不玩游戏了。","giai":"Thứ tự đúng: 再也 + 不."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 52)","huongDan":"Hoàn thành câu của B, có dùng 再也不 / 再也没","cau":[{"kieu":"vandung","de":"A：你和小王还有联系吗？ B：毕业以后，＿＿。","goiY":"Kể: từ khi tốt nghiệp đến giờ không liên lạc / không gặp lại nữa (再也没……过)","mau":"我们就再也没联系过","can":[["再也没"]]},{"kieu":"vandung","de":"A：你以后千万要注意保护好眼睛。 B：知道了，我以后＿＿。","goiY":"Hứa: từ nay sẽ không bao giờ nằm xem điện thoại / đọc sách chỗ tối nữa (再也不……)","mau":"再也不躺在床上看手机了","can":[["再也不"]]},{"kieu":"vandung","de":"A：你还常去太阳公园散步吗？ B：搬家以后离公园太远了，＿＿。","goiY":"Kể: từ khi chuyển nhà đến nay không đến đó tản bộ nữa (再也没……过)","mau":"我就再也没去那儿散过步","can":[["再也没"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Từ khi tốt nghiệp, tôi không gặp lại cô ấy nữa.","dap":["毕业以后，我就再也没见过她。","毕业以后，我再也没见过她。","毕业以后，我就再也没见过她了。"],"giai":"Quá khứ → nay: 再也没 + V过."},{"kieu":"dich","vn":"Xin lỗi, từ nay em sẽ không bao giờ đến muộn nữa.","dap":["对不起，我以后再也不迟到了。","对不起，以后我再也不迟到了。"],"giai":"Lời hứa: 以后再也不……了."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một việc em quyết tâm không bao giờ làm nữa, hoặc một người / một nơi từ đó em không gặp / không đến nữa — dùng 「再也不」 hoặc 「再也没」","mau":"那次感冒以后，我冬天再也不穿那么少出门了。","can":[["再也不","再也没"]]}]}]},{"so":"2","ten":"介词“由”","tenVn":"Giới từ 「由」 — do (ai) làm, do (ai) phụ trách","cauTruc":["(Sự việc) + 由 + người / đơn vị + (来) + động từ","(Sự việc) + 是 + 由 + người / đơn vị + (来) + động từ + 的"],"giaiThich":"Trong bài này, 「由」 dẫn ra NGƯỜI THỰC HIỆN hành động: việc này DO ai làm / phụ trách. Sự việc thường đứng đầu câu làm chủ đề, sau đó là 由 + người + (来) + động từ. Hay đi với động từ chỉ trách nhiệm, công việc: 负责, 安排, 决定, 举办, 完成, 准备, 解决, 面试. Muốn nhấn mạnh người làm thì dùng khung 「是由……(来)……的」. Mẹo cho người Việt: “do” trong “do ai làm” = 由; còn “do / vì” chỉ nguyên nhân = 由于 (Bài 2 · điểm 4) — đừng nhầm. Khác 被: 被 nhấn mạnh chủ ngữ BỊ tác động (thường không như ý), còn 由 nhấn mạnh TRÁCH NHIỆM thuộc về ai. Sau 由 + người bắt buộc phải có động từ.","viDu":[{"zh":"那天是由部门负责人来面试的，我有点儿紧张。","py":"Nàtiān shì yóu bùmén fùzérén lái miànshì de, wǒ yǒudiǎnr jǐnzhāng.","vn":"Hôm đó là người phụ trách bộ phận phỏng vấn, tôi hơi căng thẳng."},{"zh":"这个问题究竟由谁来负责解决？","py":"Zhège wèntí jiūjìng yóu shuí lái fùzé jiějué?","vn":"Vấn đề này rốt cuộc do ai phụ trách giải quyết?"},{"zh":"这次活动是由他们公司来安排的。","py":"Zhè cì huódòng shì yóu tāmen gōngsī lái ānpái de.","vn":"Hoạt động lần này do công ty họ sắp xếp."},{"zh":"作为班长，这次晚会由我来安排。","py":"Zuòwéi bānzhǎng, zhè cì wǎnhuì yóu wǒ lái ānpái.","vn":"Với tư cách lớp trưởng, buổi liên hoan lần này do tôi sắp xếp. (ôn 作为 — Bài 13)"}],"loi":[{"sai":"这个问题由于谁来解决？","why":"由于 chỉ nguyên nhân; dẫn ra người làm phải dùng 由.","dung":"这个问题由谁来解决？"},{"sai":"这次活动是由他们公司安排。","why":"Đã dùng khung 是由…… thì cuối câu cần 的.","dung":"这次活动是由他们公司（来）安排的。"},{"sai":"面试由部门负责人。","why":"Sau 由 + người phải có động từ.","dung":"面试由部门负责人来做。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["那天是","部门负责人来面试的。"],"dap":[["由"]],"chon":["由","由于","被"],"goiY":"“Hôm đó do người phụ trách bộ phận phỏng vấn.”","giai":"由 + người + 来 + V."},{"kieu":"dien","phan":["这个问题究竟由谁来","解决？"],"dap":[["负责"]],"chon":["负责","负责人","部门"],"goiY":"“Vấn đề này rốt cuộc do ai phụ trách giải quyết?”","giai":"负责 là động từ; 负责人 là danh từ."},{"kieu":"dien","phan":["这次活动是由他们公司来安排","。"],"dap":[["的"]],"chon":["的","了","着"],"goiY":"“Hoạt động lần này do công ty họ sắp xếp.”","giai":"Khung 是由……的."},{"kieu":"dien","phan":["","天气不好，比赛推迟了。"],"dap":[["由于"]],"chon":["由于","由","被"],"goiY":"“Do thời tiết xấu, trận đấu bị hoãn.” (phân biệt với 由)","giai":"Nguyên nhân → 由于 (Bài 2); người làm → 由."},{"kieu":"dien","phan":["这件事由我","负责吧。"],"dap":[["来"]],"chon":["来","去","在"],"goiY":"“Việc này để tôi phụ trách nhé.”","giai":"由 + người + 来 + V."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这次活动","由","学校","来","举办"],"dap":["这次活动由学校来举办。"],"goiY":"Hoạt động lần này do trường tổ chức.","giai":"Sự việc + 由 + đơn vị + 来 + V."},{"kieu":"xep","manh":["面试","是","由","部门负责人","来","做","的"],"dap":["面试是由部门负责人来做的。"],"goiY":"Phỏng vấn là do người phụ trách bộ phận làm.","giai":"是由……来……的."},{"kieu":"xep","manh":["今天的","晚饭","由","我","来","做","吧"],"dap":["今天的晚饭由我来做吧。"],"goiY":"Bữa tối hôm nay để tôi nấu nhé.","giai":"由 + 我 + 来 + V."},{"kieu":"dungsai","cau":"这个工作是由小王一个人完成的。","dung":true,"giai":"Đúng: 是由 + người + V + 的."},{"kieu":"dungsai","cau":"由于你来负责这件事吧。","dung":false,"sua":"由你来负责这件事吧。","giai":"Chỉ người phụ trách → 由, không phải 由于."},{"kieu":"dungsai","cau":"这期交流活动是由学生会举办。","dung":false,"sua":"这期交流活动是由学生会举办的。","giai":"Khung 是由…… cần 的 ở cuối."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 54)","huongDan":"Viết câu trả lời của B, có dùng 由","cau":[{"kieu":"vandung","de":"A：这个工作是谁完成的？ B：＿＿。","goiY":"Trả lời việc này do ai hoàn thành (是由……完成的)","mau":"这个工作是由我们部门的同事一起完成的","can":[["由"]]},{"kieu":"vandung","de":"A：这些节目是谁准备的？ B：＿＿。","goiY":"Trả lời các tiết mục do ai chuẩn bị (是由……准备的)","mau":"这些节目是由留学生们自己准备的","can":[["由"]]},{"kieu":"vandung","de":"A：这期交流活动是谁举办的？ B：＿＿。","goiY":"Trả lời hoạt động giao lưu kỳ này do ai tổ chức (是由……举办的)","mau":"这期交流活动是由学校的留学生办公室举办的","can":[["由"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bữa tối hôm nay do tôi nấu.","dap":["今天的晚饭由我来做。","今天的晚饭由我做。","今天晚饭由我来做。"],"giai":"由 + người + (来) + V."},{"kieu":"dich","vn":"Hoạt động lần này do nhà trường tổ chức.","dap":["这次活动是由学校举办的。","这次活动由学校举办。","这次活动是由学校来举办的。","这次活动由学校来举办。"],"giai":"(是)由……(来)举办(的)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể cách phân công việc trong nhà / trong lớp em, có dùng 「由……来……」","mau":"在我们家，做饭由妈妈来负责，打扫房间由我和弟弟来负责。","can":[["由"]]}]}]},{"so":"3","ten":"“把”字句“主语+把+宾语+动词（+一/了）+动词”","tenVn":"Câu chữ 「把」 với động từ lặp lại — làm (qua / thử) một chút","cauTruc":["Chủ ngữ + 把 + tân ngữ + VV / V一V → việc chưa làm: đề nghị, dự định","Chủ ngữ + 把 + tân ngữ + V了V → việc đã làm","Động từ hai âm tiết: 把 + tân ngữ + ABAB (检查检查, 复习复习)"],"giaiThich":"Ở HSK 3 em đã học: trong câu 「把」, động từ không được đứng trơ trọi, phía sau phải có thành phần khác (了, bổ ngữ…). Bài này thêm một cách: LẶP LẠI động từ — VV, V一V, V了V — để diễn tả hành động diễn ra trong thời gian NGẮN, mức độ NHẸ (làm qua, làm một chút, thử). Dùng V一V / VV cho việc CHƯA làm: lời đề nghị, dự định (你先把作业检查检查). Dùng V了V cho việc ĐÃ làm (他把头发理了理). Động từ hai âm tiết chỉ lặp kiểu ABAB, không chen 一: 复习复习 ✓, ✗ 复习一复习. Động từ ly hợp như 理发 thì tách ra: 把头发理了理 (理 là động từ, 头发 là tân ngữ). Mẹo cho người Việt: tiếng Việt hay thêm “một chút / qua / thử” — gặp ý này trong câu có 把 thì nghĩ ngay đến động từ lặp.","viDu":[{"zh":"他去理发店把头发理了理。","py":"Tā qù lǐfàdiàn bǎ tóufa lǐ le lǐ.","vn":"Cậu ấy ra tiệm cắt tóc sửa lại tóc một chút."},{"zh":"你先把作业检查检查，然后再交给老师。","py":"Nǐ xiān bǎ zuòyè jiǎnchá jiǎnchá, ránhòu zài jiāogěi lǎoshī.","vn":"Em kiểm tra bài tập một lượt trước, rồi hãy nộp cho thầy."},{"zh":"上课前，我把今天要学习的内容看了看。","py":"Shàngkè qián, wǒ bǎ jīntiān yào xuéxí de nèiróng kàn le kàn.","vn":"Trước giờ học, tôi đã xem qua nội dung hôm nay sẽ học."},{"zh":"首先把房间打扫打扫，然后再请大家进来。","py":"Shǒuxiān bǎ fángjiān dǎsǎo dǎsǎo, ránhòu zài qǐng dàjiā jìnlai.","vn":"Trước hết dọn phòng một chút, sau đó mới mời mọi người vào. (ôn 首先……然后…… — Bài 14)"}],"loi":[{"sai":"我把作业检查。","why":"Sau động từ trong câu 把 phải có thành phần khác — ở đây lặp động từ.","dung":"我把作业检查检查。"},{"sai":"你先把课文复习一复习。","why":"Động từ hai âm tiết lặp ABAB, không chen 一.","dung":"你先把课文复习复习。"},{"sai":"昨天我把衣服洗一洗。","why":"Việc đã xảy ra (昨天) dùng V了V.","dung":"昨天我把衣服洗了洗。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["他去理发店把头发","了理。"],"dap":[["理"]],"chon":["理","剪","洗"],"goiY":"“Cậu ấy ra tiệm sửa lại tóc một chút.”","giai":"V了V: 理了理 — hai động từ phải giống nhau."},{"kieu":"dien","phan":["你先把作业","，然后再交给老师。"],"dap":[["检查检查"]],"chon":["检查检查","检查一检查","检查"],"goiY":"“Em kiểm tra bài tập một lượt trước …”","giai":"Động từ hai âm tiết: ABAB; ✗ 检查一检查; 把 + O không thể chỉ có 检查."},{"kieu":"dien","phan":["上课前，我把今天要学习的内容看","看。"],"dap":[["了"]],"chon":["了","着","过"],"goiY":"“Trước giờ học, tôi đã xem qua nội dung hôm nay.” (việc đã làm)","giai":"Việc đã làm → V了V."},{"kieu":"dien","phan":["面试前，他打算在镜子前把自我介绍练","练。"],"dap":[["一"]],"chon":["一","了","过"],"goiY":"“Trước phỏng vấn, anh ấy định tập phần tự giới thiệu một chút.” (dự định)","giai":"打算 → việc chưa làm → V一V."},{"kieu":"dien","phan":["你","这件事好好想想，再告诉我吧。"],"dap":[["把"]],"chon":["把","被","给"],"goiY":"“Bạn nghĩ kỹ việc này rồi hãy nói cho tôi.”","giai":"把 + O + VV."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你","把","衣服","洗","一","洗","吧"],"dap":["你把衣服洗一洗吧。"],"goiY":"Bạn giặt quần áo một chút đi.","giai":"Đề nghị: 把 + O + V一V + 吧."},{"kieu":"xep","manh":["我","去","把","房间","打扫打扫"],"dap":["我去把房间打扫打扫。"],"goiY":"Tôi đi dọn phòng một chút.","giai":"Hai âm tiết: ABAB."},{"kieu":"xep","manh":["她","把","老师的话","想了想","，","点了点头"],"dap":["她把老师的话想了想，点了点头。"],"goiY":"Cô ấy nghĩ một chút về lời thầy nói rồi gật đầu.","giai":"Việc đã làm: 把 + O + V了V."},{"kieu":"dungsai","cau":"你先把课文复习一复习。","dung":false,"sua":"你先把课文复习复习。","giai":"Động từ hai âm tiết lặp ABAB, không chen 一."},{"kieu":"dungsai","cau":"他把头发理了理，又买了一身新衣服。","dung":true,"giai":"Đúng: việc đã làm → V了V."},{"kieu":"dungsai","cau":"我把这本书看。","dung":false,"sua":"我把这本书看了看。","giai":"Động từ sau 把 không được đứng một mình (có thể sửa: 看了看 / 看一看 / 看完了)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 56)","huongDan":"Hoàn thành câu bằng câu chữ 把 với động từ lặp, dùng từ trong ngoặc","cau":[{"kieu":"vandung","de":"我＿＿，也说出了自己的看法。（想）","goiY":"Dùng 「想」: việc đã làm (đã nghĩ một chút về vấn đề) → 把……想了想","mau":"把这个问题想了想","can":[["把"],["想了想"]]},{"kieu":"vandung","de":"看到办公室有点儿脏，他打算＿＿。（扫）","goiY":"Dùng 「扫」: dự định quét văn phòng một chút → 把……扫一扫 / 扫扫","mau":"把办公室扫一扫","can":[["把"],["扫一扫","扫扫"]]},{"kieu":"vandung","de":"我建议你每次先＿＿，然后再开始写作业。（复习）","goiY":"Dùng 「复习」: lời khuyên ôn lại bài một chút → 把……复习复习","mau":"把学过的内容复习复习","can":[["把"],["复习复习"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Em sửa bài văn này một chút rồi hãy nộp cho thầy.","dap":["你把这篇作文改一改，再交给老师。","你把这篇作文改改，再交给老师。","你先把这篇作文改一改，然后再交给老师。","你把这篇作文改一改，然后再交给老师。"],"giai":"Đề nghị → 把 + O + V一V / VV."},{"kieu":"dich","vn":"Anh ấy xem qua tin nhắn một chút rồi cười.","dap":["他把短信看了看，笑了。","他把短信看了看，就笑了。"],"giai":"Việc đã làm → V了V; ôn từ mới 短信."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể em đã / sẽ chuẩn bị gì trước một buổi phỏng vấn hoặc kỳ thi, dùng 「把……V了V」 hoặc 「把……V一V」","mau":"考试前一天，我把生词看了看，又把书上的练习做了做。","can":[["把"]]}]}]},{"so":"4","ten":"比较句“A不如B（+形容词）”","tenVn":"Câu so sánh 「A 不如 B (+ tính từ)」 — A không bằng B","cauTruc":["A + 不如 + B → A không bằng B (B tốt hơn)","A + 不如 + B + tính từ → về mặt này A kém B","A (cách làm này) + 不如 + B (cách làm khác) → làm A chẳng bằng làm B"],"giaiThich":"「A不如B」 nghĩa là A KHÔNG BẰNG B, tức B tốt hơn. Nếu cuối câu có tính từ thì so sánh ở MỘT MẶT cụ thể: 这家店不如那家店环境好 = cửa hàng này môi trường không tốt bằng cửa hàng kia. Tính từ sau 不如 thường mang nghĩa tích cực (好, 方便, 便宜, 舒服, 干净…). A và B có thể là người, vật, hoặc cả một hành động: 在课本上学不如自己做一遍. Khác câu 比: không thêm 很, 非常, 多了, 一点儿 sau tính từ (✗ 不如他高多了). Gần nghĩa với 「A没有B + tính từ」, nhưng 不如 thiên về đánh giá A kém hơn. Mẹo cho người Việt: “không bằng”, “chẳng bằng”, “thua” → 不如; tính từ đặt CUỐI câu, sau B.","viDu":[{"zh":"有些事情，在课本上学不如自己做一遍。","py":"Yǒuxiē shìqing, zài kèběn shàngxué bùrú zìjǐ zuò yí biàn.","vn":"Có những việc, học trên sách không bằng tự mình làm một lần."},{"zh":"这家店不如那家店环境好。","py":"Zhè jiā diàn bùrú nà jiā diàn huánjìng hǎo.","vn":"Cửa hàng này môi trường không tốt bằng cửa hàng kia."},{"zh":"我觉得坐公交不如坐地铁方便。","py":"Wǒ juéde zuò gōngjiāo bùrú zuò dìtiě fāngbiàn.","vn":"Tôi thấy đi xe buýt không tiện bằng đi tàu điện ngầm."},{"zh":"对于我来说，坐飞机不如坐高铁舒服。","py":"Duìyú wǒ láishuō, zuò fēijī bùrú zuò gāotiě shūfu.","vn":"Đối với tôi, đi máy bay không thoải mái bằng đi tàu cao tốc. (ôn 对于……来说 — Bài 14)"}],"loi":[{"sai":"这家店不如那家店很好。","why":"Tính từ sau 不如 + B không thêm 很.","dung":"这家店不如那家店好。"},{"sai":"我的中文不如他好多了。","why":"不如 không đi với 多了 / 一点儿 như câu 比.","dung":"我的中文不如他好。 / 他的中文比我好多了。"},{"sai":"坐公交不如方便坐地铁。","why":"Tính từ đứng sau B, ở cuối câu.","dung":"坐公交不如坐地铁方便。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["有些事情，在课本上学","自己做一遍。"],"dap":[["不如"]],"chon":["不如","比","没"],"goiY":"“Học trên sách không bằng tự làm một lần.”","giai":"A不如B."},{"kieu":"dien","phan":["这家店不如那家店环境","。"],"dap":[["好"]],"chon":["好","很好","好多了"],"goiY":"“Cửa hàng này môi trường không tốt bằng cửa hàng kia.”","giai":"不如 + B + Adj (không thêm 很 / 多了)."},{"kieu":"dien","phan":["坐公交要换两次车，我觉得坐公交不如坐地铁","。"],"dap":[["方便"]],"chon":["方便","不方便","更方便"],"goiY":"“… không tiện bằng đi tàu điện ngầm.”","giai":"Tính từ tích cực, không thêm 更 / 不."},{"kieu":"dien","phan":["今年冬天","去年冷。"],"dap":[["不如"]],"chon":["不如","比","跟"],"goiY":"“Mùa đông năm nay không lạnh bằng năm ngoái.”","giai":"A不如B + Adj."},{"kieu":"dien","phan":["一个人去不如跟大家一起去，","安全又开心。"],"dap":[["既"]],"chon":["既","又","也"],"goiY":"“… vừa an toàn vừa vui.” (ôn Bài 4)","giai":"既……又……"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这家店","不如","那家店","环境","好"],"dap":["这家店不如那家店环境好。"],"goiY":"Cửa hàng này môi trường không tốt bằng cửa hàng kia.","giai":"A + 不如 + B + (mặt so sánh) + Adj."},{"kieu":"xep","manh":["我","觉得","坐公交","不如","坐地铁","方便"],"dap":["我觉得坐公交不如坐地铁方便。"],"goiY":"Tôi thấy đi xe buýt không tiện bằng tàu điện ngầm.","giai":"A, B là hành động."},{"kieu":"xep","manh":["在家","看书","不如","去图书馆","看"],"dap":["在家看书不如去图书馆看。"],"goiY":"Đọc sách ở nhà chẳng bằng lên thư viện đọc.","giai":"A不如B (không có tính từ)."},{"kieu":"dungsai","cau":"我唱歌不如她唱得好。","dung":true,"giai":"Đúng: A不如B + V得 + Adj."},{"kieu":"dungsai","cau":"这件衣服不如那件很漂亮。","dung":false,"sua":"这件衣服不如那件漂亮。","giai":"Không thêm 很 trước tính từ."},{"kieu":"dungsai","cau":"坐出租车不如便宜坐地铁。","dung":false,"sua":"坐出租车不如坐地铁便宜。","giai":"Tính từ đặt sau B."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 58)","huongDan":"Hoàn thành câu, dùng 不如","cau":[{"kieu":"vandung","de":"你多走走吧，坐车＿＿。","goiY":"Ngồi xe không tốt cho sức khỏe bằng đi bộ (不如……好)","mau":"不如走路对身体好","can":[["不如"]]},{"kieu":"vandung","de":"不知道怎么解决问题时，自己想＿＿。","goiY":"Tự nghĩ chẳng bằng đi hỏi người khác (不如问问……)","mau":"不如问问老师和同学","can":[["不如"]]},{"kieu":"vandung","de":"我更愿意在家做饭，因为在外面吃饭＿＿。","goiY":"Ăn ngoài không sạch / rẻ / tốt cho sức khỏe bằng ăn ở nhà (不如……)","mau":"不如在家吃健康、便宜","can":[["不如"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tiếng Trung của tôi không tốt bằng chị tôi.","dap":["我的中文不如我姐姐好。","我的中文不如姐姐好。","我的中文不如我姐姐的好。","我的中文不如姐姐的好。"],"giai":"A不如B + Adj."},{"kieu":"dich","vn":"Mua ở cửa hàng không rẻ bằng mua trên mạng.","dap":["在商店买不如在网上买便宜。","在商店买东西不如在网上买便宜。"],"giai":"A, B là hành động; tính từ cuối câu."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"So sánh hai thành phố / hai cách đi lại / hai món ăn em biết, dùng 「A不如B + tính từ」","mau":"我觉得河内的夏天不如大叻的夏天凉快，可是河内比大叻热闹多了。","can":[["不如"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-16.html"] = [{"so":"1","ten":"“把”字句“主语+把+宾语+动词+了”","tenVn":"Câu chữ 「把」: Chủ ngữ + 把 + tân ngữ + động từ + 了 — xử lý xong một người / vật xác định","cauTruc":["Chủ ngữ + 把 + tân ngữ (xác định) + động từ + 了","Chủ ngữ + 已经 / 没 / 别忘了 / 快 + 把 + tân ngữ + động từ (+ 了)","Câu đề nghị: (你 +) 把 + tân ngữ + động từ + 了 + 吧"],"giaiThich":"Câu chữ 「把」 dạng này diễn tả: chủ ngữ XỬ LÝ một người / vật XÁC ĐỊNH (cả hai bên đều biết là cái nào) và việc xử lý đã có KẾT QUẢ — 了 ở cuối cho biết việc đã xong. Hay gặp với các động từ mang nghĩa “làm cho mất đi, làm xong”: 取消 (hủy), 关 (tắt), 吃, 喝, 卖, 还 (trả), 洗, 改, 扔…: 我已经把机票和酒店取消了 (vé và khách sạn ĐÃ bị hủy). Tiếng Việt thường nói “Tôi hủy vé rồi”, nhưng tiếng Trung dùng 把 để nhấn mạnh “đem cái vé ấy đi hủy”. Quy tắc nhớ: (1) tân ngữ của 把 phải xác định — 这 / 那 / 我的… hoặc đã nhắc tới, không dùng ✗一本书; (2) động từ không đứng trơ trọi, phải có 了 (hoặc thành phần khác); (3) 已经 / 没 / 别 / 要 / 快 đặt TRƯỚC 把 (✓ 我没把机票取消 — câu phủ định 没 thì bỏ 了); (4) các động từ không có tác động như 是, 有, 知道, 喜欢, 觉得, 来, 去 không dùng trong câu 把. Câu đề nghị 「你把灯关了吧」 rất hay dùng trong đời sống. Ôn lại: Bài 15 · điểm 3 học 把 + O + V(一/了)V (làm thử, làm nhẹ nhàng: 把房间收拾收拾); HSK 3 học 把 + O + V + 好 / 完 / 在 / 给…. Bài này: 把 + O + V + 了 — việc đã hoàn tất.","viDu":[{"zh":"我已经把机票和酒店取消了。","py":"Wǒ yǐjīng bǎ jīpiào hé jiǔdiàn qǔxiāo le.","vn":"Tôi đã hủy vé máy bay và khách sạn rồi."},{"zh":"你把灯关了吧，我想睡觉了。","py":"Nǐ bǎ dēng guān le ba, wǒ xiǎng shuìjiào le.","vn":"Bạn tắt đèn đi, tôi muốn ngủ rồi."},{"zh":"你别忘了把衣服洗了，明天还得穿呢。","py":"Nǐ bié wàng le bǎ yīfu xǐ le, míngtiān hái děi chuān ne.","vn":"Bạn đừng quên giặt quần áo nhé, ngày mai còn phải mặc đấy."},{"zh":"下雨了，快把窗户关了，否则房间里会进水的。","py":"Xiàyǔ le, kuài bǎ chuānghu guān le, fǒuzé fángjiān lǐ huì jìn shuǐ de.","vn":"Mưa rồi, mau đóng cửa sổ lại, nếu không nước sẽ vào phòng đấy. (ôn 否则 – Bài 8 · điểm 2)"}],"loi":[{"sai":"我已经取消把机票了。","why":"把 + tân ngữ phải đứng TRƯỚC động từ.","dung":"我已经把机票取消了。"},{"sai":"我把一本书还了。","why":"Tân ngữ của 把 phải xác định (quyển sách đã biết), không dùng 一本 không xác định.","dung":"我把那本书还了。"},{"sai":"我把机票没取消。","why":"Phủ định 没 / 别 đặt TRƯỚC 把; câu phủ định với 没 thì bỏ 了.","dung":"我没把机票取消。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["我已经","机票和酒店取消了。"],"dap":[["把"]],"chon":["把","被","给"],"goiY":"“Tôi đã hủy vé máy bay và khách sạn rồi.”","giai":"Chủ ngữ + 已经 + 把 + O + V + 了."},{"kieu":"dien","phan":["你把灯","了吧，我想睡觉了。"],"dap":[["关"]],"chon":["关","放","看"],"goiY":"“Bạn tắt đèn đi, tôi muốn ngủ rồi.”","giai":"把灯关了 = tắt đèn đi."},{"kieu":"dien","phan":["你别忘了把衣服洗","，明天还得穿呢。"],"dap":[["了"]],"chon":["了","过","着"],"goiY":"“Đừng quên giặt quần áo nhé, mai còn phải mặc.”","giai":"把 + O + V + 了: việc phải làm xong."},{"kieu":"dien","phan":["快把药","了，这样你才能快点儿好。"],"dap":[["吃"]],"chon":["吃","做","打"],"goiY":"“Mau uống thuốc đi, như vậy bạn mới mau khỏi.”","giai":"Tiếng Trung nói 吃药 (✗ 喝药)."},{"kieu":"dien","phan":["下雨了，快把窗户关了，","房间里会进水的。"],"dap":[["否则"]],"chon":["否则","于是","并且"],"goiY":"“… nếu không nước sẽ vào phòng.” (ôn 否则 – Bài 8)","giai":"……，否则…… = nếu không thì …"}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","已经","把","机票和酒店","取消","了"],"dap":["我已经把机票和酒店取消了。"],"goiY":"Tôi đã hủy vé máy bay và khách sạn rồi.","giai":"已经 đứng trước 把."},{"kieu":"xep","manh":["你","把","灯","关","了","吧"],"dap":["你把灯关了吧。"],"goiY":"Bạn tắt đèn đi.","giai":"Câu đề nghị: 把 + O + V + 了 + 吧."},{"kieu":"xep","manh":["别忘了","把","借的书","还","了"],"dap":["别忘了把借的书还了。"],"goiY":"Đừng quên trả sách đã mượn nhé.","giai":"别忘了 + 把 + O + V + 了."},{"kieu":"dungsai","cau":"你快把这些水果吃了吧，放久了就不新鲜了。","dung":true,"giai":"Đúng: 这些水果 xác định, V + 了."},{"kieu":"dungsai","cau":"我把一杯咖啡喝了。","dung":false,"sua":"我把那杯咖啡喝了。","giai":"Tân ngữ của 把 phải xác định."},{"kieu":"dungsai","cau":"我把机票没取消。","dung":false,"sua":"我没把机票取消。","giai":"没 đặt trước 把."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 64)","huongDan":"Hoàn thành đối thoại, dùng câu chữ 「把」: Chủ ngữ + 把 + tân ngữ + động từ + 了","cau":[{"kieu":"vandung","de":"A：＿＿＿。 B：好，我也觉得房间里挺热的。","goiY":"A đề nghị: phòng nóng quá, mình bật điều hòa lên đi (把……开了)","mau":"房间里太热了，咱们把空调开了吧","can":[["把"],["了"]]},{"kieu":"vandung","de":"A：＿＿＿。 B：放心吧，我一会儿就去图书馆。","goiY":"A nhắc: đừng quên trả sách đã mượn ở thư viện (把……还了)","mau":"你别忘了把借的书还了","can":[["把"],["还了"]]},{"kieu":"vandung","de":"A：快＿＿＿，这样你才能快点儿好。 B：好的，吃完药我再睡一觉。","goiY":"A giục: mau uống thuốc đi (把……吃了)","mau":"把药吃了","can":[["把"],["吃了"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tôi đã hủy vé máy bay và khách sạn rồi.","dap":["我已经把机票和酒店取消了。","我已经把飞机票和酒店取消了。"],"giai":"已经 + 把 + O + 取消了."},{"kieu":"dich","vn":"Kế hoạch thay đổi rồi, bạn hủy khách sạn đã đặt đi.","dap":["计划变了，你把订好的酒店取消了吧。","计划有变化，你把订好的酒店取消了吧。","计划变了，你把订的酒店取消了吧。"],"giai":"Câu đề nghị 把……取消了吧."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Trước khi ra khỏi nhà, mẹ dặn em mấy việc. Viết một câu dặn dò có 「把……了」","mau":"出门前别忘了把灯关了，把垃圾扔了。","can":[["把"],["了"]]}]}]},{"so":"2","ten":"递进复句“……，并且……”","tenVn":"Câu phức tăng tiến 「……，并且……」 — …, hơn nữa / đồng thời …","cauTruc":["Vế 1 (hành động / tình huống)，并且 + vế 2 (bổ sung, tiến thêm một bước)","Chủ ngữ + V1……，并且 + V2……","Chủ ngữ + Adj1，并且 + Adj2 / ……，并且 + (chủ ngữ 2) + 也 / 还……"],"giaiThich":"「并且」 là liên từ nối hai động tác hoặc hai tình huống; vế sau BỔ SUNG, nói tiến thêm một bước so với vế trước — giống tiếng Việt “và, hơn nữa, đồng thời, lại còn”. 并且 đứng ở ĐẦU vế sau (trước vị ngữ thứ hai); nếu vế sau có chủ ngữ mới thì 并且 đứng trước chủ ngữ đó: ……，并且生活方式也发生了很大的变化. Vế sau hay có 也 / 还 đi kèm. Phân biệt: (1) 和 nối DANH TỪ (苹果和香蕉), còn 并且 nối động từ / vế câu — người Việt hay dịch “và” thành 并且 giữa hai danh từ là sai; (2) 而且 (不但……而且…… – HSK 3) rất gần nghĩa, nhưng 并且 trang trọng hơn và hay nối các HÀNH ĐỘNG nối tiếp nhau (检查……并且增加……); (3) 并 (Bài 2 · điểm 3) là dạng rút gọn văn viết của 并且, nối trực tiếp hai động từ: 讨论并通过了. Mẹo: thấy vế sau là “làm thêm một việc nữa / thêm một ưu điểm nữa” → dùng 并且.","viDu":[{"zh":"再检查一下有没有细节上的错误，并且试着增加一些例子。","py":"Zài jiǎnchá yíxià yǒu méiyǒu xìjié shàng de cuòwù, bìngqiě shì zhe zēngjiā yìxiē lìzi.","vn":"Kiểm tra lại xem có lỗi ở chi tiết không, đồng thời thử thêm một vài ví dụ."},{"zh":"他按时完成了任务，并且做得很好。","py":"Tā ànshí wánchéng le rènwu, bìngqiě zuò de hěn hǎo.","vn":"Anh ấy đã hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt."},{"zh":"人们的生活水平提高了，并且生活方式也发生了很大的变化。","py":"Rénmen de shēnghuó shuǐpíng tígāo le, bìngqiě shēnghuó fāngshì yě fāshēng le hěn dà de biànhuà.","vn":"Mức sống của mọi người đã được nâng cao, đồng thời lối sống cũng đã thay đổi rất lớn."},{"zh":"随着经济的发展，人们的收入增加了，并且生活也越来越方便了。","py":"Suízhe jīngjì de fāzhǎn, rénmen de shōurù zēngjiā le, bìngqiě shēnghuó yě yuèláiyuè fāngbiàn le.","vn":"Cùng với sự phát triển của kinh tế, thu nhập của mọi người tăng lên, hơn nữa cuộc sống cũng ngày càng tiện lợi. (ôn 随着 – Bài 1 · điểm 3)"}],"loi":[{"sai":"我买了苹果并且香蕉。","why":"并且 không nối hai danh từ — nối danh từ dùng 和.","dung":"我买了苹果和香蕉。"},{"sai":"他按时完成了任务，做得并且很好。","why":"并且 đứng ĐẦU vế sau, không chen vào giữa động từ và bổ ngữ.","dung":"他按时完成了任务，并且做得很好。"},{"sai":"并且再检查一下有没有错误，试着增加一些例子。","why":"并且 nối vế SAU với vế trước — không đặt ở đầu vế thứ nhất.","dung":"再检查一下有没有错误，并且试着增加一些例子。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["再检查一下有没有细节上的错误，","试着增加一些例子。"],"dap":[["并且"]],"chon":["并且","但是","所以"],"goiY":"“… đồng thời thử thêm một vài ví dụ.”","giai":"Vế sau là hành động bổ sung → 并且."},{"kieu":"dien","phan":["人们的生活水平提高了，并且生活方式也发生了很大的","。"],"dap":[["变化"]],"chon":["变化","例子","错误"],"goiY":"“… đồng thời lối sống cũng đã thay đổi rất lớn.”","giai":"发生变化 = xảy ra thay đổi."},{"kieu":"dien","phan":["他按时完成了任务，","做得很好。"],"dap":[["并且"]],"chon":["并且","和","跟"],"goiY":"“Anh ấy hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.”","giai":"和 / 跟 nối danh từ; nối hai vế dùng 并且."},{"kieu":"dien","phan":["会议时间改了，并且还","了一些新的内容。"],"dap":[["增加"]],"chon":["增加","推迟","取消"],"goiY":"“Thời gian họp đổi rồi, hơn nữa còn thêm một số nội dung mới.”","giai":"增加 + 内容."},{"kieu":"dien","phan":["","你已经决定了，就把计划写得详细一些，并且严格按照计划去做。"],"dap":[["既然"]],"chon":["既然","即使","虽然"],"goiY":"“Đã quyết định rồi thì viết kế hoạch chi tiết một chút, và làm nghiêm túc theo kế hoạch.” (ôn 既然 – Bài 7)","giai":"既然……，就…… (Bài 7 · điểm 2)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","按时","完成了任务","，","并且","做得很好"],"dap":["他按时完成了任务，并且做得很好。"],"goiY":"Anh ấy hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.","giai":"并且 đứng đầu vế sau."},{"kieu":"xep","manh":["人们的生活水平","提高了","，","并且","生活方式","也发生了很大的变化"],"dap":["人们的生活水平提高了，并且生活方式也发生了很大的变化。"],"goiY":"Mức sống được nâng cao, đồng thời lối sống cũng thay đổi rất lớn.","giai":"Vế sau có chủ ngữ mới → 并且 + chủ ngữ + 也……"},{"kieu":"xep","manh":["你","再检查一下","材料","，","并且","试着","增加一些例子"],"dap":["你再检查一下材料，并且试着增加一些例子。"],"goiY":"Bạn kiểm tra lại tài liệu, đồng thời thử thêm một vài ví dụ.","giai":"Hai hành động nối tiếp: V1……，并且 + V2……"},{"kieu":"dungsai","cau":"小王工作很认真，并且对人很热情。","dung":true,"giai":"Đúng: hai ưu điểm, vế sau bổ sung."},{"kieu":"dungsai","cau":"我买了苹果并且香蕉。","dung":false,"sua":"我买了苹果和香蕉。","giai":"Nối hai danh từ dùng 和."},{"kieu":"dungsai","cau":"他按时完成了任务，做得并且很好。","dung":false,"sua":"他按时完成了任务，并且做得很好。","giai":"并且 đứng đầu vế sau."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 66)","huongDan":"Hoàn thành đối thoại, có dùng 「……，并且……」","cau":[{"kieu":"vandung","de":"A：你觉得小王这个人怎么样？ B：＿＿＿。","goiY":"Khen hai mặt: làm việc nghiêm túc + đối xử với mọi người nhiệt tình","mau":"他工作很认真，并且对人很热情","can":[["并且"]]},{"kieu":"vandung","de":"A：为什么你建议我看这本书？ B：＿＿＿。","goiY":"Nêu hai lý do: nội dung thú vị + có nhiều ví dụ, giúp ích cho việc học","mau":"这本书的内容很有趣，并且有很多例子，对学习中文很有帮助","can":[["并且"]]},{"kieu":"vandung","de":"A：明天的会议，你做好准备了吗？ B：＿＿＿。","goiY":"Đã chuẩn bị xong tài liệu, hơn nữa đã kiểm tra lại một lượt","mau":"做好了，我已经把会议材料准备好了，并且又检查了一遍","can":[["并且"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Anh ấy đã hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.","dap":["他按时完成了任务，并且做得很好。","他按时完成了任务，并且完成得很好。"],"giai":"……，并且 + V得……"},{"kieu":"dich","vn":"Tôi đã điều chỉnh kế hoạch, đồng thời thêm vài ví dụ vào tài liệu.","dap":["我调整了计划，并且在材料里增加了一些例子。","我调整了计划，并且在材料里增加了几个例子。"],"giai":"V1 + 了……，并且 + V2 + 了…… + từ mới 调整, 增加, 例子."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giới thiệu một người bạn tốt của em: nêu hai ưu điểm, có dùng 「并且」","mau":"我的好朋友小林学习很努力，并且很愿意帮助别人。","can":[["并且"]]}]}]},{"so":"3","ten":"固定短语“说不定”","tenVn":"Cụm cố định 「说不定」 — không chừng, biết đâu, có khi","cauTruc":["(Chủ ngữ +) 说不定 + (会 / 就 / 已经 / 还 / 也) + V……","说不定 + chủ ngữ + V……","……还说不定。 (làm vị ngữ: còn chưa chắc)"],"giaiThich":"「说不定」 dùng để PHỎNG ĐOÁN, ước đoán một khả năng có thể xảy ra hoặc một kết quả có thể có — giống tiếng Việt “không chừng, biết đâu, có khi”. Vị trí linh hoạt: trước hoặc sau chủ ngữ (说不定他有事 / 他说不定有事); thường đi với 会, 就 (biết đâu lại …), 已经, 还在, 也. Khi làm vị ngữ ở cuối câu nghĩa là “chưa chắc, chưa nói trước được”: 我明天去不去还说不定. Đọc: shuōbudìng (不 đọc nhẹ). So sánh: 也许 / 可能 (bài khoá 4) trung tính hơn; 说不定 mang màu khẩu ngữ, hay hàm ý “biết đâu lại xảy ra điều bất ngờ / điều tốt” (你再试一次，说不定就成功了). Ngược nghĩa với 一定 (chắc chắn) — không dùng chung ✗一定说不定. ⚠ Mẹo của Tiểu Ngữ (bài khoá 2): mẫu 「说 + V/Adj + 就 + V/Adj」 như 说变就变, 说走就走, 说冷就冷 diễn tả hành động, trạng thái thay đổi xảy ra RẤT NHANH, bất ngờ — chữ 说 ở đây cũng không có nghĩa là “nói”: 时间都安排好了，怎么说变就变了？ (sao nói đổi là đổi luôn vậy?).","viDu":[{"zh":"不做计划，说不定也会带来新的发现。","py":"Bú zuò jìhuà, shuōbudìng yě huì dàilái xīn de fāxiàn.","vn":"Không lập kế hoạch, không chừng cũng sẽ mang lại phát hiện mới."},{"zh":"今天这么阴，说不定会下雨。","py":"Jīntiān zhème yīn, shuōbudìng huì xiàyǔ.","vn":"Hôm nay âm u thế này, không chừng sẽ mưa."},{"zh":"你再试一次，说不定就成功了。","py":"Nǐ zài shì yí cì, shuōbudìng jiù chénggōng le.","vn":"Bạn thử lại lần nữa, biết đâu lại thành công."},{"zh":"你再试一次吧，即使这次没成功，说不定也能学到不少东西。","py":"Nǐ zài shì yí cì ba, jíshǐ zhè cì méi chénggōng, shuōbudìng yě néng xuédào bùshǎo dōngxi.","vn":"Bạn thử lại đi, cho dù lần này không thành công, biết đâu cũng học được không ít điều. (ôn 即使 – Bài 11 · điểm 1)"}],"loi":[{"sai":"他今天没来，说不定他有事吗？","why":"说不定 là câu phỏng đoán (trần thuật), không thêm 吗 ở cuối.","dung":"他今天没来，说不定有事。"},{"sai":"今天这么阴，一定说不定会下雨。","why":"一定 (chắc chắn) và 说不定 (không chắc) mâu thuẫn nhau.","dung":"今天这么阴，说不定会下雨。"},{"sai":"我说不定明天去不去。","why":"Muốn nói “mai đi hay không còn chưa chắc” → đặt 说不定 cuối câu làm vị ngữ.","dung":"我明天去不去还说不定。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["不做计划，","也会带来新的发现。"],"dap":[["说不定"]],"chon":["说不定","一定","不得不"],"goiY":"“Không lập kế hoạch, không chừng cũng sẽ mang lại phát hiện mới.”","giai":"Phỏng đoán khả năng → 说不定."},{"kieu":"dien","phan":["今天这么阴，说不定会","。"],"dap":[["下雨"]],"chon":["下雨","出太阳","轻松"],"goiY":"“Hôm nay âm u thế này, không chừng sẽ mưa.”","giai":"阴 (âm u) → có thể mưa."},{"kieu":"dien","phan":["你再试一次，说不定","成功了。"],"dap":[["就"]],"chon":["就","才","却"],"goiY":"“Thử lại lần nữa, biết đâu lại thành công.”","giai":"说不定就……了: biết đâu lại … ngay."},{"kieu":"dien","phan":["明天的会议开不开","说不定，可能会推迟。"],"dap":[["还"]],"chon":["还","就","却"],"goiY":"“Cuộc họp mai có họp hay không còn chưa chắc, có thể sẽ hoãn.”","giai":"……还说不定 = còn chưa chắc."},{"kieu":"dien","phan":["","你这么喜欢，那就买吧，说不定以后就买不到了。"],"dap":[["既然"]],"chon":["既然","即使","虽然"],"goiY":"“Đã thích thế thì mua đi, biết đâu sau này không mua được nữa.” (ôn 既然 – Bài 7)","giai":"既然……，就…… (Bài 7 · điểm 2)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["今天","这么阴","，","说不定","会","下雨"],"dap":["今天这么阴，说不定会下雨。"],"goiY":"Hôm nay âm u thế này, không chừng sẽ mưa.","giai":"说不定 + 会 + V."},{"kieu":"xep","manh":["你","再试一次","，","说不定","就","成功了"],"dap":["你再试一次，说不定就成功了。"],"goiY":"Bạn thử lại lần nữa, biết đâu lại thành công.","giai":"说不定 + 就 + V + 了."},{"kieu":"xep","manh":["他","说不定","已经","到","机场了"],"dap":["他说不定已经到机场了。","说不定他已经到机场了。"],"goiY":"Có khi anh ấy đã đến sân bay rồi.","giai":"说不定 đứng trước hoặc sau chủ ngữ."},{"kieu":"dungsai","cau":"他今天没来，说不定有事。","dung":true,"giai":"Đúng: phỏng đoán nguyên nhân."},{"kieu":"dungsai","cau":"今天这么阴，一定说不定会下雨。","dung":false,"sua":"今天这么阴，说不定会下雨。","giai":"Bỏ 一定 — mâu thuẫn với 说不定."},{"kieu":"dungsai","cau":"我明天去不去还说不定。","dung":true,"giai":"Đúng: 说不定 làm vị ngữ = còn chưa chắc."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 68)","huongDan":"Hoàn thành câu, dùng 「说不定」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"他今天没来，＿＿＿。（有事）","goiY":"Đoán lý do: không chừng nhà có việc","mau":"说不定家里有事","can":[["说不定"],["有事"]]},{"kieu":"vandung","de":"＿＿＿，再等一会儿吧。（路上）","goiY":"Đoán: không chừng anh ấy còn đang trên đường","mau":"他说不定还在路上","can":[["说不定"],["路上"]]},{"kieu":"vandung","de":"这件事你找经理说吧，＿＿＿。（同意）","goiY":"Đoán: biết đâu giám đốc sẽ đồng ý","mau":"说不定他会同意","can":[["说不定"],["同意"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đừng thất vọng, lần sau không chừng bạn sẽ làm tốt hơn.","dap":["别失望，下次你说不定会做得更好。","别失望，说不定下次你会做得更好。","别失望，你下次说不定会做得更好。"],"giai":"说不定 + 会 + V + từ mới 失望."},{"kieu":"dich","vn":"Bạn thử đi hỏi thầy giáo xem, biết đâu thầy sẽ đồng ý.","dap":["你去问问老师吧，说不定他会同意。","你去问问老师吧，说不定老师会同意。"],"giai":"V V (thử) + 说不定……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em buồn vì chuyến du lịch bị hủy. Hãy an ủi bạn bằng một câu có 「说不定」","mau":"没关系，在家附近逛逛，说不定也会有新的发现。","can":[["说不定"]]}]}]},{"so":"4","ten":"关联副词“却”","tenVn":"Phó từ liên kết 「却」 — lại, nhưng lại (chuyển ý, trái với mong đợi)","cauTruc":["Vế 1，(chủ ngữ 2 +) 却 + vị ngữ (trái với điều mong đợi)","虽然……，(chủ ngữ +) 却……","Chủ ngữ + 却 + V / Adj (却 luôn đứng SAU chủ ngữ, TRƯỚC vị ngữ)"],"giaiThich":"「却」 là phó từ liên kết biểu thị CHUYỂN Ý: điều nói sau 却 trái ngược hoặc khác với điều người nghe mong đợi từ vế trước — giống “lại, nhưng lại, mà lại” trong tiếng Việt (准备好了一切，却突然出现了新情况). Vì là PHÓ TỪ nên 却 phải đứng SAU chủ ngữ, TRƯỚC động từ / tính từ: 她长得很像她姐姐，性格却完全不同 (✗ 却性格完全不同). Nếu hai vế cùng chủ ngữ thì vế sau có thể bỏ chủ ngữ: 他通过了面试，却一点儿也不激动. Phân biệt cho người Việt: 但是 / 可是 / 不过 (Bài 2) là LIÊN TỪ, đứng ĐẦU vế câu, trước chủ ngữ; 却 là phó từ, đứng trong vế. Có thể kết hợp 虽然……，却…… (giọng văn viết nhẹ nhàng). 而 (Bài 10 · điểm 3) cũng nối hai vế tương phản nhưng là liên từ. ⚠ Chỉ dùng 却 khi vế sau thật sự “ngược” với mong đợi — kết quả hợp lý thì dùng 所以 / 因此.","viDu":[{"zh":"你准备好了一切，却突然出现了新情况，让你不得不改变计划。","py":"Nǐ zhǔnbèi hǎo le yíqiè, què tūrán chūxiàn le xīn qíngkuàng, ràng nǐ bùdébù gǎibiàn jìhuà.","vn":"Bạn đã chuẩn bị xong mọi thứ, nhưng lại đột nhiên xuất hiện tình huống mới, khiến bạn buộc phải thay đổi kế hoạch."},{"zh":"他通过了面试，却一点儿也不激动。","py":"Tā tōngguò le miànshì, què yìdiǎnr yě bù jīdòng.","vn":"Anh ấy đã qua vòng phỏng vấn, nhưng lại chẳng hề phấn khích chút nào."},{"zh":"她长得很像她姐姐，性格却完全不同。","py":"Tā zhǎng de hěn xiàng tā jiějie, xìnggé què wánquán bùtóng.","vn":"Cô ấy trông rất giống chị gái, nhưng tính cách lại hoàn toàn khác."},{"zh":"尽管他每天都很努力，成绩却一直没有提高。","py":"Jǐnguǎn tā měitiān dōu hěn nǔlì, chéngjì què yìzhí méiyǒu tígāo.","vn":"Mặc dù ngày nào cậu ấy cũng rất cố gắng, thành tích lại mãi không tiến bộ. (ôn 尽管 – Bài 9 · điểm 2)"}],"loi":[{"sai":"他通过了面试，却他一点儿也不激动。","why":"却 là phó từ — đứng SAU chủ ngữ, không đứng trước chủ ngữ như 但是.","dung":"他通过了面试，他却一点儿也不激动。"},{"sai":"她长得很像她姐姐，却性格完全不同。","why":"Vế sau có chủ ngữ riêng (性格) → 却 đặt sau chủ ngữ đó.","dung":"她长得很像她姐姐，性格却完全不同。"},{"sai":"他学习很努力，却考得很好。","why":"却 chỉ dùng khi vế sau TRÁI với điều mong đợi; đây là kết quả hợp lý → dùng 所以.","dung":"他学习很努力，所以考得很好。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["你准备好了一切，","突然出现了新情况。"],"dap":[["却"]],"chon":["却","就","才"],"goiY":"“Bạn đã chuẩn bị xong mọi thứ, nhưng lại đột nhiên xuất hiện tình huống mới.”","giai":"Vế sau trái với mong đợi → 却."},{"kieu":"dien","phan":["他通过了面试，却一点儿也不","。"],"dap":[["激动"]],"chon":["激动","可惜","详细"],"goiY":"“Anh ấy qua vòng phỏng vấn nhưng lại chẳng phấn khích chút nào.”","giai":"一点儿也不 + Adj."},{"kieu":"dien","phan":["她长得很像她姐姐，性格","完全不同。"],"dap":[["却"]],"chon":["却","并且","也"],"goiY":"“… nhưng tính cách lại hoàn toàn khác.”","giai":"却 đứng sau chủ ngữ 性格."},{"kieu":"dien","phan":["他说今天一定来，","却没来，真让人失望。"],"dap":[["最后"]],"chon":["最后","本来","等到"],"goiY":"“Anh ấy nói hôm nay nhất định đến, cuối cùng lại không đến, thật khiến người ta thất vọng.”","giai":"最后却…… = cuối cùng lại …"},{"kieu":"dien","phan":["","他每天都很努力，成绩却一直没有提高。"],"dap":[["尽管"]],"chon":["尽管","既然","只要"],"goiY":"“Mặc dù ngày nào cũng cố gắng, thành tích lại không tiến bộ.” (ôn 尽管 – Bài 9)","giai":"尽管……，却…… (nhượng bộ – chuyển ý)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","通过了面试","，","却","一点儿也","不激动"],"dap":["他通过了面试，却一点儿也不激动。"],"goiY":"Anh ấy qua vòng phỏng vấn nhưng lại chẳng phấn khích chút nào.","giai":"Cùng chủ ngữ → vế sau bỏ chủ ngữ, 却 + V."},{"kieu":"xep","manh":["她","长得很像她姐姐","，","性格","却","完全不同"],"dap":["她长得很像她姐姐，性格却完全不同。"],"goiY":"Cô ấy trông rất giống chị gái, tính cách lại hoàn toàn khác.","giai":"Chủ ngữ 2 + 却 + vị ngữ."},{"kieu":"xep","manh":["大家","都","到了","，","他","却","还没来"],"dap":["大家都到了，他却还没来。"],"goiY":"Mọi người đều đến rồi, anh ấy lại vẫn chưa đến.","giai":"他却…… — 却 sau chủ ngữ."},{"kieu":"dungsai","cau":"我们都很着急，他却一点儿也不着急。","dung":true,"giai":"Đúng: 却 sau chủ ngữ 他, vế sau ngược với vế trước."},{"kieu":"dungsai","cau":"他学习很努力，却考得很好。","dung":false,"sua":"他学习很努力，所以考得很好。","giai":"Kết quả hợp lý, không trái mong đợi → không dùng 却."},{"kieu":"dungsai","cau":"他通过了面试，却他一点儿也不激动。","dung":false,"sua":"他通过了面试，他却一点儿也不激动。","giai":"却 đứng sau chủ ngữ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 70)","huongDan":"Hoàn thành câu, có dùng 「却」","cau":[{"kieu":"vandung","de":"他没有做太多准备，＿＿＿。","goiY":"Kết quả bất ngờ: lại thi / làm rất tốt","mau":"却考得很不错","can":[["却"]]},{"kieu":"vandung","de":"我觉得这个电影很有趣，＿＿＿。","goiY":"Người khác lại thấy ngược lại: bạn tôi lại thấy chẳng có gì hay","mau":"我朋友却觉得一点儿意思都没有","can":[["却"]]},{"kieu":"vandung","de":"这些打折的商品虽然便宜，＿＿＿。","goiY":"Mặt trái: chất lượng lại không tốt lắm","mau":"质量却不太好","can":[["却"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Đã hẹn gặp bạn rồi, nhưng trời lại đột nhiên đổ mưa.","dap":["约好见朋友了，却突然下起了大雨。","约好了见朋友，天却突然下雨了。","已经约好见朋友了，却突然下雨了。"],"giai":"约好…… + 却 + 突然……"},{"kieu":"dich","vn":"Tôi học tiếng Trung ba năm rồi, nhưng lại chưa từng đến Trung Quốc.","dap":["我学了三年中文，却从来没去过中国。","我学中文三年了，却从来没去过中国。","我学了三年中文，却从来没有去过中国。"],"giai":"却 + ôn 从来没 + V过 (Bài 9 · điểm 4)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần kế hoạch của em bị thay đổi bất ngờ, có dùng 「却」","mau":"我本来打算周末去爬山，周六早晨天气却忽然变阴了，只好在家看书。","can":[["却"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-17.html"] = [{"so":"1","ten":"固定格式“你×你的吧”","tenVn":"Cụm cố định 「你×你的吧」 — anh / chị cứ (làm việc) của mình đi","cauTruc":["你 / 您 / 你们 + V + 你 / 您 / 你们 + 的 + 吧","你×你的吧，我…… (nói lý do / việc của mình)"],"giaiThich":"Sách: cụm cố định 「你×你的吧」 biểu thị MỖI NGƯỜI LÀM VIỆC CỦA MÌNH, không cần làm cùng nhau; thường dùng để TỪ CHỐI MỘT CÁCH LỊCH SỰ lời mời / ý tốt của người khác. × là một động từ đơn (走, 忙, 玩, 吃, 看, 写…); đại từ ở hai chỗ phải giống nhau: 您走您的吧 / 你忙你的吧 / 你们玩你们的吧. Câu thường có thêm vế giải thích: 我一会儿还要…… / 我自己就能…… / 我今天想…… — để người nghe yên tâm, không thấy bị từ chối phũ. Tiếng Việt tương đương: “Chị cứ về trước đi”, “Anh cứ làm việc của anh đi, không cần lo cho em”. 吧 làm giọng mềm, mang ý khuyên. Liên hệ 各×各的 (Bài 5 · điểm 3): 各×各的 là câu TRẦN THUẬT khách quan “ai làm việc nấy” (我们各吃各的); còn 你×你的吧 là lời nói TRỰC TIẾP với người kia, có 吧, để từ chối khéo. ⚠ Chỉ dùng khi KHÔNG muốn làm cùng; nếu đồng ý thì nói 好啊，一起……吧. Nói với giọng gắt (bỏ 吧) có thể thành “mặc kệ anh”, kém lịch sự.","viDu":[{"zh":"您走您的吧，我一会儿还要去一趟健身房。","py":"Nín zǒu nín de ba, wǒ yíhuìr hái yào qù yí tàng jiànshēnfáng.","vn":"Chị cứ về trước đi, lát nữa em còn phải đến phòng gym một chuyến."},{"zh":"你忙你的吧，我自己就能完成。","py":"Nǐ máng nǐ de ba, wǒ zìjǐ jiù néng wánchéng.","vn":"Anh cứ làm việc của anh đi, em tự làm xong được."},{"zh":"你们玩你们的吧，我今天想在家休息。","py":"Nǐmen wán nǐmen de ba, wǒ jīntiān xiǎng zài jiā xiūxi.","vn":"Các cậu cứ đi chơi đi, hôm nay mình muốn ở nhà nghỉ ngơi."},{"zh":"你看你的吧，就是再晚，我也要把这份材料写完。","py":"Nǐ kàn nǐ de ba, jiùshì zài wǎn, wǒ yě yào bǎ zhè fèn cáiliào xiěwán.","vn":"Anh cứ xem của anh đi, dù muộn đến mấy em cũng phải viết xong tài liệu này. (ôn 就是……也…… – Bài 11 · điểm 2)"}],"loi":[{"sai":"您走你的吧，我还要去健身房。","why":"Hai đại từ phải giống nhau: 您……您的 / 你……你的.","dung":"您走您的吧，我还要去健身房。"},{"sai":"你忙你吧，我自己就能完成。","why":"Thiếu 的 — khuôn là 你 + V + 你的 + 吧.","dung":"你忙你的吧，我自己就能完成。"},{"sai":"A：我们一起去吃饭吧！B：好啊，你吃你的吧。","why":"你×你的吧 dùng để TỪ CHỐI (ai làm việc nấy); đã đồng ý đi cùng thì không dùng.","dung":"A：我们一起去吃饭吧！B：不了，你吃你的吧，我还不饿。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["谢谢一雪姐，不过您走","的吧，我一会儿还要去健身房。"],"dap":[["您"]],"chon":["您","你","我"],"goiY":"“… nhưng chị cứ về trước đi …” — đại từ phải giống chữ đầu","giai":"您走您的吧: hai đại từ giống nhau."},{"kieu":"dien","phan":["你","你的吧，我自己就能完成。"],"dap":[["忙"]],"chon":["忙","帮","等"],"goiY":"“Anh cứ làm việc của anh đi, em tự làm xong được.”","giai":"你忙你的吧 = anh cứ bận việc của anh."},{"kieu":"dien","phan":["你们玩你们","，我今天想在家休息。"],"dap":[["的吧"]],"chon":["的吧","吧的","了吧"],"goiY":"“Các cậu cứ đi chơi đi, hôm nay mình muốn ở nhà nghỉ.”","giai":"Khuôn: 你们 + V + 你们 + 的吧."},{"kieu":"dien","phan":["我一会儿还要去一","健身房，您先走吧。"],"dap":[["趟"]],"chon":["趟","张","家"],"goiY":"“Lát nữa em còn phải đến phòng gym một chuyến …”","giai":"去一趟 + nơi: đi một chuyến."},{"kieu":"dien","phan":["你吃你的吧，我今天要加班，回来得很","。"],"dap":[["晚"]],"chon":["晚","早","快"],"goiY":"“Anh cứ ăn đi, hôm nay em phải tăng ca, về rất muộn.”","giai":"Lý do từ chối: về muộn → 回来得很晚."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["您","走","您的吧","，","我","还要去","一趟健身房"],"dap":["您走您的吧，我还要去一趟健身房。"],"goiY":"Chị cứ về trước đi, em còn phải đến phòng gym một chuyến.","giai":"您 + V + 您的吧，+ lý do."},{"kieu":"xep","manh":["你","看","你的吧","，","我","去","接个电话"],"dap":["你看你的吧，我去接个电话。"],"goiY":"Anh cứ xem của anh đi, em đi nghe điện thoại một chút.","giai":"你×你的吧 + việc của mình."},{"kieu":"xep","manh":["你们","聊","你们的吧","，","我","有点儿累了"],"dap":["你们聊你们的吧，我有点儿累了。"],"goiY":"Các bạn cứ nói chuyện đi, mình hơi mệt rồi.","giai":"你们……你们的吧."},{"kieu":"dungsai","cau":"你忙你的吧，我自己就能完成。","dung":true,"giai":"Đúng: từ chối khéo ý giúp đỡ."},{"kieu":"dungsai","cau":"您走你的吧，我还要去健身房。","dung":false,"sua":"您走您的吧，我还要去健身房。","giai":"Hai đại từ phải thống nhất."},{"kieu":"dungsai","cau":"你玩你吧，我想在家休息。","dung":false,"sua":"你玩你的吧，我想在家休息。","giai":"Thiếu 的."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 76)","huongDan":"Hoàn thành đối thoại, có dùng 「你×你的吧」","cau":[{"kieu":"vandung","de":"A：你几点回来？我等你一起吃饭吧。 B：＿＿＿。","goiY":"Từ chối khéo: anh cứ ăn trước đi, không cần đợi em (nêu lý do)","mau":"你吃你的吧，不用等我了，我今天要加班，回来得很晚","can":[["吃你的吧"]]},{"kieu":"vandung","de":"A：我有点儿累了，不想继续看这个电影了。 B：好，＿＿＿。","goiY":"Bảo người kia cứ đi nghỉ, mình tự xem nốt","mau":"你休息你的吧，我自己把它看完","can":[["你的吧"]]},{"kieu":"vandung","de":"A：你＿＿＿，我去接个电话。 B：好，我写完告诉你。","goiY":"A đang ngồi cùng B làm bài, A bảo B cứ viết tiếp (B trả lời 写完)","mau":"写你的吧","can":[["写你的吧"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chị cứ về trước đi, lát nữa em còn phải đến phòng gym một chuyến.","dap":["您走您的吧，我一会儿还要去一趟健身房。","你走你的吧，我一会儿还要去一趟健身房。"],"giai":"你×你的吧 + từ mới 趟, 健身房."},{"kieu":"dich","vn":"Các cậu cứ chơi đi, mình phải ở nhà ôn bài.","dap":["你们玩你们的吧，我得在家复习。","你们玩你们的吧，我要在家复习。"],"giai":"你们……你们的吧，+ lý do."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Đồng nghiệp rủ em đi ăn tối nhưng em phải đi tập gym. Hãy từ chối khéo bằng 「你×你的吧」","mau":"谢谢你，不过你吃你的吧，我一会儿还要去健身房锻炼。","can":[["你的吧"]]}]}]},{"so":"2","ten":"固定短语“一A一B”","tenVn":"Cụm cố định 「一A一B」 — một … một … (hai mặt đối xứng)","cauTruc":["一 + A + 一 + B (A, B là từ đơn âm tiết)","A, B trái nghĩa / đối xứng: 一来一回, 一问一答, 一大一小, 一长一短","A, B cùng loại: 一字一句 (từng chữ từng câu)"],"giaiThich":"Sách: cụm cố định 「一A一B」 biểu thị tình huống ĐỐI XỨNG hoặc HAI PHƯƠNG DIỆN của một việc; A và B là từ ĐƠN ÂM TIẾT. Hay gặp hai kiểu: (1) A, B trái nghĩa / đối nhau → nói hai bên, hai chiều: 一来一回 (cả đi lẫn về), 一问一答 (người hỏi người đáp), 一大一小 (một to một nhỏ), 一长一短, 一前一后, 一高一矮; (2) A, B là hai danh từ cùng loại → nhấn mạnh “từng … từng …”, rõ ràng, cẩn thận: 一字一句 (từng chữ từng câu). Cụm này làm được nhiều thành phần: chủ ngữ (一来一回得半个小时), vị ngữ (这两个房间一大一小), trạng ngữ (一字一句地说), và không thêm 的 sau A hay B (✗ 一大的一小的). Liên hệ 有A有B (Bài 8 · điểm 4 — 有说有笑): 有A有B liệt kê hai thứ CÙNG CÓ; 一A一B nhấn hai bên ĐỐI XỨNG, mỗi bên một. ⚠ Phát âm: 一 trước thanh 4 đọc yí (一大 yí dà, 一字 yí zì), trước thanh 1, 2, 3 đọc yì (一来 yì lái, 一长 yì cháng, 一小 yì xiǎo). Trong 一来一回得半个小时, 得 đọc děi = phải mất.","viDu":[{"zh":"一来一回得半个小时，太浪费时间了。","py":"Yì lái yì huí děi bàn gè xiǎoshí, tài làngfèi shíjiān le.","vn":"Cả đi lẫn về mất nửa tiếng, phí thời gian quá."},{"zh":"她说话的声音不大，但是一字一句说得很清楚。","py":"Tā shuōhuà de shēngyīn bú dà, dànshì yí zì yí jù shuō de hěn qīngchu.","vn":"Cô ấy nói không to, nhưng từng chữ từng câu đều rất rõ ràng."},{"zh":"记者和运动员一问一答，谈到了很多比赛中的事情。","py":"Jìzhě hé yùndòngyuán yí wèn yì dá, tándào le hěn duō bǐsài zhōng de shìqing.","vn":"Phóng viên và vận động viên một hỏi một đáp, nói đến rất nhiều chuyện trong trận đấu."},{"zh":"这两个孩子一大一小，可是大的不如小的跑得快。","py":"Zhè liǎng gè háizi yí dà yì xiǎo, kěshì dà de bùrú xiǎo de pǎo de kuài.","vn":"Hai đứa trẻ này một lớn một nhỏ, nhưng đứa lớn chạy không nhanh bằng đứa nhỏ. (ôn A不如B – Bài 15 · điểm 4)"}],"loi":[{"sai":"一来回得半个小时。","why":"Phải đủ hai chữ 一: 一来一回.","dung":"一来一回得半个小时。"},{"sai":"这两个房间一大的一小的。","why":"一A一B làm vị ngữ, không thêm 的.","dung":"这两个房间一大一小。"},{"sai":"记者和运动员一问一回答。","why":"A, B phải là từ đơn âm tiết, đối xứng nhau.","dung":"记者和运动员一问一答。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["离我家最近的健身房也要坐两站公交车，一","一回得半个小时。"],"dap":[["来"]],"chon":["来","到","回"],"goiY":"“… cả đi lẫn về mất nửa tiếng.”","giai":"一来一回 = cả đi lẫn về."},{"kieu":"dien","phan":["她说话的声音不大，但是一字一","说得很清楚。"],"dap":[["句"]],"chon":["句","话","声"],"goiY":"“… nhưng từng chữ từng câu đều rất rõ.”","giai":"一字一句: A, B cùng loại, đơn âm tiết."},{"kieu":"dien","phan":["记者和运动员一问一","，谈到了很多比赛中的事情。"],"dap":[["答"]],"chon":["答","说","问"],"goiY":"“Phóng viên và vận động viên một hỏi một đáp …”","giai":"问 ↔ 答: hai mặt đối xứng."},{"kieu":"dien","phan":["这两个房间一大一","，你们两个人住大的，我自己住小的。"],"dap":[["小"]],"chon":["小","多","少"],"goiY":"“Hai phòng này một to một nhỏ …”","giai":"大 ↔ 小."},{"kieu":"dien","phan":["您看这条裤子，怎么左腿和右腿一","一短？"],"dap":[["长"]],"chon":["长","高","大"],"goiY":"“… sao ống trái ống phải một dài một ngắn?”","giai":"长 ↔ 短; 一 trước 长 đọc yì."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["一来一回","得","半个小时","，","太浪费","时间了"],"dap":["一来一回得半个小时，太浪费时间了。"],"goiY":"Cả đi lẫn về mất nửa tiếng, phí thời gian quá.","giai":"一来一回 làm chủ ngữ; 得 (děi) = phải mất."},{"kieu":"xep","manh":["老师","一字一句地","读","，","大家","都","听清楚了"],"dap":["老师一字一句地读，大家都听清楚了。"],"goiY":"Thầy đọc từng chữ từng câu, mọi người đều nghe rõ.","giai":"一字一句 + 地 + V: làm trạng ngữ."},{"kieu":"xep","manh":["两个孩子","一胖一瘦","，","都","很喜欢","打乒乓球"],"dap":["两个孩子一胖一瘦，都很喜欢打乒乓球。"],"goiY":"Hai đứa trẻ một béo một gầy, đều rất thích chơi bóng bàn.","giai":"一胖一瘦 làm vị ngữ (胖 ↔ 瘦)."},{"kieu":"dungsai","cau":"这两个房间一大一小。","dung":true,"giai":"Đúng: 一A一B làm vị ngữ."},{"kieu":"dungsai","cau":"记者和运动员一问一回答。","dung":false,"sua":"记者和运动员一问一答。","giai":"A, B phải đơn âm tiết, đối xứng."},{"kieu":"dungsai","cau":"从家到公司一来回要一个多小时。","dung":false,"sua":"从家到公司一来一回要一个多小时。","giai":"Đủ hai chữ 一."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 78)","huongDan":"Hoàn thành đối thoại, có dùng 「一A一B」","cau":[{"kieu":"vandung","de":"A：你怎么没去医院看病？ B：只是点儿小问题，而且＿＿＿，所以就没去。","goiY":"Lý do: bệnh viện xa, cả đi lẫn về mất nhiều thời gian","mau":"医院离我家太远，一来一回要两个多小时","can":[["一来一回"]]},{"kieu":"vandung","de":"A：这两个房间怎么安排？ B：＿＿＿，你们两个人住大的，我自己住小的。","goiY":"Nói hai phòng một to một nhỏ","mau":"这两个房间一大一小","can":[["一大一小"]]},{"kieu":"vandung","de":"A：您看这条裤子，怎么左腿和右腿＿＿＿？ B：实在抱歉，我现在就给您换一条。","goiY":"Khách phàn nàn: hai ống quần một dài một ngắn","mau":"一长一短","can":[["一长一短"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Hai đứa con nhà chị ấy một béo một gầy.","dap":["她家的两个孩子一胖一瘦。","她家两个孩子一胖一瘦。"],"giai":"一胖一瘦 làm vị ngữ."},{"kieu":"dich","vn":"Từ nhà đến công ty cả đi lẫn về mất một tiếng.","dap":["从家到公司一来一回要一个小时。","从家到公司一来一回得一个小时。"],"giai":"一来一回 + 得 / 要 + thời gian."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Giải thích vì sao em không chọn phòng gym ở xa, có dùng 「一A一B」","mau":"那家健身房离我家太远了，一来一回要一个小时，所以我在家附近办了会员卡。","can":[["一来一回"]]}]}]},{"so":"3","ten":"兼语句“主语+表扬/批评+宾语1+动词+宾语2”","tenVn":"Câu kiêm ngữ với 表扬 / 批评 — khen / phê bình ai (đã) làm gì","cauTruc":["Chủ ngữ + 表扬 / 批评 + O1 (người) + V + O2 (việc người đó làm)","O1 vừa là tân ngữ của 表扬 / 批评, vừa là chủ ngữ của phần sau"],"giaiThich":"Sách: câu kiêm ngữ 「主语+表扬/批评+宾语1+动词+宾语2」 dùng để ĐÁNH GIÁ việc mà ai đó đã làm. Động từ thứ nhất là 表扬 (khen) hoặc 批评 (phê bình, trách); O1 là người được khen / bị trách; phần sau (V + O2) chính là LÝ DO khen / trách — có thể là cụm động từ (取得了很大的进步, 坚持每天学习中文), câu phủ định (没有按时完成工作) hay cụm tính từ (工作很细心). Không cần thêm 因为: ✗ 表扬他因为…… → ✓ 表扬他取得了进步. Phủ định / phó từ đặt TRƯỚC 表扬 / 批评: 妈妈总是批评我……, 老师没有批评他……. So sánh với các câu kiêm ngữ đã học: 让 / 叫 / 请 (HSK 3), 使 (Bài 7 · điểm 4), 鼓励 + ai + V (từ mới bài này) là loại SAI KHIẾN — việc phía sau CHƯA làm, người nói muốn người kia làm; còn 表扬 / 批评 thì việc phía sau ĐÃ xảy ra (hoặc là thói quen), là lý do để khen / chê. ⚠ Bẫy Hán Việt: 批评 nhẹ hơn chữ “phê bình” trang trọng của tiếng Việt — 妈妈批评我 thường chỉ là “mẹ mắng / trách tôi”.","viDu":[{"zh":"教练也表扬他取得了很大的进步。","py":"Jiàoliàn yě biǎoyáng tā qǔdé le hěn dà de jìnbù.","vn":"Huấn luyện viên cũng khen anh ấy đã có tiến bộ rất lớn."},{"zh":"老师表扬白家月坚持每天学习中文。","py":"Lǎoshī biǎoyáng Bái Jiāyuè jiānchí měitiān xuéxí Zhōngwén.","vn":"Cô giáo khen Bạch Gia Nguyệt kiên trì học tiếng Trung mỗi ngày."},{"zh":"经理批评他没有按时完成工作。","py":"Jīnglǐ pīpíng tā méiyǒu ànshí wánchéng gōngzuò.","vn":"Giám đốc phê bình anh ấy không hoàn thành công việc đúng hạn."},{"zh":"经理表扬小王把工作做得又快又好。","py":"Jīnglǐ biǎoyáng Xiǎo Wáng bǎ gōngzuò zuò de yòu kuài yòu hǎo.","vn":"Giám đốc khen Tiểu Vương làm việc vừa nhanh vừa tốt. (ôn câu 把 – Bài 15, 16)"}],"loi":[{"sai":"老师表扬了因为白家月坚持每天学习中文。","why":"Không chèn 因为; người + việc sau 表扬 chính là lý do.","dung":"老师表扬白家月坚持每天学习中文。"},{"sai":"经理批评没有按时完成工作他。","why":"O1 (người) đứng ngay sau 批评, rồi mới đến việc người đó làm.","dung":"经理批评他没有按时完成工作。"},{"sai":"妈妈总是批评我把房间不收拾。","why":"Câu 把 không đặt 不 sau 把; nói 不收拾房间.","dung":"妈妈总是批评我不收拾房间。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["教练也","他取得了很大的进步。"],"dap":[["表扬"]],"chon":["表扬","批评","羡慕"],"goiY":"“Huấn luyện viên cũng khen anh ấy đã tiến bộ rất lớn.”","giai":"Tiến bộ → khen: 表扬 + ai + V."},{"kieu":"dien","phan":["经理","他没有按时完成工作。"],"dap":[["批评"]],"chon":["批评","表扬","鼓励"],"goiY":"“Giám đốc phê bình anh ấy không hoàn thành đúng hạn.”","giai":"Việc chưa tốt → 批评."},{"kieu":"dien","phan":["老师表扬白家月","每天学习中文。"],"dap":[["坚持"]],"chon":["坚持","受伤","路过"],"goiY":"“… khen Bạch Gia Nguyệt kiên trì học tiếng Trung mỗi ngày.”","giai":"坚持 + V."},{"kieu":"dien","phan":["教练表扬他把动作做得很","。"],"dap":[["准确"]],"chon":["准确","全身","设备"],"goiY":"“HLV khen anh ấy làm động tác rất chuẩn.”","giai":"V得 + 准确."},{"kieu":"dien","phan":["妈妈总是批评我不收拾","。"],"dap":[["房间"]],"chon":["房间","操场","会员"],"goiY":"“Mẹ lúc nào cũng trách tôi không dọn phòng.”","giai":"收拾房间 = dọn phòng."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["教练","表扬","他","取得了","很大的进步"],"dap":["教练表扬他取得了很大的进步。"],"goiY":"Huấn luyện viên khen anh ấy đã có tiến bộ rất lớn.","giai":"S + 表扬 + O1 + V + O2."},{"kieu":"xep","manh":["经理","批评","他","没有","按时完成工作"],"dap":["经理批评他没有按时完成工作。"],"goiY":"Giám đốc phê bình anh ấy không hoàn thành công việc đúng hạn.","giai":"Phủ định nằm trong phần lý do."},{"kieu":"xep","manh":["老师","表扬","我们","把教室","打扫得","很干净"],"dap":["老师表扬我们把教室打扫得很干净。"],"goiY":"Cô giáo khen chúng tôi dọn lớp rất sạch.","giai":"Phần lý do có thể là câu 把."},{"kieu":"dungsai","cau":"老师表扬白家月坚持每天学习中文。","dung":true,"giai":"Đúng: câu kiêm ngữ với 表扬."},{"kieu":"dungsai","cau":"经理批评没有按时完成工作他。","dung":false,"sua":"经理批评他没有按时完成工作。","giai":"Người bị phê bình đứng ngay sau 批评."},{"kieu":"dungsai","cau":"教练表扬了因为他动作很标准。","dung":false,"sua":"教练表扬他动作很标准。","giai":"Không dùng 因为 sau 表扬."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 80)","huongDan":"Hoàn thành câu, dùng từ trong ngoặc","cau":[{"kieu":"vandung","de":"经理表扬他＿＿＿。（细心）","goiY":"Lý do khen: làm việc cẩn thận, chưa từng sai sót","mau":"工作很细心，从来没出过错","can":[["细心"]]},{"kieu":"vandung","de":"今天老师表扬我＿＿＿。（成绩）","goiY":"Lý do khen: lần thi này đạt thành tích tốt","mau":"这次考试取得了很好的成绩","can":[["成绩"]]},{"kieu":"vandung","de":"妈妈总是批评我＿＿＿。（房间）","goiY":"Lý do bị trách: không dọn phòng của mình","mau":"不收拾自己的房间","can":[["房间"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Huấn luyện viên khen tôi làm động tác rất chuẩn.","dap":["教练表扬我动作做得很准确。","教练表扬我动作做得很标准。"],"giai":"表扬 + ai + (O) + V得 + Adj."},{"kieu":"dich","vn":"Thầy giáo phê bình cậu ấy đi học muộn.","dap":["老师批评他上课迟到。","老师批评他上课迟到了。"],"giai":"批评 + ai + việc đã làm."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một lần em được thầy cô / bố mẹ khen, dùng 「表扬」 theo mẫu kiêm ngữ","mau":"上个月，中文老师表扬我口语进步得很快。","can":[["表扬"]]}]}]},{"so":"4","ten":"递进复句“连……也/都……，……更……”","tenVn":"Câu phức tăng tiến 「连……也/都……，……更……」 — ngay cả … cũng …, (thì) … càng …","cauTruc":["连 + ví dụ cực đoan + 也 / 都 + V……，(đối tượng / việc khác) + 更 + ……","连 + chủ ngữ / tân ngữ đưa lên trước + 也 / 都 (+ 不 / 没) + V"],"giaiThich":"Sách: câu phức tăng tiến 「连……也/都……，……更……」 dùng một VÍ DỤ CỰC ĐOAN để nói rõ một tình huống. Vế 1: 连 đưa ra trường hợp “ít khả năng nhất” (người già, việc dễ nhất, nghe thầy nói…) + 也 / 都 — đến cái đó còn như vậy; vế 2: suy ra trường hợp khác CÀNG như vậy với 更 (更是, 就更……了, 更没有, 更不用说). Ví dụ: người già còn kiên trì chơi bóng → người trẻ càng chơi; lời thầy còn không hiểu → nghe đài càng khó. Phần sau 连 có thể là chủ ngữ (连一些老人都坚持打球) hoặc tân ngữ được đưa lên trước động từ (连脸都没来得及洗, 连老师说的话也听不懂). Câu phủ định: 连……也 / 都 + 不 / 没…… → vế sau 更 + 不 / 没 / 难…… (càng không). Tiếng Việt: “ngay cả / đến … còn …, huống chi / càng …”. ⚠ 连 bắt buộc đi với 也 / 都 (✗ 连老人坚持打球); 也 / 都 đứng sau phần 连, trước động từ. Hai vế phải cùng chiều: vế 1 khó → vế 2 càng khó. Liên hệ 甚至 (Bài 3 · điểm 3): cũng nêu trường hợp cực đoan, hay kết hợp 甚至连……都……; 即使……也…… (Bài 11 · điểm 1) là giả thiết, còn 连……也 là sự thật được nhấn mạnh.","viDu":[{"zh":"连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。","py":"Lián yìxiē niánlíng bǐjiào dà de lǎorén dōu jiānchí dǎqiú, niánqīngrén gèng shì bǎ tā zuòwéi yì zhǒng rìcháng duànliàn de fāngshì.","vn":"Ngay cả một số người già lớn tuổi cũng kiên trì chơi bóng, người trẻ thì càng coi nó là một cách rèn luyện hằng ngày."},{"zh":"我有时候连老师说的话也听不懂，听广播就更难了。","py":"Wǒ yǒushíhou lián lǎoshī shuō de huà yě tīngbudǒng, tīng guǎngbō jiù gèng nán le.","vn":"Có lúc tôi đến lời thầy nói còn nghe không hiểu, nghe đài thì càng khó hơn."},{"zh":"今天早上他连脸都没来得及洗，更没有时间准备早饭了。","py":"Jīntiān zǎoshang tā lián liǎn dōu méi láidejí xǐ, gèng méiyǒu shíjiān zhǔnbèi zǎofàn le.","vn":"Sáng nay cậu ấy đến mặt còn không kịp rửa, càng không có thời gian chuẩn bị bữa sáng."},{"zh":"这个问题太难了，甚至连老师都要想很久，我们就更不会了。","py":"Zhège wèntí tài nán le, shènzhì lián lǎoshī dōu yào xiǎng hěn jiǔ, wǒmen jiù gèng bú huì le.","vn":"Câu hỏi này khó quá, thậm chí thầy giáo cũng phải nghĩ rất lâu, chúng ta thì càng không biết. (ôn 甚至 – Bài 3 · điểm 3)"}],"loi":[{"sai":"连一些年龄比较大的老人坚持打球。","why":"Thiếu 都 / 也 sau phần 连.","dung":"连一些年龄比较大的老人都坚持打球。"},{"sai":"他都连脸没来得及洗。","why":"Thứ tự: 连 + phần nhấn mạnh + 都 + V.","dung":"他连脸都没来得及洗。"},{"sai":"我连老师说的话也听不懂，听广播就更容易了。","why":"Hai vế phải cùng chiều: vế 1 khó → vế 2 càng khó.","dung":"我连老师说的话也听不懂，听广播就更难了。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["","一些年龄比较大的老人都坚持打球。"],"dap":[["连"]],"chon":["连","就","才"],"goiY":"“Ngay cả một số người già lớn tuổi cũng kiên trì chơi bóng.”","giai":"连……都……: nêu ví dụ cực đoan."},{"kieu":"dien","phan":["连老人都坚持打球，年轻人","是把它作为一种日常锻炼的方式。"],"dap":[["更"]],"chon":["更","最","太"],"goiY":"“… người trẻ thì càng coi nó là cách rèn luyện hằng ngày.”","giai":"Vế 2 dùng 更 (càng)."},{"kieu":"dien","phan":["我有时候连老师说的话","听不懂，听广播就更难了。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“… đến lời thầy nói còn không hiểu …”","giai":"连 + tân ngữ đưa lên trước + 也 + V."},{"kieu":"dien","phan":["今天早上他连脸都没来得及洗，更没有时间准备","了。"],"dap":[["早饭"]],"chon":["早饭","操场","设备"],"goiY":"“… càng không có thời gian chuẩn bị bữa sáng.”","giai":"Ôn 来得及 / 来不及 (Bài 4 · điểm 4)."},{"kieu":"dien","phan":["受伤以后，他连走路都困难，更不能去","锻炼了。"],"dap":[["健身房"]],"chon":["健身房","会员","饼干"],"goiY":"“… càng không thể đến phòng gym tập luyện.”","giai":"去 + nơi + 锻炼."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","连","脸","都","没来得及洗"],"dap":["他连脸都没来得及洗。"],"goiY":"Cậu ấy đến mặt còn không kịp rửa.","giai":"连 + tân ngữ + 都 + 没 + V."},{"kieu":"xep","manh":["这个问题","连","孩子","都","知道","，","你","更","应该知道了"],"dap":["这个问题连孩子都知道，你更应该知道了。"],"goiY":"Câu hỏi này đến trẻ con cũng biết, bạn thì càng phải biết.","giai":"连……都……，……更……"},{"kieu":"xep","manh":["我","忙得","连饭","都","没时间吃","，","更","不能去健身了"],"dap":["我忙得连饭都没时间吃，更不能去健身了。"],"goiY":"Tôi bận đến mức đến cơm cũng không có thời gian ăn, càng không thể đi tập.","giai":"V得 + 连……都……"},{"kieu":"dungsai","cau":"连一些年龄比较大的老人坚持打球。","dung":false,"sua":"连一些年龄比较大的老人都坚持打球。","giai":"连 phải đi với 都 / 也."},{"kieu":"dungsai","cau":"他连这么难的事情都能解决，这件小事就更没问题了。","dung":true,"giai":"Đúng: việc khó còn làm được → việc nhỏ càng được."},{"kieu":"dungsai","cau":"我连老师说的话也听不懂，听广播就更容易了。","dung":false,"sua":"我连老师说的话也听不懂，听广播就更难了。","giai":"Hai vế phải cùng chiều."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 82)","huongDan":"Hoàn thành câu, có dùng 「连……也/都……，……更……」","cau":[{"kieu":"vandung","de":"受伤以后，他连走路都困难，＿＿＿。","goiY":"Vế 2 với 更: càng không thể chạy bộ / chơi bóng","mau":"更不能去跑步、打球了","can":[["更"]]},{"kieu":"vandung","de":"他连这么难的事情都能解决，＿＿＿。","goiY":"Vế 2 với 更: việc nhỏ này càng không thành vấn đề","mau":"这件小事他就更没问题了","can":[["更"]]},{"kieu":"vandung","de":"他＿＿＿，硕士研究生课程就更难了。","goiY":"Vế 1 với 连……都: đến chương trình đại học còn thấy rất khó","mau":"连大学的课程都觉得很难","can":[["连"],["都","也"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Ngay cả ông tôi cũng biết dùng điện thoại thông minh, các bạn trẻ thì càng khỏi phải nói.","dap":["连我爷爷都会用智能手机，年轻人就更不用说了。","连我爷爷也会用智能手机，年轻人就更不用说了。"],"giai":"连……都 / 也……，……就更不用说了."},{"kieu":"dich","vn":"Anh ấy bận đến nỗi cuối tuần cũng phải tăng ca, càng không có thời gian đi phòng gym.","dap":["他忙得连周末都要加班，更没有时间去健身房了。","他忙得连周末也要加班，更没有时间去健身房了。"],"giai":"V得 + 连……都……，更没有……"},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Nói về một môn thể thao rất được ưa chuộng ở Việt Nam, có dùng 「连……都……，……更……」","mau":"在越南，连很多老人都每天早上去公园跑步，年轻人更是喜欢踢足球、打羽毛球。","can":[["连"],["更"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-18.html"] = [{"so":"1","ten":"“数词+形容词+量词”结构","tenVn":"Cấu trúc 「Số từ + Tính từ + Lượng từ」 — 一大碗, 一小段 (nhấn mạnh nhiều / ít, to / nhỏ)","cauTruc":["一 + 大 / 小 + lượng từ (+ danh từ): 一大碗面条儿 · 一大包巧克力 · 一小段路","Động từ + 了 + 一 + 大 / 小 + lượng từ (+ danh từ)"],"giaiThich":"Cấu trúc 「数词 + 形容词 + 量词」 mang sắc thái KHOA TRƯƠNG: người nói chủ quan nhấn mạnh số lượng NHIỀU / TO (一大……) hoặc ÍT / NHỎ (一小……). Số từ thường là 「一」; tính từ thường là từ đơn âm tiết 「大」「小」; lượng từ thường là LƯỢNG TỪ TẠM THỜI mượn danh từ chỉ đồ đựng, khối, nhóm: 碗、杯、盘、包、箱、桌子、屋子、口、块、堆、段…. Rất hay dùng trong khẩu ngữ. ⚠ Người Việt nói “một bát TO mì”, “một quãng NGẮN” (tính từ đứng sau) nên hay đặt sai: tiếng Trung đặt 大 / 小 ngay TRƯỚC lượng từ: 一大碗面条儿 (✗ 一碗大面条儿). Tính từ ở đây không thêm 很 / 非常 (✗ 一很大包). Chú ý nghĩa: 一大碗 nhấn mạnh “nhiều” theo cảm nhận của người nói, không nhất thiết cái bát thật sự to; 一小段路 = một quãng đường ngắn, còn 一段小路 = một đoạn đường nhỏ (hẹp). Ôn lượng từ: lượng từ tạm thời giống 「一屋子人」「一桌子菜」 (cả phòng người, cả bàn thức ăn) — thêm 大 thì càng khoa trương: 一大屋子人, 一大桌子菜.","viDu":[{"zh":"快到那边那个出口时又推了一小段。","py":"Kuài dào nàbiān nàge chūkǒu shí yòu tuī le yì xiǎo duàn.","vn":"Sắp đến cái cổng ra đằng kia thì lại dắt xe đi bộ một đoạn ngắn."},{"zh":"今天早上我没吃饭就去上班了，中午饿极了，吃了一大碗面条儿。","py":"Jīntiān zǎoshang wǒ méi chīfàn jiù qù shàngbān le, zhōngwǔ è jí le, chī le yí dà wǎn miàntiáor.","vn":"Sáng nay tôi chưa ăn gì đã đi làm, trưa đói cực kỳ, ăn liền một bát mì to."},{"zh":"我今天又收到了妈妈寄来的快递，打开一看，除了衣服外，里边还有一大包巧克力。","py":"Wǒ jīntiān yòu shōudào le māma jìlái de kuàidì, dǎkāi yí kàn, chúle yīfu wài, lǐbian hái yǒu yí dà bāo qiǎokèlì.","vn":"Hôm nay tôi lại nhận được bưu kiện mẹ gửi, mở ra xem, ngoài quần áo, bên trong còn có cả một túi sô-cô-la to."},{"zh":"周末我把一大箱旧书整理了整理，送给了小区的图书角。","py":"Zhōumò wǒ bǎ yí dà xiāng jiù shū zhěnglǐ le zhěnglǐ, sònggěi le xiǎoqū de túshū jiǎo.","vn":"Cuối tuần tôi sắp xếp qua một thùng sách cũ to, rồi tặng cho góc thư viện của khu nhà. (ôn 把+宾+动+了+动 – Bài 15 · điểm 3)"}],"loi":[{"sai":"我中午吃了一碗大面条儿。","why":"大 phải đứng TRƯỚC lượng từ, không đứng trước danh từ (khác tiếng Việt “một bát to”).","dung":"我中午吃了一大碗面条儿。"},{"sai":"妈妈给我寄了一很大包巧克力。","why":"Trong cấu trúc này tính từ là 大 / 小 đơn âm tiết, không thêm 很.","dung":"妈妈给我寄了一大包巧克力。"},{"sai":"快到出口时，我又推了一段小路。","why":"Muốn nói “dắt xe thêm một quãng ngắn” → 一小段 (小 trước lượng từ); 一段小路 là “một con đường nhỏ”.","dung":"快到出口时，我又推了一小段。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["快到那边那个出口时又推了一","段。"],"dap":[["小"]],"chon":["小","很","多"],"goiY":"“… lại dắt xe đi bộ một đoạn ngắn.”","giai":"一 + 小 + lượng từ 段: một quãng ngắn."},{"kieu":"dien","phan":["中午饿极了，我吃了一","碗面条儿。"],"dap":[["大"]],"chon":["大","太","好"],"goiY":"“Trưa đói cực kỳ, tôi ăn một bát mì to.”","giai":"一 + 大 + 碗: nhấn mạnh nhiều."},{"kieu":"dien","phan":["快递里除了衣服外，还有一大","巧克力。"],"dap":[["包"]],"chon":["包","个","本"],"goiY":"“… còn có cả một túi sô-cô-la to.”","giai":"Lượng từ tạm thời 包 (túi, gói)."},{"kieu":"dien","phan":["他从图书馆借了一大","书，说要在假期里看完。"],"dap":[["堆"]],"chon":["堆","张","位"],"goiY":"“Anh ấy mượn cả một chồng sách to ở thư viện …”","giai":"一大堆 + N: cả đống, cả chồng."},{"kieu":"dien","phan":["这个小吃太辣了，我只吃了一小","就不敢吃了。"],"dap":[["口"]],"chon":["口","条","件"],"goiY":"“… tôi mới ăn một miếng nhỏ đã không dám ăn nữa.” (ôn từ 小吃 của bài)","giai":"一小口 = một miếng nhỏ (口 mượn từ “miệng”)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","中午","吃了","一大碗","面条儿"],"dap":["我中午吃了一大碗面条儿。","中午我吃了一大碗面条儿。"],"goiY":"Trưa nay tôi ăn một bát mì to.","giai":"V + 了 + 一大碗 + N."},{"kieu":"xep","manh":["快到出口时","，","我","又","推了","一小段"],"dap":["快到出口时，我又推了一小段。"],"goiY":"Sắp đến cổng ra, tôi lại dắt xe đi một đoạn ngắn.","giai":"又 + V + 了 + 一小段."},{"kieu":"xep","manh":["桌子上","放着","一大盘","小吃"],"dap":["桌子上放着一大盘小吃。"],"goiY":"Trên bàn đặt một đĩa đồ ăn vặt to.","giai":"Nơi chốn + V着 + 一大盘 + N (ôn câu tồn hiện, HSK 3)."},{"kieu":"dungsai","cau":"妈妈给我寄了一很大包巧克力。","dung":false,"sua":"妈妈给我寄了一大包巧克力。","giai":"Không thêm 很 vào giữa 一 và 大."},{"kieu":"dungsai","cau":"我只吃了一小块蛋糕，就吃不下了。","dung":true,"giai":"Đúng: 一小块 nhấn mạnh rất ít."},{"kieu":"dungsai","cau":"他点了一碗大面条儿。","dung":false,"sua":"他点了一大碗面条儿。","giai":"大 đứng trước lượng từ 碗."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 88)","huongDan":"Hoàn thành đối thoại, có dùng cấu trúc 「数词+形容词+量词」","cau":[{"kieu":"vandung","de":"A：这＿＿＿，够热闹的。 B：今天是我生日，请朋友们来家里一起聚聚，热闹热闹。","goiY":"Khen: cả một phòng to toàn người (一大 + 屋子 + 人)","mau":"一大屋子人","can":[["一大"]]},{"kieu":"vandung","de":"A：最近天气有些热，我天天喝绿茶。 B：我也是，昨天又买了＿＿＿。","goiY":"Nói: hôm qua lại mua cả một túi trà xanh to","mau":"一大包绿茶","can":[["一大"]]},{"kieu":"vandung","de":"A：您太客气了，怎么做了＿＿＿。 B：不客气，你们好不容易来一次，我特别开心。","goiY":"Khách ngại: chủ nhà nấu cả một bàn đầy thức ăn","mau":"一大桌子菜","can":[["一大"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Sáng nay tôi chưa ăn sáng đã đi làm, trưa đói cực kỳ, ăn liền một bát mì to.","dap":["今天早上我没吃早饭就去上班了，中午饿极了，吃了一大碗面条儿。","今天早上我没吃饭就去上班了，中午饿极了，吃了一大碗面条儿。"],"giai":"一大碗 nhấn mạnh ăn nhiều; ôn ……极了 (HSK 3)."},{"kieu":"dich","vn":"Sắp đến cổng ra, tôi lại dắt xe đạp công cộng đi bộ một đoạn ngắn.","dap":["快到出口时，我又把共享单车推了一小段。","快到出口的时候，我又推着共享单车走了一小段。"],"giai":"一小段 + từ mới 出口, 推, 共享单车."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể về một bữa ăn / một món quà làm em bất ngờ, có dùng 「一大 / 一小 + lượng từ」","mau":"生日那天，朋友们给我做了一大桌子菜，还送了我一大包小吃，我感动极了。","can":[["一大","一小"]]}]}]},{"so":"2","ten":"被动句“主语+让/叫+宾语+动词+其他成分”","tenVn":"Câu bị động 「Chủ ngữ + 让 / 叫 + tân ngữ + động từ + thành phần khác」 — bị / được (ai) làm gì (khẩu ngữ)","cauTruc":["Người / vật chịu tác động + 让 / 叫 + người gây ra hành động + (给) + động từ + 了 / bổ ngữ","Phủ định: Chủ ngữ + 没(有) + 让 / 叫 + tân ngữ + động từ + ……"],"giaiThich":"Đây là câu BỊ ĐỘNG kiểu khẩu ngữ: CHỦ NGỮ là người / vật CHỊU tác động (受事), sau 「让」 hoặc 「叫」 là người GÂY RA hành động (施事). Nghĩa giống câu chữ 「被」 (HSK 3), nhưng dùng nhiều khi nói chuyện. Ba quy tắc cần nhớ: (1) Sau 让 / 叫 BẮT BUỘC có tân ngữ — 被 có thể bỏ (书被借走了), còn 让 / 叫 thì không (✗ 书让借走了 → ✓ 书让同学借走了). (2) Động từ không đứng một mình, phía sau phải có 了, bổ ngữ kết quả / xu hướng / nơi chốn (吃了, 拿走了, 放到了……上); khẩu ngữ hay thêm 「给」 trước động từ: 门叫小明给关上了. (3) Phủ định / phó từ đặt TRƯỚC 让 / 叫: 没让他拿走, 都让我吃了 — 都 nói về chủ ngữ (月饼都……). Câu bị động thường mang ý KHÔNG MONG MUỐN (bị mất, bị ăn hết…), nhưng cũng có khi trung tính (视频让同学放到了互联网上). ⚠ Phân biệt với 让 / 叫 SAI KHIẾN đã học (bảo, khiến ai làm gì): 老师叫各个小组拍个短视频 — chủ ngữ 老师 là người RA LỆNH. Mẹo: thay 让 / 叫 bằng 被 mà câu vẫn đúng → đó là bị động. So sánh với câu chữ 把 (Bài 15, 16): 我同学把这个视频放到了互联网上 (chủ động) = 这个视频让我同学放到了互联网上 (bị động).","viDu":[{"zh":"后来这个视频让我同学放到了互联网上。","py":"Hòulái zhège shìpín ràng wǒ tóngxué fàngdào le hùliánwǎng shàng.","vn":"Sau đó video này được bạn cùng lớp tôi đăng lên mạng."},{"zh":"门叫小明给关上了。","py":"Mén jiào Xiǎomíng gěi guānshàng le.","vn":"Cửa bị Tiểu Minh đóng lại rồi."},{"zh":"不好意思，月饼都让我吃了。","py":"Bù hǎoyìsi, yuèbing dōu ràng wǒ chī le.","vn":"Xin lỗi nhé, bánh trung thu bị tôi ăn hết rồi."},{"zh":"那本小说让妹妹借走了，说不定她要看一个月呢。","py":"Nà běn xiǎoshuō ràng mèimei jièzǒu le, shuōbudìng tā yào kàn yí gè yuè ne.","vn":"Cuốn tiểu thuyết đó bị em gái mượn đi rồi, không chừng nó phải đọc cả tháng đấy. (ôn 说不定 – Bài 16 · điểm 3)"}],"loi":[{"sai":"我的书让借走了。","why":"Sau 让 / 叫 bị động bắt buộc có người làm; không nói được người làm thì dùng 被.","dung":"我的书让同学借走了。 / 我的书被借走了。"},{"sai":"月饼都让我吃。","why":"Động từ không đứng một mình — phải có 了 hoặc bổ ngữ.","dung":"月饼都让我吃了。"},{"sai":"我的自行车让别人没骑走。","why":"没 đặt TRƯỚC 让 / 叫, không chen giữa tân ngữ và động từ.","dung":"我的自行车没让别人骑走。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["后来这个视频","我同学放到了互联网上。"],"dap":[["让"]],"chon":["让","把","对"],"goiY":"“Sau đó video này được bạn cùng lớp tôi đăng lên mạng.”","giai":"Chủ ngữ chịu tác động (视频) + 让 + người làm."},{"kieu":"dien","phan":["门叫小明","关上了。"],"dap":[["给"]],"chon":["给","把","被"],"goiY":"“Cửa bị Tiểu Minh đóng lại rồi.”","giai":"Khẩu ngữ: 让 / 叫 + O + 给 + V."},{"kieu":"dien","phan":["不好意思，月饼都让我吃","。"],"dap":[["了"]],"chon":["了","过","着"],"goiY":"“Xin lỗi, bánh trung thu bị tôi ăn hết rồi.”","giai":"Động từ phải có 了 / bổ ngữ phía sau."},{"kieu":"dien","phan":["那双鞋叫别人买","了。"],"dap":[["走"]],"chon":["走","来","起"],"goiY":"“Đôi giày đó bị người khác mua mất rồi.”","giai":"Bổ ngữ xu hướng 走: mua đi mất."},{"kieu":"dien","phan":["我的手机","让弟弟拿走，还在桌子上呢。"],"dap":[["没"]],"chon":["没","别","都"],"goiY":"“Điện thoại của tôi không bị em trai lấy đi, vẫn còn trên bàn.”","giai":"Phủ định 没 đứng trước 让."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这个视频","让","我同学","放到了","互联网上"],"dap":["这个视频让我同学放到了互联网上。"],"goiY":"Video này được bạn cùng lớp tôi đăng lên mạng.","giai":"Chủ ngữ + 让 + người làm + V + 到 + nơi chốn."},{"kieu":"xep","manh":["我的自行车","让","朋友","骑走了"],"dap":["我的自行车让朋友骑走了。"],"goiY":"Xe đạp của tôi bị bạn đạp đi mất rồi.","giai":"让 + O + V + bổ ngữ 走 + 了."},{"kieu":"xep","manh":["蛋糕","都","叫","孩子们","给","吃完了"],"dap":["蛋糕都叫孩子们给吃完了。"],"goiY":"Bánh ngọt bị bọn trẻ ăn hết sạch rồi.","giai":"都 trước 叫; 给 ngay trước động từ."},{"kieu":"dungsai","cau":"那本书让借走了。","dung":false,"sua":"那本书让同学借走了。","giai":"Sau 让 bị động phải có người làm."},{"kieu":"dungsai","cau":"我的钱包叫小偷给偷了。","dung":true,"giai":"Đúng: 叫 + người làm + 给 + V + 了."},{"kieu":"dungsai","cau":"饺子都让我吃。","dung":false,"sua":"饺子都让我吃了。","giai":"Thiếu 了 sau động từ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 91)","huongDan":"Hoàn thành đối thoại, dùng câu bị động 「主语+让/叫+宾语+动词+其他成分」","cau":[{"kieu":"vandung","de":"A：那双鞋你没买到吗？ B：对，＿＿＿买去了。","goiY":"Nói: đôi giày đã bị người khác mua mất (让 / 叫 + người làm)","mau":"让别人","can":[["让","叫"]]},{"kieu":"vandung","de":"A：杯子在哪儿呢？ B：杯子＿＿＿。","goiY":"Nói: cái cốc bị em gái lấy đi rồi","mau":"叫妹妹拿走了","can":[["让","叫"]]},{"kieu":"vandung","de":"A：你的手机呢？ B：＿＿＿。","goiY":"Nói cả câu: điện thoại của tôi bị em trai cầm đi chơi rồi","mau":"我的手机让弟弟拿去玩儿了","can":[["让","叫"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Bánh trung thu của tôi bị em trai ăn hết rồi.","dap":["我的月饼都让弟弟吃了。","我的月饼都叫弟弟吃了。","我的月饼都让弟弟给吃了。","我的月饼让弟弟吃完了。"],"giai":"Chủ ngữ chịu tác động + 让 / 叫 + người làm + V + 了."},{"kieu":"dich","vn":"Video của chúng tôi được bạn cùng lớp đăng lên mạng, rất nhiều người vào bấm thích.","dap":["我们的视频让同学放到了互联网上，很多人都来点赞。","我们的视频叫同学放到了互联网上，很多人都来点赞。"],"giai":"Bị động 让 + từ mới 互联网, 点赞."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một chuyện “xui”: đồ của em bị ai đó lấy / ăn / mượn mất, có dùng 「让 / 叫」 bị động","mau":"我放在冰箱里的蛋糕叫室友给吃了，我只好又去买了一个。","can":[["让","叫"]]}]}]},{"so":"3","ten":"语气副词“到底”","tenVn":"Phó từ ngữ khí 「到底」 — rốt cuộc, rốt cục (truy hỏi đến cùng)","cauTruc":["Chủ ngữ + 到底 + câu hỏi (đại từ nghi vấn / V不V / A还是B)?","到底 + 谁 / 哪…… + ……? (chủ ngữ là đại từ nghi vấn → 到底 đứng trước)"],"giaiThich":"「到底」 dùng trong CÂU HỎI để TRUY HỎI, hỏi dồn cho ra lẽ — giống tiếng Việt “rốt cuộc, rốt cục, thế rốt cuộc là…”; thường lộ vẻ sốt ruột, muốn có câu trả lời dứt khoát. Rất hay dùng trong khẩu ngữ. Vị trí: sau chủ ngữ, trước vị ngữ (你到底去不去？); nếu chủ ngữ là đại từ nghi vấn thì 到底 phải đứng TRƯỚC chủ ngữ (到底谁去？ ✗ 谁到底去？). ⚠ Câu có 到底 phải là câu hỏi dùng đại từ nghi vấn (什么、怎么、为什么、哪…), câu hỏi chính phản (来不来) hoặc 还是 (A还是B) — KHÔNG dùng với 吗 (✗ 你到底去吗？). Liên hệ bài cũ: 「究竟」 (Bài 14 · điểm 1) cùng nghĩa, nhưng 究竟 trang trọng, thiên về văn viết; 到底 thân mật, khẩu ngữ. (到底 còn có nghĩa khác “cuối cùng thì, rốt cục cũng” trong câu trần thuật — gần 终于 — sẽ gặp sau; bài này chỉ học 到底 trong câu hỏi.)","viDu":[{"zh":"科技到底对世界产生了怎样的影响？","py":"Kējì dàodǐ duì shìjiè chǎnshēng le zěnyàng de yǐngxiǎng?","vn":"Rốt cuộc công nghệ đã tạo ra ảnh hưởng như thế nào đối với thế giới?"},{"zh":"你们到底还来不来？","py":"Nǐmen dàodǐ hái lái bu lái?","vn":"Rốt cuộc các bạn còn đến hay không?"},{"zh":"你到底是怎么想的？为什么不同意？","py":"Nǐ dàodǐ shì zěnme xiǎng de? Wèishénme bù tóngyì?","vn":"Rốt cuộc bạn nghĩ thế nào? Sao lại không đồng ý?"},{"zh":"无论去还是不去，你今天都得告诉我：你到底是怎么想的？","py":"Wúlùn qù háishi bú qù, nǐ jīntiān dōu děi gàosu wǒ: nǐ dàodǐ shì zěnme xiǎng de?","vn":"Dù đi hay không đi, hôm nay bạn cũng phải nói cho tôi biết: rốt cuộc bạn nghĩ thế nào? (ôn 无论……都…… – Bài 12 · điểm 3)"}],"loi":[{"sai":"你到底去吗？","why":"到底 không đi với 吗; dùng câu hỏi chính phản / đại từ nghi vấn.","dung":"你到底去不去？"},{"sai":"谁到底拿了我的手机？","why":"Chủ ngữ là đại từ nghi vấn → 到底 đứng trước nó.","dung":"到底谁拿了我的手机？"},{"sai":"你到底喜欢这个还是那个吗？","why":"Câu đã có 还是 thì không thêm 吗.","dung":"你到底喜欢这个还是那个？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["科技","对世界产生了怎样的影响？"],"dap":[["到底"]],"chon":["到底","终于","一定"],"goiY":"“Rốt cuộc công nghệ đã tạo ra ảnh hưởng như thế nào …?”","giai":"Câu hỏi truy vấn → 到底."},{"kieu":"dien","phan":["你们到底还来","来？"],"dap":[["不"]],"chon":["不","吗","没"],"goiY":"“Rốt cuộc các bạn còn đến hay không?”","giai":"到底 + V不V; không dùng 吗."},{"kieu":"dien","phan":["你到底是怎么想的？为什么不","？"],"dap":[["同意"]],"chon":["同意","讨论","预约"],"goiY":"“Rốt cuộc bạn nghĩ thế nào? Sao không đồng ý?”","giai":"不同意 = không đồng ý."},{"kieu":"dien","phan":["到底","把视频放到了互联网上？"],"dap":[["谁"]],"chon":["谁","什么","哪儿"],"goiY":"“Rốt cuộc là ai đã đăng video lên mạng?”","giai":"到底 + 谁 (chủ ngữ là đại từ nghi vấn)."},{"kieu":"dien","phan":["这次旅行的","到底是多少？我们一起算一下吧。"],"dap":[["费用"]],"chon":["费用","原因","说明"],"goiY":"“Rốt cuộc chi phí chuyến du lịch này là bao nhiêu?”","giai":"费用 = chi phí (từ mới của bài)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["你们","到底","还","来不来"],"dap":["你们到底还来不来？"],"goiY":"Rốt cuộc các bạn còn đến hay không?","giai":"Chủ ngữ + 到底 + V不V?"},{"kieu":"xep","manh":["到底","谁","把视频","放到了","互联网上"],"dap":["到底谁把视频放到了互联网上？"],"goiY":"Rốt cuộc ai đã đăng video lên mạng?","giai":"到底 + 谁 + 把……"},{"kieu":"xep","manh":["你","到底","是坐公交车","还是","骑共享单车"],"dap":["你到底是坐公交车还是骑共享单车？"],"goiY":"Rốt cuộc bạn đi xe buýt hay đạp xe đạp công cộng?","giai":"到底 + (是) A 还是 B?"},{"kieu":"dungsai","cau":"你到底喜欢不喜欢这部电影吗？","dung":false,"sua":"你到底喜欢不喜欢这部电影？","giai":"Câu chính phản + 到底, không thêm 吗."},{"kieu":"dungsai","cau":"这个问题到底怎么解决？","dung":true,"giai":"Đúng: 到底 + 怎么 + V."},{"kieu":"dungsai","cau":"谁到底说得对？","dung":false,"sua":"到底谁说得对？","giai":"Chủ ngữ là 谁 → 到底 đứng trước."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 93)","huongDan":"Hoàn thành câu, có dùng 「到底」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"你们＿＿＿呢？（点赞）","goiY":"Hỏi dồn: rốt cuộc vì sao các bạn đều bấm thích video này","mau":"到底为什么都给这个视频点赞","can":[["到底"],["点赞"]]},{"kieu":"vandung","de":"这个AI眼镜＿＿＿？还是请他＿＿＿。（说明）","goiY":"Hỏi: rốt cuộc dùng thế nào? → nhờ anh ấy hướng dẫn cho","mau":"到底怎么用 / 给我们说明一下吧","can":[["到底"],["说明"]]},{"kieu":"vandung","de":"这次旅行＿＿＿？咱们还是一起算一下吧。（费用）","goiY":"Hỏi: rốt cuộc chi phí là bao nhiêu","mau":"的费用到底是多少","can":[["到底"],["费用"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Rốt cuộc bạn có đi hay không? Mọi người đều đang đợi bạn đấy.","dap":["你到底去不去？大家都在等你呢。","你到底去不去？大家都在等你。"],"giai":"到底 + V不V."},{"kieu":"dich","vn":"Rốt cuộc công nghệ đã thay đổi cuộc sống của chúng ta như thế nào?","dap":["科技到底怎样改变了我们的生活？","科技到底是怎么改变我们的生活的？","科技到底怎么改变了我们的生活？"],"giai":"到底 + đại từ nghi vấn 怎样 / 怎么."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em bàn mãi không quyết định quay video gì. Hãy hỏi dồn bạn bằng 「到底」","mau":"你到底想拍什么样的短视频？是介绍美食，还是介绍著名景点？","can":[["到底"]]}]}]},{"so":"4","ten":"转折复句“……，然而……”","tenVn":"Câu phức chuyển ngoặt 「……，然而……」 — …, thế nhưng / tuy nhiên …","cauTruc":["Vế 1，然而 + vế 2 (tương phản với vế 1 / trái với dự đoán)","Vế 1，然而 + (chủ ngữ) + 又 / 却 / 还 + ……"],"giaiThich":"「然而」 là liên từ chuyển ngoặt, đặt ở ĐẦU vế sau (trước chủ ngữ của vế sau, nếu có): nội dung sau 然而 TƯƠNG PHẢN với vế trước hoặc KHÔNG GIỐNG điều người ta dự đoán — giống tiếng Việt “thế nhưng, tuy nhiên, vậy mà”. Nghĩa gần 但是 / 可是 / 不过 (Bài 2), nhưng 然而 trang trọng hơn, hay gặp trong văn viết, bài báo, bài phát biểu. Sau 然而 hay có 又 / 却 (Bài 16 · điểm 4) / 还 để nhấn mạnh sự trái ngược: 然而又很担心…, 然而天却…. ⚠ (1) 然而 KHÔNG đứng sau chủ ngữ như phó từ (✗ 她然而……). (2) Hai vế phải thật sự trái ngược; nếu chỉ bổ sung cùng chiều thì dùng 而且 / 并且 (✗ 菜好吃，然而价格也不贵). (3) Câu giả thiết “cho dù … cũng …” dùng 即使……也…… (Bài 11), không dùng 然而. Có thể dùng 虽然……，然而…… nhưng 虽然……，但是…… thông dụng hơn.","viDu":[{"zh":"由于工作等原因，她需要经常出差，然而又很担心猫的安全。","py":"Yóuyú gōngzuò děng yuányīn, tā xūyào jīngcháng chūchāi, rán'ér yòu hěn dānxīn māo de ānquán.","vn":"Vì công việc và những lý do khác, chị phải thường xuyên đi công tác, thế nhưng lại rất lo cho sự an toàn của con mèo."},{"zh":"毕业旅行现在越来越流行，然而由于学生没什么社会和生活经验，可能会遇到各种问题。","py":"Bìyè lǚxíng xiànzài yuèláiyuè liúxíng, rán'ér yóuyú xuésheng méi shénme shèhuì hé shēnghuó jīngyàn, kěnéng huì yùdào gèzhǒng wèntí.","vn":"Du lịch tốt nghiệp bây giờ ngày càng thịnh hành, tuy nhiên vì học sinh chưa có mấy kinh nghiệm xã hội và cuộc sống nên có thể gặp đủ thứ vấn đề."},{"zh":"春天应该是花开的季节，然而由于前一段时间下大雪，现在花都没开。","py":"Chūntiān yīnggāi shì huā kāi de jìjié, rán'ér yóuyú qián yí duàn shíjiān xià dàxuě, xiànzài huā dōu méi kāi.","vn":"Mùa xuân lẽ ra là mùa hoa nở, vậy mà vì thời gian trước tuyết rơi dày nên giờ hoa vẫn chưa nở."},{"zh":"我们本来打算周末去爬山，然而那天却下了一整天的雨。","py":"Wǒmen běnlái dǎsuàn zhōumò qù páshān, rán'ér nàtiān què xià le yì zhěngtiān de yǔ.","vn":"Chúng tôi vốn định cuối tuần đi leo núi, vậy mà hôm đó lại mưa suốt cả ngày. (ôn 却 – Bài 16 · điểm 4)"}],"loi":[{"sai":"她需要经常出差，她然而又很担心猫的安全。","why":"然而 là liên từ, đứng ĐẦU vế sau, không đứng sau chủ ngữ.","dung":"她需要经常出差，然而又很担心猫的安全。"},{"sai":"这家饭店的菜很好吃，然而价格也不贵。","why":"Hai vế cùng chiều (đều là ưu điểm) → dùng 而且, không dùng 然而.","dung":"这家饭店的菜很好吃，而且价格也不贵。"},{"sai":"即使明天下雨，然而我们也去。","why":"Giả thiết “cho dù … cũng …” dùng 即使……也……, không dùng 然而.","dung":"即使明天下雨，我们也去。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["由于工作等原因，她需要经常出差，","又很担心猫的安全。"],"dap":[["然而"]],"chon":["然而","而且","于是"],"goiY":"“… phải thường xuyên đi công tác, thế nhưng lại rất lo cho con mèo.”","giai":"Hai vế trái ngược → 然而."},{"kieu":"dien","phan":["毕业旅行越来越流行，然而由于学生没什么社会经验，可能会","各种问题。"],"dap":[["遇到"]],"chon":["遇到","提出","推出"],"goiY":"“… có thể gặp đủ thứ vấn đề.”","giai":"遇到 + 问题 = gặp vấn đề."},{"kieu":"dien","phan":["春天应该是花开的季节，然而现在花都","开。"],"dap":[["没"]],"chon":["没","才","就"],"goiY":"“… vậy mà giờ hoa vẫn chưa nở.”","giai":"都没 + V: đều chưa."},{"kieu":"dien","phan":["我们计划了一周，然而到了出发那天，天","下起了大雨。"],"dap":[["却"]],"chon":["却","就","才"],"goiY":"“… vậy mà đến hôm xuất phát, trời lại đổ mưa to.” (ôn 却 – Bài 16)","giai":"然而……却……: nhấn mạnh trái ngược."},{"kieu":"dien","phan":["上门服务很方便，","现有服务人员有些还不够专业。"],"dap":[["然而"]],"chon":["然而","所以","因为"],"goiY":"“Dịch vụ tận nhà rất tiện, tuy nhiên một số nhân viên hiện có chưa đủ chuyên nghiệp.”","giai":"Ưu điểm ↔ vấn đề → 然而."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["她","很想去旅行","，","然而","工作","太忙了"],"dap":["她很想去旅行，然而工作太忙了。"],"goiY":"Cô ấy rất muốn đi du lịch, thế nhưng công việc bận quá.","giai":"Vế 1，然而 + vế 2."},{"kieu":"xep","manh":["春天","应该是","花开的季节","，","然而","现在","花都没开"],"dap":["春天应该是花开的季节，然而现在花都没开。"],"goiY":"Mùa xuân lẽ ra là mùa hoa nở, vậy mà giờ hoa vẫn chưa nở.","giai":"Dự đoán (应该) ↔ thực tế → 然而."},{"kieu":"xep","manh":["我们","准备了很久","，","然而","比赛","却","取消了"],"dap":["我们准备了很久，然而比赛却取消了。"],"goiY":"Chúng tôi chuẩn bị rất lâu, vậy mà cuộc thi lại bị hủy.","giai":"然而 + chủ ngữ + 却 + V."},{"kieu":"dungsai","cau":"大家都在等他，他然而没有来。","dung":false,"sua":"大家都在等他，然而他没有来。","giai":"然而 đứng trước chủ ngữ vế sau."},{"kieu":"dungsai","cau":"这家饭店的菜很好吃，然而价格也不贵。","dung":false,"sua":"这家饭店的菜很好吃，而且价格也不贵。","giai":"Hai vế cùng chiều → 而且."},{"kieu":"dungsai","cau":"他学了三年中文，然而还是不敢开口说。","dung":true,"giai":"Đúng: học lâu ↔ vẫn không dám nói (trái dự đoán)."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 95)","huongDan":"Hoàn thành câu, có dùng 「然而」","cau":[{"kieu":"vandung","de":"我们计划了一周，＿＿＿，天却下起了大雨。","goiY":"Nêu điều trái dự đoán: vậy mà đến hôm xuất phát","mau":"然而到了出发那天","can":[["然而"]]},{"kieu":"vandung","de":"他想站起来，＿＿＿，怎么也站不起来。","goiY":"Nêu lý do trái ý muốn: nhưng chân đau quá","mau":"然而腿实在太疼了","can":[["然而"]]},{"kieu":"vandung","de":"他很想出去旅行，＿＿＿。","goiY":"Nêu thực tế trái mong muốn: công việc quá bận, mãi không có thời gian","mau":"然而工作太忙，一直没有时间","can":[["然而"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cô ấy rất muốn nuôi một con mèo, thế nhưng lại phải thường xuyên đi công tác.","dap":["她很想养一只猫，然而又需要经常出差。","她很想养一只猫，然而她需要经常出差。","她很想养一只猫，然而又要经常出差。"],"giai":"Mong muốn ↔ thực tế → 然而 (+ 又)."},{"kieu":"dich","vn":"Dịch vụ tận nhà rất tiện lợi, tuy nhiên một số nhân viên phục vụ vẫn chưa đủ chuyên nghiệp.","dap":["上门服务很方便，然而有些服务人员还不够专业。","上门服务很方便，然而现有服务人员有些还不够专业。"],"giai":"然而 + từ mới 上门, 现有."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể một kế hoạch của em không thành như mong đợi, có dùng 「然而」","mau":"我本来打算周末去公园拍短视频，然而那天却下了一整天的雨。","can":[["然而"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-19.html"] = [{"so":"1","ten":"选择复句“不是……，就是……”","tenVn":"Câu phức lựa chọn 「不是……，就是……」 — không phải … thì là …","cauTruc":["(Chủ ngữ) + 不是 + A，就是 + B","A, B: hai khả năng / hai việc cùng loại (cụm động từ, danh từ…) — chắc chắn là một trong hai"],"giaiThich":"Câu phức biểu thị quan hệ LỰA CHỌN: trong hai khả năng A và B, chắc chắn có một cái đúng — “không phải A thì là B”, “không A thì B”. Hay dùng trong hai trường hợp: (1) PHỎNG ĐOÁN chắc chắn một trong hai: 估计不是刮风，就是下雨; (2) KỂ việc lặp đi lặp lại, lúc thì A lúc thì B, nhiều khi mang ý than “toàn là…, suốt ngày…”: 最近很忙，不是出差，就是加班. A và B nên cùng loại, cùng kết cấu (cụm động từ với cụm động từ). Có chung chủ ngữ thì chủ ngữ đứng TRƯỚC 不是. Vế sau bắt buộc là 就是 (✗ 就 + V). ⚠ Phân biệt quan trọng với 不是……，而是…… (Bài 11 · điểm 3): 不是 A，而是 B = phủ định A, KHẲNG ĐỊNH B (biết chắc là B); 不是 A，就是 B = A HOẶC B, một trong hai (chưa biết chắc, hoặc cả hai luân phiên). VD: 她不是中国人，而是韩国人 (cô ấy là người Hàn) ≠ 她不是中国人，就是韩国人 (đoán: hoặc người Trung, hoặc người Hàn). Người Việt cũng đừng nhầm với 不……就…… (“hễ không… thì…”, câu điều kiện) hay 不……也…… (Bài 9). Gần nghĩa: 或者 (hoặc — liệt kê nhẹ nhàng, không có ý “chắc chắn một trong hai”).","viDu":[{"zh":"有时候不是忘词，就是忘记做动作。","py":"Yǒushíhou bú shì wàng cí, jiùshì wàngjì zuò dòngzuò.","vn":"Có lúc không phải quên lời thì là quên làm động tác."},{"zh":"周末的时候，小文不是在家看书，就是出去看演出。","py":"Zhōumò de shíhou, Xiǎowén bú shì zài jiā kànshū, jiùshì chūqu kàn yǎnchū.","vn":"Cuối tuần, Tiểu Văn không ở nhà đọc sách thì là ra ngoài xem biểu diễn."},{"zh":"杨同乐最近很忙，不是去外地出差，就是在公司加班。","py":"Yáng Tónglè zuìjìn hěn máng, bú shì qù wàidì chūchāi, jiùshì zài gōngsī jiābān.","vn":"Dương Đồng Lạc dạo này rất bận, không đi công tác tỉnh ngoài thì là tăng ca ở công ty."},{"zh":"这几天天气真奇怪，不是刮大风，就是下大雨，加上降温，好多人都感冒了。","py":"Zhè jǐ tiān tiānqì zhēn qíguài, bú shì guā dàfēng, jiùshì xià dàyǔ, jiāshang jiàngwēn, hǎoduō rén dōu gǎnmào le.","vn":"Mấy hôm nay thời tiết lạ thật, không gió to thì mưa lớn, cộng thêm trời trở lạnh, nhiều người bị cảm. (ôn 加上 – Bài 14 · điểm 3)"}],"loi":[{"sai":"她不是中国人，就是韩国人，我跟她聊过，她是韩国人。","why":"Đã biết chắc là người Hàn (phủ định A, khẳng định B) → phải dùng 不是……而是…… (Bài 11).","dung":"她不是中国人，而是韩国人。"},{"sai":"不是他在家看书，就是出去看演出。","why":"Chung chủ ngữ thì chủ ngữ đứng TRƯỚC 不是.","dung":"他不是在家看书，就是出去看演出。"},{"sai":"最近很忙，不是出差，就加班。","why":"Vế sau phải là 就是, không dùng 就 + động từ.","dung":"最近很忙，不是出差，就是加班。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["有时候","忘词，就是忘记做动作。"],"dap":[["不是"]],"chon":["不是","不但","虽然"],"goiY":"“Có lúc không phải quên lời thì là quên động tác.”","giai":"Vế sau có 就是 → vế trước dùng 不是 (lựa chọn một trong hai)."},{"kieu":"dien","phan":["周末的时候，小文不是在家看书，","出去看演出。"],"dap":[["就是"]],"chon":["就是","而是","还是"],"goiY":"“… không ở nhà đọc sách thì là ra ngoài xem biểu diễn.” (lúc thế này, lúc thế kia)","giai":"Hai việc luân phiên, một trong hai → 不是……，就是……"},{"kieu":"dien","phan":["杨同乐最近很忙，不是去外地出差，就是在公司","。"],"dap":[["加班"]],"chon":["加班","度假","散步"],"goiY":"“… không đi công tác thì là tăng ca ở công ty.”","giai":"Rất bận → 出差 / 加班 cùng loại công việc."},{"kieu":"dien","phan":["她不是中国人，","韩国人，我跟她聊过。"],"dap":[["而是"]],"chon":["而是","就是","或者"],"goiY":"“Cô ấy không phải người Trung Quốc mà là người Hàn, tôi từng nói chuyện với cô ấy.” (biết chắc)","giai":"Biết chắc → phủ định A, khẳng định B → 不是……而是…… (Bài 11 · điểm 3), không dùng 就是."},{"kieu":"dien","phan":["这几天不是刮大风，就是下大雨，","降温，好多人都感冒了。"],"dap":[["加上"]],"chon":["加上","于是","甚至"],"goiY":"“… cộng thêm trời trở lạnh, nhiều người bị cảm.” (ôn Bài 14)","giai":"加上 = cộng thêm nguyên nhân (Bài 14 · điểm 3)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["周末","小文","不是","在家看书","，","就是","出去看演出"],"dap":["周末小文不是在家看书，就是出去看演出。","小文周末不是在家看书，就是出去看演出。"],"goiY":"Cuối tuần Tiểu Văn không ở nhà đọc sách thì là ra ngoài xem biểu diễn.","giai":"Chủ ngữ + 不是 A，就是 B."},{"kieu":"xep","manh":["估计","明天","不是","刮风","，","就是","下雨"],"dap":["估计明天不是刮风，就是下雨。","明天估计不是刮风，就是下雨。"],"goiY":"Chắc là ngày mai không có gió thì cũng mưa.","giai":"Phỏng đoán một trong hai: 估计 + 不是……就是……"},{"kieu":"xep","manh":["他","每天晚上","不是","去公园跑步","，","就是","去游泳"],"dap":["他每天晚上不是去公园跑步，就是去游泳。"],"goiY":"Tối nào anh ấy cũng không đi công viên chạy bộ thì là đi bơi.","giai":"Trạng ngữ thời gian đứng trước 不是."},{"kieu":"dungsai","cau":"杨同乐最近很忙，不是去外地出差，就是在公司加班。","dung":true,"giai":"Đúng: hai việc luân phiên, cùng kết cấu."},{"kieu":"dungsai","cau":"最近很忙，不是出差，就加班。","dung":false,"sua":"最近很忙，不是出差，就是加班。","giai":"Vế sau phải là 就是."},{"kieu":"dungsai","cau":"那本书不是小王的，就是小李的，你看，上面写着小李的名字。","dung":false,"sua":"那本书不是小王的，而是小李的，你看，上面写着小李的名字。","giai":"Đã biết chắc là của Tiểu Lý → 不是……而是……"}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 101)","huongDan":"Hoàn thành đối thoại, có dùng 「不是……，就是……」","cau":[{"kieu":"vandung","de":"A：明天天气看起来不太好啊。 B：是啊，估计＿＿＿，就是下雨。","goiY":"Đoán: không phải (gió to / trời âm u) thì là mưa","mau":"不是刮大风","can":[["不是"]]},{"kieu":"vandung","de":"A：听说老张病好了以后，开始天天锻炼身体了。 B：是的，他＿＿＿，＿＿＿。","goiY":"Kể hai cách ông ấy tập luyện luân phiên mỗi ngày","mau":"不是早上去公园跑步，就是晚上去体育馆游泳","can":[["不是"],["就是"]]},{"kieu":"vandung","de":"A：你明天去哪儿？ B：我明天＿＿＿，＿＿＿。","goiY":"Chưa chắc, một trong hai nơi","mau":"不是去图书馆看书，就是去书店买书","can":[["不是"],["就是"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Dạo này anh ấy rất bận, không đi công tác thì là tăng ca.","dap":["他最近很忙，不是出差，就是加班。","他最近很忙，不是去出差，就是在加班。","最近他很忙，不是出差，就是加班。"],"giai":"不是 A，就是 B — hai việc luân phiên."},{"kieu":"dich","vn":"Cuối tuần tôi không ở nhà đọc sách thì là đi xem biểu diễn với bạn.","dap":["周末我不是在家看书，就是和朋友去看演出。","我周末不是在家看书，就是跟朋友去看演出。","周末我不是在家看书，就是跟朋友一起去看演出。"],"giai":"Chủ ngữ đứng trước 不是."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể thói quen buổi tối / cuối tuần của em, có dùng 「不是……，就是……」","mau":"晚上我不是在宿舍复习生词，就是去操场跑步。","can":[["不是"],["就是"]]}]}]},{"so":"2","ten":"固定格式“动词+一×是一×”","tenVn":"Cấu trúc cố định 「V + 一× 是一×」 — làm được … nào hay … ấy","cauTruc":["(能/多) + V + 一 + lượng từ (hoặc 点儿) + 是 + 一 + lượng từ (hoặc 点儿)","能懂一点儿是一点儿 · 看一页是一页 · 做一件是一件 · 解决一个是一个"],"giaiThich":"Nhấn mạnh: trong điều kiện có hạn (thời gian ít, việc nhiều, sức có hạn, trình độ chưa đủ), cứ cố hết sức làm được bao nhiêu hay bấy nhiêu — tiếng Việt: “được chút nào hay chút ấy”, “đọc được trang nào hay trang ấy”, “làm được việc nào hay việc ấy”. × là lượng từ (页, 件, 个, 天, 课…) hoặc 点儿; HAI BÊN PHẢI GIỐNG NHAU (一点儿……一点儿, 一页……一页). Động từ chỉ xuất hiện một lần ở đầu, sau 是 không lặp lại động từ. Trước động từ hay có 能 / 多 (能懂一点儿是一点儿, 多吃一点儿是一点儿). Ngữ khí tích cực, chấp nhận hoàn cảnh và kiên trì từng bước; hay đi cùng 慢慢, 别着急, 先…. Hay đứng ở vế sau, vế trước nêu khó khăn: 虽然这本书很厚，但是…看一页是一页. Đừng nhầm với 一A一B (Bài 17 · điểm 2) hay 一+量词+比+一+量词 (Bài 13 · điểm 2): ở đây phải có động từ đứng trước và 是 ở giữa.","viDu":[{"zh":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","py":"Zánmen xiān zuòzuo gōngkè, tíqián liǎojiě xià, néng dǒng yìdiǎnr shì yìdiǎnr.","vn":"Chúng mình cứ tìm hiểu trước đã, hiểu được chút nào hay chút ấy."},{"zh":"虽然这本书很厚，但是我还是要看，看一页是一页，最后一定能看完。","py":"Suīrán zhè běn shū hěn hòu, dànshì wǒ háishi yào kàn, kàn yí yè shì yí yè, zuìhòu yídìng néng kànwán.","vn":"Tuy cuốn sách này rất dày nhưng tôi vẫn muốn đọc, đọc được trang nào hay trang ấy, cuối cùng nhất định sẽ đọc xong."},{"zh":"你能多吃一点儿是一点儿，这样身体才能好起来。","py":"Nǐ néng duō chī yìdiǎnr shì yìdiǎnr, zhèyàng shēntǐ cáinéng hǎoqǐlai.","vn":"Con ăn thêm được chút nào hay chút ấy, như vậy sức khoẻ mới khá lên được."},{"zh":"即使每天只有十分钟，我也坚持背生词，背一个是一个。","py":"Jíshǐ měitiān zhǐyǒu shí fēnzhōng, wǒ yě jiānchí bèi shēngcí, bèi yí gè shì yí gè.","vn":"Cho dù mỗi ngày chỉ có mười phút, tôi cũng kiên trì học thuộc từ mới, thuộc được từ nào hay từ ấy. (ôn 即使……也…… – Bài 11 · điểm 1)"}],"loi":[{"sai":"你多吃一点儿是一些。","why":"Hai bên phải cùng một lượng từ: 一点儿……一点儿.","dung":"你多吃一点儿是一点儿。"},{"sai":"看一页看一页，最后一定能看完。","why":"Giữa hai vế phải có 是; động từ không lặp lại sau 是.","dung":"看一页是一页，最后一定能看完。"},{"sai":"我们一点儿学是一点儿。","why":"Động từ đứng TRƯỚC 一×: V + 一点儿 + 是 + 一点儿.","dung":"我们学一点儿是一点儿。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["咱们先做做功课，提前了解下，能懂一点儿","一点儿。"],"dap":[["是"]],"chon":["是","就","也"],"goiY":"“… hiểu được chút nào hay chút ấy.”","giai":"V + 一点儿 + 是 + 一点儿."},{"kieu":"dien","phan":["虽然这本书很厚，但是我还是要看，看一","是一页。"],"dap":[["页"]],"chon":["页","本","次"],"goiY":"“… đọc được trang nào hay trang ấy.”","giai":"Hai lượng từ phải giống nhau: 一页……一页."},{"kieu":"dien","phan":["你能多吃一点儿是一点儿，这样身体","能好起来。"],"dap":[["才"]],"chon":["才","就","都"],"goiY":"“… như vậy sức khoẻ mới khá lên được.”","giai":"这样……才…… = có như thế mới… (điều kiện cần)."},{"kieu":"dien","phan":["事情实在太多了，别着急，慢慢做，做一","是一件。"],"dap":[["件"]],"chon":["件","个","遍"],"goiY":"“… làm được việc nào hay việc ấy.”","giai":"事情 dùng lượng từ 件; hai bên phải cùng 件."},{"kieu":"dien","phan":["即使每天只有十分钟，我","坚持背生词，背一个是一个。"],"dap":[["也"]],"chon":["也","就","才"],"goiY":"“Cho dù mỗi ngày chỉ có mười phút, tôi cũng kiên trì…” (ôn Bài 11)","giai":"即使……，Sub + 也…… (Bài 11 · điểm 1)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["咱们","先做做功课","，","能懂","一点儿","是","一点儿"],"dap":["咱们先做做功课，能懂一点儿是一点儿。"],"goiY":"Chúng mình cứ chuẩn bị trước, hiểu được chút nào hay chút ấy.","giai":"能 + V + 一点儿是一点儿."},{"kieu":"xep","manh":["别着急","，","慢慢做","，","做","一件","是","一件"],"dap":["别着急，慢慢做，做一件是一件。"],"goiY":"Đừng vội, làm từ từ, làm được việc nào hay việc ấy.","giai":"V + 一件 + 是 + 一件."},{"kieu":"xep","manh":["这么多问题","，","我们","解决","一个","是","一个"],"dap":["这么多问题，我们解决一个是一个。"],"goiY":"Nhiều vấn đề thế này, chúng ta giải quyết được cái nào hay cái ấy.","giai":"V + 一个是一个."},{"kieu":"dungsai","cau":"你能多吃一点儿是一点儿，这样身体才能好起来。","dung":true,"giai":"Đúng: 能多 + V + 一点儿是一点儿."},{"kieu":"dungsai","cau":"看一页看一页，最后一定能看完。","dung":false,"sua":"看一页是一页，最后一定能看完。","giai":"Thiếu 是 ở giữa; không lặp động từ."},{"kieu":"dungsai","cau":"这些生词，我每天记一个是两个。","dung":false,"sua":"这些生词，我每天记一个是一个。","giai":"Hai bên phải cùng là 一 + cùng lượng từ."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 103–104)","huongDan":"Hoàn thành đối thoại, có dùng 「动词 + 一×是一×」","cau":[{"kieu":"vandung","de":"A：我们＿＿＿，最后一定都能学会。 B：是的，现在就开始吧。","goiY":"Mỗi ngày học được chút nào hay chút ấy","mau":"每天学一点儿是一点儿","can":[["是一"]]},{"kieu":"vandung","de":"A：事情实在太多了，你能做完吗？ B：慢慢做，＿＿＿。","goiY":"Làm được việc nào hay việc ấy","mau":"做一件是一件","can":[["是一"]]},{"kieu":"vandung","de":"A：这么多问题能解决完吗？ B：＿＿＿，＿＿＿。","goiY":"Khuyên đừng vội; giải quyết được cái nào hay cái ấy","mau":"别着急，咱们慢慢来，解决一个是一个","can":[["是一"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Không sao, chúng ta tìm hiểu trước một chút, hiểu được chút nào hay chút ấy.","dap":["没事，咱们提前了解一下，能懂一点儿是一点儿。","没关系，我们先了解一下，能懂一点儿是一点儿。","没事，我们提前了解一下，能懂一点儿是一点儿。"],"giai":"能懂一点儿是一点儿."},{"kieu":"dich","vn":"Cuốn sách tuy dày, nhưng đọc được trang nào hay trang ấy, cuối cùng nhất định đọc xong.","dap":["这本书虽然很厚，但是看一页是一页，最后一定能看完。","虽然这本书很厚，但是看一页是一页，最后一定能看完。"],"giai":"虽然……但是…… + 看一页是一页."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Khuyên một người bạn đang thấy từ mới quá nhiều, có dùng 「V + 一×是一×」","mau":"生词虽然多，但是别着急，每天记一个是一个，坚持下去就能记住。","can":[["是一"]]}]}]},{"so":"3","ten":"“把”字句“主语+把+宾语+动词+动量补语”","tenVn":"Câu chữ 「把」: Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ động lượng — làm việc gì với đối tượng mấy lần","cauTruc":["Chủ ngữ + 把 + tân ngữ (xác định) + động từ + (了) + số từ + động lượng từ (遍 / 次 / 下 / 趟)","把故事了解了一遍 · 把这个动作做了好几次 · 把这本书看了几遍"],"giaiThich":"Một dạng của câu chữ 把: nhấn mạnh động tác tác động lên tân ngữ BAO NHIÊU LẦN. “Bổ ngữ động lượng” = số từ + động lượng từ, đứng sau động từ: 遍 (một lượt trọn vẹn từ đầu đến cuối — đọc, xem, nghe, viết, tập, giảng), 次 (lần — nói chung), 下 (một cái, nhẹ và nhanh — 敲了三下门), 趟 (chuyến đi về). Việc đã xảy ra thì có 了 sau động từ; con số hay gặp: 一遍, 两次, 几遍, 好几次, 十几遍. Tân ngữ sau 把 phải là thứ XÁC ĐỊNH (这本书, 故事, 这个动作 — ✗ 一本书). Phó từ (又, 已经, 都, 提前), động từ năng nguyện và từ phủ định đứng TRƯỚC 把: 白家月又把这本书看了几遍. So với câu thường: 我看了两遍这本书 (kể bình thường) — 我把这本书看了两遍 (nhấn mạnh cuốn sách đã được “xử lý” hai lượt). Ôn chuỗi câu chữ 把 của 4下: Bài 15 · điểm 3 把 + 宾 + 动(+一/了)+动 (把房间打扫打扫), Bài 16 · điểm 1 把 + 宾 + 动 + 了. Lỗi người Việt hay mắc: đặt số lần trước động từ theo tiếng Việt (“hai lượt đọc”) hoặc quên động lượng từ sau số từ.","viDu":[{"zh":"因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","py":"Yīnwèi Lǐ Wén tāmen tíqián bǎ gùshi liǎojiě le yí biàn, suǒyǐ chàbuduō dōu kàndǒng le.","vn":"Vì nhóm Lý Văn đã tìm hiểu trước câu chuyện một lượt, nên họ gần như xem hiểu hết."},{"zh":"他把这个动作做了好几次，最后终于做对了。","py":"Tā bǎ zhège dòngzuò zuò le hǎojǐ cì, zuìhòu zhōngyú zuò duì le.","vn":"Anh ấy làm động tác này mấy lần liền, cuối cùng cũng làm đúng."},{"zh":"白家月又把这本书看了几遍，越看越喜欢。","py":"Bái Jiāyuè yòu bǎ zhè běn shū kàn le jǐ biàn, yuè kàn yuè xǐhuan.","vn":"Bạch Gia Nguyệt lại đọc cuốn sách này mấy lượt, càng đọc càng thích."},{"zh":"尽管已经把课文读了好几遍，他上台时还是有点儿紧张。","py":"Jǐnguǎn yǐjīng bǎ kèwén dú le hǎojǐ biàn, tā shàngtái shí háishi yǒudiǎnr jǐnzhāng.","vn":"Mặc dù đã đọc bài khoá mấy lượt rồi, khi lên sân khấu anh ấy vẫn hơi căng thẳng. (ôn 尽管……还是…… – Bài 9 · điểm 2)"}],"loi":[{"sai":"我把这本书两遍看了。","why":"Bổ ngữ động lượng đứng SAU động từ, không đứng trước như tiếng Việt.","dung":"我把这本书看了两遍。"},{"sai":"她把这个动作做了好几。","why":"Thiếu động lượng từ (次 / 遍) sau số từ.","dung":"她把这个动作做了好几次。"},{"sai":"他把一本书看了三遍。","why":"Tân ngữ sau 把 phải xác định (这本书 / 那本书), không dùng 一本书.","dung":"他把这本书看了三遍。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["因为李文他们提前把故事了解了一","，所以差不多都看懂了。"],"dap":[["遍"]],"chon":["遍","本","个"],"goiY":"“… đã tìm hiểu trước câu chuyện một lượt …”","giai":"Động lượng từ 遍 = một lượt trọn vẹn."},{"kieu":"dien","phan":["他","这个动作做了好几次，最后终于做对了。"],"dap":[["把"]],"chon":["把","被","给"],"goiY":"“Anh ấy làm động tác này mấy lần …”","giai":"Chủ ngữ chủ động tác động lên 这个动作 → 把."},{"kieu":"dien","phan":["白家月","把这本书看了几遍，越看越喜欢。"],"dap":[["又"]],"chon":["又","再","还"],"goiY":"“Bạch Gia Nguyệt LẠI đọc cuốn sách này mấy lượt …” (việc đã xảy ra)","giai":"又 (lặp lại, đã xảy ra) đứng trước 把; 再 dùng cho việc chưa xảy ra."},{"kieu":"dien","phan":["为了演好，我们把这个节目排了十几","。"],"dap":[["遍"]],"chon":["遍","趟","下"],"goiY":"“… chúng tôi tập tiết mục này mười mấy lượt.”","giai":"Tập trọn tiết mục từ đầu đến cuối → 遍."},{"kieu":"dien","phan":["他把门敲了三","，可是没有人开。"],"dap":[["下"]],"chon":["下","遍","本"],"goiY":"“Anh ấy gõ cửa ba cái, nhưng không ai mở.”","giai":"Động tác nhanh, ngắn (gõ, vỗ) → 下."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["他","把","这个动作","做了","好几次","，","最后","终于做对了"],"dap":["他把这个动作做了好几次，最后终于做对了。"],"goiY":"Anh ấy làm động tác này mấy lần, cuối cùng cũng làm đúng.","giai":"把 + 宾 + V了 + 好几次."},{"kieu":"xep","manh":["白家月","又","把","这本书","看了","几遍"],"dap":["白家月又把这本书看了几遍。"],"goiY":"Bạch Gia Nguyệt lại đọc cuốn sách này mấy lượt.","giai":"又 đứng trước 把."},{"kieu":"xep","manh":["我们","把","这个节目","排了","十几遍"],"dap":["我们把这个节目排了十几遍。"],"goiY":"Chúng tôi tập tiết mục này mười mấy lượt.","giai":"Số lần ở cuối câu."},{"kieu":"dungsai","cau":"因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","dung":true,"giai":"Đúng: 提前 đứng trước 把, 一遍 sau động từ."},{"kieu":"dungsai","cau":"我把这本书两遍看了。","dung":false,"sua":"我把这本书看了两遍。","giai":"Bổ ngữ động lượng đứng sau động từ."},{"kieu":"dungsai","cau":"他把一个问题讲了好几遍。","dung":false,"sua":"他把这个问题讲了好几遍。","giai":"Tân ngữ của 把 phải xác định."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 105)","huongDan":"Dùng từ trong ngoặc, hoàn thành câu theo cấu trúc 「主语 + 把 + 宾语 + 动词 + 动量补语」","cau":[{"kieu":"vandung","de":"他们小组特别认真，＿＿＿，最后才定下来。（讨论）","goiY":"Thảo luận kế hoạch / phương án mấy lần","mau":"把这个计划讨论了好几遍","can":[["把"],["讨论"]]},{"kieu":"vandung","de":"我＿＿＿，还是不满意。（计划书）","goiY":"Đã sửa bản kế hoạch mấy lượt","mau":"把计划书改了三遍","can":[["把"],["计划书"]]},{"kieu":"vandung","de":"我们＿＿＿，最后所有人都记住了。（排）","goiY":"Tập tiết mục mấy lượt","mau":"把这个节目排了十几遍","can":[["把"],["排"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Cô ấy đã đọc cuốn sách này mấy lượt, càng đọc càng thích.","dap":["她把这本书看了好几遍，越看越喜欢。","她把这本书看了几遍，越看越喜欢。","她把这本书读了好几遍，越读越喜欢。"],"giai":"把 + 宾 + V了 + 好几遍 + ôn 越……越……"},{"kieu":"dich","vn":"Tôi đã xem trước bài khoá một lượt, nên trên lớp nghe hiểu hết.","dap":["我提前把课文看了一遍，所以上课都听懂了。","我提前把课文看了一遍，所以课上都听懂了。","因为我提前把课文看了一遍，所以上课都听懂了。"],"giai":"提前 đứng trước 把; 一遍 sau động từ."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể em đã chuẩn bị cho một kỳ thi / buổi biểu diễn thế nào, có dùng 「把 + 宾 + V + 动量补语」","mau":"为了参加艺术节，我们把这个话剧排了二十多遍。","can":[["把"],["遍","次"]]}]}]},{"so":"4","ten":"“把”字句“主语+把+宾语+动词+时量补语”","tenVn":"Câu chữ 「把」: Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ thời lượng — làm việc gì với đối tượng trong bao lâu","cauTruc":["Chủ ngữ + 把 + tân ngữ (xác định) + (又) + động từ + (了) + thời lượng (十分钟 / 一个小时 / 两天 / 一个星期…)","把这本书看了两天 · 把这个问题又讲了十分钟 · 把这个动作又练了一小时"],"giaiThich":"Một dạng nữa của câu chữ 把: nhấn mạnh chủ ngữ tác động lên tân ngữ trong KHOẢNG THỜI GIAN bao lâu. “Bổ ngữ thời lượng” là các từ chỉ độ dài thời gian: 十分钟, 半个小时, 一个上午, 两天, 一个星期, 整整一年… đặt SAU động từ. Rất hay đi với 又 (lại thêm): 又 có thể đứng trước 把 (又把这本书看了两天) hoặc trước động từ (把这个问题又讲了十分钟) — sách có cả hai cách. Thường có vế sau nói kết quả: …，大家才明白 / …，终于都会写了 / …才看完. So với câu thường: động từ có tân ngữ mà muốn thêm thời lượng thì tiếng Trung phải lặp động từ (讲这个问题讲了十分钟) hoặc đưa tân ngữ ra trước bằng 把 (把这个问题讲了十分钟) — ✗ 讲了这个问题十分钟 (câu kiểu tiếng Việt). So sánh với điểm 3: 动量补语 trả lời “mấy lần?” (几遍 / 几次), 时量补语 trả lời “bao lâu?” (多长时间). Tân ngữ sau 把 vẫn phải xác định. Đừng đặt thời lượng trước động từ (✗ 把这本书两天看了).","viDu":[{"zh":"（我）到家后又把这本书看了两天。","py":"(Wǒ) dào jiā hòu yòu bǎ zhè běn shū kàn le liǎng tiān.","vn":"(Tôi) về đến nhà lại đọc cuốn sách này suốt hai ngày."},{"zh":"王老师把这个问题又讲了十分钟，大家才明白。","py":"Wáng lǎoshī bǎ zhège wèntí yòu jiǎng le shí fēnzhōng, dàjiā cái míngbai.","vn":"Thầy Vương giảng vấn đề này thêm mười phút nữa, mọi người mới hiểu."},{"zh":"陈天中把这个动作又练了一小时。","py":"Chén Tiānzhōng bǎ zhège dòngzuò yòu liàn le yì xiǎoshí.","vn":"Trần Thiên Trung luyện động tác này thêm một tiếng nữa."},{"zh":"为了这次面试，他把自我介绍准备了整整一个星期，说不定能成功。","py":"Wèile zhè cì miànshì, tā bǎ zìwǒ jièshào zhǔnbèi le zhěngzhěng yí gè xīngqī, shuōbudìng néng chénggōng.","vn":"Vì lần phỏng vấn này, anh ấy chuẩn bị phần tự giới thiệu suốt cả một tuần, không chừng sẽ thành công. (ôn 说不定 – Bài 16 · điểm 3)"}],"loi":[{"sai":"我把这本书两天看了。","why":"Bổ ngữ thời lượng đứng SAU động từ.","dung":"我把这本书看了两天。"},{"sai":"王老师讲了这个问题十分钟。","why":"Động từ có tân ngữ + thời lượng: không đặt thời lượng sau tân ngữ kiểu tiếng Việt → dùng 把 (hoặc lặp động từ).","dung":"王老师把这个问题讲了十分钟。"},{"sai":"他把一个动作练了一个小时。","why":"Tân ngữ sau 把 phải xác định.","dung":"他把这个动作练了一个小时。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["到家后，我又把这本书看了两","。"],"dap":[["天"]],"chon":["天","本","页"],"goiY":"“Về đến nhà, tôi lại đọc cuốn sách này suốt hai ngày.”","giai":"Bổ ngữ thời lượng: 两天."},{"kieu":"dien","phan":["王老师把这个问题又讲了十分钟，大家","明白。"],"dap":[["才"]],"chon":["才","就","都"],"goiY":"“… mọi người MỚI hiểu.” (muộn, khó khăn)","giai":"Tốn thời gian rồi mới có kết quả → 才."},{"kieu":"dien","phan":["为了演好，陈天中把这个动作又练了一个","。"],"dap":[["小时"]],"chon":["小时","遍","次"],"goiY":"“… luyện động tác này thêm một tiếng.”","giai":"一个 + 小时 (thời lượng); 遍 / 次 không đi với 个."},{"kieu":"dien","phan":["桌子上的东西太多、太乱了，我把它们","了半个小时。"],"dap":[["整理"]],"chon":["整理","转发","报考"],"goiY":"“… tôi sắp xếp chúng mất nửa tiếng.”","giai":"整理 = sắp xếp (từ mới bài khoá 4)."},{"kieu":"dien","phan":["为了这次面试，他把自我介绍准备了整整一个星期，","能成功。"],"dap":[["说不定"]],"chon":["说不定","到底","究竟"],"goiY":"“… không chừng sẽ thành công.” (ôn Bài 16)","giai":"说不定 = có lẽ, không chừng (Bài 16 · điểm 3)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["王老师","把","这个问题","又","讲了","十分钟"],"dap":["王老师把这个问题又讲了十分钟。","王老师又把这个问题讲了十分钟。"],"goiY":"Thầy Vương giảng vấn đề này thêm mười phút.","giai":"又 đứng trước động từ (hoặc trước 把)."},{"kieu":"xep","manh":["我","到家后","又","把","这本书","看了","两天"],"dap":["我到家后又把这本书看了两天。","到家后我又把这本书看了两天。"],"goiY":"Về đến nhà tôi lại đọc cuốn sách này suốt hai ngày.","giai":"Thời lượng ở cuối câu."},{"kieu":"xep","manh":["同学们","把","这个汉字","练了","一个上午"],"dap":["同学们把这个汉字练了一个上午。"],"goiY":"Các bạn luyện chữ Hán này cả một buổi sáng.","giai":"把 + 宾 + V了 + 一个上午."},{"kieu":"dungsai","cau":"陈天中把这个动作又练了一小时。","dung":true,"giai":"Đúng: 又 + V了 + thời lượng."},{"kieu":"dungsai","cau":"我把这本书两天看了。","dung":false,"sua":"我把这本书看了两天。","giai":"Thời lượng đứng sau động từ."},{"kieu":"dungsai","cau":"王老师讲了这个问题十分钟。","dung":false,"sua":"王老师把这个问题讲了十分钟。","giai":"Không đặt thời lượng sau tân ngữ → dùng 把."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 107)","huongDan":"Hoàn thành câu theo cấu trúc 「主语 + 把 + 宾语 + 动词 + 时量补语」","cau":[{"kieu":"vandung","de":"桌子上的东西太多、太乱了，＿＿＿。","goiY":"Kể đã sắp xếp chúng mất bao lâu","mau":"我把它们整理了半个小时","can":[["把"]]},{"kieu":"vandung","de":"同学们＿＿＿，终于都会写了。","goiY":"Đã luyện chữ Hán này bao lâu","mau":"把这个汉字练了一个上午","can":[["把"]]},{"kieu":"vandung","de":"这本历史书太厚了，＿＿＿才看完。","goiY":"Đọc nó mất bao lâu mới xong","mau":"我把它看了整整两个星期","can":[["把"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Thầy Vương giảng vấn đề này thêm mười phút, mọi người mới hiểu.","dap":["王老师把这个问题又讲了十分钟，大家才明白。","王老师又把这个问题讲了十分钟，大家才明白。"],"giai":"把 + 宾 + 又 + V了 + 十分钟，……才……"},{"kieu":"dich","vn":"Về đến nhà, tôi lại đọc cuốn sách này suốt hai ngày.","dap":["到家后，我又把这本书看了两天。","回家后，我又把这本书看了两天。","到家以后，我又把这本书看了两天。"],"giai":"又 + 把 + 宾 + V了 + 两天."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Kể em đã luyện / ôn một thứ gì đó trong bao lâu, có dùng 「把 + 宾 + V + 时量补语」","mau":"为了参加汉语比赛，我把自己的演讲练了整整一个星期。","can":[["把"]]}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk4v3-bai-20.html"] = [{"so":"1","ten":"语气副词“难道”","tenVn":"Phó từ ngữ khí 「难道」 — lẽ nào, chẳng lẽ (câu hỏi tu từ, phỏng đoán)","cauTruc":["难道 + (chủ ngữ) + hình thức KHẲNG ĐỊNH + 吗？ → ý PHỦ ĐỊNH","难道 + (chủ ngữ) + 不 / 没 + V + 吗？ → ý KHẲNG ĐỊNH","……，难道 + ……(了)？ → phỏng đoán, nghi ngờ (có thể không có 吗)"],"giaiThich":"「难道」 là phó từ ngữ khí, có hai cách dùng. (1) Biểu thị PHỎNG ĐOÁN, nghi ngờ: thấy một hiện tượng lạ rồi đoán — 车快开了他还没到，难道他不去了？ (lẽ nào anh ấy không đi nữa?). (2) Dùng trong CÂU HỎI TU TỪ (phản vấn) 「难道……吗？」 — hỏi mà không cần trả lời, để NHẤN MẠNH: nếu là hình thức khẳng định thì ý thật là phủ định (难道我会骗你吗？ = tôi không lừa bạn đâu); nếu là hình thức phủ định thì ý thật là khẳng định (难道我们不应该保护环境吗？ = chúng ta đương nhiên phải bảo vệ môi trường). Tiếng Việt tương đương: “lẽ nào…?, chẳng lẽ…?, chẳng phải… sao?”. 难道 đứng đầu câu hoặc sau chủ ngữ (你难道不知道吗？). Cuối câu thường có 吗 (khẩu ngữ có khi bỏ). ⚠ 难道 KHÔNG dùng với câu hỏi chính phản V不V hay đại từ nghi vấn; KHÔNG nhầm với 到底 / 究竟 (Bài 18, Bài 14) — hai từ này là hỏi THẬT, muốn biết đáp án (你到底去不去？), không đi với 吗. Mẹo: muốn “trách nhẹ” hay “khẳng định mạnh” thì đổi câu thành 难道 + ý ngược lại + 吗？","viDu":[{"zh":"难道你买的是无座票吗？","py":"Nándào nǐ mǎi de shì wú zuò piào ma?","vn":"Chẳng lẽ cậu mua vé không có chỗ ngồi à?"},{"zh":"车快开了他还没到，难道他不去了？","py":"Chē kuài kāi le tā hái méi dào, nándào tā bú qù le?","vn":"Tàu sắp chạy rồi mà anh ấy vẫn chưa tới, lẽ nào anh ấy không đi nữa?"},{"zh":"难道我们不应该保护环境吗？","py":"Nándào wǒmen bú yīnggāi bǎohù huánjìng ma?","vn":"Chẳng lẽ chúng ta không nên bảo vệ môi trường sao? (= đương nhiên phải bảo vệ)"},{"zh":"这么简单的问题，难道你连这个都不会吗？","py":"Zhème jiǎndān de wèntí, nándào nǐ lián zhège dōu bú huì ma?","vn":"Câu hỏi đơn giản thế này, chẳng lẽ đến cái này bạn cũng không biết? (ôn 连……都…… – Bài 17 · điểm 4)"}],"loi":[{"sai":"我难道是你的朋友吗？我一定会帮你的。","why":"Hình thức khẳng định + 难道 lại thành ý phủ định (“tôi không phải bạn bạn”) — ngược ý muốn nói.","dung":"难道我不是你的朋友吗？我一定会帮你的。"},{"sai":"难道你知道不知道这件事？","why":"难道 không đi với câu hỏi chính phản V不V; dùng 难道……(不)……吗？","dung":"难道你不知道这件事吗？"},{"sai":"难道你到底去不去？","why":"到底 hỏi thật (muốn biết đáp án), 难道 là câu tu từ — không dùng chung.","dung":"你到底去不去？ / 难道你不去了吗？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["看你一直不坐下，我还在想，","你买的是无座票吗？"],"dap":[["难道"]],"chon":["难道","到底","究竟"],"goiY":"“… chẳng lẽ cậu mua vé không có chỗ ngồi à?”","giai":"Câu tu từ có 吗 → 难道; 到底 / 究竟 là hỏi thật, không đi với 吗."},{"kieu":"dien","phan":["难道我们不应该保护环境","？"],"dap":[["吗"]],"chon":["吗","呢","吧"],"goiY":"“Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?”","giai":"Khuôn 难道……吗？"},{"kieu":"dien","phan":["这么冷的天，你只穿了一件衬衫，难道不怕","吗？"],"dap":[["感冒"]],"chon":["感冒","堵车","登机"],"goiY":"“… lẽ nào không sợ bị cảm à?”","giai":"Phủ định 不怕 → ý khẳng định: sẽ bị cảm đấy."},{"kieu":"dien","phan":["你中文说得这么","，难道你在中国住过吗？"],"dap":[["流利"]],"chon":["流利","所有","细"],"goiY":"“Bạn nói tiếng Trung lưu loát thế, lẽ nào bạn từng sống ở Trung Quốc?”","giai":"难道 dùng để phỏng đoán; V得 + 流利."},{"kieu":"dien","phan":["这件事大家都知道，难道你","知道吗？"],"dap":[["不"]],"chon":["不","也","就"],"goiY":"“Chuyện này ai cũng biết, chẳng lẽ bạn không biết?”","giai":"难道 + 不 + V + 吗？ = ý khẳng định: bạn phải biết chứ."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["难道","你","买的","是","无座票","吗"],"dap":["难道你买的是无座票吗？"],"goiY":"Chẳng lẽ cậu mua vé không có chỗ ngồi à?","giai":"难道 + câu + 吗？"},{"kieu":"xep","manh":["难道","我们","不应该","保护","环境","吗"],"dap":["难道我们不应该保护环境吗？","我们难道不应该保护环境吗？"],"goiY":"Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?","giai":"难道 đứng đầu câu hoặc sau chủ ngữ."},{"kieu":"xep","manh":["车快开了","，","他还没到","，","难道","他不去了"],"dap":["车快开了，他还没到，难道他不去了？"],"goiY":"Tàu sắp chạy rồi, anh ấy vẫn chưa đến, lẽ nào anh ấy không đi nữa?","giai":"难道 biểu thị phỏng đoán, có thể không có 吗."},{"kieu":"dungsai","cau":"你已经是大学生了，难道这点儿小事也不会做吗？","dung":true,"giai":"Đúng: phủ định 不会做 → ý khẳng định “việc nhỏ này bạn phải làm được”."},{"kieu":"dungsai","cau":"难道你知道不知道这件事？","dung":false,"sua":"难道你不知道这件事吗？","giai":"难道 không đi với câu hỏi chính phản V不V."},{"kieu":"dungsai","cau":"我难道是你的朋友吗？我一定会帮你的。","dung":false,"sua":"难道我不是你的朋友吗？我一定会帮你的。","giai":"Muốn khẳng định “tôi là bạn của bạn” phải dùng hình thức phủ định 难道……不……吗？"}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 114)","huongDan":"Hoàn thành đối thoại, có dùng 「难道」","cau":[{"kieu":"vandung","de":"A：你应该向她道歉。 B：为什么要道歉？＿＿＿？","goiY":"B không đồng ý, hỏi lại bằng câu tu từ: lẽ nào là tôi làm sai?","mau":"难道是我做错了吗","can":[["难道"]]},{"kieu":"vandung","de":"A：这个东西不是你的。 B：＿＿＿？它就是我的。","goiY":"B khẳng định: lẽ nào tôi lại không nhận ra đồ của chính mình?","mau":"难道我连自己的东西都不认识吗","can":[["难道"]]},{"kieu":"vandung","de":"A：他为什么不在？＿＿＿？ B：对，＿＿＿。","goiY":"A phỏng đoán: lẽ nào anh ấy tan làm rồi? B xác nhận và nói thêm lý do","mau":"难道他已经下班了吗；他今天有事，提前下班了","can":[["难道"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chẳng lẽ bạn không biết ngày mai có kỳ thi sao?","dap":["难道你不知道明天有考试吗？","你难道不知道明天有考试吗？"],"giai":"难道 + 不 + V + 吗？ → ý khẳng định."},{"kieu":"dich","vn":"Đã mười giờ rồi mà anh ấy vẫn chưa đến, lẽ nào anh ấy quên rồi?","dap":["已经十点了他还没来，难道他忘了？","已经十点了，他还没来，难道他忘了吗？"],"giai":"难道 biểu thị phỏng đoán."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em nói “học tiếng Trung chẳng có ích gì”. Hãy phản bác bằng một câu có 「难道」","mau":"难道会说中文没有用吗？现在很多公司都需要会中文的人。","can":[["难道"]]}]}]},{"so":"2","ten":"反问句：由疑问代词构成的反问句","tenVn":"Câu hỏi tu từ (phản vấn) dùng đại từ nghi vấn 「谁、什么、怎么、哪里、为什么」","cauTruc":["谁 + 说 / V + ……？ (谁说不是呢？ = ai bảo không phải → đúng thế)","怎么 + 能 / 会 + ……？ (hình thức khẳng định → ý phủ định)","为什么不 + V + ……呢？ (hình thức phủ định → ý khẳng định: nên làm)","哪儿 / 哪里 / 什么 + ……？ (哪儿有时间？ = không có thời gian)"],"giaiThich":"Câu hỏi tu từ (反问句) là câu có hình thức câu hỏi nhưng KHÔNG cần trả lời — người nói đã có ý rõ ràng, chỉ hỏi để nhấn mạnh ngữ khí. Bài 20 · điểm 1 dùng 难道; điểm này dùng ĐẠI TỪ NGHI VẤN 谁、什么、怎么、哪里 / 哪儿、为什么. Quy tắc giống nhau: hình thức KHẲNG ĐỊNH → ý PHỦ ĐỊNH (我们连手机都没有，怎么能查到？ = không thể tra được); hình thức PHỦ ĐỊNH → ý KHẲNG ĐỊNH (我们为什么不去苏州玩玩呢？ = nên đi; 谁说不是呢？ = đúng thế, tôi đồng ý). Cuối câu thường dùng 呢 hoặc 啊, KHÔNG dùng 吗 (vì đã có đại từ nghi vấn). Mẫu hay gặp: 谁说……？ (phản bác: ai bảo …), 谁知道……？ (ai mà biết), 怎么会……呢？ (sao có thể …), 哪儿有……？ (đâu có …), 有什么……的？ (ôn Bài 6 · điểm 2: 有什么好着急的？ = chẳng có gì phải vội). Người Việt cũng nói tương tự: “Ai bảo thế?”, “Làm sao mà … được?”, “Sao lại không …?” — nên dễ hiểu, chỉ cần nhớ dùng 呢 chứ không dùng 吗, và đọc với ngữ điệu nhấn mạnh.","viDu":[{"zh":"谁说不是呢？","py":"Shuí shuō bú shì ne?","vn":"Ai bảo không phải chứ? (= Đúng thế!)"},{"zh":"这里离苏州这么近，我们为什么不去苏州玩玩呢？","py":"Zhèli lí Sūzhōu zhème jìn, wǒmen wèishénme bú qù Sūzhōu wánwan ne?","vn":"Ở đây gần Tô Châu thế, sao chúng ta lại không đi Tô Châu chơi một chút? (= nên đi)"},{"zh":"我们连手机都没有，怎么能查到这些信息啊？","py":"Wǒmen lián shǒujī dōu méiyǒu, zěnme néng chádào zhèxiē xìnxī a?","vn":"Chúng ta đến điện thoại cũng không có, làm sao mà tra được những thông tin này? (= không thể tra được)"},{"zh":"时间还早呢，你有什么好着急的？","py":"Shíjiān hái zǎo ne, nǐ yǒu shénme hǎo zháojí de?","vn":"Thời gian còn sớm mà, bạn có gì đâu mà phải vội? (ôn 有什么好×的 – Bài 6 · điểm 2)"}],"loi":[{"sai":"我已经检查好几遍了，怎么会出错吗？","why":"Câu tu từ đã có đại từ nghi vấn thì không dùng 吗 — dùng 呢 (hoặc không có trợ từ).","dung":"我已经检查好几遍了，怎么会出错呢？"},{"sai":"这么好的机会，你为什么去试试呢？","why":"Muốn khuyên “nên đi thử” phải dùng hình thức PHỦ ĐỊNH 为什么不……呢？","dung":"这么好的机会，你为什么不去试试呢？"},{"sai":"A：中国文化真是读也读不完。B：谁说是呢？","why":"Đồng tình phải nói 谁说不是呢？ (phủ định → khẳng định); 谁说是呢 lại thành phản đối.","dung":"谁说不是呢？"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["中国文化真是读也读不完。——谁说不","呢？"],"dap":[["是"]],"chon":["是","对","好"],"goiY":"“Ai bảo không phải chứ?” (= đúng thế)","giai":"Câu cố định 谁说不是呢？ biểu thị đồng tình."},{"kieu":"dien","phan":["这里离苏州这么近，我们为什么","去苏州玩玩呢？"],"dap":[["不"]],"chon":["不","没","也"],"goiY":"“… sao chúng ta lại không đi Tô Châu chơi?” (= nên đi)","giai":"为什么不……呢？ phủ định → ý khẳng định."},{"kieu":"dien","phan":["我们连手机都没有，","能查到这些信息啊？"],"dap":[["怎么"]],"chon":["怎么","什么","谁"],"goiY":"“… làm sao mà tra được những thông tin này?”","giai":"怎么能……？ = không thể … (ôn 连……都…… – Bài 17)."},{"kieu":"dien","phan":["我已经检查好几遍了，怎么会出错","？"],"dap":[["呢"]],"chon":["呢","吗","吧"],"goiY":"“Tôi đã kiểm tra mấy lần rồi, làm sao mà sai được?”","giai":"Câu tu từ có đại từ nghi vấn dùng 呢, không dùng 吗."},{"kieu":"dien","phan":["他一句中文都不会，","能看懂老舍的小说呢？"],"dap":[["哪儿"]],"chon":["哪儿","什么","谁"],"goiY":"“Cậu ấy một câu tiếng Trung cũng không biết, làm sao mà đọc hiểu tiểu thuyết của Lão Xá được?”","giai":"哪儿能……？ = không thể …; ôn 一……都不…… (HSK 3)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这里","离苏州","这么近","，","我们","为什么不","去苏州玩玩呢"],"dap":["这里离苏州这么近，我们为什么不去苏州玩玩呢？"],"goiY":"Ở đây gần Tô Châu thế, sao chúng ta lại không đi Tô Châu chơi?","giai":"为什么不……呢？"},{"kieu":"xep","manh":["我们","连手机都没有","，","怎么能","查到","这些信息啊"],"dap":["我们连手机都没有，怎么能查到这些信息啊？"],"goiY":"Chúng ta đến điện thoại cũng không có, làm sao tra được những thông tin này?","giai":"怎么能 + V？ = không thể."},{"kieu":"xep","manh":["我","已经检查好几遍了","，","怎么会","出错呢"],"dap":["我已经检查好几遍了，怎么会出错呢？"],"goiY":"Tôi đã kiểm tra mấy lần rồi, làm sao mà sai được?","giai":"怎么会……呢？ = không thể nào …"},{"kieu":"dungsai","cau":"谁说不是呢？中国文化真是读也读不完。","dung":true,"giai":"Đúng: 谁说不是呢 = đồng tình."},{"kieu":"dungsai","cau":"我已经检查好几遍了，怎么会出错吗？","dung":false,"sua":"我已经检查好几遍了，怎么会出错呢？","giai":"Đã có 怎么 thì không dùng 吗."},{"kieu":"dungsai","cau":"这么好的机会，你为什么去试试呢？","dung":false,"sua":"这么好的机会，你为什么不去试试呢？","giai":"Khuyên nên làm → 为什么不……呢？"}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成对话 · Hoàn thành đối thoại (sách trang 116)","huongDan":"Hoàn thành đối thoại bằng câu hỏi tu từ có đại từ nghi vấn","cau":[{"kieu":"vandung","de":"A：你看看，是不是出错了？ B：我已经检查好几遍了，＿＿＿？","goiY":"B phản bác: làm sao mà sai được?","mau":"怎么会出错呢","can":[["怎么","哪儿","哪里"]]},{"kieu":"vandung","de":"A：你头发也不长，别理发了。 B：＿＿＿？＿＿＿。","goiY":"B phản bác: ai bảo không dài? rồi nêu lý do","mau":"谁说不长；你看，我已经两个多月没理发了","can":[["谁","怎么","哪儿","哪里"]]},{"kieu":"vandung","de":"A：＿＿＿？这片树林里有熊，你们不能去！ B：没关系，我们会非常小心的。","goiY":"A ngăn lại bằng câu tu từ: sao các cậu có thể đi chỗ đó được? (ôn 熊, 树林 – Bài 13)","mau":"你们怎么能去那儿呢","can":[["怎么","为什么","谁","哪儿"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Tiền tiết kiệm được, sao lại không dùng để đi du lịch?","dap":["节省下来的钱，为什么不用来旅行呢？","节省下来的钱，为什么不拿来旅行呢？"],"giai":"为什么不……呢？ = nên làm."},{"kieu":"dich","vn":"Bài tập nhiều thế này, một ngày làm sao làm xong được?","dap":["作业这么多，一天怎么能做完呢？","这么多作业，一天怎么做得完呢？"],"giai":"怎么能 / 怎么 + V得完 + 呢？ = không thể."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Bạn em nói “Đi du lịch chỉ tốn tiền, đọc sách là đủ rồi”. Hãy phản bác bằng câu tu từ có đại từ nghi vấn","mau":"谁说旅行只是花钱？不出门看看，怎么能真正了解一个国家呢？","can":[["谁","怎么","什么","哪儿","为什么"]]}]}]},{"so":"3","ten":"固定格式“×就×（点儿）吧”","tenVn":"Cấu trúc 「×就×(点儿)吧」 — … thì … (một chút) thôi, cũng được (chấp nhận, nhượng bộ)","cauTruc":["Adj + 就 + Adj + (点儿) + 吧 (累就累点儿吧 / 远就远吧)","V(O) + 就 + V(O) + 吧 (堵车就堵车吧 / 去就去吧)","×就×(点儿)吧，+ lý do chấp nhận (至少……/ ……最重要 / 很值得)"],"giaiThich":"Khuôn cố định biểu thị THỎA HIỆP, NHƯỢNG BỘ: người nói biết tình huống chưa hoàn hảo (mệt, xa, chậm, đắt…) nhưng chấp nhận — “thôi thì … một chút cũng được”, “… thì … vậy”. Rất hay dùng trong KHẨU NGỮ. × lặp lại NGUYÊN DẠNG ở hai bên 就: 累就累点儿吧, 远就远吧, 堵车就堵车吧. Với tính từ hay thêm 点儿 (giảm nhẹ: chỉ hơi … thôi), cuối câu có 吧. Vế sau thường nêu LÝ DO khiến mình chấp nhận: 至少房租便宜 (ít nhất tiền thuê rẻ), 安全最重要, 很值得. ⚠ Không thêm 很 / 非常 vào × (✗ 累就很累吧); 点儿 đứng TRƯỚC 吧 (✗ 累就累吧点儿); vế sau không dùng 所以. Liên hệ bài cũ: ×就是了 (Bài 2) cũng mang giọng “cứ … là được”; 你×你的吧 (Bài 17) cũng là giọng thoải mái, buông bỏ.","viDu":[{"zh":"累就累点儿吧，花更少的钱去看更多的地方，很值得。","py":"Lèi jiù lèi diǎnr ba, huā gèng shǎo de qián qù kàn gèng duō de dìfang, hěn zhíde.","vn":"Mệt thì mệt một chút thôi, tiêu ít tiền hơn mà đi được nhiều nơi hơn, rất đáng."},{"zh":"我租的房子离公司有些远，我想，远就远吧，至少房租便宜。","py":"Wǒ zū de fángzi lí gōngsī yǒuxiē yuǎn, wǒ xiǎng, yuǎn jiù yuǎn ba, zhìshǎo fángzū piányi.","vn":"Nhà tôi thuê hơi xa công ty, tôi nghĩ, xa thì xa thôi, ít nhất tiền thuê rẻ."},{"zh":"慢就慢点儿吧，安全最重要。","py":"Màn jiù màn diǎnr ba, ānquán zuì zhòngyào.","vn":"Chậm thì chậm một chút cũng được, an toàn là quan trọng nhất."},{"zh":"既然你这么喜欢，贵就贵点儿吧，质量好最重要。","py":"Jìrán nǐ zhème xǐhuan, guì jiù guì diǎnr ba, zhìliàng hǎo zuì zhòngyào.","vn":"Đã thích như thế thì đắt một chút cũng được, chất lượng tốt là quan trọng nhất. (ôn 既然……就…… – Bài 7 · điểm 2)"}],"loi":[{"sai":"累就累吧点儿，很值得。","why":"点儿 đứng trước 吧: × + 就 + × + 点儿 + 吧.","dung":"累就累点儿吧，很值得。"},{"sai":"累就很累吧，花更少的钱去看更多的地方。","why":"× lặp nguyên dạng, không thêm 很; muốn giảm nhẹ dùng 点儿.","dung":"累就累点儿吧，花更少的钱去看更多的地方。"},{"sai":"远就远吧，所以房租便宜。","why":"Vế sau nêu lý do chấp nhận (至少 / ……最重要), không dùng 所以.","dung":"远就远吧，至少房租便宜。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["虽然有些累，但累就","点儿吧，花更少的钱去看更多的地方，很值得。"],"dap":[["累"]],"chon":["累","远","慢"],"goiY":"“… mệt thì mệt một chút thôi …”","giai":"× lặp lại nguyên dạng: 累就累点儿吧."},{"kieu":"dien","phan":["我租的房子离公司有些远，我想，远","远吧，至少房租便宜。"],"dap":[["就"]],"chon":["就","也","才"],"goiY":"“… xa thì xa thôi, ít nhất tiền thuê rẻ.”","giai":"× + 就 + × + 吧."},{"kieu":"dien","phan":["慢就慢点儿吧，","最重要。"],"dap":[["安全"]],"chon":["安全","特点","意见"],"goiY":"“Chậm thì chậm một chút, an toàn là quan trọng nhất.”","giai":"Vế sau nêu lý do chấp nhận."},{"kieu":"dien","phan":["这件衣服贵就贵点儿","，质量好就行。"],"dap":[["吧"]],"chon":["吧","吗","呢"],"goiY":"“Chiếc áo này đắt thì đắt một chút, chất lượng tốt là được.”","giai":"Khuôn kết thúc bằng 吧."},{"kieu":"dien","phan":["转机累就累点儿吧，节省下来的钱就","是给自己的大红包了。"],"dap":[["当"]],"chon":["当","把","让"],"goiY":"“… tiền tiết kiệm được coi như là phong bao lì xì lớn tặng mình.”","giai":"当 (dàng) = coi như (từ mới)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["累","就","累点儿吧","，","花更少的钱","去看更多的地方"],"dap":["累就累点儿吧，花更少的钱去看更多的地方。"],"goiY":"Mệt thì mệt một chút, tiêu ít tiền hơn mà đi được nhiều nơi hơn.","giai":"Adj就Adj点儿吧，+ lý do."},{"kieu":"xep","manh":["远就远吧","，","至少","房租","便宜"],"dap":["远就远吧，至少房租便宜。"],"goiY":"Xa thì xa thôi, ít nhất tiền thuê rẻ.","giai":"至少 (Bài 5) nêu lý do chấp nhận."},{"kieu":"xep","manh":["慢","就","慢点儿吧","，","安全","最重要"],"dap":["慢就慢点儿吧，安全最重要。"],"goiY":"Chậm thì chậm một chút, an toàn là quan trọng nhất.","giai":"……最重要 = lý do."},{"kieu":"dungsai","cau":"贵就贵点儿吧，质量好最重要。","dung":true,"giai":"Đúng: Adj就Adj点儿吧 + lý do."},{"kieu":"dungsai","cau":"累就累吧点儿，很值得。","dung":false,"sua":"累就累点儿吧，很值得。","giai":"点儿 đứng trước 吧."},{"kieu":"dungsai","cau":"远就很远吧，所以房租便宜。","dung":false,"sua":"远就远吧，至少房租便宜。","giai":"Không thêm 很; vế sau dùng 至少, không dùng 所以."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 118)","huongDan":"Hoàn thành câu, dùng 「×就×(点儿)吧」 và từ trong ngoặc","cau":[{"kieu":"vandung","de":"别着急，下班时间路上车多，＿＿＿。（堵车）","goiY":"Chấp nhận: tắc đường thì tắc thôi, đến muộn chút cũng không sao","mau":"堵车就堵车吧，晚点儿到也没关系","can":[["堵车就堵车"]]},{"kieu":"vandung","de":"＿＿＿都要在这周末前完成，＿＿＿，至少能换来下个星期的休假。（所有）","goiY":"Vế 1: tất cả công việc; vế 2: chấp nhận vất vả (累 / 忙就……点儿吧)","mau":"所有的工作；累就累点儿吧","can":[["所有"],["就"]]},{"kieu":"vandung","de":"他对这件事＿＿＿，我们觉得这是大家共同的决定，＿＿＿。（意见）","goiY":"Vế 1: anh ấy có ý kiến (không hài lòng); vế 2: có ý kiến thì cứ có ý kiến thôi","mau":"有些意见；有意见就有意见吧，我们还是按计划做","can":[["意见"],["就"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Chậm thì chậm một chút, an toàn là quan trọng nhất.","dap":["慢就慢点儿吧，安全最重要。","慢就慢点儿吧，安全是最重要的。"],"giai":"Adj就Adj点儿吧，……最重要."},{"kieu":"dich","vn":"Đắt thì đắt một chút thôi, đồ tốt dùng được lâu.","dap":["贵就贵点儿吧，好东西可以用很久。","贵就贵点儿吧，好东西能用很长时间。"],"giai":"贵就贵点儿吧 + lý do chấp nhận."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Vé bay thẳng hết rồi, chỉ còn vé nối chuyến. Dùng 「×就×(点儿)吧」 động viên bạn","mau":"转机就转机吧，正好可以在西安玩一天，还能节省不少钱。","can":[["就"],["吧"]]}]}]},{"so":"4","ten":"假设复句“要是……，（就）……，否则……”","tenVn":"Câu phức giả thiết 「要是……，(就)……，否则……」 — nếu … thì …, nếu không thì …","cauTruc":["要是 + giả thiết / điều kiện，(chủ ngữ) + 就 + hành động nên làm / kết quả，否则 + hậu quả (nếu không như vậy)","要是……的话，……就……，否则……"],"giaiThich":"Đây là câu phức ba vế, ghép hai cấu trúc đã học: 要是……，就…… (Bài 1 · điểm 2: nếu … thì …) và ……，否则…… (Bài 8 · điểm 2: nếu không thì …). Vế 1 (要是) nêu một giả thiết / tình huống; vế 2 (就) nói nên làm gì hoặc kết quả trong tình huống đó; vế 3 (否则) nói HẬU QUẢ nếu không làm như vế 2 (hoặc nếu giả thiết không xảy ra). 就 có thể lược (nên sách ghi (就)); có thể thêm 的话 sau vế 要是. Tiếng Việt: “Nếu … thì …, nếu không thì …”. ⚠ Người Việt hay: (1) dùng 但是 / 所以 thay cho 否则 — sai, vì 否则 = “nếu không thì”; (2) vế 否则 lặp lại ý vế 就 — sai, vế 否则 phải nói kết quả XẤU / ngược lại; (3) đặt 否则 ngay sau vế 要是 mà bỏ vế 就. 否则 thường đi với 会 / 就 / 只能 / 可能 (否则会来不及的, 否则只能……).","viDu":[{"zh":"你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。","py":"Nǐmen yàoshi xiǎng duō liǎojiě Zhōngguó, jiù bù néng zhǐ tōngguò dúshū, hái yào duō chūmén lǚxíng, fǒuzé zhǐnéng rènshi kèběn lǐ de Zhōngguó.","vn":"Các em nếu muốn hiểu thêm về Trung Quốc thì không thể chỉ qua sách vở, còn phải ra ngoài du lịch nhiều, nếu không thì chỉ biết một Trung Quốc trong sách giáo khoa."},{"zh":"要是出去的话，咱们就爬山，否则我哪儿都不去。","py":"Yàoshi chūqu dehuà, zánmen jiù páshān, fǒuzé wǒ nǎr dōu bú qù.","vn":"Nếu đi ra ngoài thì mình đi leo núi, nếu không thì tớ chẳng đi đâu cả."},{"zh":"要是你同意的话，这个计划就通过，否则可能需要重新讨论。","py":"Yàoshi nǐ tóngyì dehuà, zhège jìhuà jiù tōngguò, fǒuzé kěnéng xūyào chóngxīn tǎolùn.","vn":"Nếu bạn đồng ý thì kế hoạch này được thông qua, nếu không có thể phải thảo luận lại."},{"zh":"要是你不舒服，就早点儿回家休息，否则病会越来越厉害。","py":"Yàoshi nǐ bù shūfu, jiù zǎodiǎnr huíjiā xiūxi, fǒuzé bìng huì yuèláiyuè lìhai.","vn":"Nếu bạn không khỏe thì về nhà nghỉ sớm đi, nếu không bệnh sẽ ngày càng nặng. (ôn 厉害 – Bài 6 · điểm 1)"}],"loi":[{"sai":"要是下雨，你们就关上窗户，但是雨水会进到房间里。","why":"Nối hậu quả “nếu không thì …” bằng 否则, không dùng 但是.","dung":"要是下雨，你们就关上窗户，否则雨水会进到房间里。"},{"sai":"要是路上堵车，你们就改乘地铁，否则你们改乘地铁。","why":"Vế 否则 phải nói hậu quả khi KHÔNG làm theo vế 就, không lặp lại vế 就.","dung":"要是路上堵车，你们就改乘地铁，否则会来不及的。"},{"sai":"要是天气好，否则我们去爬山。","why":"Thiếu vế 就; 否则 đứng ở vế thứ ba, sau vế 就.","dung":"要是天气好，我们就去爬山，否则就在家学习。"}],"bt":[{"so":1,"cap":"Cơ học","tieuDe":"Chọn từ điền vào chỗ trống","cau":[{"kieu":"dien","phan":["你们","想多了解中国，就不能只通过读书。"],"dap":[["要是"]],"chon":["要是","即使","难道"],"goiY":"“Các em nếu muốn hiểu thêm về Trung Quốc thì …”","giai":"Giả thiết + 就 → 要是……就……"},{"kieu":"dien","phan":["要是出去的话，咱们就爬山，","我哪儿都不去。"],"dap":[["否则"]],"chon":["否则","然后","于是"],"goiY":"“… nếu không thì tớ chẳng đi đâu cả.”","giai":"否则 = nếu không thì."},{"kieu":"dien","phan":["要是你同意的话，这个计划就","，否则可能需要重新讨论。"],"dap":[["通过"]],"chon":["通过","解释","总结"],"goiY":"“… kế hoạch này được thông qua …”","giai":"计划 + 通过 = thông qua kế hoạch."},{"kieu":"dien","phan":["要是路上堵车，你们","改乘地铁，否则会来不及的。"],"dap":[["就"]],"chon":["就","才","也"],"goiY":"“Nếu tắc đường thì các bạn đổi sang tàu điện ngầm …” (ôn 来不及 – Bài 4)","giai":"要是……，(主语) + 就……"},{"kieu":"dien","phan":["节假日要是想出去玩，就得早点儿订机票，否则很难订","。"],"dap":[["到"]],"chon":["到","完","住"],"goiY":"“… nếu không thì rất khó đặt được.”","giai":"订到 = đặt được (bổ ngữ kết quả 到)."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["要是","你同意的话","，","这个计划","就通过","，","否则","需要重新讨论"],"dap":["要是你同意的话，这个计划就通过，否则需要重新讨论。"],"goiY":"Nếu bạn đồng ý thì kế hoạch này thông qua, nếu không phải thảo luận lại.","giai":"要是……，就……，否则……"},{"kieu":"xep","manh":["要是","路上堵车","，","你们就","改乘地铁","，","否则","会来不及的"],"dap":["要是路上堵车，你们就改乘地铁，否则会来不及的。"],"goiY":"Nếu tắc đường thì các bạn đổi sang tàu điện ngầm, nếu không sẽ không kịp.","giai":"否则 + 会……的 (hậu quả)."},{"kieu":"xep","manh":["要是","想说得流利","，","就得","每天练口语","，","否则","会忘的"],"dap":["要是想说得流利，就得每天练口语，否则会忘的。"],"goiY":"Nếu muốn nói lưu loát thì phải luyện nói mỗi ngày, nếu không sẽ quên.","giai":"就得 (děi) = thì phải."},{"kieu":"dungsai","cau":"要是出去的话，咱们就爬山，否则我哪儿都不去。","dung":true,"giai":"Đúng: đủ ba vế 要是……就……否则……"},{"kieu":"dungsai","cau":"要是下雨，你们就关上窗户，但是雨水会进到房间里。","dung":false,"sua":"要是下雨，你们就关上窗户，否则雨水会进到房间里。","giai":"“Nếu không thì” → 否则, không dùng 但是."},{"kieu":"dungsai","cau":"要是天气好，否则我们去爬山。","dung":false,"sua":"要是天气好，我们就去爬山，否则就在家学习。","giai":"Thiếu vế 就; 否则 nói hậu quả ở vế thứ ba."}]},{"so":3,"cap":"Bài tập SGK","tieuDe":"完成句子 · Hoàn thành câu (sách trang 120)","huongDan":"Hoàn thành câu với 「要是……，(就)……，否则……」","cau":[{"kieu":"vandung","de":"要是路上堵车，你们就改乘地铁，否则＿＿＿。","goiY":"Nói hậu quả: sẽ không kịp / sẽ đến muộn (ôn 来不及 – Bài 4)","mau":"会来不及的"},{"kieu":"vandung","de":"要是＿＿＿，＿＿＿，否则就在家学习。","goiY":"Nêu giả thiết (ví dụ thời tiết đẹp) và việc sẽ làm (dùng 就)","mau":"明天天气好；我们就去公园散步","can":[["就"]]},{"kieu":"vandung","de":"＿＿＿，你们就关上窗户，否则＿＿＿。","goiY":"Vế 1: nêu giả thiết (trời mưa / gió to); vế 3: hậu quả nếu không đóng cửa sổ","mau":"要是外边下雨了；雨水会进到房间里","can":[["要是","如果"]]}]},{"so":4,"cap":"Giao tiếp","tieuDe":"Dịch và tự đặt câu","cau":[{"kieu":"dich","vn":"Nếu bạn muốn hiểu Trung Quốc thì phải đi du lịch nhiều, nếu không chỉ biết một Trung Quốc trong sách.","dap":["要是你想了解中国，就要多出门旅行，否则只能认识书里的中国。","要是你想了解中国，就要多出去旅行，否则只能认识课本里的中国。"],"giai":"要是……就……，否则只能……"},{"kieu":"dich","vn":"Nếu không khỏe thì về nhà nghỉ sớm đi, nếu không bệnh sẽ ngày càng nặng.","dap":["要是不舒服，就早点儿回家休息吧，否则病会越来越厉害。","要是你不舒服，就早点儿回家休息，否则病会越来越厉害。"],"giai":"否则 + 会 + hậu quả; ôn 厉害 (Bài 6)."},{"kieu":"vandung","tuDo":true,"de":"＿＿＿","goiY":"Dặn bạn sắp đi du lịch dịp lễ: phải đặt vé sớm, có dùng 「要是……就……否则……」","mau":"要是你想国庆节去旅行，就得早点儿订机票和酒店，否则很难订到。","can":[["要是"],["否则"]]}]}]}];
